window.__D("text/zohar-hebrew-translation/c035",{"p":[[9522012533,"<p>וְדֶרֶךָ סוֹד, א\"ח - הוּא תִּשְׁעָה פֵּרוּרִים, שְׁלֹשָׁה לְכָל כִּוּוּן, שְׁלֹשָׁה מִן אַרְבָּעָה - שְׁנֵים עָשָׂר. ד' הִיא הַשְּׁלֵמוּת, לְהַשְׁלִים בָּהּ עֲשָׂרָה. וּלְהַשְׁלִים אַרְבָּעָה, שֶׁהֵם יְהֹוָה. מָהֶם עֲשָׂרָה? אֵלּוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. קוֹץ שֶׁל אוֹת ד' מֵאֶחָד, שִׁעוּרָהּ בְּכַזַּיִת. י' מֵהֲוָיָ\"ה, שִׁעוּרָהּ כַּבֵּיצָה.</p>\n<p>הִיא ד', שְׁלֵמוּת הַמֶּרְכָּבָה שֶׁל אָדָם וּשְׁלֵמוּת שֶׁל אַרְבַּע פָּנִים שֶׁל אָדָם. וּמִשּׁוּם זֶה (במדבר ו) יִשָּׂא יְהֹוָה פָּנָיו אֵלֶיךְ. וּבֵאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, וַהֲרֵי כָּתוּב (דברים י) אֲשֶׁר לֹא יִשָּׂא פָנִים. אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא אָמַרְתִּי לָהֶם (שם יא) וְאָכַלְתָּ וְשָׂבָעְתָּ? וְהֵם דִּקְדְּקוּ עֲלֵיהֶם, עַד כַּזַּיִת אוֹ עַד כַּבֵּיצָה, וְאֵיךְ לֹא אֶשָּׂא לָהֶם פָּנִים?! וְחַכְמֵי הַמִּשְׁנָה וְהָאָמוֹרָאִים, כָּל הַתַּלְמוּד שֶׁלָּהֶם עַל סוֹדוֹת הַתּוֹרָה סִדְּרוּ אוֹתוֹ.</p>\n<p>קָם הָרוֹעֶה הַנֶּאֱמָן, וְהֵרִים יָדָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, וְכָךְ אָמַר: קֻדְשָׁא בְּרִיךְ הוּא, יְהִי רָצוֹן שֶׁלְּךְ לָתֵת לָנוּ מָזוֹן שָׁלֵם, לְתַקֵּן אֶצְלְךְ וְאֵצֶל הַמַּלְכָּה הָעֶלְיוֹנָה, עוֹלָם הַבָּא, שֶׁנֶּאֱמַר עָלָיו (תהלים כב) כִּי לַה' הַמְּלוּכָה וּמוֹשֵׁל בַּגּוֹיִם. וּלְגַבֵּי הַמַּלְכָּה הַשְּׁנִיָּה שֶׁנֶּאֱמַר בָּהּ פַּעַם שְׁנִיָּה, (עובדיה א) וְהָיְתָה לַה' הַמְּלוּכָה. לְתַקֵּן שֻׁלְחָן שָׁלֵם מִכָּל מַעֲדַנִּים וּמִכָּל מַאֲכָלִים.</p>\n<p>וַאֲנִי מְזַמֵּן עִמְּךְ לְכָל בַּעֲלֵי הַמִּשְׁנָה, וּלְבַעֲלֵי הַמִּקְרָא, וּלְבַעֲלֵי הַתַּלְמוּד, וְכָל שֶׁכֵּן לְבַעֲלֵי סוֹדוֹת הַתּוֹרָה שֶׁלְּךְ, כַּלָּה שֶׁלְּךְ, מַלְכָּה קְדוֹשָׁה שֶׁלְּךְ, עֶלְיוֹנָה וְתַחְתּוֹנָה, וְהַכֹּל בִּרְשׁוּת שֶׁל עֶלְיוֹן כָּל עֶלְיוֹנִים, אֲדוֹן כָּל הָאֲדוֹנִים, מֶלֶךְ עַל כָּל הַמְּלָכִים שֶׁל מַעְלָה וּמַטָּה, שֶׁהוּא יָחִיד בְּלִי שֵׁנִי, וְאֵין אוֹת וּנְקֻדָּה שֶׁמִּשְׁתַּתֶּפֶת עִמּוֹ, וְלֹא שִׁנּוּי גְּוָנִים שֶׁל אֲנָשִׁים. שֶׁהוּא בַּעַל כָּל הַמַּפְתְּחוֹת שֶׁל סוֹדוֹת הַהֲוָיוֹת, וְשֵׁמוֹת וְכִנּוּיִים, וְכָל סוֹדוֹת הַגְּנוּזִים שֶׁל הַחָכְמָה, שֶׁתִּפְתַּח אוֹתָם כֻּלָּם לִכְבוֹדְךְ, עֶלְיוֹן עַל כָּל הָעִלּוֹת. אֲנִי מִתְחַנֵּן לְפָנֶיךְ שֶׁתִּפְתַּח אוֹתָם לִכְבוֹדְךְ, שֶׁכְּבוֹדְךְ הוּא מֵאָבִי וְאִמִּי שֶׁבַּשָּׁמַיִם, וְאָב שֶׁל כָּל יִשְׂרָאֵל וְאֵם שֶׁלָּהֶם, שֶׁנֶּאֱמַר בָּהּ (משלי א) וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ, וְעִמְּךְ אֵין שֻׁתָּף שֶׁל אֵם בָּעוֹלָם.</p>\n<p>קָם זְמַן שֵׁנִי וְאָמַר, בַּעֲלֵי הַמִּשְׁנָה, נְשָׁמוֹת וְרוּחוֹת וּנְפָשׁוֹת שֶׁלָּכֶם, הִתְעוֹרְרוּ כָּעֵת כֻּלְּכֶם וְהַעֲבִירוּ שֵׁנָה מִכֶּם, שֶׁהִיא וַדַּאי מִשְׁנָה, דֶּרֶךְ פְּשָׁט שֶׁל עוֹלָם הַזֶּה. שֶׁאֲנִי לֹא עוֹרַרְתִּי בָּכֶם אֶלָּא בְּסוֹדוֹת עֶלְיוֹנִים שֶׁל הָעוֹלָם הַבָּא, שֶׁאַתֶּם בָּהֶם (תהלים קכא) הִנֵּה לֹא יָנוּם וְלֹא יִישָׁן.</p>\n<p>פָּתַח וְאָמַר, הֲרֵי בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, בַּעַל הַבַּיִת בּוֹצֵעַ וְאוֹרֵחַ מְבָרֵךְ. וְעוֹד בֵּאֲרוּהוּ, צָרִיךְ לְדַקְדֵּק בְּה' מִן הַמּוֹצִיא. וּשְׁתֵּי ה' הֵן כְּנֶגֶד שְׁתֵּי הַלֶּחֶם. שְׁתֵּי כִכָּרוֹת שֶׁל הַשַּׁבָּת. אוֹת י' הִיא כַּבֵּיצָה שֶׁל כָּל אֶחָד וְאֶחָד. וּמִיהוּ בַּעַל הַבַּיִת שֶׁבּוֹצֵעַ? זוֹ אוֹת ו'.</p>\n<p>בֵּין כָּךְ הִנֵּה זְקַן הַזְּקֵנִים הָיָה יוֹרֵד אֶצְלוֹ וְאָמַר, רוֹעֶה נֶאֱמָן, חֲזֹר בְּךְ, שֶׁהֲרֵי לֶחֶם הוּא אוֹת ו', שְׁתֵּי כִכָּרוֹת שֶׁלּוֹ, כְּמוֹ שֶׁאָמַרְתָּ הֵן אוֹתִיּוֹת ה' ה'. וַדַּאי אוֹת ו' הִיא כְּנֶגֶד יַעֲקֹב, ה' ה' כְּנֶגֶד לֵאָה וְרָחֵל. י' כַּבֵּיצָה לְכָל אֶחָד.</p>\n<p>אָמַר לוֹ, זָקֵן זָקֵן, וַהֲרֵי בְּכַמָּה מְקוֹמוֹת בֵּאֲרוּהוּ, שֶׁיַּעֲקֹב הוּא בַּעַל הַבַּיִת, וְיוֹסֵף אוֹרֵחַ, שֶׁמַּדְרֵגָתוֹ יְסוֹד חַי הָעוֹלָמִים, כּוֹלֵל ח\"י בִּרְכוֹת הַתְּפִלָּה, וּמִשּׁוּם זֶה אָמְרוּ עָלָיו, (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק. אָמַר לוֹ, כָּךְ הוּא, וְהַכֹּל אֱמֶת. כָּל סוֹד בִּמְקוֹמוֹ, מַה שֶּׁאֲנִי אָמַרְתִּי וּמַה שֶּׁאַתָּה אָמַרְתָּ. אֲבָל זֶה שֶׁבּוֹצֵעַ אֶת הַלֶּחֶם מִיהוּ?</p>\n<p>אָמַר לוֹ, זָקֵן, אַתָּה בִּדְמוּתוֹ, וְזֶה שֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, וְזֶה אָדָם שֶׁל הַמֶּרְכָּבָה הָעֶלְיוֹנָה שֶׁהַפָּנִים שֶׁלּוֹ יְהֹוָה. וּמִשּׁוּם זֶה ו' - לֶחֶם, שֶׁהֵן ה' ה'. וְשִׁעוּר שֶׁקָּבְעוּ כַּזַּיִת וְכַבֵּיצָה, הֲרֵי נִתְבָּאֵר כַּזַּיִת בְּאֵיזֶה שֵׁם מְשַׁעֲרִים, שֶׁהֲרֵי בֵּאֲרוּ חֲכָמִים שֶׁאֵין עוֹשִׂים מִצְווֹת חֲבִילוֹת, אַף כָּאן לֹא נוֹתְנִים שְׁנֵי שִׁעוּרִים בָּאוֹת י', לִהְיוֹת כַּזַּיִת וְכַבֵּיצָה. אֶלָּא שְׁתֵּי אַלְפָא בֵּיתוֹת הֵן, יֵשׁ י' עֶלְיוֹנָה, וְיֵשׁ י' קְטַנָּה. י' מִן יְהֹוָה - עֶלְיוֹנָה. י' מִן אֲדֹנָי - קְטַנָּה. וְאֵלּוּ הַשְּׁתַּיִם, אַחַת בְּכַזַּיִת וְאַחַת בְּכַבֵּיצָה, בְּסוֹד זֶה הַשִּׁלּוּב יְאֲהדוָנָהי. בָּא הַזָּקֵן וְנָשַׁק לוֹ.</p>\n<p>בֵּין כָּךְ קָם הַמְּנוֹרָה הַקְּדוֹשָׁה, פָּתַח וְאָמַר, וַדַּאי כָּעֵת מִתְחַבְּרִים (משלי ל) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ. שָׂמְחוּ הַחֲבֵרִים וְאָמְרוּ, אַשְׁרָיו מִי שֶׁזּוֹכֶה לֶאֱכֹל מֵהַלֶּחֶם הַזֶּה שֶׁנֶּאֱמַר בּוֹ (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי, וְאַשְׁרֵי הַנֶּפֶשׁ שֶׁנֶּאֱמַר בָּהּ (ויקרא כב) מִלֶּחֶם אָבִיהָ תֹּאכֵל. (שם) וְכָל זָר לֹא יֹאכַל בּוֹ. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ נֶאֱמַר, (מלאכי ב) הֲלֹא אָב אֶחָד לְכֻלָּנוּ. וְהַנֶּפֶשׁ שֶׁעוֹסֶקֶת בַּתּוֹרָה - מִלֶּחֶם אָבִיהָ תֹּאכֵל.</p>\n<p>וּמִי גָרַם לָהּ שֶׁאוֹכֶלֶת מִלֶּחֶם אָבִיהָ? מִשּׁוּם שֶׁחָזְרָה בִּתְשׁוּבָה וְנֶאֱחֶזֶת (ומתחדשת) כִּנְעוּרֶיהָ. זֶהוּ שֶׁכָּתוּב (ויקרא כב) וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ, כְּמוֹ (איוב לג) (ו) יָשׁוּב לִימֵי עֲלוּמָיו. כְּמוֹ הָאִילָן שֶׁקָּצְצוּ אוֹתוֹ וּמִתְחַדֵּשׁ בְּשָׁרָשָׁיו. וְזֶהוּ סוֹד שֶׁל מִי שֶׁמֵּת בְּלִי זֶרַע.</p>\n<p>וְעוֹד יֵשׁ סוֹד אַחֵר, שֶׁלְּבַסּוֹף יָבוֹא בְּגִלְגּוּל וְיִתְחַדֵּשׁ כְּמִזְּמַן קַדְמוֹן. וְזֶהוּ אַלְמָנָה וּגְרוּשָׁה, שֶׁהִתְגָּרְשָׁה מִגַּן עֵדֶן, וּמִשּׁוּם זֶה נִקְרֵאת גְּרוּשָׁה, כְּמוֹ (בראשית ג) וַיְגָרֶשׁ אֶת הָאָדָם. וּמַה גָּרַם לָהּ? מִשּׁוּם שֶׁזֶּרַע אֵין לָהּ, שֶׁמֵּת בְּלֹא בָנִים. וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ, שֶׁשָּׁבָה בָּעוֹלָם הַזֶּה בְּאוֹתוֹ נַעַר בֶּן הַיָּבָם, וְזֶהוּ וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ. וּלְבַסּוֹף שֶׁזָּכְתָה לְזֶרַע - מִלֶּחֶם אָבִיהָ תֹּאכֵל. וְכָל זָר לֹא יֹאכַל בּוֹ וְגוֹ'. (דברים כה) לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה - לְאִישׁ זָר.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, הִלֵּל וְשַׁמַּאי, שֶׁאַתֶּם אֶחָד מִצַּד הָרַחֲמִים וְאֶחָד מִצַּד הַדִּין, שֶׁהֵם חֶסֶד וּגְבוּרָה, מַדְרֵגוֹת שֶׁל אַבְרָהָם וְיִצְחָק. וְאַתֶּם מֵהַגֶּזַע שֶׁלָּהֶם, הֵאָסְפוּ לְכָאן אַתֶּם וּשְׁמוֹנִים תַּלְמִידִים שֶׁהָיוּ לוֹ לְהִלֵּל, וְאַף כָּךְ תַּלְמִידֵי בֵּית שַׁמַּאי, לִסְעוּדַת הַמֶּלֶךְ.</p>\n<p>הֲרֵי בֵּאַרְתֶּם, אַתֶּם וְהַחֲבֵרִים שֶׁעִמָּכֶם, בַּעֲלֵי הוֹרָאוֹת, שֶׁבֵּאַרְתֶּם אֵין הַבּוֹצֵעַ רַשַּׁאי לֶאֱכֹל עַד שֶׁיַּעֲנוּ אָמֵן בַּעֲלֵי הַסְּעוּדָה, וְאֵין בַּעֲלֵי הַסְּעוּדָה רַשָּׁאִים לֶאֱכֹל עַד שֶׁיֹּאכַל הַבּוֹצֵעַ. וַדַּאי כַּאֲשֶׁר בּוֹצֵעַ בַּעַל הַבַּיִת, וּבוֹצֵעַ לְאוֹתָם בַּעֲלֵי הַסְּעוּדָה, לֹא לְכֻלָּם מְשַׁעֵר שִׁעוּר אֶחָד, שֶׁאֵין דֶּרֶךְ אֵלּוּ הַבּוֹצְעִים לִבְצֹעַ בְּשָׁוֶה, שֶׁלִּפְעָמִים נוֹתֵן לָזֶה כַּבֵּיצָה, וְלָזֶה כַּזַּיִת. וְכַאֲשֶׁר עוֹנִים אָמֵן עַל בְּצִיעָה זוֹ, קֹדֶם שֶׁיֹּאכַל בַּעַל הַבַּיִת, מְחַבְּרִים שְׁנֵי שִׁעוּרִים כְּאֶחָד בְּכַזַּיִת וְכַבֵּיצָה, שִׁלּוּב יְאֲהדוָנָהי - אָמֵן זֶה אֵינוֹ עַל הָאֲכִילָה, אֶלָּא עַל הַבְּצִיעָה. לְאַחַר שֶׁאֵלּוּ הַשִּׁעוּרִים מִצְטָרְפִים בְּאָמֵן, יֹאכַל בַּעַל הַבַּיִת. וְזֶהוּ (שיר השירים ה) אָרִיתִי מוֹרִי עִם בְּשָׂמִי אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי. וְאַחַר כָּךְ - אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דוֹדִים. אִכְלוּ רֵעִים - בַּעֲלֵי הַסְּעוּדָה. שֶׁיִּהְיוּ הַבָּנִים בִּדְמוּת אֲבוֹתָם.</p>\n<p>הֲרֵי כָּאן לֶחֶם בִּשְׁתֵּי כִכָּרוֹת, וְשִׁעוּרוֹ - כַּזַּיִת וְכַבֵּיצָה. מַהוּ לֶחֶם הַפָּנִים שֶׁל שֻׁלְחַן הַמֶּלֶךְ? אֶלָּא זֶה פֵּרְשׁוּהוּ, שֶׁיֵּשׁ לוֹ שְׁתֵּים עֶשְׂרֵה פָּנִים. וּמָהֶן? אֶלָּא הֵן אַרְבַּע פָּנִים שֶׁל אַרְיֵה, אַרְבַּע פְּנֵי שׁוֹר, אַרְבַּע פְּנֵי נֶשֶׁר. וְהֵם (במדבר ו) יְבָרֶכְךְ יְהֹוָה. יָאֵר יְהֹוָה. יִשָּׂא יְהֹוָה.</p>"],[9522012534,"<p>וּמִנַּיִן לָנוּ שֶׁלֶּחֶם הַפָּנִים הוּא מִשֻּׁלְחַן הַמֶּלֶךְ? שֶׁכָּתוּב (יחזקאלמא) וַיְדַבֵּר אֵלַי זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְהֹוָה. זֶ\"ה - גִּימַטְרִיָּא שְׁתֵּים עֶשְׂרֵה פָּנִים. וְאַף כָּךְ, מִי שֶׁיֵּשׁ לוֹ, צָרִיךְ לְתַקֵּן וּלְסַדֵּר עַל שֻׁלְחָן אַרְבַּע כִּכָּרוֹת בְּכָל סְעוּדָה שֶׁל שַׁבָּת, לְשָׁלֹשׁ סְעוּדוֹת - שְׁתֵּים עֶשְׂרֵה פָּנִים.</p>\n<p>וְאִם תֹּאמַר שֶׁאֵינָם אֶלָּא שֵׁשׁ מֵהַתּוֹרָה, מִשּׁוּם לֶחֶם מִשְׁנֶה - אֶלָּא לֹא נוּכַל לְהַזְכִּיר שֵׁשׁ בְּלִי חֲבֵרוֹ. ו' ו', שֵׁשׁ מִלְמַעְלָה לְמַטָּה, וְשֵׁשׁ מִלְּמַטָּה לְמַעְלָה, כְּנֶגֶד שֵׁשׁ מַדְרֵגוֹת שֶׁל הַכִּסֵּא הָעֶלְיוֹן וְשֵׁשׁ מַדְרֵגוֹת שֶׁל הַכִּסֵּא הַתַּחְתּוֹן. שֵׁשׁ בְּהֶסְתֵּר, וְשֵׁשׁ בְּגִלּוּי. (דברים כט) הַנִּסְתָּרֹת לַיהֹוָה אֱלֹהֵינוּ וְהַנִּגְלֹת לָנוּ וּלְבָנֵינוּ עַד עוֹלָם.</p>"],[9522012535,"<p>וְלַחְמֵי תוֹדָה הֵם אַרְבָּעִים חַלּוֹת. עֲשָׂרָה רְקִיקִין, עֲשָׂרָה רְבוּכִין, עֲשָׂרָה שֶׁל חָמֵץ, עֲשָׂרָה שֶׁל מַצָּה. הֲרֵי הֵם אַרְבָּעִים. כְּנֶגֶד אוֹת י' מִן יְהֹוָ\"ה, ד' פְּנֵי אָדָם. י' מִן יְהֹוָ\"ה, ד' פְּנֵי אַרְיֵה. י' מִן יְהֹוָ\"ה, ד' פְּנֵי שׁוֹר. י' מִן יְהֹוָ\"ה, ד' פְּנֵי נֶשֶׁר. זֶהוּ תִּקּוּן רִאשׁוֹן שֶׁל שֻׁלְחַן הַמֶּלֶךְ, שֶׁהֵם עֲשָׂרָה דְבָרִים שֶׁצָּרִיךְ אָדָם לְהַנְהִיג בְּשֻׁלְחַן הַשַּׁבָּת.</p>\n<p>אֶחָד - לְתַקֵּן שֻׁלְחָן כְּמִי שֶׁאוֹכֵל לִפְנֵי הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְהֹוָ\"ה. שֵׁנִי - נְטִילַת יָדַיִם עַד שִׁעוּר שֶׁגָּזְרוּ חֲכָמִים, שֶׁהֵם חֲמִשָּׁה קְשָׁרִים שֶׁבָּהֶם אַרְבָּעָה עָשָׂר פְּרָקִים. וְאַף כָּךְ אַרְבָּעָה עָשָׂר פְּרָקִים הֵם שֶׁל יַד שְׂמֹאל. וְהֵם שְׁמוֹנָה וְעֶשְׂרִים פְּרָקִים. כְּנֶגְדָּם נֶאֱמַר כֹּ\"חַ יְהֹוָ\"ה, שֶׁהֵם שְׁמוֹנֶה וְעֶשְׂרִים אוֹתִיּוֹת שֶׁל פָּסוּק רִאשׁוֹן שֶׁל מַעֲשֵׂה בְרֵאשִׁית, שֶׁנֶּאֱמַר בָּהֶם (במדבר יד) וְעַתָּה יִגְדַּל נָא כֹּחַ יְהֹוָה.</p>\n<p>וְעָשֶׂר אֶצְבָּעוֹת רוֹמְזוֹת לַעֲשָׂרָה מַאֲמָרוֹת שֶׁל מַעֲשֵׂה בְרֵאשִׁית. וּמִשּׁוּם זֶה בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, מִי שֶׁמְּזַלְזֵל בִּנְטִילַת יָדַיִם, נֶעֱקָר מִן הָעוֹלָם. מַדּוּעַ? מִשּׁוּם שֶׁיֵּשׁ בָּהֶם סוֹד שֶׁל עֲשָׂרָה מַאֲמָרוֹת וּשְׁמוֹנֶה וְעֶשְׂרִים אוֹתִיּוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם.</p>\n<p>שְׁלִישִׁי - כּוֹס שֶׁל בְּרָכָה שֶׁתִּקְּנוּ בוֹ עֲשָׂרָה דְבָרִים: הֲדָחָה וּשְׁטִיפָה. עִטּוּר. עִטּוּף. חַי. מָלֵא. מְקַבְּלוֹ בִּשְׁתֵּי יָדָיו. וְנוֹתְנוֹ בַּיָּמִין. וְנוֹתֵן עֵינָיו בּוֹ. וּמַגְבִּיהוֹ מִן הַקַּרְקַע טֶפַח. וּמְשַׁגְּרוֹ בְּמַתָּנָה לְאַנְשֵׁי בֵיתוֹ.</p>\n<p>וּבְדֶרֶךָ סוֹד, כּוֹס (דברים לג) מָלֵא בִּרְכַּת ה'. כּוֹס בְּגִימַטְרִיָּא אֱלֹהִי\"ם, וּמִשָּׁם הַנְּשָׁמָה, שֶׁהִיא עַל שְׁמוֹ - כּוֹס. זֶהוּ שֶׁכָּתוּב (תהלים קטז) כּוֹס יְשׁוּעוֹת אֶשָּׂא. מִי נִקְרָא יְשׁוּעוֹת? חָמֵשׁ אֶצְבָּעוֹת, שֶׁהֵן כְּנֶגֶד חָמֵשׁ סְפִירוֹת שֶׁל כּוֹס, שֶׁהוּא שֵׁם אֱלֹהִים חַיִּים שֶׁהַבִּינָה מִתְפַּשֶּׁטֶת בָּהֶם לַחֲמִשִּׁים שְׁעָרִים. ה' פְּעָמִים עֶשֶׂר, בְּאוֹת י', שֶׁהוּא עֲשָׂרָה דְבָרִים שֶׁתִּקְּנוּ חֲכָמִים בְּכוֹס, שֶׁהוּא אֱלֹהִים חַיִּים, חָמֵשׁ אוֹתִיּוֹת בְּחֶשְׁבּוֹן ה'.</p>\n<p>וּבֵאֲרוּ, בְּכוֹס שֶׁצָּרִיךְ הֲדָחָה וּשְׁטִיפָה. הֲדָחָה מִבַּחוּץ, וּשְׁטִיפָה מִבִּפְנִים. וְסוֹד הַדָּבָר - שֶׁיְּהֵא תּוֹכוֹ כְּבָרוֹ. מִי שֶׁזָּכָה לַנְּשָׁמָה מִכּוֹס זֶה, לִהְיוֹת נְשָׁמָה טְהוֹרָה מִבִּפְנִים וּמִבַּחוּץ. וְסוֹד הַדָּבָר - (ויקרא טז) וְטִהֲרוֹ וְקִדְּשׁוֹ. טָהֳרָה מִבִּפְנִים, וּקְדֻשָּׁה מִבַּחוּץ. וּמַה כּוֹס אֵין טָהֳרָתוֹ וּקְדֻשָּׁתוֹ מִבִּפְנִים וּמִבַּחוּץ בְּלִי מַיִם - אַף כָּךְ הַנְּשָׁמָה אֵין טָהֳרָתָהּ וּקְדֻשָּׁתָהּ מִבִּפְנִים וּמִבַּחוּץ בְּלִי תוֹרָה. וּמִשּׁוּם זֶה אָמַר רַבָּן גַּמְלִיאֵל, מִי שֶׁאֵין תּוֹכוֹ כְּבָרוֹ לֹא יִכָּנֵס לְבֵית הַמִּדְרָשׁ. בִּגְלַל שֶׁאֵין הוּא מִצַּד עֵץ הַחַיִּים, אֶלָּא מֵעֵץ הַדַּעַת טוֹב וָרָע.</p>\n<p>עַטוּר - פֵּרְשׁוּהוּ מְעַטְּרוֹ בְּתַלְמִידִים. וְדֶרֶךְ סוֹד - ה' הִיא כּוֹס, מְעַטְּרוֹ בְּתַלְמִידִים בְּאוֹת י', שֶׁהִיא עֲטָרָה עַל ה'. עִטּוּף - צָרִיךְ לַעֲטֹף רֹאשׁוֹ בִּגְלַל שֶׁהַשְּׁכִינָה עַל רֹאשׁוֹ. שֶׁכָּךְ פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, אָסוּר לְתַלְמִיד חָכָם לְהַלֵּךְ ד' אַמּוֹת בְּגִלּוּי הָרֹאשׁ, מִשּׁוּם (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. כָּל שֶׁכֵּן בִּבְרָכָה וּבְהַזְכָּרַת שֵׁם הַקָּדוֹשׁ שֶׁאָסוּר לִהְיוֹת בְּגִלּוּי הָרֹאשׁ.</p>\n<p>שֶׁאוֹת י' מִן יְהֹוָ\"ה הִיא שֶׁהִתְעַטְּפָה בָּאוֹר, וְנֶעֶשְׂתָה אֲוִיר. (וזהו אויר של ארץ ישראל מחכים) מִשּׁוּם שֶׁאוֹת י', שֶׁהִיא חָכְמָה, בָּאֲוִיר, וְזֶהוּ אוֹר שֶׁהִתְעַטֵּף בּוֹ כְּשֶׁבָּרָא אֶת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים קד) עֹטֶה אוֹר כַּשַּׂלְמָה. וְזֶהוּ (בראשית א) יְהִי אוֹר - יְהִי אֲוִיר. וּפֵרְשׁוּהוּ בַּעֲלֵי סוֹדוֹת הַתּוֹרָה, בְּטֶרֶם שֶׁנִּתְהַוָּה כָּל דָּבָר, נִתְהַוּוּ הַהֲוָיוֹת. וּמִשּׁוּם זֶה נֶאֱמַר יְהִי אוֹר וַיְהִי אוֹר, שֶׁהָיָה מִזְּמַן קַדְמוֹן.</p>\n<p>חַי - פֵּרְשׁוּהוּ חַי מִן הֶחָבִית. וְדֶרֶךְ סוֹד - שְׁכִינָה עֶלְיוֹנָה הִיא שְׁמִינִית לַסְּפִירוֹת מִמַּטָּה לְמַעְלָה, וּמִשּׁוּם זֶה נִקְרֵאת אוֹת ח', וְנֶאֱמַר בָּהּ (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת. וְזֶהוּ חָבִית: ח' בַּיִ\"ת. וּמִשּׁוּם שֶׁהִיא חַיִּים, שֶׁכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, הַיַּיִן מִשָּׁם הוּא חַי. וְזֶהוּ יֵינָהּ שֶׁל תּוֹרָה. מִי שֶׁמִּשְׁתַּדֵּל בָּהּ נִקְרָא חַי. וְעוֹד, צַדִּיק חַי, שֶׁהוּא חַי מִן הֶחָבִית. יַיִן יֵשׁ מִמֶּנּוּ שְׁנֵי גְוָנִים - לָבָן</p>\n<p>וְאָדם. יַיִן גִּימַטְרִיָּא שִׁבְעִים פָּנִים. הֲרֵי ע\"ב. וּכְנֶגֶד שְׁנֵי גְוָנִים שֶׁל הַיַּיִן, הוּא זָכוֹר וְשָׁמוֹר שֶׁל שַׁבָּת, וְשִׁבְעִים תֵּבוֹת שֶׁל קִדּוּשׁ וַיְכֻלּ\"וּ - הֲרֵי ע\"ב.</p>\n<p>מָלֵא - זֶהוּ שֶׁכָּתוּב כּוֹס (דברים לג) מָלֵא בִּרְכַּת ה'. וְאַף שֶׁהוּא מָלֵא מִיֵּינָהּ שֶׁל תּוֹרָה. אָדָם כָּךְ צָרִיךְ לִהְיוֹת שָׁלֵם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כה) אִישׁ תָּם - גֶּבֶר שָׁלֵם, כְּמוֹ (שם לג) וַיָּבֹא יַעֲקֹב שָׁלֵם. כָּךְ צָרִיךְ לִהְיוֹת נְשָׁמָה שְׁלֵמָה, וְלֹא יִהְיֶה בָּהּ פְּגָם, שֶׁנֶּאֱמַר (ויקרא כא) שֶׁכָּל (איש) אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. אַף כָּךְ אוֹתִיּוֹת אִלֵּם עִם יָ\"הּ - הוּא אֱלֹהִים, כְּחֶשְׁבּוֹן כּוֹס. (שם י\"ה) הוּא מָלֵא, וַהֲפֹךְ אוֹתִיּוֹת אִלֵּם וְתִמְצָא מָלֵא. מָתַי? כַּאֲשֶׁר יֵשׁ שָׁם אוֹתִיּוֹת יָ\"הּ. וְהַיְנוּ (שמות יז) כִּי יָד עַל כֵּס יָ\"הּ. אֲדנָ\"י חֶשְׁבּוֹנוֹ ו\"ה. הָעַמּוּד הָאֶמְצָעִי מָלֵא מִשְּׁנֵיהֶם, וּמִשּׁוּם זֶה שׁוֹרֶה עָלָיו אָדָם, שֶׁהוּא שֵׁם מְפֹרָשׁ.</p>\n<p>מְקַבְּלוֹ בִּשְׁתֵּי יָדָיו - כְּמוֹ הַתּוֹרָה שֶׁהָיְתָה בִּשְׁנֵי לוּחוֹת, חֲמִשָּׁה דִּבְּרוֹת בְּלוּחַ אֶחָד כְּנֶגֶד חָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד יָמִין, וַחֲמִשָּׁה בְּלוּחַ שֵׁנִי כְּנֶגֶד חָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד שְׂמֹאל. וְנִתְּנוּ בְיָמִין, כְּלוֹמַר בְּיַד יָמִין. וּמִשּׁוּם זֶה, שְׁנֵי לוּחוֹת אֲבָנִים בְּיָדוֹ, וְלֹא בְיָדָיו. וְזֶהוּ שֶׁמֵּעִיד הַפָּסוּק, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ.</p>\n<p>וְנוֹתֵן עֵינָיו בּוֹ - מִשּׁוּם שֶׁכּוֹס זֶה הוּא כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל, שֶׁנֶּאֱמַר בָּהּ (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךְ בָּהּ. וְעֵינַיִם שֶׁל מַעְלָה הֵם שִׁבְעִים סַנְהֶדְרִין, וַעֲלֵיהֶם מֹשֶׁה וְאַהֲרֹן. שְׁתֵּי עֵינַיִם עֶלְיוֹנוֹת. אַחַת עֵין יָמִין, וְאַחַת עֵין שְׂמֹאל. וְהֵם ע\"ב, כְּמִנְיַן \"בַּיַּיִן\". וְזֶהוּ סוֹד שֶׁל נוֹתֵן בַּכּוֹס עֵינוֹ.</p>\n<p>וּמַגְבִּיהוֹ מִן הַקַּרְקַע טֶפַח - מִשּׁוּם שֶׁאוֹת ה' הִיא כּוֹס, צָרִיךְ לְהַעֲלוֹת אוֹתָהּ בָּאוֹת י', שֶׁהִיא טֶפַח, שֶׁבּוֹ נִפְתַּחַת אוֹת ה' בְּחָמֵשׁ אֶצְבָּעוֹת. וּמְשַׁגְּרוֹ לְאַנְשֵׁי בֵיתוֹ בְּמַתָּנָה - מִשּׁוּם שֶׁתִּתְבָּרֵךְ אִשְׁתּוֹ, שֶׁהִיא נֶפֶשׁ, שֶׁנֶּאֱמַר בָּהּ (במדבר יא) נַפְשֵׁנוּ יְבֵשָׁה אֵין כֹּל. וּמִתְבָּרֶכֶת וְעוֹשָׂה פֵּרוֹת. זֶהוּ שֶׁכָּתוּב (בראשית א) תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא.</p>\n<p>רְבִיעִי - לִהְיוֹת עַל הַשֻּׁלְחָן דִּבְרֵי תוֹרָה, שֶׁלֹּא יִתְקַיֵּם בּוֹ כְּדֻגְמַת עַמֵּי הָאָרֶץ שֶׁנֶּאֱמַר עֲלֵיהֶם (ישעיה כח) כִּי כָּל שֻׁלְחָנוֹת מָלְאוּ קִיא צֹאָה. אֲבָל בְּסוֹדוֹת הַתּוֹרָה פֵּרְשׁוּהוּ, הָרוֹצֶה לְהַעֲשִׁיר - יַצְפִּין, יִתֵּן שֻׁלְחָן לַצָּפוֹן. הֲרֵי שֻׁלְחָן לִשְׂמֹאל, שֶׁהוּא דִּין, צָרִיךְ לִקְשֹׁר בּוֹ הַיָּמִין, שֶׁהוּא הַתּוֹרָה, שֶׁנִּתְּנָה מֵחֶסֶד, שֶׁהוּא רַחֲמִים, יְמִין ה'.</p>\n<p>חֲמִישִׁי - פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁצָּרִיךְ לְהַאֲרִיךְ עַל הַשֻּׁלְחָן בִּגְלַל עֲנִיִּים. וְסוֹד הַדָּבָר - בִּגְלַל הַצְּדָקָה יַאֲרִיךְ יָמָיו, שֶׁלֹּא יִתְקַצְּרוּ. כְּמוֹ הַתּוֹרָה שֶׁהִיא אֲרִיכוּת יָמִים בִּשְׁנֵי עוֹלָמוֹת, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא לַנְּשָׁמוֹת - אַף כָּךְ הַצְּדָקָה הִיא אֲרִיכוּת יָמִים לַגּוּף בִּשְׁנֵי עוֹלָמוֹת. זֶהוּ שֶׁכָּתוּב (דברים ל) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ. כִּי הוּא חַיֶּיךְ - בָּעוֹלָם הַזֶּה. וְאֹרֶךְ יָמֶיךְ - בָּעוֹלָם הַבָּא. שֶׁעוֹלָם הַבָּא לַגּוּף לִתְחִיַּת הַמֵּתִים, שֶׁאַחַר שֶׁיָּקוּם לֹא יָמוּת. וּכְמוֹ שֶׁהָעוֹלָם הַבָּא יִהְיֶה עוֹמֵד, כָּךְ הָעוֹלָם הַזֶּה יִהְיֶה עוֹמֵד.</p>\n<p>שִׁשִּׁי - שֶׁלֹּא יְהֵא גַרְגְּרָן וּבַלְעָן עַל שֻׁלְחָנוֹ שֶׁל הַמֶּלֶךְ, כְּמוֹ עֵשָׂו שֶׁאָמַר (בראשית כה) הַלְעִיטֵנִי, דֶּרֶךְ הַלְעָטָה, אֶלָּא דֶּרֶךְ טְחִינָה. אַף כָּךְ מִי שֶׁמּוֹצִיא דִבּוּרִים שֶׁל תְּפִלָּה אוֹ תּוֹרָה מִפִּיו, צָרִיךְ לְהוֹצִיא אוֹתָם בְּדֶרֶךְ טְחִינָה - שְׁלֵמִים, וְלֹא בְּהַלְעָטָה - חֲסֵרִים. וְלֹא עוֹד, אֶלָּא בִּגְלַל סַכָּנָה שֶׁמָּא יַקְדִּים קָנֶה לְוֵשֶׁט.</p>\n<p>שְׁבִיעִי - מַיִם אַחֲרוֹנִים. וּפֵרְשׁוּהוּ, מַיִם רִאשׁוֹנִים מִצְוָה, וְאַחֲרוֹנִים חוֹבָה, וְאֶמְצָעִיִּים רְשׁוּת. מַיִם רִאשׁוֹנִים צָרִיךְ לְהַגְבִּיהַּ הָאֶצְבָּעוֹת כְּדֵי שֶׁלֹּא יַחְזְרוּ מַשְׁקִים וִיטַמְּאוּ אֶת הַיָּדַיִם. וְיֵשׁ מֵהַחֲכָמִים שֶׁאָמְרוּ, שֶׁאַחֲרוֹנִים מִשּׁוּם מֶלַח סְדוֹמִית, שֶׁלֹּא יְסַמֵּא אֶת הָעֵינַיִם. אֲפִלּוּ כָּךְ הוֹצִיא אוֹתָם מֵחוֹבָה. וְסוֹתְרִים הַדְּבָרִים אֶת אֵלּוּ שֶׁאָמְרוּ עֲלֵיהֶם חוֹבָה, וְאֵין דֶּרֶךְ אֶרֶץ לִסְתֹּר דִּבְרֵי הַגְּאוֹנִים, (מאלו שאמרו עליהם) אֶלָּא שֶׁנֶּאֱמַר עֲלֵיהֶם, (דברים יז) עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךְ.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁאָמְרוּ עֲלֵיהֶם שָׁלֹשׁ קְדֻשּׁוֹת. זֶהוּ שֶׁכָּתוּב (ויקרא יא) והתקדשתם והייתם קדשים. והתקדשתם - אלו מים ראשונים. והייתם קדשים - אלו מים אחרונים. כי קדוש - זה שמן ערב. אני ה' - זו ברכה. ואמצעיים, בין גבינה לבשר, ומשום זה והתקדשתם והייתם קְדשִׁים כִּי קָדוֹשׁ אֲנִי ה'. אַשְׁרֵי הָעָם שֶׁאֲדוֹנָם יָשִׂים אוֹתָם אֶצְלוֹ.</p>\n<p>אַף כָּךְ וְהִתְקַדִּשְׁתֶּם - בִּשְׁעַת תַּשְׁמִישׁ. מַיִם רִאשׁוֹנִים שֶׁזּוֹרֵעַ אָדָם - מִצְוָה. אַחֲרוֹנִים, שֶׁל הַנְּקֵבָה - חוֹבָה. וְאֶמְצָעִיִּים - הֲרֵי רוֹמֵז, וְכַגְּבִינָה תַּקְפִּיאֵנִי. זֶהוּ שֶׁכָּתוּב (איוב י) הֲלֹא כֶחָלָב תַּתִּיכֵנִי וְכַגְּבִינָה תַּקְפִּיאֵנִי. וְזֶהוּ שֶׁבָּא הָרֶמֶז בֵּין גְּבִינָה לְבָשָׂר, שֶׁנֶּאֱמַר בּוֹ (איוב י) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי.</p>\n<p>שְׁמִינִי - לִשְׁלֹשָׁה צָרִיךְ כּוֹס. מַדּוּעַ? בִּינָה הִיא הַשְּׁלִישִׁית מֵעֶשֶׂר סְפִירוֹת, מִמַּעְלָה לְמַטָּה. וּמִשּׁוּם זֶה פָּחוֹת מִשְּׁלֹשָׁה לֹא צָרִיךְ כּוֹס (ד\"א). לִשְׁלֹשָׁה צָרִיךְ כּוֹס. וּבָא בְרֶמֶז - קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. וְלֹא עוֹד, אֶלָּא שֶׁהַתּוֹרָה לֹא יוֹרֶדֶת פָּחוֹת מִשְּׁלֹשָׁה - כֹּהֲנִים, לְוִיִּם, יִשְׂרְאֵלִים. תּוֹרָה, נְבִיאִים, וּכְתוּבִים. בַּחֹדֶשׁ הַשְּׁלִישִׁי, בַּיּוֹם הַשְּׁלִישִׁי. וְזוֹ בִּינָה, יְה\"וּ. וּבִגְלָלָהּ נֶאֱמַר, שָׁלֹשׁ מִשְׁמָרוֹת הָוֵ\"י הַלַּיְלָה. מַלְכוּת, אוֹת ה' רְבִיעִית, עָלֶיהָ נֶאֱמַר, אַרְבַּע מִשְׁמָרוֹת הָוֵי הַלַּיְלָה. וְאוֹת ש' שֶׁל שְׁלֹשָׁה עֲנָפִים כְּנֶגֶד שָׁלֹשׁ מִשְׁמָרוֹת. וְאוֹת שֶׁל אַרְבַּע פָּנִים כְּנֶגֶד אַרְבַּע מִשְׁמָרוֹת.</p>\n<p>תְּשִׁיעִי - כּוֹס שֶׁל בְּרָכָה, רְבִיעִית הַלֹּג. וְשִׁעוּר שֶׁלּוֹ לְעֻמַּת אוֹת ה', רְבִיעִית שֶׁל שֵׁם יְהֹוָ\"ה. עֲשִׂירִי - בַּעֲשָׂרָה אוֹמֵר נְבָרֵךְ לֵאלֹהֵינוּ. וּשְׁכִינָה תַּחְתּוֹנָה הִיא רְבִיעִית וַעֲשִׂירִית. רְבִיעִית לְשֵׁם יְהֹוָה. עֲשִׂירִית לְעֶשֶׂר סְפִירוֹת, שֶׁהֵן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְכַמָּה צָרִיךְ אָדָם לִשְׁמֹר עַצְמוֹ שֶׁלֹּא לִזְרֹק דְּבָרִים אֵלּוּ בְּמָקוֹם שֶׁלֹּא צָרִיךְ כְּמוֹ מִי שֶׁזּוֹרֵק לֶחֶם. כָּל שֶׁכֵּן מִי שֶׁזּוֹרֵק לֶחֶם שֶׁל הַתּוֹרָה הַחוּצָה מִשֻּׁלְחָנוֹ, שֶׁהִיא הַשְּׁכִינָה, שֶׁנֶּאֱמַר בָּהּ (יחזקאל מא) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה'. (ע\"כ רעיא מהימנא).</p>"],[9522012536,"<p>וּבַחִבּוּר הַקַּדְמוֹן, שְׁלֹשָׁה הֵם שֶׁגּוֹרְמִים רָעָה לְעַצְמָם - שְׁנַיִם בָּעוֹלָם הַזֶּה, וְאֶחָד בְּעוֹלָם אַחֵר. וְאֵלּוּ הֵם: מִי שֶׁמְּקַלֵּל עַצְמוֹ, שֶׁלָּמַדְנוּ, מְמֻנֶּה אֶחָד מֻפְקָד לִפְנֵי הָאָדָם, וּבְשָׁעָה שֶׁמְּקַלֵּל עַצְמוֹ אוֹתוֹ הָאָדָם, מְמֻנֶּה זֶה, וְשִׁבְעִים אֲחֵרִים שֶׁמְּמֻנִּים תַּחְתָּיו, נוֹטְלִים אוֹתוֹ דִּבּוּר וְאוֹמְרִים אָמֵן, וּמַעֲלִים אוֹתָהּ לְמַעְלָה וְדָנִים אוֹתָהּ, וְהוּא רוֹדֵף אַחֲרָיו עַד שֶׁעוֹשֶׂה אוֹתוֹ וּמְשַׁלֵּם לוֹ אוֹתוֹ דִּבּוּר.</p>\n<p>מִי לָנוּ גָּדוֹל מִמֹּשֶׁה, שֶׁאָמַר (שמות לב) וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ, וְאָמַר לְצֹרֶךְ, וְאַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה רְצוֹנוֹ, עִם כָּל זֶה לֹא נִצּוֹל מֵעֹנֶשׁ, וַהֲרֵי נִתְבָּאֵר שֶׁלֹּא נִזְכַּר בְּפָרָשַׁת וְאַתָּה תְּצַוֶּה, וְנִמְחָה מִשָּׁם. וַהֲרֵי פֵּרְשׁוּהוּ. מִי לָנוּ גָּדוֹל מִדָּוִד הַמֶּלֶךְ שֶׁאָמַר (תהלים לט) אָמַרְתִּי אֶשְׁמְרָה דְרָכַי מֵחֲטוֹא בִלְשׁוֹנִי אֶשְׁמְרָה לְפִי מַחְסוֹם בְּעוֹד רָשָׁע לְנֶגְדִּי. מַהוּ בְּעוֹד רָשָׁע לְנֶגְדִּי? הַמְמֻנֶּה הַהוּא הַמֻּפְקָד עַל זֶה, וְלוֹקֵחַ הַדִּבּוּר הַהוּא לְקַלְקֵל לוֹ לָאָדָם.</p>\n<p>וְאֶחָד מִי שֶׁזּוֹרֵק לֶחֶם אוֹ פֵּרוּרִים שֶׁל לֶחֶם בַּקַּרְקַּע וְעוֹשֶׂה בּוֹ זִלְזוּל, כְּמוֹ שֶׁנִּתְבָּאֵר. אֵלּוּ הַשְּׁנַיִם בָּעוֹלָם הַזֶּה. וְאֶחָד בָּעוֹלָם הַהוּא - מִי שֶׁמַּדְלִיק נֵר בְּמוֹצָאֵי שַׁבָּת טֶרֶם מַגִּיעִים יִשְׂרָאֵל לִקְדֻשָּׁא דְסִדְרָא, מִשּׁוּם שֶׁמְּחַלֵּל שַׁבָּת, וְגוֹרֵם לָאֵשׁ שֶׁל הַגֵּיהִנָּם לִדְלֹק טֶרֶם הִגִּיעַ זְמַנּוֹ.</p>\n<p>מָקוֹם אֶחָד יֵשׁ בַּגֵּיהִנָּם לְאוֹתָם שֶׁמְּחַלְּלִים שַׁבָּת. כֵּיוָן שֶׁהוּא הִדְלִיק נֵר טֶרֶם הִגִּיעַ זְמַנּוֹ, יֵשׁ מְמֻנֶּה אֶחָד בַּגֵּיהִנָּם בְּמוֹצָאֵי שַׁבָּת, וּמַבְעִיר בָּרִאשׁוֹנָה לְאוֹתוֹ מָקוֹם וְאוֹמֵר: זֶה מָקוֹם שֶׁל פְּלוֹנִי. וְכָל חַיָּבֵי הַגֵּיהִנָּם מְסַיְּעִים לְהַבְעִיר אֶת אוֹתוֹ מָקוֹם. אוֹתוֹ מְמֻנֶּה קוֹרֵא וְאוֹמֵר: (ישעיה כב) הִנֵּה ה' מְטַלְטֶלְךְ טַלְטֵלָה גָּבֶר וְעֹטְךְ עָטֹה. חַיָּבֵי הַגֵּיהִנָּם אוֹמְרִים: (שם) כַּדּוּר אֶל אֶרֶץ רַחֲבַת יָדָיִם שָׁמָּה תָמוּת וְגוֹ'. מִשּׁוּם שֶׁהוּא גָּרַם לָהֶם לְהִשָּׂרֵף טֶרֶם הִגִּיעַ זְמַנָּם. הֲרֵי לָנוּ שְׁלֹשָׁה שֶׁגּוֹרְמִים רַע לְעַצְמָם, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522012537,"<p>דָּבָר אַחֵר (בראשית כח) וַיַּחֲלֹם וְהִנֵּה סֻלָּם, רוֹעֶה נֶאֱמָן, מָה ל' עוֹלָה עַל כָּל הָאוֹתִיּוֹת, כָּךְ אַתָּה עָתִיד לְהִתְעַלּוֹת עַל כָּל הַבְּרִיּוֹת, מִשּׁוּם שֶׁעָלָה לַשֵּׁם שֶׁל יוֹ\"ד הֵ\"י וָא\"ו הֵ\"י, שֶׁבּוֹ שָׁלֹשׁ י' י' י', שֶׁחֶשְׁבּוֹנָן שְׁלֹשִׁים. שֶׁבַּהַתְחָלָה הָיִיתָ בְּשֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁהוּא יאאא, בְּי\"ג מִדּוֹת שֶׁל רַחֲמִים שֶׁהֵן גִּימַטְרִיָּא אֶחָד. כָּעֵת תִּתְעַלֶּה בְּאֵל, שֶׁהוּא אוֹתִיּוֹת ייא\"י. שֶׁשְּׁנֵי שֵׁמוֹת הֵם עֵדִים הֲלֹא אֵל אֶחָד בְּרָאָנוּ. זֶהוּ שֶׁכָּתוּב (מלאכי ב) הֲלֹא אָב אֶחָד לְכֻלָּנוּ הֲלֹא אֵל אֶחָד בְּרָאָנוּ.</p>\n<p>וּבְשָׁלֹש יוֹדִין אֵלּוּ יִתְקַיֵּם בְּךְ, (ישעיה נב) יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד בְּשֵׁם מ\"ה. שֶׁכָּךְ עוֹלֶה מְאֹ\"ד לְחֶשְׁבּוֹן אָדָ\"ם. וּבְהִפּוּךְ אוֹתִיּוֹת - מְאֹד הוּא אָדָם. יָרוּם - בְּאַרְבַּע פָּנִים שֶׁל אַרְיֵה, שֶׁהֵם (במדבר ו) יְבָרֶכְךְ יְהֹוָ\"ה. וְנִשָּׂא - בְּאַרְבַּע פְּנֵי שׁוֹר, שֶׁהֵם יִשָּׂא יְהֹוָ\"ה, בִּשְׂמֹאל. וְגָבַהּ מְאֹד - יָאֵר יְהֹוָ\"ה, בְּאֶמְצָעִיתוֹ. וְזֶה שֵׁם יוֹד הֵי וָאו הֵי, יִשָּׂא יְהֹוָ\"ה פָּנָיו אֵלֶיךְ וְיָשֵׂם לְךְ שָׁלוֹם. רְבִיעִי - יְהֹוָ\"ה, וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרֲכֵם.</p>"],[9522012538,"<p>מִצַד הַיָּמִין נִקְרֵאת אֶבֶן. וְכַמָּה אֲבָנִים לַחוֹת יְקָרוֹת נִמְצְאוּ מִמֶּנָּה, שֶׁמִּמֶּנָּה מֵי הַתּוֹרָה יוֹצְאִים. וּבִגְלָלָם נֶאֱמַר, אָמַר רַבִּי עֲקִיבָא לְתַלְמִידָיו: כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר אַל תֹּאמְרוּ מַיִם מַיִם, שֶׁמָּא תִסְתַּכְּנוּ בְנַפְשְׁכֶם. אַל תֹּאמְרוּ שֶׁהֵם מַיִם, מַיִם מַמָּשׁ, מִשּׁוּם (תהלים קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. שֶׁאֵלּוּ הַמַּיִם זוֹ הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (משלי ו) וְתוֹרָה אוֹר. וּמִשּׁוּם שֶׁזֶּה הָאוֹר נוֹבֵעַ בִּמְקוֹר הַמַּיִם (ישעיה נח) אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו, נִקְרָא מַיִם.</p>\n<p>וּמִצַד הַשְּׂמֹאל, זוֹ הָאֶבֶן שֶׁהִיא אוֹת י' - נִקְרֵאת גַּחֶלֶת. וּמִשָּׁם עֶשֶׂר סְפִירוֹת, כְּשַׁלְהֶבֶת קְשׁוּרָה בְּגַחֶלֶת. וְיֵשׁ לָהּ אַרְבָּעָה גְוָנִים, (ועשרה) וְהֵם: יוֹד הֵא וָאו הֵא. יְהֹוָ\"ה. וְהִיא יָד הַגְּדוֹלָה בְּיָמִין, יָד הַחֲזָקָה בִּשְׂמֹאל, הָעַמּוּד הָאֶמְצָעִי, מִשָּׁם הִיא יָד רָמָה, כְּלוּלָה מֵאַרְבָּעִים וּשְׁנַיִם גְּוָנִים.</p>\n<p>וּמִשּׁוּם שֶׁהִיא מִצַּד הַיָּמִין - אֶבֶן. וּמִצַּד הַשְּׂמֹאל - גַּחֶלֶת. בָּהּ לוֹקֵחַ הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמָה מִיִּשְׁמָעֵאל וֶאֱדוֹם, שֶׁהֵם אִשִּׁים נָכְרִיִּים וּמַיִם הַזֵּידוֹנִים. וְהַמְמֻנִּים שֶׁלָּהֶם - סָמָאֵל וְנָחָשׁ. סָמָאֵל אֵשׁ הַגֵּיהִנָּם, מְמֻנֶּה עַל הָאֻמָּה שֶׁל עֵשָׂו. נָחָשׁ מְמֻנֶּה עַל הָאֻמָּה שֶׁל יִשְׁמָעֵאל, וְהוּא רַהַב הַמְמֻנֶּה עַל הַמַּיִם.</p>\n<p>בִּימִין אַבְרָהָם, שֶׁדַּרְגָּתוֹ חֶסֶד, נוֹטֵל נְקָמָה מִיִּשְׁמָעֵאל וּמֵהַמְמֻנֶּה שֶׁלּוֹ. וּבִשְׂמֹאל יִצְחָק, שֶׁדַּרְגָּתוֹ פַּחַד, נוֹטֵל נְקָמָה מֵעֵשָׂו וּמֵהַמְמֻנֶּה שֶׁלּוֹ. בִּשְׁנֵי מְשִׁיחִים, שֶׁהֵם אֶחָד מִיָּמִין - מָשִׁיחַ בֶּן דָּוִד, וְאֶחָד מִשְּׂמֹאל - מָשִׁיחַ בֶּן יוֹסֵף. וּבְדַרְגָּתוֹ שֶׁל יַעֲקֹב, שֶׁהִיא כְּנֶגְדּוֹ, בְּסוֹד שֶׁל (בראשית מח) שִׂכֵּל אֶת יָדָיו (כי מנשה הבכור). אַרְיֵה לִשְׂמֹאל. שׁוֹר לְיָמִין, שֶׁל יִשְׁמָעֵאל. בִּגְלַל שֶׁיְּהוּדָה גָּלָה בְּעֵשָׂו, נִמְצָא יְמִין הַקְּדֻשָּׁה עִם הַשְּׂמֹאל שֶׁל עֵשָׂו. וּשְׂמֹאל הַקְּדֻשָּׁה עִם יָמִין טְמֵאָה שֶׁל יִשְׁמָעֵאל, (שם מט) עַד כִּי יָבֹא שִׁילֹה, רוֹעֶה נֶאֱמָן, בְּדַרְגָּה שֶׁל תִּפְאֶרֶת יִשְׂרָאֵל, נוֹטֵל נְקָמָה מֵעֵרֶב רַב.</p>\n<p>בְּשָׁלֹש דְּרָגוֹת אֵלּוּ יִפְקֹד (יצאו) כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים מִן הַגָּלוּת, וּבָהֶן יִקַּח נְקָמָה מֵעֵשָׂו וְיִשְׁמָעֵאל וְעֵרֶב רַב. כְּדֻגְמָא שֶׁל עֵרֶב רַב מְעֹרָבִים בְּעֵשָׂו וְיִשְׁמָעֵאל, כָּךְ יַעֲקֹב מְעֹרָב בְּאַבְרָהָם וְיִצְחָק, עֵרוּב שֶׁל שְׁנֵיהֶם. וְכָךְ מִתְעָרֵב שִׁילֹה עִם מָשִׁיחַ בֶּן דָּוִד וּמָשִׁיחַ בֶּן יוֹסֵף, וּתְהֵא שַׁלְשֶׁלֶת שֶׁל שְׁנֵיהֶם כְּאוֹתוֹ זְמַן שֶׁרָאָה בִּלְעָם בִּנְבוּאָתוֹ, שֶׁכָּךְ מִתְקַשְּׁרִים שְׁנֵי מְשִׁיחִים בָּרוֹעֶה הַנֶּאֱמָן בִּשְׁלֹשָׁה אָבוֹת בַּגָּלוּת הָאַחֲרוֹנָה.</p>\n<p>פָּתַח וְאָמַר, (במדבר כג) לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל ה' אֱלֹהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ. וְהַכֹּל לְקַיֵּם הַפָּסוּק (ישעיה נד) וּבְרַחֲמִים גְּדלִים אֲקַבְּצֵךְ. בְּאוֹתוֹ זְמַן נִשְׁבָּרוֹת הַקְּלִפּוֹת שֶׁהָיוּ מְסוֹבְבוֹת לַשְּׁכִינָה. מִיָּד מִתְגַּלֵּית אֶבֶן אַחַת מִשָּׁלֹשׁ אֲבָנִים, שֶׁהֵן סֶגוֹלְתָּא, שֶׁעֲלֵיהֶן נֶאֱמַר (יחזקאל א) וַיְהִי בִּשְׁלֹשִׁים שָׁנָה, וְהֵן ייי. בָּרְבִיעִי - אֶבֶן רְבִיעִית. בַּחֲמִשָּׁה לַחֹדֶשׁ - אֶבֶן חֲמִישִׁית. כְּנֶגְדָּן וַיִּקַּח דָּוִד (שמואל א יז) חֲמִשָּׁה חַלֻּקֵי אֲבָנִים מִן הַנַּחַל. וְאֵלּוּ לְעֻמָּתָם חָמֵשׁ תֵּבוֹת, שֶׁהֵן: שְׁמַע יִשְׂרָאֵל יְהֹוָ\"ה אֱלֹהֵינוּ יְהֹוָ\"ה.</p>\n<p>וַאֲנִי בְּתוֹךְ הַגּוֹלָה (יחזקאל א) - זוֹ שְׁכִינָה, בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶחָד. אוֹת ו' בְּתוֹסֶפֶת וַאֲנִי - הוּא נָהָר, צַדִּיק חַי הָעוֹלָמִים. (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. מַהוּ עֵדֶן? זוֹ בִּינָה. נָהָר שֶׁיּוֹצֵא מִמֶּנָּה זוֹ ו', בֶּן יָ\"הּ, דַּרְגָּה שֶׁל הָרוֹעֶה הַנֶּאֱמָן, וְהָרוֹעֶה הַנֶּאֱמָן יוֹצֵא מֵאִמָּא הָעֶלְיוֹנָה, וּמִתְפַּשֵּׁט בְּשֵׁשׁ סְפִירוֹת עַד צַדִּיק, וּמִמֶּנּוּ מַשְׁקֶה לַגָּן (של עדן), שֶׁהִיא הַשְּׁכִינָה.</p>\n<p>מַהוּ כְּבָר? כ' - כֶּתֶר. ב' - בִּינָה. ר' - רֵאשִׁית חָכְמָה. כֶּתֶר בְּיָמִין, חָכְמָה בִּשְׂמֹאל, בִּינָה בָּאֶמְצַע. רֶכֶב לָעֶלְיוֹן, לְעִלַּת הָעִלּוֹת. עֶשֶׂר הַסְּפִירוֹת כֻּלָּן נִכְלְלוּ בְּנָהָר, שֶׁהוּא מִתְפַּשֵּׁט עַד צַדִּיק שֶׁנִּקְרָא כֹּל, כּוֹלֵל הַכֹּל. וּבִגְלָלוֹ פֵּרְשׁוּהוּ (דניאל ד) אִילָן גָּדוֹל וְתַקִּיף, וּמָזוֹן לְכֻלָּם בּוֹ. מִמֶּנּוּ תָּלוּי הַכֹּל. כַּאֲשֶׁר רָאָה הַשְּׁכִינָה מִתּוֹךְ הַקְּלִפּוֹת, רָאָה עִמָּהּ עֶשֶׂר סְפִירוֹת. (ע\"כ רעיא מהימנא).</p>"],[9522012539,"<p>סֹלֶת לְמִנְחָה, לְהַעֲלוֹת לְזֹּאת הַסֹּלֶת לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן לְמִנְחָה בֵּין שְׁתֵּי זְרוֹעוֹת.</p>\n<p>בַּחִבּוּר הַקַּדְמוֹן, אָמַר הָרוֹעֶה הַנֶּאֱמָן, מִכָּאן נוֹדָע אֵלּוּ דְּבָרִים סְתוּמִים הֵם, וְצָרִיךְ לִפְתֹּחַ אוֹתָם לִפְנֵי הַחֲבֵרִים. אַבְרָהָם וְיִצְחָק שֶׁתִּקְּנוּ תְּפִלַּת שַׁחֲרִית וּמִנְחָה, נֶאֱמַר עֲלֵיהֶם, (ישעיה מח) אַף יָדִי יָסְדָה אֶרֶץ - זֶה יִצְחָק. וִימִינִי טִפְּחָה שָׁמָיִם - זֶה אַבְרָהָם. שֶׁהַדְּרָגוֹת שֶׁלָּהֶם חֶסֶד וָפַחַד, שֶׁנֶּאֱמַר עֲלֵיהֶם (שם סב) נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ. אֵלּוּ שְׁתֵּי זְרוֹעוֹת הַמֶּלֶךְ, שֶׁהוּא יְהֹוָ\"ה, הָעַמּוּד הָאֶמְצָעִי. הַסֹּלֶת שֶׁלּוֹ זוֹ הַשְּׁכִינָה הַתַּחְתּוֹנָה, הָאוֹר שֶׁלּוֹ, סֹלֶת נְקִיָּה מִצִּדּוֹ בְּלִי פְגָם שֶׁל חֹשֶׁךְ וּבְלִי תַעֲרֹבֶת חֹשֶׁךְ כְּלָל. שֶׁכָּךְ הֵם חֹשֶׁךְ עִם אוֹר, כְּמוֹ דָּגָן בִּפְנֵי מוֹץ וְתֶבֶן.</p>\n<p>וּבַחֲטָאֵיהֶם שֶׁל יִשְׂרָאֵל מִתְעָרְבִים חֹשֶׁךְ וְאוֹר, וּכְמוֹ שֶׁאָדָם דָּשׁ תְּבוּאָה וּלְבַסּוֹף הוּא בּוֹרֵר אוֹתָהּ כְּבוֹרֵר אֹכֶל מִתּוֹךְ פְּסֹלֶת - כָּךְ יִשְׂרָאֵל צָרִיךְ לַעֲשׂוֹת בְּרוּחָם כַּאֲשֶׁר מִתְעָרֵב בָּהֶם חֹשֶׁךְ. וְסוֹד הַדָּבָר - (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה וְגוֹ'. שֶׁבְּכָךְ נִשְׁבָּר הַחֹשֶׁךְ, שֶׁהוּא יֵצֶר הָרָע, שֶׁמְּכַסֶּה עַל הָרוּחַ כְּמוֹ מוֹץ שֶׁמְּכַסֶּה עַל הַחִטָּה, אוֹ כְּמוֹ עָנָן שֶׁמְּכַסֶּה עַל הַשֶּׁמֶשׁ וְלֹא מַנִּיחַ לוֹ לְהָאִיר.</p>\n<p>וּבִזְמַן שֶׁחֹשֶׁךְ, שֶׁהוּא יֵצֶר הָרָע, מְכַסֶּה עַל יֵצֶר הַטּוֹב, שֶׁהוּא אוֹר, הוּא כְּמִי שֶׁאָסוּר בְּבֵית הָאֲסוּרִים שֶׁל יֵצֶר הָרָע. וְאַף כָּךְ, כַּאֲשֶׁר יֵצֶר הַטּוֹב הוּא אָסוּר בִּרְשׁוּת יֵצֶר הָרָע, כָּךְ הֵם אֲסוּרִים הַחַיָּלִים שֶׁל יֵצֶר הַטּוֹב בִּרְשׁוּת הַחַיָּלִים שֶׁל יֵצֶר הָרָע. וּבִזְמַן שֶׁיִּשְׁבּראָדָם רוּחוֹ בְּכָל אֵיבָרָיו לִפְנֵי יְהֹוָ\"ה, מַה כָּתוּב? (ישעיה מט) לֵאמֹר לַאֲסוּרִים צֵאוּ וְלַאֲשֶׁר בַּחֹשֶׁךְ הִגָּלוּ.</p>\n<p>אֲבָל הַשְּׁכִינָה הִיא סֹלֶת נְקִיָּה, שֶׁאֵין חֹשֶׁךְ וַאֲפֵלָה יָכוֹל לְהִתְעָרֵב בָּהּ. הִיא כְּמוֹ גֶּפֶן שֶׁאֵינָהּ מְקַבֶּלֶת הַרְכָּבָה מִמִּין אַחֵר שֶׁאֵינוֹ מִינָהּ. וְזוֹ הַסֹּלֶת בֵּין זְרוֹעוֹת הַמֶּלֶךְ הִיא יוֹשֶׁבֶת, בְּלוּלָה בְּשֶׁמֶן כָּתִית. (ע\"כ רעיא מהימנא).</p>"],[9522012540,"<p>זֹהַר (ובחבור קדמון) בְּלוּלָה בְּשֶׁמֶן כָּתִית, בְּשֶׁמֶן - בְּאוֹתוֹ שֶׁמֶן שֶׁנִּמְשָׁךְ וְיוֹצֵא מִלְמַעְלָה. אָמַר רַבִּי שִׁמְעוֹן, יָפֶה אָמַרְתָּ. אֲבָל מַהוּ כָּתִית? אֶלָּא סוֹד עֶלְיוֹן הוּא. שֶׁכֵּיוָן שֶׁהוּא שֶׁמֶן, מַהוּ כָּתִית? אֶלָּא רֶמֶז הוּא שֶׁהוּא רוֹמֵז לְשַׁמֵּשׁ בַּנְּקֵבָה, לְהַמְשִׁיךְ אֶצְלָהּ שֶׁמֶן כָּתִית כְּמוֹ שֶׁרָאוּי לָהּ, לֹא הָיְתָה אֶלָּא כָּתִית (אלא סוד עליון הוא, שהוא רומז להמשיך אצלה שמן כתית כמו שראוי לה), לְהוֹצִיא מִזֵּיתִים, שֶׁהֵם אֶבְרֵי הַגּוּף, וּלְהַמְשִׁיךְ אוֹתָהּ הַמְשָׁכָה מִלְמַעְלָה בְּכָל אֵיבָר וְאֵיבָר. (לא היה אלא כתית).</p>\n<p>וְהַצַדִּיק הוּא שֶׁכּוֹתֵשׁ כְּתִישׁוֹת, וּמוֹצִיא מִכָּל אוֹתָם אֵיבָרִים עֶלְיוֹנִים, שֶׁהֵם זֵיתִים קְדוֹשִׁים, שֶׁמֶן הַמִּשְׁחָה, בִּתְשׁוּקָה שְׁלֵמָה לְגַבֵּי הַנְּקֵבָה. וְאִם לֹא יִכְתֹּשׁ, לֹא יֵצֵא אוֹתוֹ הַשֶּׁמֶן, אֶלָּא בְּלִי תְּשׁוּקַת הָאֵיבָרִים. וְאוֹתוֹ שֶׁפַע לֹא תֵהָנֶה מִמֶּנּוּ הַנְּקֵבָה, וְלֹא יִהְיֶה כְּמוֹ שֶׁרָאוּי עַד שֶׁתִּהְיֶה בְּלוּלָה מִמֶּנּוּ מִכָּל הָאֵיבָרִים. וְעַל זֶה בְּלוּלָה בְּשֶׁמֶן כָּתִית, לֵהָנוֹת וְלִהְיוֹת נִזּוֹנָה מִמֶּנּוּ.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, מְנוֹרָה הַקְּדוֹשָׁה, כַּמָּה מְתוּקִים דְּבָרֶיךְ. וַדַּאי נֶאֱמַר כָּאן בְּלוּלָה בְּשֶׁמֶן כָּתִית, וְנֶאֱמַר שָׁם בַּתּוֹרָה שֶׁבְּעַל פֶּה, בְּלוּלָה בַּמִּקְרָא, בַּמִּשְׁנָה, בַּתַּלְמוּד. וְעוֹד יֵשׁ סוֹד שֵׁנִי, בְּלוּלָה בְּשֶׁמֶן כָּתִית - וַדַּאי אֵין הַתּוֹרָה הִיא בְּלוּלָה אֶלָּא לְמִי שֶׁסּוֹבֵל כַּמָּה יִסּוּרִים בִּשְׁבִילָהּ, כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, שֶׁאֵין הַתּוֹרָה מִתְקַיֶּמֶת אֶלָּא בְּמִי שֶׁמֵּמִית עַצְמוֹ עָלֶיהָ. וְעוֹד אָמְרוּ, בִּזְמַן שֶׁאַתָּה מְכַתֵּת רַגְלֶיךְ מִמְּדִינָה לִמְדִינָה, תִּזְכֶּה לִרְאוֹת פְּנֵי שְׁכִינָה.</p>\n<p>וְעוֹד בְּלוּלָה בְּשֶׁמֶן כָּתִית - זֶהוּ שֶׁמְּקַיֵּם פַּת בַּמֶּלַח תֹּאכֵל (יחזקאלד) וּמַיִם בִּמְשׂוּרָה תִשְׁתֶּה. וְעוֹד בְּלוּלָה בְּשֶׁמֶן כָּתִית - זֶהוּ שֶׁכָּתוּב (ישעיה נג) וְהוּא מְחֹלָל מִפְּשָׁעֵנוּ מְדֻכָּא מֵעֲוֹנֹתֵינוּ. וְעוֹד בְּלוּלָה בְּשֶׁמֶן כָּתִית - זֶה צַדִּיק חַי הָעוֹלָמִים שֶׁמּוֹשֵׁךְ טִפּוֹת קְדוֹשׁוֹת, שֶׁהֵן פֵּרוּרִים כַּזֵּיתִים, מֵהַמֹּחַ הָעֶלְיוֹן, שֶׁהֵם עִשָּׂרוֹן אֶחָד כְּנֶגֶד י'. וּשְׁנֵי עֶשְׂרוֹנִים - י' י'. וּשְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר - י' י' י'. וְהֵם - עִשָּׂרוֹן לַכֶּבֶשׂ, וּשְׁנֵי עֶשְׂרוֹנִים לָאַיִל, וּשְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר.</p>\n<p>וְסוֹד הַדָּבָר אָמְרוּ בְּתַעֲנִיּוֹת, אֵין טִפָּה יוֹרֶדֶת מִלְמַעְלָה שֶׁאֵין עוֹלוֹת כְּנֶגְדָּהּ טִפַּיִם. וְהֵם בְּסוֹד זֶה: וְהָרֶמֶז שֶׁלָּהֶן כְּנֶגֶד שְׁלֹשָׁה מֹחִין. אֶחָד - מֹחַ הַזִּכָּרוֹן. שֵׁנִי - מֹחַ הַמַּחֲשָׁבָה. שְׁלִישִׁי - מֹחַ הַדִּמְיוֹן. הַדִּמְיוֹן וְהַזִּכָּרוֹן עוֹלִים מִן הַלֵּב. הַמַּחֲשָׁבָה יוֹרֶדֶת עַל הַלֵּב, וּמְקַבְּלִים אוֹתָהּ עֲלֵיהֶם כְּמֶלֶךְ, מִשּׁוּם שֶׁזֶּה הָאָדָם, שֶׁהוּא מַחֲשָׁבָה, שֶׁרוֹכֵב וְשׁוֹלֵט עַל חַיָּה שְׁלִישִׁית, וְיוֹרֶדֶת עָלֶיהָ אֵצֶל שְׁתֵּי הַחַיּוֹת, וּפוֹתְחִים כַּנְפֵיהֶם לְקַבֵּל אוֹתָהּ כְּמוֹ נִקּוּד חוֹלָם עַל צֵירֵי - נַעֲשֶׂה סֶגוֹלְתָּא, וְזֶה כֶּתֶר עֶלְיוֹן עַל חָכְמָה וּבִינָה.</p>\n<p>עִשָּׂרוֹן וּשְׁנֵי עֶשְׂרוֹנִים רוֹמְזִים לְשָׁלֹשׁ חַיּוֹת שֶׁל הַמֶּרְכָּבָה הָעֶלְיוֹנָה, שֶׁהֵן: גְּדֻלָּה, גְּבוּרָה, תִּפְאֶרֶת. שְׁלֹשָׁה עֶשְׂרוֹנִים רוֹמְזִים לְנֵצַח, הוֹד, יְסוֹד. מֶרְכֶּבֶת הַמִּשְׁנֶה. רְבִיעִית הַהִין - זוֹ מַלְכוּת הַקְּדוֹשָׁה, ה' רְבִיעִית מִשֵּׁם יְהֹוָ\"ה, שֶׁהוּא אַרְבַּע פְּנֵי אָדָם. (ע\"כ רעיא מהימנא). (ובחבור קדמון).</p>\n<p>רְבִיעִית הַהִין, רֶגֶל רְבִיעִית לַכִּסֵּא הָעֶלְיוֹן, וְהִיא עוֹלָה תָּמִיד אֶצְלוֹ בְּכָל יוֹם וָיוֹם עַד מַחֲשָׁבָה עֶלְיוֹנָה שֶׁאֵין לָהּ סוֹף, וּמִשּׁוּם זֶה הָעוֹלָה בָּאָה עַל הִרְהוּר הַלֵּב.</p>"],[9522012541,"<p>וּבַחִבּוּר הַקַּדְמוֹן אָמַר, רוֹעֶה נֶאֱמָן, אוֹתוֹ טַעַם שֶׁל זַרְקָא הִיא אוֹת יוֹ\"ד, רבִיעִית. אַף כָּךְ בַּחַיָּה שֶׁשְּׁמָהּ אָדָם, שֶׁאַרְבַּע פָּנִים שֶׁלָּהּ שֶׁהֵם יְהֹוָ\"ה, מַקַּף שׁוֹפָר הוֹלֵךְ סֶגוֹלְתָּא. שָׁלֹשׁ חַיּוֹת שֶׁהֵן שְׁנֵים עָשָׂר שְׁבָטִים. (ע\"כ רעיא מהימנא).</p>\n<p>וּבְחִבּוּר קַדְמוֹן, עוֹלַת תָּמִיד הִיא רִגֶל רְבִיעִית לַכִּסֵּא הָעֶלְיוֹן. זוֹ עוֹלָה תָּמִיד בְּכָל יוֹם מֵאֵלּוּ הַיָּמִים שֵׁשֶׁת יְמֵי בְרֵאשִׁית. בְּשַׁבָּת - עַל אֶחָד שְׁנַיִם, כְּדֵי שֶׁיִּתּוֹסֵף בָּהּ אוֹר וּשְׁלֵמוּת כְּמוֹ שֶׁרָאוּי, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012542,"<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, הַמַּלְכוּת בְּשֵׁשׁ סְפִירוֹת הִיא עוֹלָה תָּמִיד אֵצֶל אוֹת ו' שֶׁאֲחוּזָה בָּהֶן. בֶּן יָ\"הּ, גָּנוּז בְּבִינָה. וּבְאֵילוּ סְפִירוֹת מֵאֵלּוּ הַשֵּׁשׁ עוֹלָה אֶצְלוֹ? בַּיּוֹם הַשְּׁלִישִׁי, הַנִּקְרָא תִּפְאֶרֶת. שֶׁבְּיוֹם הַשַּׁבָּת נוֹסֶפֶת עִמּוֹ נְפֶשׁ יְתֵרָה, שֶׁהִיא בִּינָה, ה' עֶלְיוֹנָה. י' - אוֹת בְּשַׁבָּת, חָכְמָה עֶלְיוֹנָה, מֶלֶךְ מְעֻטָּר בְּכֶתֶר, וּמִשּׁוּם זֶה בִּתְפִלַּת מוּסָף כֶּתֶר יִתְּנוּ לְךְ.</p>\n<p>וּבְרָאשֵׁי חָדְשֵׁיכֶם - וְכִי כַּמָּה רָאשִׁים יֵשׁ לָהּ לַלְּבָנָה? אֶלָּא הֵם שְׁתֵּי נְקֻדּוֹת כְּדֻגְמַת זֶה נְקֻדָּה תַּחְתּוֹנָה - הַלְּבָנָה, שְׁנֵי רָאשִׁים שֶׁלָּהּ אֵלּוּ שְׁתֵּי נְקֻדּוֹת שֶׁהֵן עָלֶיהָ סֶגּוֹל. בָּרִאשׁוֹנָה היָה כֶּתֶר עַל שְׁנֵי מְלָכִים כְּדֻגְמַת זֶה, וְהָיְתָה סֶגוֹלְתָּא. וּלְבַסּוֹף שֶׁאָמְרָה אִי אֶפְשִׁי לִשְׁנֵי מְלָכִים לְהִשְׁתַּמֵּשׁ בְּכֶתֶר אֶחָד, אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: לְכִי וּמַעֲטִי אֶת עַצְמֵךְ. וְיָרְדָה לְרַגְלֵיהֶם שֶׁל שְׁנֵי מְלָכִים כְּמוֹ זֶה, וְזֶהוּ נִקּוּד סֶגּוֹל. מַה שֶּׁהָיְתָה סֶגוֹלְתָּא, חָזְרָה לִהְיוֹת סֶגּוֹל.</p>\n<p>וְסוֹד הַדָּבָר - כְּנֶגֶד שְׁתֵּי נְקֻדּוֹת שֶׁהֵן שְׁנֵי מְלָכִים, רוֹמֵז בְּפָסוּק פָּרִים בְּנֵי בָקָר שְׁנַיִם. וּכְנֶגֶד נְקֻדָּה שֶׁהִיא עֲטָרָה עַל רָאשֵׁיהֶם, אָמַר וְאַיִל אֶחָד, כְּמוֹ כֶּתֶר אֶחָד. אַחַר שֶׁאָמְרָה אִי אֶפְשָׁר לִשְׁנֵי מְלָכִים שֶׁיִּשְׁתַּמְּשׁוּ בְּכֶתֶר אֶחָד, הִקְטִינָה עַצְמָהּ. אַף כָּךְ, וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת. אַיִל שֶׁל יִצְחָק חָזַר לִהְיוֹת שָׂעִיר. הִתְהַפֵּךְ מֵרַחֲמִים לְדִין, וְנִקְטַן.</p>\n<p>וּמִשּׁוּם זֶה נֶאֱמַר שְׂעִיר עִזִּים אֶחָד לְחַטָּאת, וְלֹא אָמַר לְעוֹלָה, לִהְיוֹת כֶּתֶר. וּמִנַּיִן לָנוּ שֶׁיֵּשׁ יְרִידָה בְּחַטָּאת? שֶׁנֶּאֱמַר (ויקרא ט) וַיֵּרֶד מֵעֲשּת הַחַטָּאת. וּמַדּוּעַ שִׁתֵּף עוֹלָה עִם חַטָּאת בַּיְרִידָה? אֶלָּא לְלַמֵּד, שֶׁעוֹלָה הָיְתָה בַּהַתְחָלָה מִדַּת הָרַחֲמִים, וּלְבַסּוֹף הִתְהַפְּכָה לְמִדַּת הַדִּין בַּיְרִידָה, וְנִקְרֵאת חַטָּאת, וְהַכֹּל אֶחָד.</p>\n<p>וּמִשּׁוּם זֶה נֶאֱמַר הָבִיאוּ עָלַי כַּפָּרָה. עָלַיֻ - הָיְתָה הַלְּבָנָה כֶּתֶר וַדַּאי, כְּדֻגְמַת זֶה, וּלְבַסּוֹף הִתְמַעֲטָה וְיָרְדָה לְרַגְלָיו כְּדֻגְמַת זֶה וּבִזְמַן זֶה נֶאֱמַר הָבִיאוּ עָלַי כַּפָּרָה, שֶׁנֶּאֱמַר בָּהּ (שם ו) הִיא הָעֹלָה, עוֹלָה מֵרַגְלָיו, שֶׁנֶּאֱמַר בָּהּ (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי, לוֹמַר בָּהּ הַשָּׁמַיִם כִּסְאִי. וְזֶהוּ סוֹד (שמואל ב כג) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. שֶׁמְּהַפֵּךְ דִּין לְרַחֲמִים. וְסוֹד הַדָּבָר - (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. כְּדֻגְמַת זֶה הוה\"י, יְהֹוָה.</p>\n<p>וְעוֹד, כֶּבֶשׂ אֶחָד וּשְׁנֵי כְבָשִׂים בְּנֵי שָׁנָה תְמִימִים - כְּנֶגֶד שָׁלֹשׁ סְפִירוֹת. שִׁבְעָה כְבָשִׂים בְּנֵי שָׁנָה - כְּנֶגֶד שֶׁבַע סְפִירוֹת. שִׁבְעָה כְבָשִׂים - הֵם שִׁבְעָה יָמִים שֶׁל הַלְּבָנָה. בְּנֵי שָׁנָה - בְּנֵי הַלְּבָנָה שֶׁנִּקְרֵאת שָׁנָה, שֶׁהִיא אַחַת מֵאוֹתָן שָׁנִים קַדְמוֹנִיּוֹת. (ע\"כ רעיא מהימנא).</p>"],[9522012543,"<p>וּבְרָאשֵׁי חָדְשֵׁיכֶם וְגוֹ'. וְכִי כַּמָּה רָאשִׁים יֵשׁ לַלְּבָנָה? וַהֲרֵי אֵין רֹאשׁ לַלְּבָנָה אֶלָּא הַשֶּׁמֶשׁ, שֶׁהוּא רֹאשׁ בּשְׁבִילָהּ. אֶלָּא רָאשֵׁי - שְׁנַיִם, בְּכָל חֹדֶשׁ וְחֹדֶשׁ, וְהֵם יַעֲקֹב וְיוֹסֵף שֶׁמִּתְחַדְּשִׁים עַל הַלְּבָנָה, וְעַל זֶה רָצוּ לְחַדֵּשׁ אוֹתָהּ.</p>\n<p>פָּרִים בְּנֵי בָקָר שְׁנַיִם - אֵלּוּ הֵם שֶׁאָמְרָה הַלְּבָנָה אֵיךְ יִשְׁתַּמְּשׁוּ בָּהּ כּאֶחָד, וְהִמְעִיטָה עַצְמָהּ תַּחְתֵּיהֶם. אַיִל אֶחָד - זֶה אֵילוֹ שֶׁל יִצְחָק. וְכִי אַבְרָהָם לְהֵיכָן הָלַךְ? אֶלָּא מִשּׁוּם שֶׁהִתְעוֹרֵר שָׁם עֵשָׂו, נֶאֱסַף אַבְרָהָם, שֶׁלֹּא יִרְאֶה אוֹתוֹ. וּמִי הוּא? שָׂעִיר שֶׁל רֹאשׁ חֹדֶשׁ. (שתי נסחאות) וּמִשּׁוּם שֶׁמְּזֻמָּן לְהִתְעוֹרֵר שָׁם עֵשָׂו, שֶׁהוּא שָׂעִיר - נֶאֱסַף אַבְרָהָם וְלֹא נִמְצָא שָׁם. יִצְחָק נִמְצָא שָׁם, שֶׁהָאַהֲבָה שֶׁלּוֹ אֶצְלוֹ כְּיַיִן עַל שְׁמָרָיו. יַעֲקֹב מְצָא שָׁם לִשְׁבֹּר פָּנָיו. יוֹסֵף הוּא הַשּׁוֹר (שטן) שֶׁלּוֹ אֵצֶל רָחֵל.</p>"],[9522012544,"<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, וַדַּאי בְּנֵי שָׁנָה קְרָאִים עַל שֵׁם הַחַמָּה (מלכות), הָאֵם הַקְּדוֹשָׁה, שֶׁנֶּאֱמַר בָּהּ פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. (הלבנה שנקראת שנה, שישבה שנ\"ה ימים חשבון) שָׁנָה יֵשׁ בָּהּ שס\"ה יָמִים, כּחֶשְׁבּוֹן שס\"ה מִצְווֹת לֹא תַעֲשֶׂה, לָכֵן הוּא לִשְׂמֹאל. אִמָּא עֶלְיוֹנָה - הַלְּבָנָה בְּיָמִין. אֲסוּרָה הַבַּת לָאָב, שֶׁהוּא לְיָמִין, חֶסֶד. וְהִיא כְּלוּלָה מִרמ\"ח מִצְווֹת. נִמְצֵאת ו' עִם אִמָּא לשְׂמֹאל. הַבַּת עִם הָאָב לִימִין הַחֶסֶד. (והיא כלולה מרמ\"ח מצוות. נמצאת ו' עם אמא, והבת עם האב לימין). וְסוֹד הַדָּבָר (משלי ג) בְּחָכְמָה יָסַד אֶרֶץ. חָכְמָה אַבָּא. אָרֶץ - בַּת. כּוֹנֵן שָׁמַיִם - שֶׁהוּא בֵּן, עִם אִמָּא, שֶׁהִיא תְּבוּנָה. וזֶהוּ צֵרוּף יהה\"ו, הֲוָיוֹת בָּאֶמְצַע.</p>"],[9522012545,"<p>עוֹד, וּשְׂעִיר עִזִּים אֶחָד - שְׁנֵי שְׂעִירִים הֵם, שֶׁנֶּאֱמַר עֲלֵיהֶם (ויקרא טז) וְלָקַח אֶת שְׁנֵי הַשְּׂעִירִים וְגוֹ' גּוֹרָל אִחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל. שָׂעִיר לה', בִּגְלַל מִעוּט הַלְּבָנָה, וְהוּא שָׂעִיר אֶחָד לַיהֹוָ\"ה לְחַטָּאת. אֶחָד - מִצַּד הַיִּחוּד. אֲבָל שָׂעִיר שֶׁל עֲזָאזֵל לֹא כָתוּב בּוֹ אֶחָד, לָא קָרְבָּן, וְלֹא אִשֶּׁה, וְלֹא עוֹלָה. אֶלָּא - וְשִׁלַּח בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה. וְשִׁלַּח, כְּמוֹ שֶׁאָמַר יַעֲקֹב, (בראשית לב) מִנְחָה הִיא שְׁלוּחָה לַאדנִי לְעֵשָׂו. אַף כָּךְ שֹׁחַד, לִשְׁבֹּר הָרֹגֶז שֶׁל סָמָאֵ\"ל שֶׁלֹּא יִתְקָרֵב לַמִּקְדָּשׁ לְקַטְרֵג.</p>\n<p>מָשָׁל לְכֶלֶב שֶׁהוּא רָעֵב, וּמִי שֶׁרוֹצֶה שֶׁלֹּא יִנְשֹׁךְ אוֹתוֹ, נוֹתֵן לוֹ בָּשָׂר לֶאֱכֹל אוֹ לֶחֶם, וְיַשְׁקֶה אוֹתוֹ מַיִם. וְסוֹד הַדָּבָר - (משלי כה) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִלֵהוּ לָחֶם וְגוֹ'. וּבָזֶה יַחֲזֹר לְאַהֲבָתוֹ שֶׁל הָאָדָם. שֶׁלֹּא דַי שֶׁלֹּא יִנְשֹׁךְ אוֹתוֹ בְּכַמָּה יִסּוּרִים, אֶלָּא יַחֲזֹר לִהְיוֹת עָלָיו סָנֵגוֹר, וְיַחֲזֹר לִהְיוֹת אוֹהֲבוֹ.</p>\n<p>וּמַדּוּעַ הָיוּ שׁוֹלְחִים אוֹתוֹ בְּיַד אִישׁ עִתִּי, פָּגוּם? מִשּׁוּם שֶׁהַצְּדָדִים הָאֲחֵרִים כֻּלָּם בַּעֲלֵי מוּמִים, וְנִקְרְאוּ שְׂעִירִים, שֶׁכָּתוּב (ישעיה יג) וּשְׂעִירִים יְרַקְּדוּ שָׁם. וְנֶאֱמַר בָּהֶם, (ויקרא יז) וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִם. שֶׁעֲלֵיהֶם נֶאֱמַר (דברים לב) יִזְבְּחוּ לַשֵּׁדִים לֹא אֱלֹהַּ. וּבְשָׂעִיר זֶה נִפְרָשׁ מֵהַכֹּל, וְנוֹשֵׂא אֶת כָּל חוֹבוֹת יִשְׂרָאֵל עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנֹתָם. וְעוֹד, אַחַר שֶׁנּוֹטֵל הוּא - וְנָשָׂא. הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לד) נֹשֵׂא עָוֹן. מַה בֵּין נוֹשֵׂא לְנָשָׂא? נָשָׂא - מַשּׂאוֹי. נֹשֵׂא - הֲרָמַת הַמַּשּׂאוֹי. (ובחבור קדמון) (ע\"כ רעיא מהימנא).</p>\n<p>וּשְׁלֹשָה עֶשְׂרֹנִים - שָׁלֹשׁ מַדְרֵגוֹת רִאשׁוֹנוֹת שֶׁלָּהּ, שֶׁכָּל אַחַת וְאַחַת - עֶשֶׂר, כְּדֻגְמָא שֶׁל מַעְלָה - עֶשְׂרֹנִים, אֶחָד מֵעֲשָׂרָה. וּשְׂעִיר חַטָּאת אֶחָד, מַדּוּעַ נִקְרָא חַטָּאת? מִשּׁוּם שֶׁהוּא חַטָּאת, וּמִצַּד הַחַטָּאת הוּא. אָמַר רַבִּי אֶלְעָזָר, וַהֲרֵי כָּתוּב לַה'. אֶלָּא לְשֵׁם ה' מֻקְרָב בְּוַדַּאי, שֶׁכָּתוּב לְכַפֵּר. לְשַׁבֵּר פָּנִים, וְהַכֹּל יִתְקָרֵב לַמִּקְדָּשׁ, אֶלָּא נוֹתְנִים חֵלֶק אֶחָד לְסָמָאֵל, וְאוֹכֵל אוֹתוֹ, וְלֹא אוֹחֵז בִּשְׁאָר הַקָּרְבָּנוֹת. וְזֶהוּ לְבַדּוֹ, שֶׁלֹּא יִשְׁתַּתֵּף אַחֵר עִמּוֹ לֶאֱכֹל בּוֹ.</p>\n<p>הוּא נֶהֱנָה בְּתוֹךְ סְעוּדַת הַמֶּלֶךְ בְּחֵלֶק זֶה, וְעַל זֶה שָׂמֵחַ, וְנִפְרָד מִיִּשְׂרָאֵל וְלֹא מְקַטְרֵג עֲלֵיהֶם. וְאִם לֹא שֶׁהָיָה מִעוּט הַלְּבָנָה, לֹא הָיוּ נוֹתְנִים לוֹ בִּסְעוּדַת הַמֶּלֶךְ כְּלוּם. וְכִי בְּמִעוּט הַלְּבָנָה מֶה הָיָה עוֹשֶׂה? אֶלָּא כְּדֵי שֶׁיִּתְקָרֵב וְיִינַק וְיִקַּח כֹּחַ לְעַמּוֹ מִתּוֹךְ צַד שְׂמֹאל שֶׁל הַלְּבָנָה, וְיִתְחַזֵּק בּוֹ. וּבְשָׂעִיר זֶה נִפְרָד מֵהַכֹּל וְנֶהֱנֶה בָּזֶה. וּמִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִמְעִיט לָהּ לַלְּבָנָה, מַקְרִיבִים לוֹ לְזֶה הַשָּׂעִיר, כְּדֵי שֶׁיִּפָּרֵד מִמֶּנּוּ וְלֹא יִתְקָרֵב לַמִּקְדָּשׁ. וְעַל זֶה שָׁנִינוּ, הָבִיאוּ עָלַי כַּפָּרָה. עָלַי - בִּגְלָלִי, שֶׁהִמְעַטְתִּי אוֹתָהּ. בִּגְלַל סִבָּה שֶׁלִּי אַתֶּם צְרִיכִים זֶה.</p>"],[9522012546,"<p>וּבְרָאשֵׁי חָדְשֵׁיכֶם (במדבר כח) - הֵם יַעֲקֹב וְיוֹסֵף. (בראשית לז) אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף, שֶׁמִּתְחַדְּשִׁים עַל הַלְּבָנָה. מָצִינוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ שֶׁאָמַר, כְּמוֹ שֶׁבְּרֹאשׁ חֹדֶשׁ, שֶׁנִּטְהֶרֶת הַלְּבָנָה לְהִתְקָרֵב בְּבַעְלָהּ, צָרִיךְ לָתֵת לַצַּד הָאַחֵר חֵלֶק אֶחָד בְּאוֹתוֹ מִין שֶׁלָּהּ - אַף כָּךְ גַּם כֵּן צְרִיכָה הָאִשָּׁה בְּשָׁעָה שֶׁנִּטְהֶרֶת לְהִתְקָרֵב בְּבַעְלָהּ לָתֵת חֵלֶק אֶחָד לַצַּד הָאַחֵר בְּאוֹתוֹ מִין שֶׁלּוֹ.</p>\n<p>וּמַהוּ, ? אוֹתוֹ חֵלֶק הַצִּפָּרְנַיִם בַּלִּכְלוּךְ שֶׁלָּהֶם. וּמְעַט מִשַּׂעֲרוֹת הָרֹאשׁ, כֵּיוָן שֶׁצָּרִיךְ לִסְרֹק רֹאשָׁהּ, וְלִכְרֹךְ אוֹתָם זֶה בָּזֶה, וְלֹא יֵלֵךְ אַחֲרֶיהָ אוֹתוֹ צַד הָרָע לְהָרַע לָהּ, וְיִפָּרֵד מִמֶּנָּה בְּכָל הַצְּדָדִים. וּמַה תַּעֲשֶׂה מֵאוֹתוֹ שֵׂעָר וְצִפָּרְנַיִם? לְאַחַר שֶׁתִּכְרֹךְ אוֹתָם כְּאֶחָד, צָרִיךְ לְהַנִּיחַ אוֹתָם בְּמָקוֹם שֶׁלֹּא עוֹבְרִים שָׁם בְּנֵי אָדָם, אוֹ בְּתוֹךְ חוֹרִים תַּחְתּוֹנִים שֶׁל הֶחָצֵר, וְיִגְנֹז אוֹתָם שָׁם.</p>\n<p>וְעוֹד וּבְרָאשֵׁי חָדְשֵׁיכֶם - אָמְרוּ חַכְמֵי הַמִּשְׁנָה, שֶׁכַּאֲשֶׁר הָיוּ מְקַדְּשִׁים חֳדָשִׁים עַל פִּי בֵּית דִּין, הָיוּ מַשִּׂיאִין מַשּׂוּאוֹת בְּרָאשֵׁי הֶהָרִים, וְהָיוּ אוֹמְרִים: כָּזֶה רְאֵה וְקַדֵּשׁ. לִפְעָמִים הָיְתָה הַלְּבָנָה כְּדֻגְמָא זוֹ (ציור) הָיְתָה מִסְתַּכֶּלֶת לְמַעְלָה בְּקַרְנֶיהָ. וְלִפְעָמִים מִסְתַּכֶּלֶת לְמַטָּה כְּדֻגְמָא זוֹ (ציור) לִפְעָמִים מִסְתַּכֶּלֶת לַמִּזְרָח כְּדֻגְמָא זוֹ (ציור) לִפְעָמִים לַמַּעֲרָב כְּדֻגְמָא זוֹ - כ. לִפְעָמִים לַדָּרוֹם, וְלִפְעָמִים לַצָּפוֹן, וְזוֹהִי אוֹת כ, הַהִסְתַּכְּלוּת שֶׁלָּהּ לְשִׁשָּׁה צְדָדִים שֶׁכּוֹלֶלֶת אוֹתָם הַתִּפְאֶרֶת, שֶׁהִיא אוֹת ו', גְּדֻלָּה גְּבוּרָה תִּפְאֶרֶת נֵצַח הוֹד יְסוֹד.</p>\n<p>נְקֻדָּה שֶׁמּוֹשֶׁכֶת עָלֶיהָ מִבִּפְנִים הִיא חָכְמָה. וְאוֹתוֹ הַחוּט הַסּוֹבֵב עָלֶיהָ הוּא כֶּתֶר. וְאוֹתָהּ הַנְּקֻדָּה הַהִיא לִפְעָמִים עֲטָרָה, וְלִפְעָמִים כִּסֵּא לָשֶׁבֶת עָלֶיהָ, לִפְעָמִים שְׁרַפְרַף לַהֲדוֹם רַגְלָיו.</p>\n<p>וּמַדּוּעַ נִקְרֵאת לְבָנָה? עַל שֵׁם לִבּוּן הַהֲלָכָה, שֶׁהִיא מִבִּפְנִים, (תהלים מה) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה. וּבְאֵשׁ הַבִּינָה שֶׁיּוֹרֵד עָלֶיהָ הִיא מִתְלַבֶּנֶת. וְסוֹד הַדָּבָר - (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וּמַה שֶּׁהָיְתָה אוֹתִיּוֹת אֲדנָי דִּין, אֲדֻמָּה בִּגְבוּרָה, שֶׁשָּׁם הַבִּינָה - הִתְלַבְּנָה מִצַּד הַחֶסֶד, שֶׁשָּׁם חָכְמָה, וְחָזְרָה אוֹתִיּוֹת יְהֹוָה.</p>\n<p>וּמַה גָּרַם לְהִתְהַפֵּךְ מִדִּין לְרַחֲמִים? צַדִּיקִים גְּמוּרִים, שֶׁהַלְּבָנָה מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע, הַקְּלִפָּה שֶׁלָּהּ הִיא חֹשֶׁךְ, אִם בַּהֶרֶת שְׁחוֹרָה, הִיא יֵצֶר הָרָע, שִׁפְחָה. (ויקרא יג) וּשְׁפָלָה אֵינֶנָּה, וְהִיא כֵהָה. וְאֵין לָהּ מִשֶּׁלָּהּ אֶלָּא אוֹתוֹ חוּט שֶׁמֵּאִיר בָּהּ, שֶׁהוּא לִוָּה אוֹתָהּ בַּלַּיְלָה, שֶׁהִיא גָּלוּת. וְעוֹבֵר מִמֶּנָּה בַּיּוֹם, שֶׁהוּא עוֹלָם הַבָּא, שֶׁבּוֹ (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>\n<p>אֲבָל הַלְּבָנָה שֶׁל עֵץ הַחַיִּים, אוֹתָהּ נְקֻדָּה שֶׁבִּפְנִים מִמֶּנָּה, הִיא כִּמְקוֹר הַמַּעְיָן שֶׁאֵין לוֹ הֶפְסֵק, שֶׁכָּתוּב בָּהּ (ישעיה נח) וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו. וְנִקְרֵאת אַיֶּלֶת אֲהָבִים מִצַּד הַחֶסֶד, כְּלוֹמַר (ירמיה לא) אַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד. וּשְׁתֵּי קַרְנַיִם יֵשׁ לָהּ מִן הָאוֹר, כְּדֻגְמָא זוֹ (ציור) לִפְעָמִים הָאַחַת גְּבוֹהָה מִן הַשְּׁנִיָּה כְּדֻגְמָא זוֹ (ציור) לִפְעָמִים הַקַּרְנַיִם הֵן שָׁווֹת. (ציור) (ע\"כ רעיא מהימנא).</p>"],[9522012547,"<p>וּבַחֹדֶשׁ הָרִאשׁוֹן וְגוֹ'. רַבִּי אַבָּא פָּתַח, (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם כֵּן נַפְשִׁי תַעֲרֹג אֵלֶיךְ אֱלֹהִים. פָּסוּק זֶה פֵּרְשׁוּהוּ, כָּתוּב כָּאן אַיָּל, וְכָתוּב שָׁם אַיֶּלֶת. מִשּׁוּם שֶׁיֵּשׁ זָכָר וְיֵשׁ נְקֵבָה (ואף על גב שיש זכרונקבה, הכלאחד. האילהזה, הואנקראזכר, והוא נקרא נקבה. זהו שכתוב כאיל תערג, ולא כתוב יערג. והכל אחד. אילת השחר).</p>\n<p>מַהִי אַיֶּלֶת הַשַּׁחַר? אֶלָּא זוֹהִי חַיָּה אַחַת רַחֲמָנִית שֶׁאֵין בְּכָל חַיּוֹת הָעוֹלָם רַחֲמָנִית כְּמוֹתָהּ. מִשּׁוּם שֶׁבְּשָׁעָה שֶׁדְּחוּקָה לָהּ הַשָּׁעָה וּצְרִיכָה לְמָזוֹן לָהּ וּלְכָל הַחַיּוֹת, הִיא הוֹלֶכֶת לְמֵרָחוֹק לְדֶרֶךְ רְחוֹקָה, וּמְבִיאָה וּמוֹבִילָה מָזוֹן, וְלֹא רוֹצָה לֶאֱכֹל עַד שֶׁתָּבֹא וְתַחֲזֹר לִמְקוֹמָהּ. מַדּוּעַ? כְּדֵי שֶׁיִּתְאַסְּפוּ אֶצְלָהּ שְׁאָר הַחַיּוֹת וּתְחַלֵּק לָהֶן מֵאוֹתוֹ מָזוֹן. וְכַאֲשֶׁר מַגִּיעָה, מִתְאַסְּפוֹת אֶצְלָהּ כָּל שְׁאָר הַחַיּוֹת, וְהִיא עוֹמֶדֶת בָּאֶמְצַע וּמְחַלֶּקֶת לְכָל אַחַת וְאַחַת. וְסִימָן לַדָּבָר - (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגוֹ'. וּמִמַּה שֶּׁמְּחַלֶּקֶת לָהֶן הִיא שְׂבֵעָה, כְּאִלּוּ אָכְלָה יוֹתֵר אֹכֶל מִכֻּלָּן. (מתי מחלקת להן, ').</p>\n<p>וְכַאֲשֶׁר יַגִּיעַ הַבֹּקֶר שֶׁנִּקְרָא שַׁחַר, יַגִּיעַ לָהּ חֶבְלֵי גָּלוּת. וּמִשּׁוּם זֶה נִקְרֵאת אַיֶּלֶת הַשַּׁחַר, עַל שֵׁם שַׁחֲרוּת הַבֹּקֶר. שֶׁיֵּשׁ לָהּ כְּאֵבִים כְּמוֹ הַיּוֹלֶדֶת. זֶהוּ שֶׁכָּתוּב (ישעיה כו) כְּמוֹ הָרָה תַקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ וְגוֹ'.</p>\n<p>מָתַי מְחַלֶּקֶת לָהֶן? כַּאֲשֶׁר הַבֹּקֶר רוֹצֶה לָבא, בְּעוֹד שֶׁהוּא לַיְלָה וְהַשַּׁחֲרוּת עוֹלָה לְהָאִיר, כְּמוֹ שֶׁנֶּאֱמַר וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגוֹ'. כֵּיוָן שֶׁהֵאִיר הַבֹּקֶר, כֻּלָּם שְׂבֵעִים בַּמָּזוֹן שֶׁלָּהּ.</p>\n<p>אָז קוֹל אֶחָד מִתְעוֹרֵר בְּאֶמְצַע הָרָקִיעַ, קוֹרֵא בְּכֹחַ וְאוֹמֵר: קְרוֹבִים הִכָּנְסוּ לִמְקוֹמְכֶם! רְחוֹקִים צְאוּ! כָּל אֶחָד וְאֶחָד יֵאָסֵף לִמְקוֹמוֹ הָרָאוּי לוֹ. כֵּיוָן שֶׁהֵאִיר הַשֶּׁמֶשׁ, כָּל אֶחָד וְאֶחָד נֶאֱסָף לִמְקוֹמוֹ. זֶהוּ שֶׁכָּתוּב (תהלים קד) תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן וְגוֹ'. וְהִיא הוֹלֶכֶת בַּיּוֹם, וּמִתְגַּלֵּית בַּלַּיְלָה, וּמְחַלֶּקֶת בַּבֹּקֶר. וְלָכֵן נִקִרֵאת אַיֶּלֶת הַשַּׁחַר.</p>\n<p>לְבַסּוֹףֹ מִתְגַּבֶּרֶת כְּגִבּוֹר וְהוֹלֶכֶת, וְנִקְרֵאת אַיָּל. לְאֵיזֶה מָקוֹם הוֹלֶכֶת? הוֹלֶכֶת שִׁשִּׁים פַּרְסָאוֹת מֵאוֹתוֹ מָקוֹם שֶׁיָּצְאָה, וְנִכְנֶסֶת לְתוֹךְ הַר שֶׁל חֹשֶׁךְ. (ומשם מריחה מזון) הוֹלֶכֶת בְּתוֹךְ אוֹתוֹ הַר שֶׁל חֹשֶׁךְ, וּמֵרִיחַ אֶת רַגְלֶיהָ נָחָשׁ אֶחָד עֲקַלָּתוֹן, וְהוֹלֵךְ לְמַרְגְּלוֹתֶיהָ. וְהִיא עוֹלָה מִשָּׁם אֵצֶל הַר שֶׁל אוֹר. כֵּיוָן שֶׁמַּגִּיעָה שָׁם, מְזַמֵן לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא נָחָשׁ אֶחָד, וְיוֹצֵא וְנִלְחָם זֶה בָּזֶה, וְהִיא נִצּוֹלֵית. וּמִשָּׁם נוֹטֶלֶת מָזוֹן וְשָׁבָה לִמְקוֹמָהּ בַּחֲצוֹת הַלַּיְלָה. וּמֵחֲצוֹת לַיְלָה מַתְחִילָה לְחַלֵּק, עַד שֶׁעוֹלָה שַׁחֲרוּת הַבֹּקֶר. כֵּיוָן שֶׁמֵּאִיר הַיּוֹם, הוֹלֶכֶת וְלֹא מִתְרָאָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וּבְשָׁעָה שֶׁהָעוֹלָם צָרִיךְ לְמָטָר, מִתְאַסְּפוֹת אֶצְלָהּ כָּל שְׁאָר הַחַיּוֹת, וְהִיא עוֹלָה לְרֹאשׁ הַר גָּבוֹהַּ, וּמַכְנִיסָה רֹאשָׁהּ בֵּין בִּרְכֶּיהָ, וּבוֹכָה בְּכִיָּה אַחַר בְּכִיָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ קוֹלָהּ וּמִתְמַלֵּא רַחֲמִים וְחָס עַל הָעוֹלָם. וְהִיא יוֹרֶדֶת מֵרֹאשׁ הָהָר, וְרָצָה, וּמַסְתִּירָה עַצְמָהּ, וְכָל שְׁאָר הַחַיּוֹת רוֹדְפוֹת אַחֲרֶיהָ וְלֹא מוֹצְאוֹת אוֹתָהּ. זֶהוּ שֶׁכָּתוּב (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם. מַהוּ עַל אֲפִיקֵי מָיִם? עַל אֲפִיקֵי מַיִם - מֵאֵלּוּ שֶׁהִתְיַבְּשׁוּ, וְהָעוֹלָם צָמֵא לְמַיִם, וְאָז תַּעֲרֹג.</p>\n<p>בְּשָׁעָה שֶׁמִּתְעַבֶּרֶת, נִסְתֶּמֶת. כֵּיוָן שֶׁמַּגִּיעַ זְמַנָּהּ לֵילֵד, בּוֹכָה וּמְרִימָה קוֹלוֹת, קוֹל אַחַר קוֹל, עַד שִׁבְעִים קוֹלוֹת כְּחֶשְׁבּוֹן תֵּבוֹת שֶׁל מִזְמוֹר (תהלים כ) יַעַנְךְ ה' בְּיוֹם צָרָה, שֶׁהִיא שִׁירָה שֶׁל הַמְעֻבֶּרֶת הַזֹּאת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ לָהּ וּמָצוּי אֶצְלָהּ. וְאָז מוֹצִיא נָחָשׁ אֶחָד גָּדוֹל מִתּוֹךְ הָרֵי הַחֹשֶׁךְ, וּבָא בֵּין הֶהָרִים, פִּיו מְלַחֵךְ בְּעָפָר, מַגִּיעַ עַד אַיָּל זֶה, וּבָא וְנוֹשֵׁךְ לָהּ בְּאוֹתוֹ מָקוֹם פַּעֲמַיִם.</p>\n<p>פַּעַם רִאשׁוֹנָה יוֹצֵא דָּם, וְהִיא לוֹחֶכֶת. פַּעַם שְׁנִיָּה יוֹצֵא מַיִם, וְשָׁתוּ כָּל אוֹתָן הַחַיּוֹת שֶׁבֶּהָרִים, וְנִפְתַּחַת וְיוֹלֶדֶת. וְסִימָנְךְ - (במדבר כ) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. וְכָתוּב וַתֵּשְׁתְּ הָעֵדָה וּבְעִירָם.</p>\n<p>בְּאוֹתוֹ זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלֶיהָ עַל (מעשה) עִבּוּר שֶׁל נָחָשׁ (של חיה) זֶה, מַה כָּתוּב? (תהלים כט) קוֹל ה' יְחוֹלֵל אַיָּלוֹת וַיֶּחֱשּף יְעָרוֹת וְגוֹ'. קוֹל ה' יְחוֹלֵל אַיָּלוֹת - אֵלּוּ חֲבָלִים וְצִירִים, לְעוֹרֵר אֵלּוּ הַשִּׁבְעִים קוֹלוֹת. מִיָּד - וַיֶּחֱשֹׂף יְעָרוֹת, לְהַעֲבִיר (לעורר) אוֹתוֹ נָחָשׁ וּלְהִתְגַּלּוֹת אוֹתָהּ חַיָּה בֵּינֵיהֶם לָלֶכֶת. וּבְהֵיכָלוֹ, מַהוּ וּבְהֵיכָלוֹ? בְּהֵיכָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל אֵלּוּ הַהֲמוֹנִים פּוֹתְחִים וְאוֹמְרִים כָּבוֹד. מַהוּ כָּבוֹד? (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ.</p>\n<p>וְאִם תֹּאמַר שֶׁלְּשִׁבְעִים שָׁנָה תָּחִיל וְלִשְׁתֵּי שָׁנִים יוֹלֶדֶת, אַחַר אֶלֶף וּמָאתַיִם, כְּחֶשְׁבּוֹן רע\"ב - הֲרֵי כָּתוּב (ישעיה סו) בְּטֶרֶם תָּחִיל יָלָדָה. וְסוֹד הַדָּבָר - (שם סה) וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה עוֹד וְגוֹ'. וּמַהוּ (היום) בְּטֶרֶם? אֶלָּא קֹדֶם שֶׁיִּשָּׁלְמוּ שִׁבְעִים וּשְׁתַּיִם שָׁנִים אַחַר אֶלֶף וּמָאתַיִם אֵלּוּ חֶבְלֵי הַיּוֹלֶדֶת, יִתְגַּלּוּ שְׁנֵי מְשִׁיחִים בָּעוֹלָם. וּבְאוֹתוֹ הַזְּמַן נֶאֱמַר, (תהלים כט) וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד, וּכְבָר פֵּרְשׁוּהוּ, (משלי ג) כָּבוֹד חֲכָמִים יִנְחָלוּ.</p>\n<p>בְּאוֹתָהּ שָׁעָה אֵלּוּ בַּעֲלֵי הַתּוֹרָה יִהְיוּ נִכְבָּדִים. אֵלּוּ שֶׁסָּבְלוּ כַּמָּה חֲבָלִים וְצִירִים כְּמוֹ הַיּוֹלֶדֶת, וְהָיוּ מְבֻזִּים בֵּין עַמֵּי הָאָרֶץ - יִהְיוּ נִכְבָּדִים. וּמִיָּד - (תהלים כט) ה' לַמַּבּוּל יָשָׁב - לָרְשָׁעִים. אֵין מַבּוּל, אֶלָּא דִּינִים שֶׁל מַבּוּל. כְּמוֹ שֶׁנִּפְתְּחוּ מַעְיְנוֹת תְּהוֹם וַאֲרֻבֹּת הַשָּׁמַיִם נִפְתָּחוּ בִּימֵי הַמַּבּוּל, אַף כָּאן יִתְעוֹרְרוּ דִּינִים עֲלֵיהֶם לְמַעְלָה וּלְמַטָּה, עַד שֶׁאֵין סוֹף וְתַכְלִית. וְכָל הַבִּזּוּיִים וְהַבּוּשָׁה שֶׁעָשׂוּ אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם לְשֵׁם ה' וּלְעַמּוֹ, וְכַמָּה חֲרָפוֹת שֶׁסָּבְלוּ יִשְׂרָאֵל מֵהֶם עַל שֵׁם ה' - מִכֻּלָּם יִקַּח הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמָה, וְעַל זֶה נִקְרָא אֶצְלָם, (נחום א) נֹקֵם ה' וְנוֹטֵר וּבַעַל חֵמָה.</p>"],[9522012548,"<p>וּבַחֹדֶשׁ הָרִאשׁוֹן, מִי הוּא רִאשׁוֹן? זֶה נִיסָן. שָׁם הוֹלִידָה אוֹתָהּ חַיָּה, לְקַיֵּם מַה שֶּׁפֵּרְשׁוּ בַּעֲלֵי הַמִּשְׁנָה, בְּנִיסָן נִגְאָלוּ וּבְנִיסָן עֲתִידִים לְהִגָּאֵל. וּבְי\"ד שֶׁלּוֹ, (שמות יז) וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ. שָׁם נִשְׁבַּע לְהַעֲבִיר מֵהָעוֹלָם זַרְעוֹ שֶׁל עֵשָׂו עֲמָלֵקִיִּים. בְּאוֹתוֹ זְמַן נֶאֱמַר, (שם יב) משכו וקחו לכם צאן למשפחתיכם ושחטו הפסח. משכו - (הושע ז) משך ידו את לצצים.</p>\n<p>בְּאוֹתוֹ זְמַן, כֹּה אָמַר ה' לָרוֹעִים הַפּוֹשְׁעִים בִּי. וְאוֹמֵר, (יחזקאל יג) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ. וְאֵלּוּ הֵם רוֹעֵי הַצֹּאן, פַּרְנְסֵי הַדּוֹר. וּמִשּׁוּם זֶה נֶאֱמַר עֲלֵיהֶם, (הושע ב) הִנֵּה אָנֹכִי מְפַתֶּיהָ וְהֹלַכְתִּיהָ הַמִּדְבָּר. (יחזקאל כ) וְנִשְׁפַּטְתִּי אִתְּכֶם וְגוֹ', כַּאֲשֶׁר נִשְׁפַּטְתִי אֶת אֲבוֹתֵיכֶם. שֶׁהָרַג אוֹתָם בְּמַכַּת חֹשֶׁךְ. (ע\"כ רעיא מהימנא).</p>\n<p>וּבַחֹדֶשׁ הָרִאשׁוֹן (במדבר כח), מִיהוּ הַחֹדֶשׁ הָרִאשׁוֹן? זֶהוּ חֹדֶשׁ שֶׁזּוֹ הַחַיָּה מִתְגַּלֵּית בּוֹ וּמִתְחַזֶּקֶת בּוֹ, וְיוֹצֵאת לָעוֹלָם בְּאַרְבָּעָה עָשָׂר יוֹם. בְּאַרְבָּעָה עָשָׂר - אֵלּוּ שְׁאָר הַחַיּוֹת שֶׁהֵן י' י' לְכָל צַד, בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם. וּבְסִפְרֵי הָרִאשׁוֹנִים, הוּא י', וְאַחַת לְכָל צַד לְאַרְבָּעָה צְדָדִים, וְהֵן אַרְבַּע עֶשְׂרֵה. כֵּיוָן שֶׁהֵן אַרְבַּע, מִתְחַבְּרוֹת וְנִתְקָנוֹת עִם אֵלּוּ הָעֶשֶׂר שֶׁבְּצַד יָמִין, וְאָז י\"ד בְּשִׂמְחָה לְתַקֵּן חַיָּה זוֹ (לתקן הלבנה חיה זו) בְּתִקּוּנֶיהָ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, וַדַּאי כָּךְ הוּא. וּבֹא רְאֵה, כָּתוּב (שמות יב) מִשְׁכוּ וּקְחוּ לָכֶם צֹאן וְגוֹ'. מִשְׁכוּ, (בחבור הקדמון) מַהוּ מִשְׁכוּ? כְּמִי שֶׁמּוֹשֵׁךְ מִמָּקוֹם אַחֵר לְמָקוֹם זֶה. מִשְׁכוּ יָמִים עֶלְיוֹנִים לְגַבֵּי יָמִים תַּחְתּוֹנִים. יָמִים עֶלְיוֹנִים הֵם שס\"ו, כְּחֶשְׁבּוֹן מִשְׁכוּ. יָמִים תַּחְתּוֹנִים, פְּעָמִים שֶׁהֵם שנ\"ה. וּבִזְמַן שֶׁמְּאִירָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, עוֹלִים לִהְיוֹת אֵלּוּ הַיָּמִים שס\"ה, כְּחֶשְׁבּוֹן \"מִשְׁכוּ\" חָסֵר אֶחָד.</p>\n<p>מִשְׁכוּ יָמִים עֶלְיוֹנִים אֵצֶל יָמִים תַּחְתּוֹנִים לִהְיוֹת כֻּלָּם כְּאֶחָד בְּחִבּוּר אֶחָד. וּמִיהוּ שֶׁמּוֹשֵׁךְ אוֹתָם? אֵלּוּ עֶשֶׂר שֶׁלְּצַד יָמִין, שֶׁכָּתוּב בֶּעָשׂוֹר. בֶּעָשׂוֹר?! בַּעֲשָׂרָה הָיָה צָרִיךְ לִכְתֹּב! מַהוּ בֶּעָשׂוֹר? אֶלָּא תֵּשַׁע הֵם לְכָל צַד, וּנְקֻדָּה אַחַת שֶׁהוֹלֶכֶת בָּאֶמְצַע כְּדֻגְמַת זֶה: (ציור למעלה), וְאוֹתָהּ נְקֻדָּה מַשְׁלִימָה לְעֶשֶׂר, וְעַל זֶה נֶאֱמַר בֶּעָשׂוֹר, כְּמוֹ שֶׁנֶּאֱמַר זָכוֹר וְשָׁמוֹר, לְהִשְׁתַּמֵּשׁ בַּעֲשָׂרָה אֵלּוּ הַתִּשְׁעָה יָמִים בְּאוֹתָהּ נְקֻדָּה. לַחֹדֶשׁ הַזֶּה - יָמִים שֶׁלְּצַד יָמִין כְּדֵי לְהִתְחַבֵּר זֹּאת בְּזֶה, לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וּבִזְמַן שֶׁאֵלּוּ הָאַרְבָּעָה נִקְשָׁרִים לְאַרְבָּעָה צְדָדִים (ומתחברים) עִמָּהֶם, אָז יוֹלֶדֶת אוֹתָהּ הַחַיָּה, וְהַנָּחָשׁ הוֹלֵךְ לוֹ. וּבְאוֹתוֹ זְמַן מְקַדְּשִׁים לְמַעְלָה לְאוֹתָהּ חַיָּה וְקוֹרְאִים לָהּ כָּבוֹד. וְאָז מִתְקַדֵּשׁ הַמּוֹעֵד, מַה שֶּׁלֹּא הָיָה עַד עַתָּה, וְעַתָּה קוֹרְאִים לָהּ כָּבוֹד. זֶהוּ שֶׁכָּתוּב (תהלים כט) וּבְהֵיכָלוֹ כֻּלּוֹ אֹמֵר כָּבוֹד.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, דְּבָרִים אֵלּוּ סְתוּמִים, וְצָרִיךְ לִפְתֹּחַ אוֹתָם אֵצֶל הַחֲבֵרִים. שֶׁמִּי שֶׁסּוֹתֵם לָהֶם סִתְרֵי הַתּוֹרָה, הוּא מְצַעֵר אוֹתָם. שֶׁלָּרְשָׁעִים, אוֹרוֹת שֶׁל הַסּוֹדוֹת חוֹזְרִים לִהְיוֹת לָהֶם חֹשֶׁךְ. וְהוּא מָשָׁל לְמָמוֹן שֶׁהוּא גָּנוּז - מִי שֶׁחוֹפֵר אוֹתוֹ עַד שֶׁמּוֹצֵא אוֹתוֹ, וְאֵינוֹ שֶׁלּוֹ, חוֹזֵר בְּשִׂכְלוֹ לְחֹשֶׁךְ וַאֲפֵלָה. וּלְמִי שֶׁהוּא שֶׁלּוֹ, מֵאִיר לוֹ. וּמִשּׁוּם זֶה יֵשׁ לַבֶּן אָדָם לְגַלּוֹת סוֹדוֹת סְתוּמִים שֶׁבַּתּוֹרָה.</p>\n<p>בֶּעָשׂוֹר - תִּשְׁעָה הֵם לְכָל כִּוּוּן, כְּנֶגֶד תִּשְׁעָה חֳדָשִׁים שֶׁל הַיּוֹלֶדֶת, כְּחֶשְׁבּוֹן א\"ח. מַהִי יוֹלֶדֶת? אוֹת ד' מֵאֶחָד. א\"ח, הִיא ט', לְאַרְבָּעָה צְדָדִים שֶׁל אוֹת ד', וְהֵם אַרְבָּעִים. א\"ח - זָכוֹר. ד' - שָׁמוֹר. הֲרֵי אַרְבָּעִים וּשְׁנַיִם.</p>\n<p>נִשְׁאָר כָּבוֹד, שֶׁנֶּאֱמַר בּוֹ בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְהוּא כָּבוֹד ל\"ב, אַרְבַּע פְּעָמִים לְכָל צַד שֶׁל אוֹת ד', הֲרֵי ס\"ד לְאַרְבָּעָה צְדָדִים - רנ\"ו. וּפֵרְשׁוּהוּ - כָּבוֹד לְמַעְלָה, ל\"ב לְמַטָּה. וּמִשּׁוּם זֶה מְיַחֲדִים בְּכָל יוֹם פַּעֲמַיִם, שֶׁאוֹמְרִים בָּהֶם פַּעֲמַיִם כָּבוֹד, שֶׁהֵם ס\"ד. וּפַעֲמַיִם ד' ד' מֵאֶחָד - הֲרֵי ע\"ב. הֲרֵי ד' שֶׁל אֶחָ\"ד הִיא שְׁלֵמוּת שֶׁל מ\"ב שֵׁמוֹת, וּשְׁלֵמוּת שֶׁל ע\"ב שֵׁמוֹת. וּמִשּׁוּם זֶה אוֹמְרִים בְּמִזְמוֹר לְדָוִד, (תהלים כד) מִי זֶה מֶלֶךְ הַכָּבוֹד ה' עִזּוּז וְגִבּוֹר. וּבְפַעַם שְׁנִיָּה אוֹמְרִים, מִי הוּא זֶה מֶלֶךְ הַכָּבוֹד. (ע\"כ רעיא מהימנא).</p>\n<p>זהר: מִיהוּ הֵיכָלוֹ? זֶה הַהֵיכָל הָעֶלְיוֹן הַפְּנִימִי שֶׁשָּׁם מִתְקַדֵּשׁ הַכֹּל. שָׁם מְקַדְּשִׁים לְמִי שֶׁרָאוּי לְהִתְקַדֵּשׁ. אֵיךְ מְקַדְּשִׁים אוֹתוֹ בְּאוֹתוֹ הֵיכָל? בָּרִאשׁוֹנָה נִפְתָּחִים שְׁעָרִים, וּמַפְתֵּחַ אֶחָד סָתוּם מְתַקֵּן וּפוֹתֵחַ שַׁעַר אֶחָד, לְצַד דָּרוֹם, וְאָז נִכְנָס הַכֹּהֵן הַגָּדוֹל בְּאוֹתוֹ פֶּתַח וּמִזְדָּרֵז לַחְגֹּר אַבְנֵטוֹ וּמַלְבּוּשָׁיו, וּמִתְעַטֵּר בַּעֲטָרָה שֶׁל קְדֻשָּׁה, וְלוֹבֵשׁ חֹשֶׁן וְאֵפוֹד, וּמְעִיל שֶׁל שִׁבְעִים פַּעֲמוֹנִים וְרִמּוֹנִים, שֶׁהֵם (שמות כח) פַּעֲמוֹן זָהָב וְרִמּוֹן. וְצִיץ נֵזֶר הַקֹּדֶשׁ עַל מִצְחוֹ, וְנִקְרָא צִיץ נֵזֶר הַקֹּדֶשׁ, וּמִתְקַשֵּׁט בְּאַרְבָּעָה בִּגְדֵי זָהָב וּבְאַרְבָּעָה בִּגְדֵי לָבָן. וְעַל אוֹתוֹ צִיץ יֵשׁ מ\"ב אוֹתִיּוֹת שֶׁלּוֹהֲטוֹת בּוֹ וְנוֹצְצוֹת עָלָיו, וּמֵאִיר כָּל אוֹתוֹ הֵיכָל בְּאוֹרוֹת עֶלְיוֹנִים.</p>\n<p>מִסְתּוֹבֵב אוֹתוֹ מַפְתֵּחַ וּפוֹתֵחַ צַד אַחֵר שֶׁבְּצַד צָפוֹן, וְאָז נִכְנָס לֵוִי, מַעֲשֵׂר שֶׁל יַעֲקֹב שֶׁהִפְרִישׁ לְהַקָּדוֹשׁ בָּרוּךְ הוּא. וְכִנּוֹר שֶׁל עֲשָׂרָה נִימִים עִמּוֹ, וּמִתְקַשֵּׁט בְּקִשּׁוּטָיו, וְאָז סוֹבֵב הַמַּפְתֵּחַ, וּפוֹתֵחַ בְּאוֹתוֹ הֵיכָל שַׁעַר אֶחָד, אוֹתוֹ שַׁעַר שֶׁעוֹמֵד בָּאֶמְצַע. עַמּוּד שֶׁלְּצַד מִזְרָח עוֹלֶה וּמִתְקַשֵּׁט בְּשִׁבְעִים עִטּוּרִים, וּמִתְקַשֵּׁט בְּאַרְבַּע אוֹתִיּוֹת, שֶׁהֵם שְׁתֵּים עֶשְׂרֵה. וּמִתְקַשֵּׁט בַּחֲקִיקוֹת שֶׁל מָאתַיִם וְשִׁבְעִים אֶלֶף עוֹלָמוֹת, וּמִתְקַשֵּׁט בְּקִשּׁוּטִים שֶׁל סוֹף הָעוֹלָם עַד סוֹף הָעוֹלָם בְּכַמָּה מַלְבּוּשֵׁי כָבוֹד, בְּכַמָּה קִשּׁוּטִים קְדוֹשִׁים.</p>\n<p>וּמִסְתּוֹבֵב אוֹתוֹ מַפְתֵּחַ, וּפוֹתֵחַ לוֹ כָּל הַשְּׁעָרִים הַגְּנוּזִים, וְכָל הַשְּׁעָרִים הַקְּדוֹשִׁים הַנִּסְתָּרִים, וּמִתְקַדֵּשׁ בָּהֶם, וְעוֹמֵד שָׁם כְּמֶלֶךְ. וּמִתְבָּרֵךְ בְּכַמָּה בְּרָכוֹת, וּמִתְקַשֵּׁט בְּכַמָּה קִשּׁוּטִים. אָז יוֹצְאִים כֻּלָּם בְּחִבּוּר אֶחָד, מִתְקַשְּׁטִים בְּקִשּׁוּטִים כְּמוֹ שֶׁרָאוּי. כֵּיוָן שֶׁיּוֹצְאִים, מְעוֹרֵר אוֹתוֹ בְּקִשּׁוּטָיו.</p>\n<p>אֵיךְ מְמַעֶטֶת עַצְמָהּ מִתּוֹךְ אַהֲבָה שֶׁל הַשִּׁירָה? הִמְעִיטָה עַצְמָהּ מְעַט מְעַט, עַד שֶׁנַּעֲשֵׂית נְקֻדָּה אַחַת. כֵּיוָן שֶׁהִיא הִקְטִינָה עַצְמָהּ (בשירה), אָז כָּתוּב (שמות ב) וַיֵּלֶךְ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. בַּת לֵוִי וַדַּאי, מִצַּד הַשְּׂמֹאל. אֵיךְ אוֹחֵז אוֹתָהּ? מוֹשִׁיט שְׂמֹאלוֹ תַּחַת רֹאשָׁהּ מִתּוֹךְ חִבָּה.</p>\n<p>וְאִם תֹּאמַר, כֵּיוָן שֶׁהִיא נְקֻדָּה אַחַת, אֵיךְ יָכוֹל לֶאֱחֹז בִּנְקֻדָּה קְטַנָּה? אֶלָּא אֵצֶל הָעֶלְיוֹן, כָּל מַה שֶּׁהוּא דָּבָר קָטָן, זֶה שֶׁבַח וְזוֹ מַעֲלָה וּגְדֻלָּה בַּגֹּדֶל הָעֶלְיוֹן. מִיָּד הַכֹּהֵן הַגָּדוֹל מְעוֹרֵר אוֹתָהּ, וְאוֹחֵז בָּהּ וּמְחַבֵּק אוֹתָהּ. שֶׁאִלּוּ הָיְתָה גְּדוֹלָה, לֹא יְכוֹלִים לְהִתְאַחֵד כְּלָל. אֲבָל כֵּיוָן שֶׁמַּקְטִינָה עַצְמָהּ, וְהִיא נְקֻדָּה אַחַת, אָז אוֹחֲזִים בָּהּ וּמַעֲלִים אוֹתָהּ לְמַעְלָה. וְכֵיוָן שֶׁמַּעֲלִים אוֹתָהּ וְיוֹשֶׁבֶת בֵּין שְׁנֵי צְדָדִים אֵלּוּ, אָז אוֹתוֹ עַמּוּד שֶׁעוֹמֵד בָּאֶמְצַע מִתְחַבֵּר עִמָּהּ בְּחִבָּה שֶׁל נְשִׁיקוֹת, בְּאַהֲבָה שֶׁל חִבּוּר אֶחָד. אָז נֶאֱמַר (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל, בָּאַהֲבָה שֶׁל הַנְּשִׁיקוֹת שֶׁמִּתְחַבְּרִים זֶה בָּזֶה בְּלִי פֵרוּד, עַד שֶׁלּוֹקַחַת אֶת הַנֶּפֶשׁ שֵׁל הָעִנּוּגִים כְּמוֹ שֶׁרָאוּי.</p>\n<p>בְּשָׁעָֹה שֶׁלּוֹקַחַת אֶת הַנֶּפֶשׁ שֶׁל הָעִנּוּגִים כְּמוֹ שֶׁרָאוּי וְרוֹצָה לְצַוּוֹת לְחֵילוֹתֶיהָ, מִתְאַסְּפִים כֻּלָּם, וְקוֹרְאִים לָהּ מִתּוֹךְ הַהֵיכָל הַקָּדוֹשׁ: כָּבוֹד כָּבוֹד כָּבוֹד. בַּהֵיכָל הַקָּדוֹשׁ אַבָּא וְאִמָּא פּוֹתְחִים וְאוֹמְרִים: מְקֵדָּשׁ מְקֵדָּשׁ. וְאָז הַלְּבָנָה מִתְקַדֶּשֶׁת כְּמוֹ שֶׁרָאוּי. וְאָז כָּתוּב וּבַחֹדֶשׁ הָרִאשׁוֹן. רִאשׁוֹן וַדַּאי. וְעַל זֶה נֶאֱמַר מִשְׁכוּ וְגוֹ'. וְעַל זֶה נֶאֱמַר בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה. שֶׁמִּתְחַבֶּרֶת הַלְּבָנָה בַּשֶּׁמֶשׁ, וּמַה שֶּׁהָיְתָה לוֹקַחַת נְקֻדָּה אַחַת, כַּאֲשֶׁר יוֹרֶדֶת, מִתְפַּשֶּׁטֶת מְעַט מְעַט וּמִתְמַלֵּאת, וְנַעֲשֵׂית אוֹת ה' מְלֵאָה מִכָּל הַצְּדָדִים, מִתְקַדֶּשֶׁת כְּמוֹ שֶׁרָאוּי.</p>\n<p>מִסְתּוֹבֵב אוֹתוֹ הֵיכָל, וּפוֹתֵחַ שַׁעַר אַחֵר שֶׁל צַד דָּרוֹם (צפון) בְּשִׁבְעִים וּשְׁתַּיִם עֲטָרוֹת. וְאַחַר כָּךְ פּוֹתֵחַ שַׁעַר שְׁלִישִׁי לְצַד מִזְרָח בַּחֲמִשִּׁים (ושנים) אוֹרוֹת שֶׁל חֲמִשִּׁים שַׁעֲרֵי בִינָה. לְבַסּוֹף פּוֹתֵחַ שַׁעַר אַחֵר שֶׁל צַד צָפוֹן (מערב) בְּשִׁבְעִים וּשְׁתַּיִם עֲטָרוֹת, וְכֻלָּם בְּחֶשְׁבּוֹן רמ\"ח תֵּבוֹת שֶׁל פָּרָשִׁיּוֹת קְרִיאַת שְׁמַע. וּמַה שֶּׁבַּהַתְחָלָה הָיְתָה אוֹתָהּ חַיָּה קְטַנָּה, בְּאוֹתוֹ זְמַן נִגְדֶּלֶת. זֶהוּ שֶׁכָּתוּב (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, שֶׁהוּא כָּבוֹד עֶלְיוֹן וְתַחְתּוֹן.</p>\n<p>כַּאֲשֶׁר מַגִּיעַ לְחַ\"י עוֹלָמוֹת, שֶׁבּוֹ ח\"י בִּרְכוֹת הַתְּפִלָּה, וּפָתַח בּוֹ פָּסוּק (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךְ. אָז הָעַמּוּד הָאֶמְצָעִי מִתְחַבֵּר עִמָּהּ בַּחֲבִיבוּת שֶׁל נְשִׁיקוֹת הַשְּׂפָתַיִם, שֶׁהֵם נֵצַח וְהוֹד, וְהַלָּשׁוֹן הוּא צַדִּיק בֵּינֵיהֶם. לְשׁוֹן לִמּוּדִים. בְּאוֹתוֹ זְמַן נֶאֱמַר, (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל. וְאָז קוֹרְאִים לְאוֹתָהּ חַיָּה כָּבוֹד כָּבוֹד, אַבָּא וְאִמָּא, מְקֻדָּשׁ מְקֻדָּשׁ. אָז הַיָּרֵחַ מִתְקַדֵּשׁ כְּמוֹ שֶׁרָאוּי, וְאָז נֶאֱמַר וּבַחֹדֶשׁ הָרִאשׁוֹן, רִאשׁוֹן וַדַּאי.</p>\n<p>וְאָז מִשְׁכוּ. וְעַל זֶה נֶאֱמַר בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה, שֶׁמִּתְחַבֶּרֶת הַלְּבָנָה הַקְּדוֹשָׁה בַּשֶּׁמֶשׁ, שֶׁנֶּאֱמַר בּוֹ (תהלים פד) כִּי שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים (צבאות). וּמַה שֶּׁהָיְתָה נְקֻדָּה קְטַנָּה, (כמו זה) (ציור) מִתְמַלֵּאת בַּלְּבָנָה, וְאָז הוּא חֹדֶשׁ מָלֵא. וְהַלְּבָנָה מִתְמַלֵּאת כְּמוֹ זֶה (ציור), מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. בַּהַתְחָלָה חֲסֵרָה, וְכָעֵת בִּשְׁלֵמוּת. (ע\"כ רעיא מהימנא).</p>\n<p>רַבִּי חִיָּיא פָּתַח, בְּאַרְבָּעָה עָשָׂר יוֹם לַחֹדֶשׁ פֶּסַח וְגוֹ'. שֶׂה שֶׁהוּא פֶּסַח, מַדּוּעַ? אֶלָּא יִרְאָתָם שֶׁל הַמִּצְרִים וֵאלוֹהַּ שֶׁלָּהֶם הָיָה שֶׂה. מִשּׁוּם שֶׁהַמִּצְרִים עוֹבְדִים לְמַזַּל טָלֶה, וּמִשּׁוּם זֶה עוֹבְדִים לַשֶּׂה. בּא וּרְאֵה, כָּתוּב (שמות ח) הֵן נִזְבַּח אֶת תּוֹעֲבַת מִצְרַיִם. מַהִי תּוֹעֲבַת מִצְרַיִם? וְכִי עַל שֶׁשּׂוֹנְאִים אוֹתוֹ כָּתוּב תּוֹעֲבַת מִצְרַיִם? אֶלָּא יִרְאָתָם שֶׁל הַמִּצְרִים וְהָאֱלוֹהַּ שֶׁלָּהֶם נִקְרָא תּוֹעֲבַת מִצְרַיִם, כְּמוֹ שֶׁכָּתוּב (דברים יח) כְּתוֹעֲבֹת הַגּוֹיִם, יִרְאָתָם שֶׁל שְׁאָר הָאֻמּוֹת.</p>\n<p>בֹּא וּרְאֵה חָכְמָתוֹ שֶׁל יוֹסֵף, שֶׁכָּתוּב (בראשית מז) וּמִקְצֵה אֶחָיו לָקַח חֲמִשָּׁה אֲנָשִׁים, וּמְלַמֵּד אוֹתָם לוֹמַר, אַנְשֵׁי מִקְנֶה הָיוּ עֲבָדֶיךְ. וְכִי יוֹסֵף שֶׁהָיָה מֶלֶךְ שֶׁהָיָה שׁוֹלֵט עַל כָּל הָאָרֶץ, וְאָב לְמַלְכוּת, עָשָׂה כָּךְ, וְעָשָׂה לְאֶחָיו שֶׁיִּשְׂנְאוּ אוֹתָם וְלֹא יַחֲשִׁיבוּ אוֹתָם (שיעשו מהם רועי צאן) ?! אֶלָּא וַדַּאי תּוֹעֲבַת מִצְרַיִם, יִרְאָה וֵאלוֹהַּ שֶׁלָּהֶם נִקְרָא כָּךְ, וְעַל זֶה כָּתוּב (שמות ח) הֵן נִזְבַּח אֶת תּוֹעֲבַת מִצְרַיִם.</p>\n<p>אָמַר יוֹסֵף, כָּל מֵיטַב מִצְרַיִם הִיא אֶרֶץ רַעְמְסֵס, וְאוֹתָהּ אֶרֶץ הִפְרִישׁוּ לְיִרְאָתָם, לִרְעוֹת וְלָלֶכֶת בְּכָל תַּעֲנוּגוֹת הָעוֹלָם. וְכָל הַמִּצְרִים הֶחְשִׁיבוּ לְאֵלֶּה שֶׁרוֹעִים לְיִרְאָתָם, כְּיִרְאָתָם. אֶעֱשֶׂה לְאַחַי שֶׁיִּירְשׁוּ אוֹתָהּ אֶרֶץ, וְיִשְׁתַּחֲווּ לָהֶם הַמִּצְרִים, וְיַחֲשִׁיבוּ אוֹתָם כְּמוֹ שֶׁרָאוּי. וְזֶהוּ שֶׁכָּתוּב (בראשית מו) כִּי תוֹעֲבַת מִצְרַיִם כָּל רֹעֵה צֹאן. מַחֲשִׁיבִים אוֹתָם כְּיִרְאָתָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וַהֲרֵי לָמַדְנוּ, כְּמוֹ שֶׁנִּפְרַע הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאֵלּוּ שֶׁעוֹבְדִים לַעֲבוֹדָה זָרָה - כָּךְ נִפְרַע מֵעֲבוֹדָה זָרָה מַמָּשׁ. וְכִי יוֹסֵף עָשָׂה לְאֶחָיו עֲבוֹדָה זָרָה?! אָמַר לוֹ, לֹא עָשָׂה יוֹסֵף לְאֶחָיו עֲבוֹדָה זָרָה, אֶלָּא עָשָׂה לָהֶם שֶׁיִּשְׁלְטוּ עַל הָעֲבוֹדָה זָרָה שֶׁלָּהֶם, וְלִכְפּוֹת הָעֲבוֹדָה זָרָה שֶׁלָּהֶם תַּחַת יְדֵיהֶם וְלִרְדּוֹתָם בְּמַקֵּל. אָמַר יוֹסֵף, אִם יִשְׁלְטוּ אַחַי עַל הָעֲבוֹדָה זָרָה שֶׁלָּהֶם, כָּל שֶׁכֵּן שֶׁיִּשְׁלְטוּ עַל עַצְמָם, וּמִשּׁוּם זֶה הוֹשִׁיב אוֹתָם בְּמֵיטַב הָאָרֶץ וְהִשְׁלִיט אוֹתָם עַל כָּל הָאָרֶץ.</p>\n<p>וְעַל זֶה שֶׂה שֶׁהוּא פֶּסַח - מַדּוּעַ? אֶלָּא יִרְאָתָם שֶׁל הַמִּצְרִים וֵאלוֹהַּ שֶׁלָּהֶם הָיָה הַשֶּׂה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִבֶּעָשׂוֹר לַחֹדֶשׁ קְחוּ אֶת יִרְאָתָם שֶׁל הַמִּצְרִים, וְתִפְשׂוּ אוֹתוֹ, וְיִהְיֶה קָשׁוּר וְתָפוּס בִּתְפִיסָה שֶׁלָּכֶם יוֹם אֶחָד וּשְׁנַיִם וּשְׁלֹשָׁה, וּבַיּוֹם הָרְבִיעִי הוֹצִיאוּ אוֹתוֹ לְדִין וְהֵאָסְפוּ עָלָיו.</p>\n<p>וּבְשָׁעָה שֶׁהַמִּצְרִים הָיוּ שׁוֹמְעִים קוֹל יִרְאָתָם שֶׁתָּפוּס בִּתְפִיסָה שֶׁל יִשְׂרָאֵל וְאֵינָם יְכוֹלִים לְהַצִּיל אוֹתוֹ, הָיוּ בוֹכִים, וְהָיָה קָשֶׁה עֲלֵיהֶם כְּאִלּוּ אֶת עַצְמָם קָשְׁרוּ לַהֲרִיגָה. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִהְיֶה תָּפוּס בִּרְשׁוּתְכֶם יוֹם אַחַר יוֹם - אַרְבָּעָה יָמִים, כְּדֵי שֶׁיִּרְאוּ אוֹתוֹ תָּפוּס, וּבַיּוֹם הָרְבִיעִי הוֹצִיאוּ אוֹתוֹ לַהֲרִיגָה, וְיִרְאוּ אוֹתוֹ הַמִּצְרִים אֵיךְ אַתֶּם עוֹשִׂים בּוֹ דִּין, וְזֶה קָשֶׁה לָהֶם מִכָּל הַמַּכּוֹת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵלּוּ הַדִּינִים שֶׁיַּעֲשׂוּ בְיִרְאָתָם.</p>\n<p>לְבַסּוֹף דָּנִים אוֹתוֹ בְּאֵשׁ, שֶׁכָּתוּב (דברים ז) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אַל תֹּאכְלוּ מִמֶּנּוּ נָא. שֶׁלֹּא יֹאמְרוּ שֶׁבְּרָצוֹן וּבַתַּאֲוָה שֶׁל יִרְאָתֵנוּ אָכְלוּ אוֹתוֹ כָּךְ. אֶלָּא תַּקְּנוּ אוֹתוֹ צָלִי, וְלֹא מְבֻשָּׁל, שֶׁאִם יִהְיֶה מְבֻשָּׁל, יִהְיֶה מֻסְתָּר וְלֹא יִרְאוּ אוֹתוֹ, אֶלָּא תִּקּוּנוֹ שֶׁיִּרְאוּ אוֹתוֹ כָּךְ שָׂרוּף בָּאֵשׁ, כְּדֵי שֶׁיִּהְיֶה רֵיחוֹ נוֹדֵף.</p>\n<p>וְעוֹד, רֹאשׁוֹ עָלָיו כָּפוּף עַל קַרְסֻלָּיו, שֶׁלֹּא יֹאמְרוּ שֶׁחַיָּה אוֹ דָּבָר אַחֵר הוּא, אֶלָּא שֶׁיַּכִּירוּ אוֹתוֹ שֶׁהוּא יִרְאָתָם. וְעוֹד, שֶׁלֹּא יֹאכְלוּ אוֹתוֹ בְּתֵאָבוֹן, אֶלָּא עַל הַשֹּׂבַע, דֶּרֶךְ קָלוֹן וּבִזָּיוֹן וְעוֹד, עֶצֶם לֹא תִשְׁבְּרוּ בוֹ, אֶלָּא שֶׁיִּרְאוּ עַצְמוֹתָיו מֻשְׁלָכוֹת בַּשּׁוּק, וְלֹא יִהְיוּ יְכוֹלִים לְהַצִּיל אוֹתוֹ. וְעַל זֶה כָּתוּב, (במדברלג) וּבֵאלֹהֵיהֶם עָשָׂה ה' שְׁפָטִים. דִּינִים רַבִּים. וְעוֹד נֶאֱמַר, וּמַקֶּלְכֶם בְּיֶדְכֶם, וְלֹא חֶרֶב וְרֹמַח וּשְׁאָר כְּלֵי מִלְחָמָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כְּבָר פֵּרְשׁוּהוּ שֶׁהַמִּצְרִים עוֹבְדִים לְמַזַּל טָלֶה, וּמִשּׁוּם כָּךְ עוֹבְדִים לְשֶׂה. אָמַר רַבִּי יוֹסֵי, אִם כֵּן, יַעַבְדוּ טָלֶה וְלֹא שֶׂה. אָמַר לוֹ, הַכֹּל עוֹבְדִים, אֶלָּא שֶׁמַּזַּל טָלֶה יוֹרֵד וְעוֹלֶה בְּטָלֶה וְשֶׂה, וּמִשּׁוּם זֶה עוֹבְדִים לְכֻלָּם. אָמַר לוֹ, כָּךְ שָׁמַעְתִּי, שֶׁכָּל בְּהֵמָה גְּדוֹלָה (של צאן), יִרְאָה שֶׁלָּהֶם הָיְתָה, וְעַל זֶה הָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל בְּכוֹר בְּהֵמָה. וַהֲרֵי נִתְבָּאֵר שֶׁאֵלּוּ הֵן מַדְרֵגוֹת שֶׁלְּמַעְלָה שֶׁנִּקְרָאוֹת כָּךְ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (שמות יב) כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ, וְכָתוּב (שם יג) לֹא יֵאָכֵל חָמֵץ. אֶלָּא זֶה זָכָר, וְזוֹ נְקֵבָה. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, בָּזֶה כָּתוּב לֹא תֹאכֵלוּ, וּבָזֶה כָּתוּב לֹא יֵאָכֵל. מַדּוּעַ לֹא כָתוּב לֹא תֹאכְלוּ? אֶלָּא נְקֵבָה שֶׁהִיא נוֹטָה מִדַּרְכָּהּ - וַדַּאי בְּאַזְהָרָה. זָכָר שֶׁהוּא אָחוּז בְּחוּט שֶׁל טָהֳרָה יוֹתֵר - בְּבַקָּשָׁה. וְעַל זֶה כָּתוּב לֹא יֵאָכֵל, לֹא תֹאכֵלוּ.</p>\n<p>אָמַר לוֹ, אַבָּא, וַהֲרֵי כָּתוּב (דברים טז) לֹא תֹאכַל עָלָיו חָמֵץ. אָמַר לוֹ, הַרְבֵּה תֵּבוֹת יְתֵרוֹת לִכְבוֹדוֹ שֶׁל הַקָּרְבָּן. אֲבָל בַּתְּחִלָּה בַּקָּשָׁה - לֹא יֵאָכֵל, אֲבָל לְבַסּוֹף בְּאַזְהָרָה - לֹא תֹאכֵלוּ, שֶׁהוּא קָשֶׁה מִשְּׁנֵיהֶם. מַחְמֶצֶת, מַה טַּעֲמָהּ? מִשּׁוּם שֶׁרֵיחַ שֶׁל מָוֶת יֵשׁ שָׁם. חָמֵץ - זָכָר, מַחְמֶצֶת - נְקֵבָה. (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת, בְּרֹאשׁ וּבְסוֹף הַתֵּבָה תִּמְצָא אוֹתָהּ. וּמִשּׁוּם זֶה מִי שֶׁאוֹכֵל חָמֵץ בְּפֶסַח הוּא מַקְדִּים לְעַצְמוֹ הַמָּוֶת, וְשֶׁיֵּדַע שֶׁהוּא מֵת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (שמות יב) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא.</p>\n<p>מַצָה, מַדּוּעַ (נקראת מצה) ? אֶלָּא כָּךְ שָׁנִינוּ, שַׁדַּי - מִשּׁוּם שֶׁאָמַר לְעוֹלָמוֹ דַּי, שֶׁיֹּאמַר לְצָרוֹתֵינוּ דַּי. אַף כָּךְ מַצָּה, מִשּׁוּם שֶׁהִיא מְשַׁדֶּדֶת וּמַבְרִיחָה לְכָל צְדָדִים רָעִים וְעוֹשָׂה קְטָטָה בֵּינֵיהֶם כְּדֻגְמַת שֵׁם שַׁדַּי שֶׁבַּמְּזוּזָה, שֶׁמַּבְרִיחַ לְשֵׁדִים וּמַזִּיקִים שֶׁבַּשַּׁעַר - אַף כָּךְ הִיא מַבְרִיחָה אוֹתָם מִכָּל מִשְׁכְּנֵי הַקְּדֻשָּׁה, וְעוֹשָׂה מְרִיבָה וּקְטָטוֹת בָּהֶם, כְּמוֹ שֶׁנֶּאֱמַר (שמות יז) מַסָּה וּמְרִיבָה. וְעַל זֶה כָּתוּב מַצָּה, וַהֲרֵי מַסָּה נִכְתֶּבֶת בָּאוֹת סָמֶ\"ךְ? אֶלָּא תַּרְגּוּם שֶׁל מַסָּה הוּא מַצּוּתָא.</p>\n<p>אָמַר הָרוֹעָה הַנֶּאֱמָן, כְּמוֹ לָשׁוֹן שֶׁהוּא מַקֵּל לְכָל אַנְשֵׁי בֵיתוֹ, וְהוּא לָשׁוֹן צוּרַת אוֹת ו', וְהוּא מַטֶּה שֶׁבּוֹ עֶשֶׂר אוֹתִיּוֹת, וּבוֹ הִכָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יָדוֹ עֶשֶׂר מַכּוֹת. וּמִשּׁוּם שֶׁכָּל הַמַּכּוֹת הָיוּ מִצַּד שֶׁל ה' ה', אָמַר רַבִּי עֲקִיבָא, מִנַּיִן שֶׁכָּל מַכָּה וּמַכָּה שֶׁהֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַמִּצְרִים בְּמִצְרַיִם הָיְתָה שֶׁל חָמֵשׁ מַכּוֹת וְכוּ', אֱמֹר מֵעַתָּה וְכוּ'. וְאוֹת ה' עוֹלָה בְּאוֹת י' לַחֲמִשִּׁים מַכּוֹת. חָמֵשׁ פְּעָמִים חֲמִשִּׁים הֵם מָאתַיִם וַחֲמִשִּׁים. וּמִשּׁוּם זֶה נֶאֱמַר, וְעַל הַיָּם לָקוּ מָאתַיִם וַחֲמִשִּׁים מַכּוֹת.</p>\n<p>אָמַר יוֹסֵף, כָּל טוּב אֶרֶץ מִצְרַיִם הִיא רַעְמְסֵס, וְאוֹתָהּ אֶרֶץ הִפְרִישׁוּ לְיִרְאָתָם, לִרְעוֹת וּלְהַלֵּךְ בְּכָל תַּעֲנוּגוֹת הָעוֹלָם. וְכָל הַמִּצְרִים הֶחְשִׁיבוּ לְאוֹתָם שֶׁרוֹעִים לְיִרְאָתָם - כְּיִרְאָתָם. וְזֶה מַה שֶּׁשָּׁאַל יוֹסֵף מִפַּרְעֹה, שֶׁיִּשְׁלְטוּ אֶחָיו עַל יִרְאָתָם שֶׁל הַמִּצְרִים, שֶׁכְּפוּיִים תַּחַת יָדָיו כַּעֲבָדִים אַחַר מַלְכֵיהֶם, לִהְיוֹת כֻּלָּם נִכְפִּים תַּחַת שֵׁם יְהֹוָה מִצִּדָּם, וְלֹא יִשְׁלֹט בָּעוֹלָם אֶלָּא שֵׁם יְהֹוָה, וְיִכָּנְעוּ כָּל מְמֻנִּים תַּחַת יָדָיו.</p>\n<p>וּלְהַרְאוֹת לָהֶם שֶׁהוּא עָתִיד לְהִפָּרַע מֵהֶם, זֶהוּ שֶׁכָּתוּב (שמות יב) וּבְכָל אֱלֹהֵי מִצְרַיִם אֶעֱשֶׂה שְׁפָטִים אֲנִי יְהֹוָה. כֵּיוָן שֶׁהִטְעוּ לַבְּרִיּוֹת וְעָשׂוּ עַצְמָם אֱלוֹהוּת, וּמִשּׁוּם שֶׁטָּלֶה, מְמֻנֶּה שֶׁלּוֹ, הוּא גָּדוֹל עַל כָּל הַמְמֻנִּים שֶׁל אֱלֹהִים אֲחֵרִים, צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, (שמותיב) וְיִקְחוּ לָהֶם אִישׁ שֶׂה לְבֵית אָבוֹת שֶׂה לַבָּיִת, וְהִשְׁלִיט אוֹתָם עָלָיו, וְתָפְסוּ אוֹתוֹ תָּפוּס בַּתְּפִיסָה שֶׁלָּהֶם יוֹם וּשְׁנַיִם וְשָׁלֹשׁ, וּלְאַחַר זֶה הוֹצִיאוּ לוֹ לְדִין לְעֵינֵי כָּל מִצְרַיִם, לְהַרְאוֹת שֶׁהָאֱלוֹהַּ שֶׁלָּהֶם בִּרְשׁוּת יִשְׂרָאֵל לַעֲשׂוֹת בּוֹ דִּין.</p>\n<p>בִּגְלַל זֶה נֶאֱמַר, (שם) אַל תֹּאכְלוּ מִמֶּנּוּ נָא וּבָשֵׁל מְבֻשָּׁל בַּמָּיִם כִּי אִם צְלִי אֵשׁ רֹאשׁוֹ עַל כְּרָעָיו וְעַל קִרְבּוֹ, לִהְיוֹת נִדּוֹן בְּאֵשׁ צָלִי, וְצִוָּה לִזְרֹק לְעַצְמוֹתָיו בַּשּׁוּק בְּבִזָּיוֹן. וּמִשּׁוּם זֶה נֶאֱמַר, (שם) וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ. וְצִוָּה לַיּוֹם הָרְבִיעִי, אַחַר שֶׁהָיָה תָּפוּס שְׁלֹשָׁה יָמִים קָשׁוּר, לַעֲשׂוֹת בּוֹ דִּין. וְזֶה קָשֶׁה לָהֶם מִכָּל נְגָעִים שֶׁהִכָּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי הָרוֹעֶה הַנֶּאֱמָן. וְלֹא עוֹד, אֶלָּא שֶׁצִּוָּה שֶׁלֹּא לֶאֱכֹל אוֹתוֹ בְּתַאֲוָה. וּמִיָּד שֶׁרָאוּ עַצְמוֹתָיו בַּשּׁוּק וְלֹא יָכְלוּ לְהַצִּילוֹ, זֶה קָשֶׁה לָהֶם מֵהַכֹּל. וְלֹא עוֹד, אֶלָּא שֶׁנֶּאֱמַר בָּהֶם (שם) וּמַקֶּלְכֶם בְּיֶדְכֶם, לִכְפּוֹת כָּל יִרְאָתָם שֶׁל הַמִּצְרִים תַּחַת יְדֵיהֶם. וּמִשּׁוּם שֶׁהֵם בְּכוֹרוֹת מְמֻנִּים, כָּתוּב (שם) וַה' הִכָּה כָל בְּכוֹר.</p>\n<p>אַחַר כָּל זֶּה, כָּתוּב (שם יג) לֹא יֵרָאֶה חָמֵץ, (דברים טז) שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עֹנִי. וְכָתוּב (שמות יב) כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ. אָמַר הָרוֹעֶה הַנֶּאֱמָן, מַדּוּעַ צִוָּה שֶׁלֹּא לֶאֱכֹל חָמֵץ שִׁבְעַת יָמִים וְלֶאֱכֹל בָּהֶם מַצָּה? וּמַדוּעַ לֹא יֵאָכֵל, וּמַדּוּעַ נֶאֱמַר לֹא תֹאכֵלוּ? אֶלָּא שִׁבְעָה כּוֹכְבֵי לֶכֶת, וְהֵם: שצ\"ם חנכ\"ל. וְהֵם מִצַּד שֶׁל טוֹב וָרָע, אוֹר הַפְּנִימִי, מַצָּה. קְלִפָּה שֶׁבַּחוּץ - חָמֵץ. וְהֵם, חָמֵץ - זָכָר. מַחְמֶצֶת - נְקֵבָה.</p>\n<p>מַצָה שֶׁבִּפְנִים - שְׁמוּרָה. וְהֵם (אסתר ב) שֶׁבַע הַנְּעָרוֹת הָרְאֻיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ. וְנֶאֱמַר עֲלֵיהֶם (שמות יב) וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת. מַצָּה הִיא שְׁמוּרָה לְבַעְלָהּ, שֶׁהוּא אוֹת ו', וּבוֹ נַעֲשֵׂית מִצְוָה.</p>\n<p>וּמִי שֶׁשּׁוֹמֵר לָהּ בִּשְׁבִיל יָ\"הּ הַגְּנוּזִים בְּאוֹתִיּוֹת מ\"ץ מִמַּצָּה, וְהֵם י\"ם ה\"ץ. וְצִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָרֵךְ אוֹתָהּ בְּשֶׁבַע בִּרְכוֹת לֵיל פֶּסַח, שֶׁהֵן שֶׁבַע הַנְּעָרוֹת שֶׁלָּהּ, שֶׁהֵן שצ\"ם חנכ\"ל. וְצִוָּה לְהַעֲבִיר מֵהֶן חָמֵץ וּמַחְמֶצֶת, שֶׁהֵם עֲנָנִים חֲשׁוּכִים שֶׁמְּכַסִּים עַל אוֹרוֹת שֶׁל שִׁבְעָה כּוֹכְבֵי לֶכֶת, שֶׁנֶּאֱמַר בָּהֶם (בראשית מא) וַתָּבאנָה אֶל קִרְבֶּנָה וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָה וּמַרְאֵיהֶן רַע. חָשׁוּךְ כַּאֲשֶׁר בַּתְּחִלָּה. שֶׁכָּל כָּךְ הַחֹשֶׁךְ שֶׁל הָעֲנָנִים שֶׁלָּהֶם, שֶׁלֹּא יְכוֹלִים אוֹרוֹת לְהָאִיר לָהֶם, וּמִשּׁוּם זֶה נֶאֱמַר וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָה. (ע\"כ רעיא מהימנא).</p>"],[9522012549,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים סח) גְּעַר חַיַּת קָנֶה עֲדַת אַבִּירִים בְּעֶגְלֵי עַמִּים. גְּעַר חַיַּת - זוֹ הַחַיָּה שֶׁאָחוּז בָּהּ עֵשָׂו. קָנֶה - לָמַדְנוּ, שֶׁבַּיּוֹם שֶׁנָּשָׂא שְׁלֹמֹה הַמֶּלֶךְ אֶת בַּת פַּרְעֹה, בָּא גַּבְרִיאֵל, נָעַץ קָנֶה בַּיָּם הַגָּדוֹל, וְעָלָיו נִבְנֵית עִיר שֶׁל רוֹמִי. מַהוּ קָנֶה? זֶה הַזָּכָר שֶׁל זוֹ הַחַיָּה רָעָה, שֶׁיֵּשׁ לוֹ צַד קָטָן בַּאֲחִיזָתוֹ בַּקְּדֻשָּׁה. וְזֶהוּ קָנֶה שֶׁנָּעוּץ בַּיָּם הַגָּדוֹל, וּמִשּׁוּם זֶה הִיא שׁוֹלֶטֶת עַל הָעוֹלָם, וְעַל שִׁלְטוֹן זֶה כָּתוּב, (ישעיה יט) קָנֶה וָסוּף קָמֵלוּ. קָנֶה, שִׁלְטוֹן וָרֹאשׁ לְכָל הַמַּלְכוּת. וְעוֹד קָנֶה, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁבֹּר אוֹתוֹ כְּקָנֶה זֶה.</p>\n<p>בֹּא וּרְאֵה, בְּמִצְרַיִם הִיא שׁוֹלֶטֶת, וּמִמֶּנָּה יוֹצְאִים כַּמָּה שִׁלְטוֹנִים לְמִינֵיהֶם, וְהַכֹּל בְּסוֹד שֶׁל חָמֵץ. כֵּיוָן שֶׁשָּׁבַר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, הוֹצִיא חָמֵץ וּמַכְנִיס מַצָּה. בַּמֶּה? בְּחוּט קָטָן מֵהַכֹּל שָׁבַר אוֹת ח' שֶׁל חָמֵץ, וְנַעֲשָׂה מַצָּה. אֵלּוּ אוֹתִיּוֹת, אֶלָּא שֶׁשָּׁבַר ח' שֶׁל חַיָּה זוֹ, שֶׁנִּקְרָא חָמֵץ. וְעַל זֶה נִקְרָא חַיַּת קָנֶה, שֶׁנּוֹחַ לְשַׁבְּרוֹ כְּמוֹ קָנֶה זֶה. בַּמֶּה נִשְׁבָּר? בְּחוּט קָטָן כְּמוֹ שַׂעֲרָה שָׁבַר ח' וְעָבַר מֵאֵיתָנָהּ, וְהָיָה מַצָּה. וְעַל זֶה כָּתוּב גְּעַר חַיַּת קָנֶה. גָּעַר בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִשְׁבַּר ח' שֶׁל חָמֵץ וְנַעֲשָׂה ה'. (ועובר ח' של חמץ ונעשה).</p>\n<p>וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁבֹּר לוֹ לְאוֹתוֹ קָנֶה כְּמוֹ זֶה, יִשְׁבֹּר רֶגֶל ק' מִקָּנֶה, וְיִשָּׁאֵר הִנֵּה. (ישעיה מ) הִנֵּה ה' אֱלֹהִים בְּחָזָק יָבוֹא וּזְרֹעוֹ מֹשְׁלָה לוֹ הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעֻלָּתוֹ לְפָנָיו. מַהוּ וּפְעֻלָּתוֹ? זֶה פֹּעַל שֶׁל אוֹתָהּ ק' (פעלה של אותו חמץ) שֶׁיִּשְׁבֹּר אוֹתָהּ, וְהִיא פְּעֻלָּה שֶׁלְּפָנָיו, וְהוּא יַעֲבִיר רַגְלוֹ וְיִהְיֶה הִנֵּה, שֶׁנֶּאֱמַר (שם מא) רִאשׁוֹן לְצִיּוֹן הִנֵּה הִנָּם וְגוֹ'.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, גְּעַר חַיַּת קָנֶה עֲדַת אַבִּירִים בְּעֶגְלֵי עַמִּים. גְּעַר חַיַּת קָנֶה - זֶה קָנֶה שֶׁאָחוּז בּוֹ עֵשָׂו, שֶׁהִיא עִיר רוֹמִי הַגְּדוֹלָה, שֶׁנָּעַץ גַּבְרִיאֵל קָנֶה בַּיָּם הַגָּדוֹל, וּבָנוּ עָלֶיהָ כְּרַךְ גָּדוֹל שֶׁל רוֹמִי. קָנֶה שֶׁל חָמֵץ. וְכַאֲשֶׁר תָּבֹא גְאֻלָּתָם שֶׁל יִשְׂרָאֵל, יִשְׁבְּרוּ אוֹתוֹ. זֶהוּ שֶׁכָּתוּב גְּעַר חַיַּת קָנֶה עֲדַת. וּמִיָּד עוֹבֵר חָמֵץ מֵהָעוֹלָם. הַמַּחְמֶצֶת שֶׁלּוֹ הִיא רוֹמִי. וְתִתְגַּלֶּה מַצָּה בָּעוֹלָם, שֶׁהוּא בֵּית הַמִּקְדָּשׁ שֶׁל בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה (הרועה הנאמן), שֶׁהֵם כְּנֶגֶד בַּת עַיִן יָמִין, וּבַת עַיִן שְׂמֹאל. וְהֵם כְּנֶגֶד (לחם משנה) רוֹמִי הַגְּדוֹלָה וְרוֹמִי הַקְּטַנָּה, וּכְנֶגֶד שְׁנֵי עֲנָנִים שֶׁמְּכַסִּים עַל בַּת עַיִן יָמִין וּשְׂמֹאל. וְהֵם כְּנֶגֶד שְׂאוֹר וְחָמֵץ. וְעַד שֶׁאֵלּוּ יִתְבַּעֲרוּ מֵהָעוֹלָם, בַּל יֵרָאֶה וּבַל יִמָּצֵא אֶחָד מֵהֶם, בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי לֹא יִתְגַּלּוּ בָּעוֹלָם.</p>\n<p>וְהָרְפוּאָה שֶׁל עַנְנֵי הָעַיִן שֶׁהֶחְשִׁיכוּ לְבַת עַיִן יָמִין וּשְׂמֹאל, מַה תִּהְיֶה רְפוּאָתָם? הַמְּרִירוּת שֶׁל הָעֵגֶל. וְזֶהוּ שֶׁכָּתוּב (ישעיה כז) שָׁם יִרְעֶה עֵגֶל וְשָׁם יִרְבָּץ. שָׁם יִרְעֶה עֵגֶל - זֶה מָשִׁיחַ בֶּן יוֹסֵף שֶׁנֶּאֱמַר בּוֹ (דברים לג) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. וְשָׁם יִרְבָּץ - זֶה מָשִׁיחַ בֶּן דָּוִד. אֶחָד לְהַעֲבִיר אֶת רוֹמִי הַגְּדוֹלָה, וְאֶחָד לְהַעֲבִיר אֶת רוֹמִי הַקְּטַנָּה. וּמִיכָאֵל וְגַבְרִיאֵל כְּנֶגְדָּם הֵם.</p>\n<p>וּמִשּׁוּם זֶה ח', שֶׁהוּא חוּט קָטָן, תִּשְׁבֹּר אוֹתָהּ, וְתִכָּנֵס אוֹת ה' בִּמְקוֹמָהּ. שֶׁבַּתְּחִלָּה נֶאֱמַר קָנֶה וָסוּף קָמֵלוּ. קָנֶה - שִׁלְטוֹן שֶׁל רוֹמִי. וָסוּף - לְכָל הַמַּלְכֻיּוֹת, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁבֹּר אוֹתוֹ. גְּעַר חַיַּת קָנֶה - גְּעַר חַיָּה רָעָה, שֶׁהִיא אוֹת ח' מֵחָמֵץ, וּשְׁבֹר רַגְלֶיהָ מִן הַמַּחְמֶצֶת, שֶׁנֶּאֱמַר בָּהּ (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת. וְעוֹד גְּעַר חַיַּת קָנֶה - שְׁבֹר רֶגֶל הַקּוֹ\"ף מִקָּנֶה, וְיִשָּׁאֵר הִנֵּה. מִיָּד - (ישעיה מ) הִנֵּה ה' אֱלֹהִים בְּחָזָק יָבֹא, (שם מא) רִאשׁוֹן לְצִיּוֹן הִנֵּה הִנָּם וְלִירוּשָׁלַיִם מְבַשֵּׂר אֶתֵּן. הִנֵּה - ס', אַחַר אֶלֶף וּמָאתַיִם.</p>"],[9522012550,"<p>וְאָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, נֶאֱמַר (בראשית מו) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב שִׁשִּׁים וָשֵׁשׁ. שִׁשִּׁים, לְהִתְעוֹרְרוּת שֶׁל מָשִׁיחַ רִאשׁוֹן. וָשֵׁשׁ, לְהִתְעוֹרְרוּת מָשִׁיחַ שֵׁנִי. נִשְׁאֲרוּ שֵׁשׁ שָׁנִים לְשִׁבְעִים וּשְׁנַיִם, לְקַיֵּם בָּהֶם (ויקרא כה) שֵׁשׁ שָׁנִים תִּזְרַע שָׂדֶךְ וְשֵׁשׁ שָׁנִים תִּזְמֹר כַּרְמֶךְ וְאָסַפְתָּ אֶת תְּבוּאָתָהּ, שֶׁנֶּאֱמַר (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה.</p>\n<p>אִם כֵּן, מַה כָּתוּב לְמַעְלָה (שם לא) רָנּוּ לְיַעֲקֹב שִׂמְחָה? אֶלָּא אַרְבַּע גְּאֻלּוֹת עֲתִידוֹת לִהְיוֹת כְּנֶגֶד אַרְבַּע כּוֹסוֹת שֶׁל פֶּסַח. מִשּׁוּם שֶׁיִּשְׂרָאֵל מְפֻזָּרִים בְּאַרְבַּע פִּנּוֹת הָעוֹלָם, וְאֵלּוּ שֶׁיִּהְיוּ רְחוֹקִים מֵהָאֻמּוֹת, יַקְדִּימוּ לְרָנּוּ. וְהַשְּׁנִיִּים - לְשִׁשִּׁים. וְהַשְּׁלִישִׁיִּים - לְשִׁשִּׁים וָשֵׁשׁ. וְהָרְבִיעִיִּים - לְשִׁבְעִים וּשְׁנַיִם.</p>\n<p>וּגְאֻלּוֹת אֵלּוּ יִהְיוּ בְּאַרְבַּע חַיּוֹת, בְּשֵׁם יְהֹוָ\"ה שֶׁרוֹכֵב עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב (חבקוק ג) כִּי תִרְכַּב עַל סוּסֶיךְ מַרְכְּבתֶיךְ יְשׁוּעָה. שֶׁכְּנֶגְדָּם יְעוֹרֵר לְמַטָּה אַרְבָּעָה דְגָלִים וּשְׁנֵים עָשָׂר שְׁבָטִים, בְּסוֹד שֶׁל יְהֹוָה מֶלֶךְ, יְהֹוָה מָלָךְ, (שמות טו) יְהֹוָה יִמְלֹךְ לְעֹלָם וָעֶד. שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת הֵן, כְּנֶגֶד שְׁנֵים עָשָׂר שְׁבָטִים, וּשְׁנֵים עָשָׂר פָּנִים שֶׁל שְׁלֹשֶׁת הָאָבוֹת, שֶׁנֶּאֱמַר עֲלֵיהֶם, הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה. וְהֵם עֲשָׂרָה שְׁבָטִים, אֶלֶף שָׁנִים. שְׁנֵי שְׁבָטִים - מָאתַיִם שָׁנָה. וּמִי\"ב אוֹתִיּוֹת תְּלוּיִים ע\"ב שֵׁמוֹת, שֶׁהֵם ע\"ב שָׁנִים אַחַר הָאֶלֶף וּמָאתַיִם.</p>\n<p>וְהֵם כ\"ד, לְכָל חַיָּה מִשָּׁלֹשׁ חַיּוֹת. כ\"ד הַסּוֹד שֶׁלּוֹ, (ישעיה ו) וְקָרָא זֶה אֶל זֶה וְאָמַר. וְהֵם שָׁלֹשׁ כִּתּוֹת מִכ\"ד צוּרוֹת. כַּת אַחַת אוֹמֶרֶת קָדוֹשׁ, וְכַת שְׁנִיָּה אוֹמֶרֶת קָדוֹשׁ, וְכַת שְׁלִישִׁית אוֹמֶרֶת קָדוֹשׁ. מִיָּד מִתְעוֹרֵר הַשְּׂמֹאל בְּמ\"ב אוֹתִיּוֹת, וְעוֹשֶׂה דִּין בַּעֲמָלֵק.</p>"],[9522012551,"<p>(דברים כב) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ בַּדֶּרֶךְ - בַּעֲלֵי מִקְרָא. בְּכָל עֵץ - בַּעֲלֵי מִשְׁנָה, שֶׁהֵם כְּאֶפְרוֹחִים הַמְקַנְּנִים בְּעַנְפֵי הָאִילָן. יֵשׁ שֶׁאוֹמְרִים, בְּכָל עֵץ - אֵלּוּ יִשְׂרָאֵל, שֶׁנֶּאֱמַר בָּהֶם (ישעיה סה) כִּי כִימֵי הָעֵץ יְמֵי עַמִּי. אוֹ עַל הָאָרֶץ - אֵלּוּ בַּעֲלֵי תוֹרָה (משנה), שֶׁנֶּאֱמַר בָּהֶם, עַל הָאָרֶץ תִּישַׁן וְחַיֵּי צַעַר תִּחְיֶה וּבַתּוֹרָה אַתָּה עָמֵל. אֶפְרֹחִים - אֵלּוּ פִּרְחֵי כְהֻנָּה. אוֹ בֵיצִים - אֵלּוּ שֶׁזָּן אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מִקַּרְנֵי רְאֵמִים וְעַד בֵּיצֵי כִנִּים. וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים - בִּזְמַן שֶׁהָיוּ מַקְרִיבִים קָרְבָּנוֹת. מַה כָּתוּב? לֹא תִקַּח הָאֵם עַל הַבָּנִים.</p>\n<p>חָרַב בֵּית הַמִּקְדָּשׁ וּבָטְלוּ הַקָּרְבָּנוֹת, מַה כָּתוּב? שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם. וְגָלוּ הַבָּנִים. וְזֶהוּ שֶׁנֶּאֱמַר וְאֶת הַבָּנִים תִּקַּח לָךְ, מִצַּד זֶה שֶׁל הָאוֹת ו', שֶׁהוּא עוֹלָם אָרֹךְ שֶׁנֶּאֱמַר בּוֹ (דברים כב) לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים, לְעוֹלָם שֶׁכֻּלּוֹ אָרֹךְ.</p>\n<p>בִּמְקוֹם הַקָּרְבָּנוֹת תִּקְּנוּ תְפִלּוֹת, וּמְצַפְצְפִים בְּקוֹלוֹת שֶׁל שִׁירִים, בְּקוֹל שֶׁל קְרִיאַת שְׁמַע, לִקְרַאת הָעַמּוּד הָאֶמְצָעִי שֶׁהוּא לְמַעְלָה. שֶׁהֲרֵי אִמָּא וּבַת בַּגָּלוּת, וּמִיָּד שֶׁיּוֹרֵד, קוֹשְׁרִים אוֹתוֹ בַּבַּת, שֶׁהִיא יָד כֵּהָה, לִהְיוֹת קְשׁוּרָה ו' עִם ה' בְּשֵׁשׁ סְפִירוֹת. מִיָּד לוֹחֲשִׁים לְעֻמַּת הַחָכְמָה: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>"],[9522012552,"<p>אֶחָד וְכָבוֹד גִּימַטְרִיָּא מ\"ה מֵחָכְמָה. שֶׁמּוֹרִיד אוֹתוֹ אֵצֶל אִמָּא, וּמִיָּד שֶׁיּוֹרֵד, קוֹשְׁרִים אוֹתוֹ עִמָּהּ בְּקֶשֶׁר שֶׁל תְּפִלִּין שֶׁל רֹאשׁ. וּמִשּׁוּם זֶה בְּאַרְבַּע פָּרָשִׁיּוֹת שֶׁל הַתְּפִלִּין, שֶׁהֵם: קַדֶּשׁ לִי - חָכְמָה. וְהָיָה כִּי יְבִיאֲךְ - בִּינָה. שְׁמַע יִשְׂרָאֵל - תִּפְאֶרֶת שֶׁכּוֹלֶלֶת שֵׁשׁ סְפִירוֹת בְּשֵׁשׁ תֵּבוֹת. וְהָיָה אִם שָׁמֹעַ - מַלְכוּת, יָד כֵּהָה. תְּפִלָּה כֶּתֶר, כ' עַל רֹאשׁוֹ, אֵין קָדוֹשׁ כַּיהֹוָה, שֶׁסַּנְדַּלְפוֹן קוֹשֵׁר כָּל הַתְּפִלּוֹת וְעוֹשֶׂה מֵהֶן כֶּתֶר.</p>\n<p>בְּאוֹתוֹ זְמַן צָרִיךְ לְסַדֵּר מְנוֹרָה (שלחן) לַסְּעוּדָה שֶׁל הַמֶּלֶךְ, וּמִשְׁכָּן וּמְנוֹרָה וְאָרוֹן וּמִזְבֵּחַ, וְכָל מִינֵי שִׁמּוּשׁ שֶׁל בֵּית הַמֶּלֶךְ. וְלֹא אַחַר שֻׁלְחָן אָנוּ הוֹלְכִים שֶׁאֵינוֹ עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵין אָנוּ הוֹלְכִים אֶלָּא אַחַר שֻׁלְחָן שֶׁהוּא מַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא הַשְּׁכִינָה, מִשְׁכָּן שֶׁלּוֹ, שֻׁלְחָן שֶׁלּוֹ, מְנוֹרָה שֶׁלּוֹ, אָרוֹן שֶׁלּוֹ, מִזְבֵּחַ שֶׁלּוֹ. הִיא כְּלוּלָה מִכָּל כְּלֵי שִׁמּוּשׁ לַמֶּלֶךְ הָעֶלְיוֹן.</p>"],[9522012553,"<p>הֵם אֵלּוּ שֶׁמְּתַקְּנִים יַיִן וְלֶחֶם שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁנֶּאֱמַר בָּהֶם אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי, שֶׁאֵין לְהַקְרִיב לוֹ אֶצְלוֹ אֶלָּא אֵלּוּ שֶׁנִּקְרָאִים אִשֵּׁי ה'. וּמִשּׁוּם זֶה נֶאֱמַר אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. שֶׁעָלָיו נֶאֱמַר (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי. וְנִקְרָא לֶחֶם הַפָּנִים, שֶׁהֵם י\"ב פָּנִים, שֶׁנֶּאֱמַר (במדבר ו) יְבָרֶכְךְ יְהֹוָה, יָאֵר יְהֹוָה, יִשָּׂא יְהֹוָה. שְׁנֵים עָשָׂר פָּנִים שֶׁל שָׁלֹשׁ חַיּוֹת.</p>\n<p>מַהוּ הַלֶּחֶם שֶׁל אֵלּוּ הַפָּנִים? זֶה לֶחֶם שֶׁל אָדָם, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְיֵשׁ לוֹ לֶחֶם בְּאַרְבָּעָה פָּנִים, שֶׁהֵם אַרְבַּע אוֹתִיּוֹת יְהֹוָ\"ה. זֶה הַלֶּחֶם שֶׁל שֻׁלְחַן הַמֶּלֶךְ, הוּא סֹלֶת נְקִיָּה.</p>\n<p>הַכִּבְשָׁן שֶׁלּוֹ שֶׁאוֹפֶה בּוֹ לֶחֶם הִיא הַשְּׁכִינָה, שֶׁשָּׁם מִתְבַּשֵּׁל וְנִשְׁלָם. וּמִשּׁוּם זֶה אֵין בּוֹצְעִים אֶלָּא מִמָּקוֹם שֶׁנִּגְמָר בִּשּׁוּלוֹ. כְּדֻגְמַת שְׁלֵמוּת הַפְּרִי, שֶׁהוּא גְּמַר בִּשּׁוּלוֹ. וְזֶהוּ שֵׁם אֲדנָי, גְּמַר וּשְׁלֵמוּת שֵׁם יְהֹוָה, שֶׁהוּא לֶחֶם הַפָּנִים. אֲדנָי הוּא הַכִּבְשָׁן שֶׁלּוֹ. שֶׁהִיא כְּבוּשָׁה תַּחַת בַּעְלָהּ. וּבִגְלָלָהּ נֶאֱמַר, (שמות יט) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשָׁן הַכִּבְשָׁן. וְלֹא כְּמוֹ כִּבְשָׁן שֶׁל אֵשׁ הֶדְיוֹט, אֶלָּא כְּמוֹ כִּבְשָׁן שֶׁבּוֹ כּוֹבֵשׁ רַחֲמָיו עַל עַמּוֹ כַּאֲשֶׁר מִתְפַּלְלִים וּמְבַקְשִׁים בַּקָּשׁוֹת, כֵּן יִכְבְּשׁוּ רַחֲמֶיךְ אֶת כַּעַסְךְ. וּבוֹ, דְּבָרִים הַכְּבוּשִׁים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לָמָּה לָךְ לַחְקֹר?</p>\n<p>וּבְלֶחֶם הַתּוֹרָה יֵשׁ סֹלֶת שֶׁנָּתַן לוֹ הַמֶּלֶךְ לְאוֹתָם שֶׁנֶּאֱמַר עֲלֵיהֶם, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. מַאֲכַל הַצַּדִּיקִים. וְיֵשׁ לֶחֶם שֶׁל הַתּוֹרָה שֶׁהוּא פְּסֹלֶת לְאוֹתָם עֲבָדִים וּשְׁפָחוֹת שֶׁל בֵּית הַמֶּלֶךְ. וּמִשּׁוּם זֶה בַּמַּלְכָּה נֶאֱמַר, (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ, שֶׁהֵם בַּעֲלֵי מִשְׁנָה. וּמִשּׁוּם זֶה נֶאֱמַר בַּמַּאֲכָל שֶׁל הַמֶּלֶךְ, וַעֲשִׂירִית הָאֵיפָה סֹלֶת, וַדַּאי. וְזוֹ יוֹ\"ד מֵאֲדנָי, שֶׁהִיא עֲשִׂירִית. וְזֶה סֹלֶת שֶׁל הֵיכַל הַמֶּלֶךְ, וּמִשְׁתַּבַּחַת (של מאכל המלך נמצאת).</p>\n<p>קוּם הַמְּנוֹרָה הַקְּדוֹשָׁה, אַתָּה וְרַבִּי אֶלְעָזָר בִּנְךְ, וְרַבִּי אַבָּא, וְרַבִּי יְהוּדָה, וְרַבִּי יוֹסֵי, וְרַבִּי חִיָּיא, וְרַבִּי יוּדָאִי, לְתַקֵּן מַתָּנָה לַמֶּלֶךְ, וּלְהַקְרִיב כָּל אֵיבָרִים, שֶׁהֵם יִשְׂרָאֵל, קָרְבָּנוֹת לְהַקָּדוֹשׁ בָּרוּךְ הוּא, זֶה שֶׁנִּקְרָא נְשָׁמָה שֶׁל הָאֵיבָרִים, שְׁכִינָה הַקְּדוֹשָׁה, אֵשׁ שֶׁל גָּבוֹהַּ. שֶׁאָחוּז בְּעֵצִים שֶׁנִּקְרָאִים עֲצֵי הָעוֹלָה, שֶׁהֵם עֵץ הַחַיִּים וְעֵץ הַדַּעַת טוֹב וָרָע. עֲצֵי הַקֹּדֶשׁ נִקְרָאִים אֵלּוּ בַּעֲלֵי תוֹרָה, שֶׁמִּתְאַחֶדֶת בָּהֶם הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (ירמיה כג) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'.</p>"],[9522012554,"<p>וְנֶאֱמַר בָּהּ עֹלָה לַה', קָרְבָּן לַה', אִשֶּׁה לַה'. וְנֶאֱמַר אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. וַהֲרֵי כָּתוּב שֶׁאֵין לְהַקְרִיב קָרְבָּן אֶלָּא לְשֵׁם ה', מַהוּ אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי? אֶלָּא הַדֶּרֶךְ, שֶׁמִּי שֶׁמַּקְרִיב דּוֹרוֹן לְהַקְרִיב אוֹתוֹ לַמֶּלֶךְ וְאַחַר כָּךְ הוּא מְחַלֵּק אוֹתוֹ לְמִי שֶׁרוֹצֶה, אַף כָּךְ יִשְׂרָאֵל מַקְרִיבִים תּוֹרָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא לַחְמוֹ, וְהוּא יֵינוֹ, וְהוּא בְּשָׂרוֹ, וְנֶאֱמַר בָּהּ (בראשית ב) עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי. בְּשַׂר קֹדֶשׁ, שֶׁפֵּרְשׁוּ עָלֶיהָ בַּעֲלֵי הַמִּשְׁנָה, בְּבָשָׂר הַיּוֹרֵד מִן הַשָּׁמַיִם אָנוּ עֲסוּקִים.</p>"],[9522012555,"<p>מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתוֹ דּוֹרוֹן? מָשָׁל לְמֶלֶךְ שֶׁאָכַל עַל שֻׁלְחָן, וּמַקְרִיבִים עַל שֻׁלְחָנוֹ מִכָּל מִין וָמִין - סֹלֶת, וּבֵינוֹנִי, וּפְסֹלֶת. וְהוּא מְחַלֵּק מִשֻּׁלְחָנוֹ לְכָל בַּעֲלֵי הַסְּעוּדָה, לְכָל אֶחָד כְּמוֹ שֶׁרָאוּי, עַל יְדֵי הַמְמֻנִּים שֶׁלּוֹ. וּמֵאוֹתוֹ לֶחֶם שֶׁהוּא סֹלֶת, שֶׁהַמֶּלֶךְ אוֹכֵל, הוּא מְצַוֶּה לָתֵת לְאֵלּוּ שֶׁאֲהוּבִים אֶצְלוֹ. זֶהוּ שֶׁכָּתוּב אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִיחֹחִי. כְּלוֹמַר, (דברים יח) אִשֵּׁי ה' וְנַחֲלָתוֹ יֹאכֵלוּן (וזהו אותו שנאמר בו (משלי ט) לכו לחמובלחמי ושתו ביין מסכתי) -זֶהוּ מִצַּד שֶׁל עֵץ הַחַיִּים. אֲבָל מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע, מְצַוֶּה לָתֵת בֵּינוֹנִי לַמַּלְאָכִים, וּפְסֹלֶת לַשֵּׁדִים וּמַזִּיקִים, שֶׁהֵם מְשַׁמְּשִׁים לַסּוּסִים וְלַפָּרָשִׁים שֶׁל הַמֶּלֶךְ.</p>\n<p>וְאַף כָּךְ שֶׁפָּרָשֵׁי הַמֶּלֶךְ הָיוּ בַּעֲלֵי מִשְׁנָה, שֶׁהֵם כְּמַלְאָכִים - מְשַׁמְּשִׁים לָהֶם שֵׁדִים יְהוּדִיִּים, שֶׁהֵם רְשׁוּמִים בְּאוֹת שַׁדַּי (באות י'). וְיֵשׁ שֵׁדִים וּמַזִּיקִים מִצַּד הַטֻּמְאָה, שֶׁנִּקְרָאִים שֵׁדִים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. (קהלת ז) וְזֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים.</p>\n<p>וּמִשּׁוּם זֶה אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁהֵם ג' מִינִים מֵהֶם: אֶחָד מִין שֶׁלָּהֶם כְּמַלְאֲכֵי הַשָּׁרֵת, וּמִין שֵׁנִי כִּבְנֵי אָדָם, וּמִין שְׁלִישִׁי כַּבְּהֵמוֹת. וְיֵשׁ בָּהֶם חֲכָמִים בַּתּוֹרָה שֶׁבִּכְתָב וְשֶׁבְּעַל פֶּה. נִקְרָא יוֹסֵף הַשֵּׁד, עַל שֵׁם שֶׁהוֹלִיד אוֹתוֹ שֵׁד. וְלֹא לְחִנָּם אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, אִם הָרַב דּוֹמֶה לְמַלְאַךְ ה' צְבָאוֹת, תּוֹרָה יְבַקְשׁוּ מִפִּיהוּ. וְאַשְׁמְדַאי הַמֶּלֶךְ, הוּא וְכָל מִשְׁפַּחְתּוֹ, כְּבָר בֵּאַרְנוּ שֶׁהֵם שֵׁדִים יְהוּדִיִּים, שֶׁנִּכְנָעִים בַּתּוֹרָה וּבִשְׁמוֹת הַתּוֹרָה.</p>\n<p>וּבְנֵי אַהֲרֹן, מִשּׁוּם שֶׁעָרְכוּ קָרְבְּנוֹתֵיהֶם, בִּגְלַל זֶה נֶעֶנְשׁוּ. שֶׁכָּל הַקָּרְבָּנוֹת, אַף עַל גַּב שֶׁנִּקְרָבִים בִּשְׁבִיל הַמֶּלֶךְ, הוּא מְחַלֵּק לָהֶם לְכָל אֶחָד כְּמוֹ שֶׁרָאוּי, וְנוֹטֵל לְחֶלְקוֹ מַה שֶּׁרָאוּי לוֹ. (ע\"כ רעיא מהימנא).</p>"],[9522012556,"<p>זהר: וּבַחִבּוּר הַקַּדְמוֹן, נֶאֱמַר (במדבר כח) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה וְגוֹ'. אָמַר רַבִּי אַבָּא, יוֹם הַבִּכּוּרִים, מִיהוּ הַיּוֹם? זֶה נָהָר הַיֹּצֵא מֵעֵדֶן, שֶׁהוּא יוֹם מֵאוֹתָם בִּכּוּרִים עֶלְיוֹנִים. וְזֶהוּ שֶׁהַתּוֹרָה תְּלוּיָה בּוֹ, וְהוּא מוֹצִיא כָּל סוֹדוֹת הַתּוֹרָה. וּמִשּׁוּם שֶׁהוּא עֵץ הַחַיִּים, צְרִיכִים לְהָבִיא פֵּרוֹת הָאִילָן.</p>\n<p>וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה וְגוֹ' (במדבר כח). רַבִּי אַבָּא אָמַר, יוֹם הַבִּכּוּרִים הֵם בִּכּוּרִים עֶלְיוֹנִים שֶׁל הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שמות כג) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךְ תָּבִיא וְגוֹ'. אָמַר הָרוֹעֶה הַנֶּאֱמָן, כְּמוֹ הַבְּכוֹרוֹת לְאִמּוֹתֵיהֶם, אַף כָּךְ נִקְרְאוּ הַפֵּרוֹת בִּכּוּרִים, שֶׁל פֵּרוֹת הָאִילָנוֹת. (הושע ט) כְּבִכּוּרָה בִתְאֵנָה, כָּךְ יִשְׂרָאֵל קַדְמוֹנִים וּבִכּוּרִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל אֻמּוֹת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַיהֹוָה וְגוֹ'. וּמִשּׁוּם זֶה נֶאֱמַר בָּהֶם, (שמות כג) תָּבִיא בֵּית ה' אֱלֹהֶיךְ. וּמִשּׁוּם זֶה אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁנֶּאֱמַר בָּהֶם (ישעיה ט) וַיֹּאכְלוּ אֶת יִשְׂרָאֵל בְּכָל פֶּה - יֶאְשְׁמוּ רָעָה תָּבֹא אֲלֵיהֶם.</p>\n<p>אַף כָּךְ ו' שֶׁכְּלוּלָה מִשֵּׁשׁ סְפִירוֹת, וְהוּא בֶּן יָ\"הּ, שֶׁנִּקְרָא בְּכֹ\"ר. וְכָל עֲנָפִים שֶׁיּוֹצְאִים מִמֶּנּוּ שֶׁבָּהֶם רָאשִׁים, כְּמוֹ זֶה (ציור למעלה) נִקְרָאִים בִּכּוּרִים. אוֹת ו' הִיא נָהָר מֵאֵלּוּ בִּכּוּרִים עֶלְיוֹנִים, וְאוֹתוֹ נָהָר יוֹצֵא מֵעֵדֶן, וְזֶהוּ שֶׁהַתּוֹרָה תְּלוּיָה בּוֹ. וְכַאֲשֶׁר יוֹצֵא, יוֹצְאִים כָּל סוֹדוֹת הַתּוֹרָה, וּמִשּׁוּם שֶׁהוּא עֵץ הַחַיִּים שֶׁל הַתּוֹרָה, זֶהוּ (אחת היא) שֶׁכָּתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְהַמִּצְווֹת שֶׁלָּהּ דּוֹמוֹת לַפְּרִי שֶׁל הָאִילָנוֹת, צְרִיכִים לַהֲבִיאָן.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, וְאִם תֹּאמְרוּ מַדּוּעַ הַבִּכּוּרִים שֶׁלָּהֶם נִקְרָאִים מִנְחָה חֲדָשָׁה, מִשִּׁשָּׁה חֳדָשִׁים לְשִׁשָּׁה חֳדָשִׁים, וּמֵאָדָם שֶׁנֶּאֱמַר בּוֹ (דברים כ) כִּי הָאָדָם עֵץ הַשָּׂדֶה - לְתִשְׁעָה חֳדָשִׁים אוֹ לְשִׁבְעָה. וּבְהֵמוֹת אַף כָּךְ - שִׁבְעַת יָמִים יִהְיֶה (ויקרא כב) תַּחַת אִמּוֹ וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה לְקָרְבַּן אִשֶּׁה לַה', לְהַקְרִיב קָרְבָּן לִפְנֵי ה'. וְעוֹד, הַסְּפִירוֹת, בָּהֶן שֵׁם יְהֹוָה, וְכָל הַכִּנּוּיִים שֶׁלּוֹ, מַדּוּעַ נִקְרָאוֹת בְּשֵׁם חַיּוֹת?</p>\n<p>אֶלָּא מִנְחָה חֲדָשָׁה בְּדֶרֶךְ סוֹד זוֹ הַשְּׁכִינָה. מִשִּׁשָּׁה חֳדָשִׁים לְשִׁשָּׁה חֳדָשִׁים אֵלּוּ שֵׁשׁ סְפִירוֹת, שֶׁנִּקְרָאוֹת שָׁנִים קַדְמוֹנִיּוֹת לִבְרִיאַת הָעוֹלָם, שֶׁהֵן שֵׁשׁ אֶלֶף שָׁנִים שֶׁקַּיָּם הָעוֹלָם, מִצַּד שֶׁל אִמָּא עֶלְיוֹנָה. וּמִצַּד שֶׁל אִמָּא תַּחְתּוֹנָה נִקְרָאִים חֳדָשִׁים. וּמִשּׁוּם שֶׁקָּדְמוּ לָעוֹלָם וּלְכָל הַבְּרִיּוֹת, נִקְרָאִים בִּכּוּרִים.</p>\n<p>וְהַשְּׁכִינָה, מִנְחָה חֲדָשָׁה, מִצַּד שֶׁל חַיָּה, שֶׁנֶּאֱמַר בָּהּ (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וְהוּא תֵּשַׁע לְחֶשְׁבּוֹן קָטָן שֶׁל חֲנוֹךְ. הוּא אָדָם שֶׁנּוֹלָד לְתִשְׁעָה חֳדָשִׁים שֶׁל הַמְעֻבֶּרֶת, שֶׁהִיא עֲשִׂירִית. וּבָזֶה כָּלוּל מִכֻּלָּם, וְנִקְרָא בֵּן בְּכוֹר, עַל שֵׁם אוֹת בְּרִית, שֶׁהִיא י', טִפָּה רִאשׁוֹנָה שֶׁנִּמְשָׁךְ מִמֶּנָּה זֶרַע יוֹרֶה כַּחֵץ, שֶׁהִיא ו', וְהִיא י' שֶׁעוֹלָה עַל ו' כִּפְרִי שֶׁעוֹלֶה עַל עֲנַף הָאִילָן.</p>\n<p>וְאַף עַל גַּב שֶׁכַּמָּה עֲנָפִים יֵשׁ בָּאִילָן וְכַמָּה תְאֵנִים עֲלֵיהֶם - אֵלּוּ שֶׁהִקְדִּימוּ בָּרִאשׁוֹנָה נִקְרָאִים בִּכּוּרִים. אֵלּוּ הֵם רָאשִׁים שֶׁל כֻּלָּם. כְּדֻגְמָא שֶׁלָּהֶם נֶאֱמַר (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם. (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. (במדבר א) שְׂאוּ אֶת רֹאשׁ כָּל עֲדַת בְּנֵי יִשְׂרָאֵל.</p>\n<p>שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם. שְׁעָרִים אֵלּוּ הֵם חֲמִשִּׁים שְׁעָרִים שֶׁל בִּינָה, שֶׁהִיא יְשִׁיבָה שֶׁל מַעְלָה. וּשְׂאוּ פִּתְחֵי עוֹלָם - שֶׁל יְשִׁיבָה שֶׁל מַטָּה. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, לְבַסּוֹף מִתְנַשֵּׂא. זֶהוּ שֶׁכָּתוּב (משלי ל) אִם נָבַלְתָּ בְּהִתְנַשֵּׂא. וּבֵאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַמְנַבֵּל עַצְמוֹ עַל דִּבְרֵי תוֹרָה, לַסּוֹף מִתְנַשֵּׂא, וְיָבֹא מֶלֶךְ הַכָּבוֹד, וְאֵין כָּבוֹד אֶלָּא תּוֹרָה.</p>\n<p>מִכָּאן, מִי שֶׁלּוֹמֵד תּוֹרָה שֶׁנִּקְרֵאת כָּבוֹד, נִקְרָא מֶלֶךְ. וְלֹא תֹאמַר בְּאוֹתוֹ עוֹלָם הַבָּא וְלֹא יוֹתֵר - אֶלָּא מֶלֶךְ בִּשְׁנֵי עוֹלָמוֹת, בִּדְמוּת רִבּוֹנוֹ. וּמִשּׁוּם זֶה כָּפוּל הַפָּסוּק פַּעֲמַיִם. אַחַת - מִי זֶה מֶלֶךְ הַכָּבוֹד. שְׁתַּיִם - מִי הוּא זֶה מֶלֶךְ הַכָּבוֹד. שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם, מַהוּ רָאשֵׁיכֶם? פַּעֲמַיִם. אֵלּוּ חַיּוֹת הַמֶּרְכָּבָה הָעֶלְיוֹנָה, וְחַיּוֹת הַמֶּרְכָּבָה הַתַּחְתּוֹנָה. וּבחבּוּר הקּדמון. (ע\"כ רעיא מהימנא).</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח פָּסוּק וְאָמַר, שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ וְנִתְבָּאֵר. אֲבָל שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם - אֵלּוּ הֵם שְׁעָרִים עֶלְיוֹנִים, שְׁעָרִים שֶׁל שֵׂכֶל עֶלְיוֹן, וְאֵלּוּ חֲמִשִּׁים שְׁעָרִים. רָאשֵׁיכֶם - אֵלּוּ הָרָאשִׁים מִי הֵם? אֶלָּא כָּל אֶחָד וְאֶחָד יֵשׁ לוֹ רֹאשׁ לְהִתְפַּשֵּׁט וְלַעֲלוֹת זֶה בָּזֶה וּלְהִכָּלֵל זֶה בָּזֶה.</p>\n<p>מָצָאנוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ: שְׂאוּ שְׁעָרִים - אֵלּוּ הֵם שְׁעָרִים שֶׁלְּמַטָּה מֵהָאָבוֹת, וְאֵלּוּ שְׁלֹשָׁה אַחֲרוֹנִים. רָאשֵׁיכֶם - אֵלּוּ הֵם רָאשֵׁי אַלְפֵי יִשְׂרָאֵל, וְאֵלּוּ הָאָבוֹת הָעֶלְיוֹנִים, וְאֵלּוּ רָאשִׁים שֶׁל אוֹתָם שְׁעָרִים. וּמִשּׁוּם אֵלּוּ שֶׁהֵם אוֹפַנִּים, שֶׁסּוֹבְבִים וְנוֹטְלִים אוֹתָם עַל כִּתְפֵיהֶם, אוֹמְרִים שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם. שְׂאוּ, לְמִי? לְרָאשֵׁיכֶם. שֶׁהֵם רָאשִׁים עֲלֵיכֶם וְשׁוֹלְטִים עֲלֵיכֶם. וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם - אֵלּוּ הָאִמָּהוֹת, וְאַרְבַּע הֵן שֶׁלְּמַטָּה.</p>\n<p>וְיָבוֹא מֶלֶךְ הַכָּבוֹד - זֶה הַמֶּלֶךְ הָעֶלְיוֹן שֶׁל הַכֹּל, שֶׁהוּא מֶלֶךְ מֵאוֹתוֹ כָּבוֹד, שֶׁמֵּאִיר לַלְּבָנָה. וּמִי הוּא? ה' צְבָאוֹת. וְיָבוֹא, לְאֵיזֶה מָקוֹם? לְהַכְנִיס הַתּוֹרָה בָּאָרוֹן, בְּחִבּוּר אֶחָד כְּמוֹ שֶׁרָאוּי. וְכֵיוָן שֶׁזֶּה נִכְנָס לִמְקוֹמוֹ, אָז הַתּוֹרָה נִכְנֶסֶת בָּאָרוֹן, וּמִתְחַבֵּר חִבּוּר אֶחָד, תּוֹרָה עֶלְיוֹנָה בְּתוֹרָה שֶׁבְּעַל פֶּה, מִתְחַבְּרוֹת לְפָרֵשׁ דְּבָרִים סְתוּמִים.</p>\n<p>מָתַי, ? בְּשָׁבֻעֹתֵיכֶם, לַמִּנְיָן שֶׁאַתֶּם מוֹנִים. שֶׁבְּכָל שָׁעָה שֶׁיִּשְׂרָאֵל עוֹשִׂים חֶשְׁבּוֹן לֶחֳדָשִׁים וּזְמַנִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא מְתַקֵּן תֵּבָה תּוֹךְ אוֹתָם רְקִיעִים, וּמַעֲבִיר כָּרוֹז: הִנֵּה בָּנַי לְמַטָּה, קַדְּשׁוּ הַחֹדֶשׁ, קַדְּשׁוּ זְמַן, הִתְקַדְּשׁוּ כֻּלְּכֶם לְמַעְלָה! וְעוֹשֶׂה לְכָל הַחֲיָלוֹת שֶׁבַּשָּׁמַיִם שֶׁמִּתְקַדְּשִׁים כְּאֶחָד בָּעָם הַקָּדוֹשׁ, וְכֻלָּם שׁוֹמְרִים כְּאֶחָד שְׁמִירָה אַחַת, וְעַל זֶה נֶאֱמַר בְּשָׁבֻעֹתֵיכֶם, לַמִּנְיָן שֶׁאַתֶּם מוֹנִים אוֹתָם שֶׁבַע שַׁבָּתוֹת.</p>"],[9522012557,"<p>וְאָז מוֹשֵׁךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הַמְשָׁכָה שֶׁל שֶׁבַע מַדְרֵגוֹת לְמַטָּה בְּאוֹתָהּ מַדְרֵגָה שֶׁמִּתְאַחֶדֶת בָּהֶן, בְּאֵלּוּ שֶׁבַע שַׁבָּתוֹת. (באותן שבע שבתות. ואז מושך הקדוש ברוך הוא המשכה של שבע מדרגות שלמעלה באותה מדרגה שלמטה שמתאחדתבאלו שבעשבתות). וְאִם תֹּאמַר, וַהֲרֵי שֵׁשׁ הֵן וְלֹא יוֹתֵר - אֶלָּא כַּאֲשֶׁר אִמָּא יוֹשֶׁבֶת עַל הָאֶפְרוֹחִים וְנִמְצֵאת רוֹבֶצֶת עֲלֵיהֶם, וְאָנוּ מְשַׁלְּחִים אוֹתָהּ וְלוֹקְחִים אֵלּוּ הַשִּׁשָּׁה בָּנִים בְּזוֹ הַמַּדְרֵגָה שֶׁלְּמַטָּה, לְקַיֵּם שֶׁנֶּאֱמַר (דברים כב) שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים וְגוֹ'.</p>"],[9522012558,"<p>רַב הַמְנוּנָא סָבָא אָמַר, בְּיוֹם זֶה לֹא לוֹקְחִים יִשְׂרָאֵל אֶלָּא חֲמִשָּׁה בָנִים, וְאֵלּוּ הֵם חֲמִשָּׁה חֻמְשֵׁי תוֹרָה. וְאִם תֹּאמַר שִׁשָּׁה הֵם - אֶלָּא שִׁבְעָה הֵם בְּצִפּוֹר אַחַת שֶׁנִּמְצֵאת בֵּין כְּנָפֶיהָ שֶׁל אִמָּא. וְיִשְׂרָאֵל יוֹדְעִים לָצוּד צַיִד טוֹב, גָּדוֹל וְחָשׁוּב. מָה עוֹשִׂים? מוֹצִיאִים מִתַּחַת כְּנָפֶיהָ שֶׁל אִמָּא אוֹתָהּ הַצִּפּוֹר, בִּלְחִישַׁת הַפֶּה מְלַחֲשִׁים לָהּ, לְחִישָׁה אַחַר לְחִישָׁה.</p>\n<p>וְאוֹתָהּ צִפּוֹר שֶׁחוֹשֶׁשֶׁת (שאוהבת) לְאוֹתָן הַלְּחִישׁוֹת וּלְאוֹתָם קוֹלוֹת שֶׁמְּלַחֲשִׁים לָהּ, וְאַף עַל גַּב שֶׁהִיא תַּחַת כַּנְפֵי אִמָּהּ, זוֹקֶפֶת רֹאשָׁהּ וּמִסְתַּכֶּלֶת אֵצֶל אוֹתָהּ לְחִישַׁת הַקּוֹל, וּפוֹרַחַת אֲלֵיהֶם, וְיוֹצֵאת מִתַּחַת כְּנָפֶיהָ שֶׁל אִמָּא. וְכֵיוָן שֶׁיִּשְׂרָאֵל לוֹקְחִים אוֹתָהּ, מַחֲזִיקִים בָּהּ וְלוֹחֲשִׁים אֶצְלָהּ, וְקוֹשְׁרִים אוֹתָהּ בְּקֶשֶׁר שֶׁלֹּא תָעוּף וְתֵלֵךְ. מִיָּד לוֹקְחִים אוֹתָהּ יִשְׂרָאֵל בְּאוֹתוֹ קֶשֶׁר, וְהִיא מְבַקֶּשֶׁת לָעוּף וְלָלֶכֶת, וְאינָהּ יְכוֹלָה לָלֶכֶת לָהּ.</p>\n<p>וּבְעוֹד שֶׁהִיא קְשׁוּרָה בִּידֵיהֶם, הֵם לוֹחֲשִׁים בְּקוֹלָם, וְהִיא מְצַפְצֶפֶת עִמָּהֶם, וּמְעוֹפֶפֶת לְמַעְלָה וְיוֹרֶדֶת. וְכָל אוֹתָם בָּנִים שֶׁתַּחַת כַּנְפֵי אִמּוֹתֵיהֶם, כֵּיוָן שֶׁשּׁוֹמְעִים אוֹתוֹ הַצִּפְצוּף שֶׁל אֲחוֹתָם וּלְחִישַׁת אוֹתוֹ הַקּוֹל, מִיָּד יוֹצְאִים תַּחַת כַּנְפֵי אִמּוֹתֵיהֶם וּמְעוֹפְפִים אֵצֶל אוֹתָהּ הַצִּפּוֹר. וְיִשְׂרָאֵל לוֹקְחִים אוֹתָם וְאוֹחֲזִים בָּהֶם. וְאִם לֹא אוֹתָהּ צִפּוֹר שֶׁאוֹחֲזִים בָּהּ בַּתְּחִלָּה, לֹא הָיוּ אֵלּוּ מְעוֹפְפִים אֶצְלָם לְעוֹלָמִים, וְלֹא יְכוֹלִים לֶאֱחֹז בָּהֶם.</p>\n<p>אֵיךָ צָדִים צִידָה שֶׁל צִפּוֹר קְדוֹשָׁה זוֹ? מְתַקְּנִים לְפָנֶיהָ מַאֲכָל מְכֻבָּד בְשִׂמְחָה וְכָל תַּעֲנוּגִים, וְנִכְנָסִים לְבָתֵּי כְנֵסִיּוֹת וּלְבָתֵּי מִדְרָשׁוֹת, וּמְצַפְצְפִים אֵלֶיהָ בְּקוֹל לַחַשׁ כְּמוֹ שֶׁרָאוּי. וְהִיא נִסְתֶּרֶת תַּחַת כְּנָפֶיהָ שֶׁל אִמָּא, וְזוֹקֶפֶת רֹאשָׁהּ, וְרוֹאָה שֻׁלְחָנוֹת מְתֻקָּנִים וְצִפְצוּפִים אֵלֶיהָ כְּמוֹ שֶׁרָאוּי. יוֹצֵאת וּמְעוֹפֶפֶת אֶצְלָם כְּמוֹ שֶׁנִּתְבָּאֵר, וּבָהּ אֲחוּזִים כָּל אוֹתָם בָּנִים.</p>\n<p>וּמְשַׁלְּחִים לְאוֹתָהּ שֶׁרוֹבֶצֶת עֲלֵיהֶם, וְהוֹלֶכֶת. מִשּׁוּם שֶׁהֲרֵי מֵהָרָקִיעַ הַשְּׁבִיעִי וּלְמַעְלָה, בַּמְכֻסֶּה מִמְּךְ אַל תִּדְרֹשׁ. שָׁלַח אוֹתָהּ, שֶׁלֹּא תוּכַל לְהַשִּׂיגָהּ, וְעַל זֶה כָּתוּב (דברים כב) שַׁלֵּחַ תְּשַׁלַּח וְגוֹ'.</p>\n<p>מִקְרָא קֹדֶשׁ - זוֹהִי הַקְּרִיאָה וְהַצִּפְצוּף שֶׁעוֹשִׂים לְאוֹתָהּ צִפּוֹר קְדוֹשָׁה בָּרִאשׁוֹנָה. וְכֵיוָן שֶׁאֲחוּזִים בָּהּ שְׁאָר הַיָּמִים, נִקְרָאִים מִקְרָאֵי קֹדֶשׁ. צִפּוֹר זוֹ נִקְרֵאת קֹדֶשׁ, שֶׁכָּתוּב כִּי קֹדֶשׁ הִיא לָכֶם. וּמִשּׁוּם שֶׁהִיא קֹדֶשׁ, הִיא קוֹרֵאת לְכֻלָּם וּבָאִים אֶצְלָהּ, וּמִשּׁוּם זֶה נִקְרָאִים מִקְרָאֵי קֹדֶשׁ.</p>\n<p>הִיא קוֹרֵאת, וְיִשְׂרָאֵל מְצַפְצְפִים עִמָּהּ וְקוֹרְאִים גַּם כָּךְ. וְעַל זֶה הֵם בָּאִים אֶצְלָם וְאוֹחֲזִים בָּהֶם. וּמִשּׁוּם זֶה (ויקרא כג) אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אֹתָם. מִקְרָאֵי קֹדֶשׁ - בַּצִּפְצוּפִים שֶׁלָּהֶם, וּבְאוֹתָהּ צִפּוֹר קְדוֹשָׁה. קֹדֶשׁ - שֶׁקּוֹרֵאת לָהֶם.</p>"],[9522012559,"<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, דְּבָרִים אֵלּוּ כַּמָּה סְתוּמִים הֵם לְמִי שֶׁלֹּא יוֹדֵעַ, וְנִגְלִים לְמִי שֶׁיּוֹדֵעַ בָּהֶם. וַדַּאי אוֹתָהּ צִפּוֹר הִיא הַשְּׁכִינָה. הַקֵּן שֶׁלָּהּ זֶה בֵּית הַמִּקְדָּשׁ. וְיִשְׂרָאֵל הֵם הָאֶפְרוֹחִים, שֶׁאִמָּא יוֹשֶׁבֶת עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב (דברים לב) וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים, וְהֵם בַּעֲלֵי מִשְׁנָה שֶׁמְּעוֹפְפִים בַּמִּצְווֹת שֶׁלָּהּ. אוֹ בֵיצִים - אֵלּוּ בַּעֲלֵי מִקְרָא.</p>\n<p>וּבִזְמַן שֶׁחָטְאוּ יִשְׂרָאֵל וְנֶחֱרַב בֵּית הַמִּקְדָּשׁ, מַה כָּתוּב? שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם. זֶהוּ שֶׁכָּתוּב (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאֵלּוּ בַּעֲלֵי שִׁשָּׁה סִדְרֵי מִשְׁנָה כָּתוּב בָּהֶם, וְאֶת הַבָּנִים תִּקַּח לָךְ. שֶׁהֵם שִׁשָּׁה מִצַּד שֶׁל שִׁשָּׁה בָנִים שֶׁתַּחַת הָאִמָּא הָעֶלְיוֹנָה, שֶׁהֵם בְּשֵׁשׁ תֵּבוֹת שֶׁל קְרִיאַת שְׁמַע, אוֹ בְּשִׁשָּׁה סִדְרֵי מִשְׁנָה, אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט וּבִלְבַד שֶׁיְּכַוֵּן לִבּוֹ לַשָּׁמַיִם. וְקוֹשְׁרִים אוֹתָם בְּקִשְׁרֵי הַתְּפִלִּין, עַל הָרֹאשׁ וְעַל הַזְּרוֹעַ.</p>\n<p>וּבַמֶּה לוֹקְחִים הַבָּנִים? בְּכַמָּה צִפְצוּפִים שֶׁל קוֹלוֹת שֶׁל קְרִיאַת שְׁמַע. וּבַסּוֹף לוֹחֲשִׁים בִּלְחִישַׁת הַתְּפִלָּה שֶׁבַּחֲשַׁאי אֵצֶל אִמָּא וּבִתָּהּ, וְאֵלּוּ ה' ה', וְיוֹרְדִים אֵצֶל ו' בַּקֶּשֶׁר שֶׁלּוֹ, שֶׁהִיא יוֹ\"ד. וְשׁוֹרָה ה' עֶלְיוֹנָה עַל ו', תְּפִלִּין עַל רֹאשׁוֹ. ה' קְטַנָּה יוֹרֶדֶת אֵצֶל י', שֶׁהִיא קֶשֶׁר שֶׁל ה' עֶלְיוֹנָה, עַל רֹאשׁ ו', וְהִיא ו', קֶשֶׁר עִמָּהּ בְּה' שֶׁל יָד כֵּהָה.</p>\n<p>וּמִשּׁוּם זֶה אֶפְרֹחִים, מִצַּד שֶׁל אוֹת ו', כּוֹלֵל שִׁשָּׁה סִדְרֵי מִשְׁנָה. אוֹ בֵיצִים - אֵלּוּ בַּעֲלֵי מִקְרָא שֶׁנֶּאֱמַר עֲלֵיהֶם בֶּן חָמֵשׁ שָׁנִים לְמִקְרָא, וְזוֹ ה'. בָּנִים מִצַּד שֶׁל בֶּן יָ\"הּ, אֵלּוּ בַּעֲלֵי קַבָּלָה. עֲלֵיהֶם נֶאֱמַר (דברים כב) לֹא תִקַּח הָאֵם עַל הַבָּנִים. וּבַעָלֵי קַבָּלָה אֵלּוּ בַּעֲלֵי תַלְמוּד, וְנֶאֱמַר עֲלֵיהֶם (שם ו) וְשִׁנַּנְתָּם. וּבֵאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, אַל תִּקְרֵי וְשִׁנַּנְתָּם אֶלָּא וְשִׁלַּשְׁתָּם. שֶׁהֵם שְׁלִישׁ בַּמִּקְרָא, שְׁלִישׁ בַּמִּשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד.</p>"],[9522012560,"<p>וְסוֹד הַדָּבָר - (שם כב) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ בַּדֶּרֶךְ, בְּבַעֲלֵי מִקְרָא. (שמות כה) וְעָשִׂיתָ מְנֹרַת זָהָב טָהוֹר. הֲרֵי בֵּאֲרוּהוּ, מְנֹרַת - כְּלָל. זָהָב - פְּרָט. מִקְשָׁה - כְּלָל. וְכַמָּה פְסוּקִים בַּעֲלֵי הַמִּשְׁנָה, אֵלּוּ מַרְבִּים וּמְמַעֲטִים, כְּגוֹן רִבָּה וּמִעֵט. אַף כָּךְ מַרְבִּים, אַל תִּקְרָא מָה אֶלָּא מֵאָה. אַף כָּךְ אַל תִּקְרָא וְשִׁנַּנְתָּם אֶלָּא וְשִׁלַּשְׁתָּם. וְדוֹרְשִׁים מִמֶּנּוּ, שְׁלִישׁ בַּמִּקְרָא, שְׁלִישׁ בַּמִּשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד. כְּמוֹ שֶׁיֵּשׁ בְּקִדּוּשִׁין.</p>\n<p>אַף כָּךְ (במדבר ז) בְּיוֹם כַּלֹּת מֹשֶׁה, וְדוֹרְשִׁים בּוֹ כַּלַּת. אִם תֹּאמַר שֶׁדּוֹרְשִׁים לָהֶם מֵהֶם - כֵּיצַד מֵאָלֶף בֵּית וְלֹא מֵעַצְמָם, שֶׁהֵם אֵין לָהֶם רְשׁוּת לְהוֹסִיף וְלֹא לִגְרֹעַ אוֹת מִמֶּנּוּ, (שהיא ו') אוֹ לְהַחֲלִיף אוֹת זוֹ בְּאוֹת אַחֶרֶת. הֲרֵי כָּתוּב כַּלּוֹת מָלֵא בַּתּוֹרָה, וּמִי נוֹתֵן לָהֶם רְשׁוּת לִגְרֹעַ אוֹת מִמֶּנָּה, שֶׁהִיא ו'? הֲרֵי אֵין כָּאן דָּבָר שֶׁמִּתְחַלֵּף בָּאָלֶף בֵּית. אֶלָּא עַל אֵלּוּ תֵּבוֹת חֲסֵרוֹת שֶׁהֵן מְלֵאוֹת, וּמְלֵאוֹת שֶׁהֵן חֲסֵרוֹת, וְעַל כָּל פֵּרוּשִׁים שֶׁיְּכוֹלִים לַעֲשׂוֹת לְקַשֵּׁט כַּלָּה בְּתַכְשִׁיטֶיהָ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְצַוֶּה לַעֲשׂוֹת כְּמוֹ שֶׁיֹּאמְרוּ, וְלִהְיוֹת מַאֲמִין לָהֶם. זֶהוּ שֶׁכָּתוּב (דברים יז) עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךְ.</p>\n<p>לְאֻמָּן שֶׁחָתַךְ כְּלֵי לְבוּשִׁים שֶׁל הַמַּלְכוּת וְעָשָׂה מֵהֶם חֲתִיכוֹת רַבּוֹת - אֵלּוּ שֶׁיּוֹדְעִים הַמְּקוֹמוֹת שֶׁחֲסֵרִים אֵלּוּ הַחֲתִיכוֹת אוֹ אֵלּוּ שֶׁנִּשְׁאָרִים, אֵלּוּ מְתַקְּנִים אוֹתָם הַלְּבוּשִׁים, וְשָׂמִים אֵלּוּ הַחֲתִיכוֹת שֶׁנּוֹסָפוֹת בִּמְקוֹם הַחֲסֵרוֹת, וַחֲתִיכוֹת שֶׁהֵן מוּעָטוֹת, מוֹסִיפִים עֲלֵיהֶן, וְזֶהוּ שֶׁנֶּאֱמַר עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךְ.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ הוּא, מַהוּ שֶׁלִּפְעָמִים טוֹעֶה אֶחָד מֵהֶם וְיֹאמַר חוֹזְרַנִי בִּי? אֶלָּא עַד שֶׁיַּעֲשׂוּ הוֹרָאָה מֵאוֹתוֹ דִּבּוּר שֶׁחוֹלְקִים עָלָיו, יָכוֹל אוֹתוֹ שֶׁהִקְשָׁה עָלָיו לוֹמַר חוֹזְרַנִי בִּי. שֶׁלֹּא כָּל אֵלּוּ שֶׁמְּפָרְקִים תַּכְשִׁיטֵי הַכַּלָּה יוֹדְעִים בַּחֲתִיכוֹת לְאָן הוֹלְכוֹת, עַד שֶׁיְּהֵא הַפְּסָק עַל בֻּרְיוֹ, תֵּרוּצֵי הַהֲלָכוֹת עַל בֻּרְיָם.</p>\n<p>הַמְּנוֹרָה, שִׁבְעַת נֵרוֹתֶיהָ הוּא שֶׁנֶּאֱמַר, (אסתרב) אֵת שֶׁבַע הַנְּעָרוֹת הָרְאֻיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ. כְּנֶגֶד שִׁי\"ן שֶׁל שְׁלֹשָׁה רָאשִׁים ש, וְאוֹת שִׁי\"ן שֶׁל אַרְבָּעָה רָאשִׁים שֶׁבַּתְּפִלִּין, וְהֵם כְּנֶגֶד שֶׁבַע בְּרָכוֹת שֶׁל קְרִיאַת שְׁמַע, שֶׁהֵן: בַּשַּׁחַר מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ. וְאַחַר כָּךְ כֹּהֵן גָּדוֹל בָּעֲבוֹדָה, שֶׁמְּשַׁמֵּשׁ בְּכַנְפֵי מִצְוָה. פַּעֲמוֹנִים וְרִמּוֹנִים - אֵלּוּ הַקְּשָׁרִים וְהַחֻלְיוֹת. וְצִיץ - תְּפִלִּין. מִשָּׁם וְאֵילָךְ, (שמות ל) וְעָשִׂיתָ מִזְבֵּחַ מִקְטַר קְטֹרֶת.</p>"],[9522012561,"<p>פָּתַח הָרוֹעֶה הַנֶּאֱמָן (רבי שמעון) וְאָמַר, כָּתוּב בְּפָרָשָׁה זוֹ, וְהִקְרַבְתֶּם אִשֶּׁה עֹלָה לַה'. וּפֵרְשׁוּהָ, שֶׁעוֹלָה לָאִשִּׁים. וְלָכֵן סָמַךְ עוֹלָה לְאִשֶּׁה. וְעוֹד פֵּרְשׁוּהוּ, שֶׁאֵין עוֹלָה בָּאָה אֶלָּא עַל הִרְהוּר הַלֵּב.</p>\n<p>וַדַּאי, כָּל הַקָּרְבָּנוֹת לֹא בָאִים אֶלָּא לְכַפָּרָה. כָּל קָרְבָּן וְקָרְבָּן עַל כָּל אֵיבָרִים שֶׁל אָדָם כְּפִי אוֹתוֹ חֵטְא שֶׁל אוֹתוֹ אֵיבָר. עַל טִפּוֹת הַמֹּחַ נֶאֱמַר, (שמות יב) עֻגֹת מַצּוֹת כִּי לֹא חָמֵץ. אִם זוֹרֵק טִפּוֹת רִאשׁוֹנוֹת קֹדֶם שֶׁהֶחְמִיצוּ בְּמָקוֹם שֶׁלֹּא שֶׁלּוֹ. וְעַל אֵלּוּ שֶׁהֶחְמִיצוּ וְזָרַק אוֹתָן בְּמָקוֹם שֶׁלֹּא צָרִיךְ, צָרִיךְ לְהָבִיא עֲלֵיהֶן לֶחֶם חָמֵץ, וְאוֹתָם לַחְמֵי תוֹדָה כָּךְ הֵם - מֵהֶם חָמֵץ וּמֵהֶם מַצָּה. פָּרִים - מִצַּד הַדִּין, וְכֵן כְּבָשִׂים וְאֵילִים וְעַתּוּדִים וְעִזִּים. מִשּׁוּם שֶׁהֵם פְּנֵי שׁוֹר, כֻּלָּם שְׁחִיטָתָם בַּצָּפוֹן, וְקִבּוּל דָּמָם בִּכְלִי שָׁרֵת בַּצָּפוֹן.</p>\n<p>שְׁחִיטָה וְקַבָּלָה וּזְרִיקָה כֻּלָּם בַּצָּפוֹן, לְבַסֵּם מִדַּת הַדִּין שֶׁבָּאָה לְבֵית דִּין מִצַּד הַגְּבוּרָה. בֵּית דִּין הַגָּדוֹל מִצַּד הַגְּבוּרָה, שֶׁשָּׁם בִּינָה. בֵּית דִּין הַקָּטָן מִצַּד הַמַּלְכוּת. וְכָל אוֹתָם שׁוֹפְכֵי דָמִים לְמִצְוָה הֵם מִצַּד הַגְּבוּרָה.</p>\n<p>וּמַה שֶּׁבֵּאֲרוּהָ עֹלַת שַׁבַּת בְּשַׁבַּתּוֹ - וְלֹא בְּשַׁבָּת אַחֶרֶת, מִשּׁוּם שֶׁעָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ. שֶׁקָּרְבָּן דּוֹחֶה שַׁבָּת, וּמַדְלִיק אֵשׁ בְּשַׁבָּת, מִשּׁוּם שֶׁהוּא אֵשׁ שֶׁל קְדֻשָּׁה. שֶׁכָּל אֵשׁ שֶׁל קָרְבָּנוֹת הוּא קֹדֶשׁ, וְשַׁבָּת קֹדֶשׁ, אֲחוּזִים זֶה בָּזֶה.</p>\n<p>אֲבָל אֵשׁ שֶׁל חֹל אָסוּר לָתֵת לוֹ אֲחִיזָה בַּקֹּדֶשׁ, וּמִשּׁוּם זֶה צִוָּה לָהֶם לְיִשְׂרָאֵל, (שמותלה) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם בְּיוֹם הַשַּׁבָּת. שֶׁזֶּהוּ כִּלְאַיִם שֶׁל טוֹב וָרָע. וּבְשַׁבָּת שֶׁשּׁוֹלֵט עֵץ הַחַיִּים, שֶׁאֵין בּוֹ תַּעֲרֹבֶת, (אסור להבעיר בו חלין, שזה האש של חלין של טמאה, ולא של חלין של טהרה) וְחֻלִּין שֶׁל טָהֳרָה אָסוּר לְעָרֵב בְּאֵשׁ שֶׁל קְדֻשָּׁה. כָּל שֶׁכֵּן חֻלִּין שֶׁל טֻמְאָה שֶׁאָסוּר לְעָרֵב אוֹתָם בִּקְדֻשָּׁה. אַף כָּךְ כָּל קָרְבָּנוֹת נִקְרָאִים בְּשַׂר קֹדֶשׁ, וְכָל קָרְבָּנוֹת שֶׁל כָּל מִין יֵשׁ בָּהֶם חֻלִּין שֶׁל טָהֳרָה, וְיֵשׁ בָּהֶם קֹדֶשׁ וְקֹדֶשׁ הַקְּדָשִׁים.</p>\n<p>וְהַסּוֹד שֶׁיֵּשׁ הֶפְרֵשׁ בֵּין קֹדֶשׁ לְקֹדֶשׁ, זֶהוּ שֶׁכָּתוּב (שמות כו) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקְּדָשִׁים. אַף כָּךְ אִשֵּׁי הַקָּרְבָּנוֹת אֵינָם שָׁוִים. שֶׁאֵשׁ שֶׁל גָּבוֹהַּ מְקֻדָּשׁ מֵאֵשׁ שֶׁל קֹדֶשׁ שֶׁלְּמַטָּה, שֶׁנִּקְרָא אֵשׁ עֲצֵי הַקֹּדֶשׁ, אוֹ אֵשׁ בְּשַׂר הַקֹּדֶשׁ. וְאֵשׁ שֶׁל קְדֻשָּׁה יֵשׁ בּוֹ הַבְדָּלָה בֵּינוֹ לְבֵין אֵשׁ שֶׁל הֶדְיוֹט. אַף עַל גַּב שֶׁבֵּאֲרוּ עָלָיו שֶׁמִּצְוָה לְהָבִיא מִן הַהֶדְיוֹט אַף עַל גַּב שֶׁיֵּשׁ אֵשׁ שֶׁל קֹדֶשׁ, שֶׁכָּל אֶחָד צָרִיךְ לִמְקוֹמוֹ. וּמָשָׁל נִמְשְׁלוּ יִשְׂרָאֵל הָרִאשׁוֹנִים לְסוֹד זֶה יִשְׂרָאֵל.</p>\n<p>(ישראל נמשלו לזה. שהרי ישראל בכלל) נִקְרָאִים מְלָכִים, כְּמוֹ שֶׁבֵּאֲרוּהוּ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. אֲבָל כַּאֲשֶׁר הָיוּ עוֹלִים לְבֵית הַמִּקְדָּשׁ, כָּל אֶחָד שׁוֹרֶה בִּמְקוֹמוֹ כְּמוֹ שֶׁרָאוּי לוֹ. אַף כָּךְ כָּל הַקָּרְבָּנוֹת אֵינָם שָׁוִים, שֶׁאַף עַל גַּב שֶׁבְּכֻלָּם כָּתוּב קָרְבָּן לַה', הוּא מְחַלֵּק הַכֹּל כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁרָאוּי. וְסוֹד זֶה נוֹדָע בְּפָרֵי הֶחָג, שֶׁהָיוּ מַקְרִיבִים לָהֶם יִשְׂרָאֵל לִפְנֵי ה'.</p>"],[9522012562,"<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, קוּם רוֹעֶה נֶאֱמָן מִשְּׁנָתְךְ, שֶׁאַתָּה וְהָאָבוֹת נִקְרָאִים יְשֵׁנֵי עָפָר, שֶׁעַד כָּאן הֱיִיתֶם מִשְׁתַּדְּלִים בַּתּוֹרָה בְּאוֹתָם יְשֵׁנִים בַּמִּשְׁנָה, שֶׁנֶּאֱמַר בָּהֶם עַל הָאָרֶץ תִּישָׁן. וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה לַה'. אַתֶּם הֵם (בני) בִּכּוּרִים שֶׁל הַשְּׁכִינָה, וּבַמַּעֲשִׂים שֶׁלָּכֶם הִיא מִתְחַדֶּשֶׁת בַּתְּפִלּוֹת שֶׁל הָאָבוֹת בְּכָל יוֹם. שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, תְּפִלּוֹת כְּנֶגֶד אָבוֹת תִּקְּנוּם. וּבִקְרִיאַת שְׁמַע שֶׁאָמַר הָרוֹעֶה הַנֶּאֱמָן שְׁמַע יִשְׂרָאֵל, וּפֵרְשׁוּהָ כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע בְּכָל יוֹם כְּאִלּוּ הוּא מְקַיֵּם (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה.</p>\n<p>וַדַּאי בַּתְּפִלּוֹת שֶׁלָּהֶם, בַּקְּרִיאַת שְׁמַע שֶׁלָּכֶם, הַשְּׁכִינָה הִיא מִתְחַדֶּשֶׁת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם זֶה נֶאֱמַר וְהִקְרַבְתֶּם מִנְחָה חֲדָשָׁה לַה'. בַּתְּפִלּוֹת שֶׁהֵן בִּמְקוֹם הַקָּרְבָּנוֹת. בְּאֵילוּ קָרְבָּנוֹת שֶׁל הַתְּפִלּוֹת הִיא מִתְחַדֶּשֶׁת? בְּשָׁבֻעֹתֵיכֶם. כְּלוֹמַר שָׁבוּעוֹת, שֶׁבּוֹ מַתַּן תּוֹרָה, וְנִקְרָא חֲמִשִּׁים יוֹם לָעֹמֶר. וּבוֹ שִׁבְעָה שָׁבוּעוֹת, מִצַּד אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ. וְהִיא מַלְכוּת, כַּלָּה, כְּלוּלָה מִשֶּׁבַע סְפִירוֹת, כְּלוּלָה בְּבִינָה, שֶׁהִיא מִתְפַּשֶּׁטֶת בְּחָמֵשׁ סְפִירוֹת לַחֲמִשִּׁים.</p>\n<p>יְסוֹד כֹּל, כָּלוּל מֵאֵלּוּ הַחֲמִשִּׁים. כַּלָּ\"ה - כֹּ\"ל ה'. כְּלוּלָה מֵחֲמִשִּׁים, כֻּלָּם נִבְלָעִים בְּתוֹךְ חֲמִשִּׁים, חָכְמָה שֶׁהִיא י' עֶלְיוֹנָה מֻבְלַעַת בְּתוֹךְ חֲמִשִּׁים. ה' פְּעָמִים עֶשֶׂר. ה' - בִּינָה. י' - חָכְמָה. עֶשֶׂר פְּעָמִים ה', כְּלוֹמַר חֲמִשִּׁים בְּחֶשְׁבּוֹן כֹּ\"ל, וּבְחֶשְׁבּוֹן יָ\"ם, וְהוּא יָם הַתּוֹרָה. הַמָּקוֹר שֶׁלּוֹ כֶּתֶר, שֶׁאֵין לוֹ סוֹף. שְׁאָר הַסְּפִירוֹת נִקְרָאוֹת עַל שְׁמָהּ שִׁבְעַת יָמִים. וְהַמַּלְכוּת יַם סוּף, שֶׁהִיא סוֹף כָּל הַיָּמִים.</p>\n<p>וּמִשּׁוּם זֶה שֶׁהֵם חֲמִשִּׁים, שִׁבְעָה שָׁבוּעוֹת, מִנְחָתָם שְׁלֹשָׁה עֶשְׂרוֹנִים וּשְׁנֵי עֶשְׂרוֹנִים, חָמֵשׁ, שֶׁהֵם חָמֵשׁ פְּעָמִים עֶשֶׂר. זֶהוּ שֶׁכָּתוּב (במדבר כח) וּמִנְחָתָם סֹלֶת בְּלוּלָה בַשָּׁמֶן שְׁלֹשָׁה עֶשְׂרֹנִים לַפָּר הָאֶחָד (ו) שְׁנֵי עֶשְׂרֹנִים לָאַיִל הָאֶחָד, עִשָּׂרוֹן עִשָּׂרוֹן לַכֶּבֶשׂ הָאֶחָד לְשִׁבְעַת הַכְּבָשִׂים. וְשִׁבְעַת הַכְּבָשִׂים כְּנֶגֶד (ויקרא כג) שֶׁבַע שַׁבָּתוֹת תְּמִימֹת תִּהְיֶינָה. כָּל אֶחָד עִם שִׁשָּׁה הַיָּמִים שֶׁלּוֹ.</p>"],[9522012563,"<p>וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי (במדבר כט) - שֶׁהוּא תִּשְׁרֵי. מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם - זֶה יוֹם הַכִּפּוּרִים, שֶׁהוּא עֲשִׂירִי, י', כָּלוּל מֵעֲשֶׂרֶת יְמֵי תְשׁוּבָה. וְתִקְּנוּ בוֹ חָמֵשׁ תְּפִלּוֹת, לְחַבֵּר אוֹתוֹ עִם ה'. (מהו מקרא קדש יהיה לכם, ' זה יום הכפורים שהוא עשירי, י', כלול מעשרת ימי תשובה. ותקנו בו חמש תפלות, לחברו עם ה') מַהוּ מִקְרָא קֹדֶשׁ? לְהַבְדִּילוֹ מִשְּׁאָר יָמִים שֶׁיֵּשׁ בָּהֶם עֲבוֹדָה שֶׁל חֹל. וּמִשּׁוּם זֶה, כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ.</p>\n<p>שֶׁיָּמִים שֶׁיֵּשׁ בָּהֶם מְלָאכָה שֶׁל חֹל, הֵם מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע. שֶׁהִתְהַפֵּךְ מִמַּטֶּה לְנָחָשׁ, וּמִנָּחָשׁ לְמַטֶּה, לְכָל אֶחָד כְּפִי מַעֲשָׂיו. וְזֶה מְטַטְרוֹן מַטֶּה, נָחָשׁ, סָמָאֵל. אֲבָל בְּיוֹם זֶה, שֶׁהוּא יוֹם הַכִּפּוּרִים שֶׁנִּקְרָא קֹדֶשׁ, שׁוֹלֵט עֵץ הַחַיִּים, שֶׁלֹּא מִשְׁתַּתֵּף עִמּוֹ שָׂטָן וּפֶגַע רָע. וּמִצִּדּוֹ (תהלים ה) לֹא יְגֻרְךְ רָע. וּמִשּׁוּם זֶה יֵשׁ בּוֹ מְנוּחָה לַעֲבָדִים בְּעֵץ הַחַיִּים, (ומשתתפים אצלו) וּבוֹ יוֹצְאִים לַחֵרוּת, בּוֹ יוֹצְאִים מִשַּׁלְשְׁלוֹתֵיהֶם.</p>\n<p>אֵלּוּ שֶׁיֵּשׁ עֲלֵיהֶם גְּזַר דִּין בְּנֶדֶר וּבִשְׁבוּעָה, וּמִשּׁוּם זֶה הִתְקִינוּ לוֹמַר בּוֹ: כָּל נְדָרִים וְאִסּוּרִים וְכוּ', כֻּלָּם יִהְיוּ מֻשְׁבָּתִים וַעֲזוּבִים בְּלִי תֹקֶף וְלֹא קַיָּמִים. וּמִשּׁוּם זֶה נֶדֶר שֶׁל שֵׁם יְהֹוָ\"ה, שֶׁהִיא תִּפְאֶרֶת. וּשְׁבוּעָה - שֶׁל אֲדנָי, שֶׁהִיא מַלְכוּת. שֶׁעָשׂוּ עַל גָּלוּת שֶׁלָּהֶם, בְּחָכְמָה וּבִינָה יִהְיוּ נֶעֱזָבִים וּמֻשְׁבָּתִים לְלֹא תֹקֶף וּבְלִי קִיּוּם, (במדבר טו) וְנִסְלַח לְכָל עֲדַת בְּנֵי יִשְׂרָאֵל. שֶׁחֶסֶד הוּא מַיִם, וּגְבוּרָה אֵשׁ, וְתִפְאֶרֶת אֲוִיר. וּמִשּׁוּם זֶה בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, הֶתֵּר נְדָרִים פּוֹרְחִים בָּאֲוִיר.</p>\n<p>וּמִשּׁוּם שֶׁשְּׁבוּעָה מִמַּלְכוּת, שֶׁהִיא לְמַטָּה מִמֶּנּוּ, פֵּרְשׁוּהוּ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִים. וְעוֹד פֵּרְשׁוּ, כָּל הַנִּשְׁבָּע כְּאִלּוּ נִשְׁבָּע בַּמֶּלֶךְ עַצְמוֹ, וְכָל הַנּוֹדֵר כְּאִלּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ. הַמֶּלֶךְ עַצְמוֹ - אֲדנָי. חַיֵּי הַמֶּלֶךְ - יְהֹוָ\"ה. וּמִשּׁוּם זֶה נֶאֱמַר (במדבר ל) כִּי יִדֹּר נֶדֶר לַיהֹוָ\"ה.</p>\n<p>וְאַף כָּךְ יֵשׁ סוֹד אַחֵר, חַיֵּי הַמֶּלֶךְ - חָכְמָה. זֶהוּ שֶׁכָּתוּב (קהלת ז) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. כָּל הַנּוֹדֵר בַּיהֹוָה, שֶׁהוּא תִּפְאֶרֶת, כְּאִלּוּ נוֹדֵר בַּחָכְמָה, שֶׁהוּא שֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, חַיֵּי הַמֶּלֶךְ. וְכָל הַנִּשְׁבָּע בַּאדנָי, כְּאִלּוּ נִשְׁבָּע בַּמֶּלֶךְ עַצְמוֹ. עַצְמוֹ, זוֹ אִמָּא עֶלְיוֹנָה, כְּאִלּוּ נִשְׁבָּע בָּהּ, שֶׁהִיא (שמות כד) עֶצֶם הַשָּׁמַיִם לָ הַר. מִצַּד הַחֶסֶד - (בראשית ב) עֶצֶם מֵעֲצָמַי. וּבָשָׂר מִבְּשָׂרִי - מִצַּד הַגְּבוּרָה, זוֹ מַלְכוּת. וּבַחָכְמָה, שֶׁהִיא חַיֵּי תִפְאֶרֶת, הוּא עוֹלֶה לִקְרַאת אָדָם. זֶהוּ שֶׁכָּתוּב (ישעיה מד) כְּתִפְאֶרֶת אָדָם.</p>\n<p>וְנֶאֱמַר בְּיוֹם הַכִּפּוּרִים, (ויקרא טז) וְעִנִּיתֶם אֶת נַפְשּתֵיכֶם. וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה תְּעַנּוּ אֶת נַפְשּתֵיכֶם. תִּקְּנוּ בוֹ חֲמִשָּׁה עִנּוּיִים, כְּדֵי שֶׁתִּתְלַבֵּן ה' קְטַנָּה בְּה' עֶלְיוֹנָה, שֶׁהִיא חָמֵשׁ תְּפִלּוֹת. לְקַיֵּם בְּיִשְׂרָאֵל, (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְזֶהוּ סוֹד שֶׁל לְשׁוֹן זְהוֹרִית, מִשּׁוּם שֶׁכָּל הַחוֹבוֹת שֶׁל יִשְׂרָאֵל מַגִּיעִים אֵצֶל הַמַּלְכוּת, וּתְשׁוּבָה, שֶׁהִיא בִּינָה, מְלַבֶּנֶת אוֹתָם, מִשּׁוּם שֶׁנֶּאֱמַר בָּהּ (ויקרא טז) הַשֹּׁכֵן אִתָּם בְּתוֹךְ טֻמְאֹתָם. וְאַרְבָּעָה בִּגְדֵי לָבָן וְאַרְבָּעָה בִּגְדֵי זָהָב לְהַלְבִּישׁ - יְאֲהדוָנָהי.</p>\n<p>וְתִקְּנוּ לִתְקֹעַ שׁוֹפָר בְּיוֹם הַכִּפּוּרִים, לְהַעֲלוֹת קוֹל, שֶׁהוּא אוֹת ו', לְחֵרוּת, שֶׁנֶּאֱמַר בָּהּ (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר - בְּא' וּבְו', קְרִי וּכְתִיב. וַעֲבוֹדַת יוֹם הַכִּפּוּרִים הִיא בַּאֲרִיכוּת, וְהִיא כְּלוּלָה מִשָּׁלֹשׁ מַדְרֵגוֹת - בְּמַחֲשָׁבָה, דִּבּוּר וּמַעֲשֶׂה.</p>"],[9522012564,"<p>בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ' (ויקרא כג), שֶׁהוּא תִּשְׁרֵי, מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם. כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ. וְחַגֹּתֶם אֹתוֹ חַג לַה' שִׁבְעַת יָמִים וְגוֹ'. בַּחֲמִשָּׁה עָשָׂר - מִצַּד שֶׁל יָ\"הּ. וְחַגֹּתֶם אֹתוֹ - זוֹ אוֹת ו', הָעַמּוּד הָאֶמְצָעִי. (ח\"ג חסד גבורה) שִׁבְעַת יָמִים - מִצַּד שֶׁל בַּת שֶׁבַע, שֶׁהִיא מַלְכוּת. הָאָבוֹת, וְהָרוֹעֶה הַנֶּאֱמָן, וְאַהֲרֹן, דָּוִד וּשְׁלֹמֹה - הֲרֵי הֵם שִׁבְעָה, כְּנֶגֶד שֶׁבַע סְפִירוֹת. אֲנִי רוֹצֶה לְתַקֵּן לָכֶם סֻכָּה, שֶׁהִיא אִמָּא עֶלְיוֹנָה, לְסַכֵּךְ עֲלֵיהֶם כְּאִמָּא עַל בָּנִים.</p>\n<p>וּמִשּׁוּם שֶׁבַע סְפִירוֹת אָמַר הַפָּסוּק, (ויקרא כג) כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל, בְּצֵאתָם מֵאֶרֶץ מִצְרַיִם, בְּשִׁבְעָה עַנְנֵי כָבוֹד. סֻכָּה (יש שכתובה באות ו', בסכת חסר ו', שנאמר בה בסכת תשבו שבעת ימים. היא אמא. אבל סכה) בְּאוֹת ו' הִיא בְּסוֹד (התבות) שֶׁל שְׁנֵי בָנִים - יְהֹוָה אֲדנָי. וְכָךְ עוֹלָה סוּכָּ\"ה בְּחֶשְׁבּוֹן יְאֲהדוָנָהי. שְׁנֵי כְרוּבִים, שֶׁהֵם (שמות כה) סֹכֲכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת וּפְנֵיהֶם אִישׁ אֶל אָחִיו.</p>\n<p>וְיִשִׁ עֲשָׂרָה טְפָחִים בַּכְּרוּבִים מִמַּטָּה לְמַעְלָה, מֵרַגְלֵיהֶם עַד רָאשֵׁיהֶם, וּמֵרָאשֵׁיהֶם עַד רַגְלֵיהֶם, וְשׁוֹרִים עַל טֶפַח שֶׁהוּא י'. וַעֲשָׂרָה עֲשָׂרָה מִמַּעְלָה לְמַטָּה, וּמִמַּטָּה לְמַעְלָה, כְּלוֹמַר יוֹ\"ד. וּמִשּׁוּם זֶה שִׁעוּר סֻכָּה אָמְרוּ חֲכָמִים, לֹא פָחוֹת מֵעֲשָׂרָה, וְלֹא לְמַעְלָה מֵעֶשְׂרִים. סֻכָּה הָעֲשׂוּיָה כְּכִבְשָׁן מִצַּד שֶׁל אִמָּא, עָלֶיהָ נֶאֱמַר (שמות יט) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. (ופרשוהו, מהו (יחזקאל א) והחיות רצוא ושוב, ' כאור היוצא מפי הכבשן) וְהַכֹּל אֶחָד.</p>\n<p>וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם (ישעיה ד), שֶׁצָּרִיךְ סְכָךְ. וּסְכָךְ נַעֲשֶׂה לְצֵל, שֶׁנֶּאֱמַר בּוֹ (תהלים צא) בְּצֵל שַׁדַּי יִתְלוֹנָן. וְלֹא בְצֵל סֻכַּת הֶדְיוֹט, שֶׁמֵּגֵן עַל הַגּוּף מִשֶּׁמֶשׁ. אֶלָּא צֵל לְהָגֵן עַל הַנְּשָׁמָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ב) בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי. (איכהד) אֲשֶׁר אָמַרְנוּ בְּצִלּוֹ נִחְיֶה בַגּוֹיִם. צֵל עִם ם' הוּא צֶלֶם, שֶׁנֶּאֱמַר בּוֹ (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. ם' סְתוּמָה יֵשׁ לָהּ אַרְבַּע דְּפָנוֹת.</p>\n<p>וּמַה שֶּׁפֵּרְשׁוּהוּ שְׁתַּיִם כְּהִלְכָתָן וּשְׁלִישִׁית אֲפִלּוּ טֶפַח, וּלְמִי שֶׁאָמַר שְׁלֹשָׁה כְּהִלְכָתָן וּרְבִיעִית אֲפִלּוּ טֶפַח, וְהֵם בִּגְלַל זֶה, שְׁתַּיִם, שָׁלֹשׁ, אַרְבַּע - הֲרֵי תֵּשַׁע. וְטֶפַח הוּא עֲשִׂירִי, לְהַשְׁלִים כָּל חִסָּרוֹן. וּמִשּׁוּם זֶה שִׁעוּר סֻכָּה לֹא פָחוֹת מֵעֶשֶׂר, שֶׁהִיא מַלְכוּת, עֲשִׂירִית שֶׁל כָּל הַדְּרָגוֹת. וְלֹא לְמַעְלָה מֵעֶשְׂרִים, שֶׁהִיא אוֹת כ', כֶּתֶר עֶלְיוֹן, שֶׁלֹּא שׁוֹלֶטֶת בּוֹ עַיִן. כָּבוֹד עֶלְיוֹן, עָלָיו אָמַר מֹשֶׁה, (שמות לג) הַרְאֵנִי נָא אֶת כְּבֹדֶךְ. וְהֵשִׁיב לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא תוּכַל לִרְאֹת אֶת פָּנָי. וְאֵין כָּבוֹד בְּלִי אוֹת כ'.</p>\n<p>וּמִשּׁוּם זֶה שִׁעֲרוּ בַּעֲלֵי הַמִּשְׁנָה כְּנֶגְדָּם, סֻכָּה הָעֲשׂוּיָה כְּמָבוֹי, מִצַּד אוֹת ב', כְּמִין גא\"ם, מִצַּד אוֹת ג'. כְּמִין צְרִיף, מִצַּד אוֹת ד'. וְשֶׁבַע אוֹתִיּוֹת הֵן, בִּגְלַל זֶה כפר\"ת: כ' - כִּבְשָׁן. ב' - בּוּרְגָנִין. וּשְׁאָר סֻכּוֹת. וְכֻלָּם רְמָזִים אֵצֶל בַּעֲלֵי הַמִּשְׁנָה, וְאֵין לְהַאֲרִיךְ בָּהֶם.</p>\n<p>וְאֵלּוּ לְעֻמָּתָם שִׁבְעָה כּוֹכְבֵי לֶכֶת, וְהֵם זָכָר וּנְקֵבָה. וּמִשּׁוּם זֶה נִקְרָאִים שֶׁבַע כְּפוּלוֹת, כְּמוֹ שִׁבְעָה קָנִים שֶׁל הַמְּנוֹרָה שֶׁנֶּאֱמַר בָּהּ (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ. כָּךְ (זכריה ד) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת. כָּךְ שֶׁבַע סְפִירוֹת כְּפוּלוֹת. וְשִׁבְעָה יְמֵי בְרֵאשִׁית לְמַטָּה, שִׁבְעָה לְמַעְלָה, (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ.</p>\n<p>לוּלָב זֶה צַדִּיק, שֶׁדּוֹמֶה לְחוּט הַשִּׁדְרָה, שֶׁבּוֹ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, כְּנֶגֶד שְׁמוֹנָה עָשָׂר נִעְנוּעִים שֶׁל הַלּוּלָב. וְהֵם כְּנֶגֶד שְׁמוֹנֶה עֶשְׂרֵה בִּרְכוֹת הַתְּפִלָּה, כְּנֶגֶד שְׁמוֹנָה עָשָׂר שֵׁמוֹת שֶׁל (תהלים כט) הָבוּ לַה' בְּנֵי אֵלִים, כְּנֶגֶד שְׁמוֹנָה עָשָׂר שֵׁמוֹת שֶׁל קְרִיאַת שְׁמַע. וְנִעְנוּעַ לְשִׁשָּׁה צְדָדִים, בְּחֶשְׁבּוֹן ו'. וּשְׁלֹשָׁה נִעְנוּעִים בְּכָל צַד, הֵם שְׁמוֹנָה עָשָׂר.</p>\n<p>לוּלָב בְּיָמִין, כּוֹלֵל שִׁשָּׁה מִינִים (שהם) שְׁלֹשָׁה הֲדַסִּים - גְּדֻלָּה גְּבוּרָה תִּפְאֶרֶת. וְדוֹמִים לִשְׁלֹשֶׁת גּוֹנֵי הָעַיִן. שְׁנֵי בַּדֵּי עֲרָבוֹת - נֵצַח וְהוֹד, וְדוֹמִים לִשְׁתֵּי שְׂפָתַיִם. לוּלָב - יְסוֹד, דּוֹמֶה לַשִּׁדְרָה, שֶׁבּוֹ קִיּוּם שֶׁל כָּל הָעֲצָמוֹת, וְעָלָיו אָמַר דָּוִד, (תהלים לה) כָּל עַצְמוֹתַי תֹאמַרְנָה ה' מִי כָמוֹךְ. אֶתְרוֹג - מַלְכוּת, דּוֹמֶה לַלֵּב, שֶׁבּוֹ הַהִ רְהוּרִים.</p>\n<p>וְנִעִִנוּעֵי הַהַלֵּל הֵם מְשֻׁתָּפִים בַּנִּעְנוּעִים שֶׁל נְטִילַת לוּלָב, וְהֵם שְׁמוֹנָה עָשָׂר בְּ\"אָנָּא\". שְׁמוֹנָה עָשָׂר שְׁמוֹנָה עָשָׂר בְּהוֹדוּ תְּחִלָּה וָסוֹף, שְׁמוֹנָה עָשָׂר שֶׁל נְטִילַת לוּלָב - הֲרֵי ע\"ב. וּמִפְּנֵי זֶה לוּלָב בְּחֶשְׁבּוֹן ח\"ס, וְאַרְבָּעָה מִינֵי הַלּוּלָב - הֲרֵי חֶסֶד, זְרוֹעַ יָמִין. וּמִפְּנֵי זֶה תִּקְּנוּ לוּלָב בְּיָמִין, לְצַד הַחֶסֶד. אֶתְרוֹג לְצַד הַגְּבוּרָה, לִשְׂמֹאל הַלֵּב. וּמִפְּנֵי זֶה אֶתְרוֹג הַדּוֹמֶה לַלֵּב, תִּקְּנוּ לִהְיוֹת בְּיַד שְׂמֹאל. כְּמוֹ שֶׁפֵּרְשׁוּהוּ, לוּלָב בְּיָמִין, וְאֶתְרוֹג בִּשְׂמֹאלוֹ. וְהֵם כְּנֶגֶד זָכוֹר וְשָׁמוֹר. וּמִי נָטַל שְׁנֵיהֶם? הָעַמּוּד הָאֶמְצָעִי. לוּלָב בִּימִינוֹ, וְאֶתְרוֹג בִּשְׂמֹאלוֹ.</p>\n<p>בָּאוּ הָאָבוֹת, וְהָרוֹעֶה הַנֶּאֱמָן, וְאַהֲרֹן וְדָוִד וּשְׁלֹמֹה, וּבֵרְכוּ אוֹתוֹ וְאָמְרוּ לוֹ, אַתָּה הַמְּנוֹרָה הַקְּדוֹשָׁה, וְהַחֲבֵרִים שֶׁלְּךְ שֶׁהֵם שִׁשָּׁה, כְּנֶגֶד אֵלּוּ שֶׁהֵם שִׁבְעָה. וְאַתָּה הַמְּנוֹרָה הַקְּדוֹשָׁה, נֵר מַעֲרָבִי בָּאֶמְצַע, שֶׁכָּל שִׁשָּׁה נֵרוֹת מְאִירִים מִמְּךְ. בְּכָל אֶחָד נֶאֱמַר בּוֹ, (משלי כ) נֵר ה' נִשְׁמַת אָדָם. וְהָרוֹעֶה הַנֶּאֱמָן מֵאִיר בְּךְ, וְאַתָּה בַּחֲבֵרִים שֶׁלְּךְ, וְהַכֹּל אֶחָד בְּלִי פֵרוּד כְּלָל. וּמִשָּׁם וְאֵילָךְ מִתְפַּשְּׁטִים עֲנָפִים לְכָל בַּעֲלֵי הַחָכְמָה, הַשְׁלֵם דִּבְרֵי הַחֲבוּרָה הָרִאשׁוֹנָה שֶׁלְּךְ לְעַטֵּר אוֹתָם.</p>\n<p>פָּתַח הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, בַּחִבּוּר הָרִאשׁוֹן נֶאֱמַר, (שיר השירים ח) מַיִם לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה וְגוֹ'. מַהוּ בּוֹז? יוֹם שֵׁנִי וְיוֹם שִׁשִּׁי וְיוֹם שְׁבִיעִי שֶׁל סֻכּוֹת, שֶׁבָּהֶם הָיוּ מְנַסְּכִים מַיִם וְיַיִן.</p>\n<p>שִׁבְעָה יְמֵי סֻכּוֹת בָּהֶם הָיוּ מַקְרִיבִים יִשְׂרָאֵל שִׁבְעִים פָּרִים לְכַפֵּר עַל שִׁבְעִים מְמֻנִּים כְּדֵי שֶׁלֹּא יִשָּׁאֵר הָעוֹלָם חָרוּב מֵהֶם. זֶהוּ שֶׁכָּתוּב וּבַחֲמִשָּׁה עָשָׂר יוֹם וְהִקְרַבְתֶּם עֹלָה אִשֶּׁה לְרֵיחַ נִיחֹחַ לַה' פָּרִים בְּנֵי בָקָר שְׁלֹשָׁה עָשָׂר תְּמִימִים. וּבַיּוֹם הַשֵּׁנִי פָּרִים שְׁנֵים עָשָׂר. וּבַיּוֹם הַשְּׁלִישִׁי אַחַד עָשָׂר. וּבַיּוֹם הָרְבִיעִי עֲשָׂרָה. וּבַיּוֹם הַחֲמִישִׁי פָּרִים תִּשְׁעָה. וּבַיּוֹם הַשִּׁשִּׁי פָּרִים שְׁמוֹנָה. וּבַיּוֹם הַשְּׁבִיעִי שִׁבְעָה. וְכֻלָּם שִׁבְעִים. וּבְכָל יוֹם הָיוּ חֲסֵרִים. מַדּוּעַ חֲסֵרִים?</p>\n<p>אֶלָּא כָּאן הוּא רָמוּז, (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי. וּמַה שָּׁם בִּימֵי הַמַּבּוּל (שם) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר - אַף כָּךְ בְּתִשְׁרֵי, שֶׁהוּא הַחֹדֶשׁ הַשְּׁבִיעִי, שֶׁבּוֹ כַּמָּה מִצְווֹת: רֹאשׁ הַשָּׁנָה, וְיוֹם הַכִּפּוּרִים, סֻכָּה וְלוּלָב, אֶתְרוֹג, מִינִים שֶׁל הַלּוּלָב, שׁוֹפָר - הַשְּׁכִינָה הָעֶלְיוֹנָה שׁוֹרָה עַל יִשְׂרָאֵל, שֶׁהִיא תְּשׁוּבָה, סֻכָּה, אֶתְרוֹג, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא לוּלָב. מִיָּד - וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר. מִתְמַעֲטִים הַחֲטָאִים שֶׁל יִשְׂרָאֵל. אַף כָּךְ מִתְמַעֲטִים הַמְמֻנִּים, שֶׁהֵם מַלְאֲכֵי הַחַבָּלָה שֶׁמְּמֻנִּים עֲלֵיהֶם שֶׁדּוֹמִים לְמֵי הַמַּבּוּל. כְּמוֹ שֶׁפֵּרְשׁוּהוּ, עָשָׂה עֲבֵרָה אַחַת, קָנָה לוֹ קָטֵגוֹר אֶחָד. בְּאוֹתוֹ זְמַן שֶׁמִּתְמַעֲטִים הַחֲטָאִים, מִתְמַעֲטִים הַפָּרִים שֶׁלָּהֶם, מִתְמַעֲטִים הַמְמֻנִּים שֶׁל שִׁבְעִים אֻמּוֹת, מִתְמַעֲטִים שִׁבְעִים אֻמּוֹת, מִתְמַעֵט הַטּוֹב שֶׁלָּהֶם.</p>\n<p>תֵּבַת נֹחַ, צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְנִיס עִמּוֹ שְׁנַיִם שְׁנַיִם (בראשית ז) שִׁבְעָה שִׁבְעָה זָכָר וּנְקֵבָה, לְקָרְבָּן, לְהָגֵן עַל נֹחַ וְעַל כָּל אֵלּוּ שֶׁנִּכְנָסִים עִמּוֹ לַתֵּבָה. אַף כָּךְ אֵלּוּ שֶׁשּׁוֹמְרִים חַגִּים וּזְמַנִּים, שֶׁהֵם יָמִים טוֹבִים, שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה. שְׁנַיִם שְׁנַיִם - שְׁנֵי יְמֵי רֹאשׁ הַשָּׁנָה וּשְׁנֵי יָמִים שֶׁל שָׁבוּעוֹת. וּמִפְּנֵי שֶׁאֵלּוּ שְׁנַיִם מֵהֶם בְּסָפֵק, הֲרֵי שְׁנֵי יְמֵי הַפּוּרִים בִּמְקוֹמָם. שִׁבְעָה שִׁבְעָה - שִׁבְעַת יְמֵי הַפֶּסַח, שִׁבְעַת יְמֵי הַסֻּכּוֹת. נֹחַ כְּנֶגֶד יוֹם הַשַּׁבָּת, וְזֶהוּ (שם ו) מִכָּל הָחַי.</p>\n<p>הַסֻּכָּה מְגִנָּה עַל יִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב (ישעיה ד) וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם מֵחֹרֶב. הַסֻּכָּה הִיא מְגִנָּה. מַה תֵּבַת נֹחַ לְהָגֵן, אַף כָּךְ סֻכָּה לְהָגֵן. וְעוֹד מִכָּל הָחַי - ח\"י בִּרְכוֹת הַתְּפִלָּה, וְהֵן תֵּשַׁע תֵּשַׁע. בִּרְכַּת הַמִּינִים בָּהּ נִשְׁלָמוֹת עֶשֶׂר סְפִירוֹת מִמַּעְלָה לְמַטָּה וּמִמַּטָּה לְמַעְלָה, וְהִיא כְּנֶגֶד נֹחַ.</p>\n<p>וְעוֹד מִכָּל הָחַי - הַשְּׁכִינָה מְגִנָּה עַל אֵלּוּ שֶׁשּׁוֹמְרִים י', אוֹת שַׁבָּת בַּתְּחוּם שֶׁלּוֹ, שֶׁהוּא שְׁמוֹנַת אֲלָפִים, אַלְפַּיִם לְכָל צַד. וְעוֹד מִכָּל הָחַי - אֵלּוּ שֶׁשּׁוֹמְרִים י', אוֹת בְּרִית, שֶׁהוּא בִּשְׁמוֹנָה יָמִים, שֶׁנֶּאֱמַר עֲלֵיהֶם, (ויקרא יב) וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. וְעוֹד מִכָּל הָחַי - אֵלּוּ שֶׁשּׁוֹמְרִים אוֹת י', תְּפִלִּין בִּשְׁמוֹנֶה פָּרָשִׁיּוֹת.</p>\n<p>הַשְּׁכִינָה, שֶׁהִיא סֻכָּה, מְגִנָּה עֲלֵיהֶם, וּפוֹרֶשֶׂת כְּנָפָהּ עֲלֵיהֶם כְּאִמָּא עַל בָּנִים, וּמִפְּנֵי זֶה תִּקְּנוּ לְבָרֵךְ הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ. וּמִפְּנֵי זֶה בַּחֹדֶשׁ הַשְּׁבִיעִי, שֶׁבּוֹ כָּל מִצְווֹת אֵלּוּ, (שיר השירים ח) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה, עַם יִשְׂרָאֵל בַּאֲבִיהֶם שֶׁבַּשָּׁמַיִם. וְאֵין מַיִם רַבִּים אֶלָּא כָּל הָאֻמּוֹת וְהַמְמֻנִּים שֶׁלָּהֶם. אִם יִתֵּן אִישׁ, שֶׁהוּא סָמָאֵל, כָּל מַה שֶּׁיֵּשׁ לוֹ בָּעוֹלָם הַזֶּה, כְּדֵי שֶׁיִּשְׁתַּתֵּף בְּאֵלּוּ הַמִּצְווֹת עִם יִשְׂרָאֵל - בּוֹז יָבוּזוּ לוֹ.</p>"],[9522012565,"<p>וּבַיּוֹם הַשְּׁמִינִי עֲצֶרֶת, פָּר אֶחָד אַיִל אֶחָד. הֲרֵי פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, לְמֶלֶךְ שֶׁזִּמֵּן אוֹרְחִים, לְאַחַר שֶׁשָּׁלַח אוֹתָם, אָמַר לְאֵלּוּ בְּנֵי בֵיתוֹ: אֲנִי וְאַתֶּם נַעֲשֶׂה סְעוּדָה קְטַנָּה. וּמָה עֲצֶרֶת? כְּמוֹ שֶׁנֶּאֱמַר (שמואל אט) זֶה יַעְצֹר בְּעַמִּי, וְאֵין עֶצֶר אֶלָּא מַלְכוּת. מִצַּד הַשְּׁכִינָה הָעֶלְיוֹנָה עוֹשֶׂה סְעוּדָה גְּדוֹלָה, וּמִצַּד הַמַּלְכוּת סְעוּדָה קְטַנָּה. וְנוֹהֲגִין לַעֲשׂוֹת יִשְׂרָאֵל עִמָּהּ שִׂמְחָה, וְנִקְרֵאת שִׂמְחַת תּוֹרָה. וּמְעַטְּרִים לַסֵּפֶר תּוֹרָה בַּכֶּתֶר שֶׁלּוֹ, רֶמֶז סֵפֶר תּוֹרָה לְתִפְאֶרֶת, הַשְּׁכִינָה - עֲטֶרֶת תִּפְאֶרֶת.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַבָּא, מַדּוּעַ מִצַּד הָאִמָּא הָעֶלְיוֹנָה מְזַמֵּן כָּל הַמְמֻנִּים שֶׁל כָּל הָאֻמּוֹת, וּמִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה לֹא מְזַמֵּן אֶלָּא אֻמָּה יְחִידָה, כְּנֶגֶד פַּר יָחִיד?</p>\n<p>אָמַר לוֹ, בְּנִי, טוֹב שָׁאַלְתָּ. מִפְּנֵי שֶׁמַּלְכוּת הִיא רוֹמֶזֶת לְבַת, שֶׁהִיא צְנוּעָה בְּבֵית אָבִיהָ וְאִמָּהּ. וְהִיא אֲרוּסָה וְלֹא נְשׂוּאָה. אֵין דֶּרֶךְ אֶרֶץ לֶאֱכֹל עִם אוֹרְחִים. אֲבָל אִמָּא שֶׁהִיא נְשׂוּאָה, דֶּרֶךְ אֶרֶץ הוּא (לאכל עם האורחים) אַחַר שֶׁמַּזְמִין בַּעְלָהּ אוֹרְחִים לֶאֱכֹל עַל הַשֻּׁלְחָן עִם בַּעְלָהּ. וְאִם הֵם אוֹרְחִים נָכְרִים, לֹא אוֹכְלִים עִמָּהֶם לֹא אַבָּא וְלֹא אִמָּא, וְכָל שֶׁכֵּן הַבַּת. וּמִשּׁוּם כָּךְ בַּסְּעוּדָה שֶׁל שִׁבְעִים הַמְמֻנִּים לֹא מִשְׁתַּתֵּף לֶאֱכֹל עִמָּהֶם אֶחָד מִבַּעֲלֵי הַמֶּלֶךְ, מִפְּנֵי שֶׁהֵם נָכְרִים. אָמַר לוֹ, וַדַּאי עַתָּה יִתְיַשֵּׁב הַדָּבָר בְּלִבִּי עַל בֻּרְיוֹ.</p>"],[9522012566,"<p>עֹלַת תָּמִיד - זוֹ הַשְּׁכִינָה, שֶׁעוֹלָה לְמַעְלָה בְּאוֹתָהּ דַּרְגָּה, שֶׁנֶּאֱמַר בָּהּ עֶרֶב וָבֹקֶר בְּכָל יוֹם תָּמִיד אוֹמְרִים פַּעֲמַיִם שְׁמַע יִשְׂרָאֵל. וְהִיא עוֹלָה בָּעַמּוּד הָאֶמְצָעִי, שֶׁהוּא תָּדִיר עִמָּהּ בְּלִי פֵרוּד כְּלָל.</p>\n<p>וּלְאָן עוֹלָה? לְמָקוֹם שֶׁנִּגְזְרָה מִשָּׁם, שֶׁהוּא אֵין סוֹף, וְהוּא גָּבוֹהַּ מִכָּל הַסְּפִירוֹת. וּמִפְּנֵי זֶה פֵּרְשׁוּהָ, עוֹלָה - כֻּלָּהּ לְגָבוֹהַּ עוֹלָה. וְכַאֲשֶׁר הִא עוֹלָה, אוֹחֲזוֹת בָּהּ כָּל הַסְּפִירוֹת, וְהֵן עוֹלוֹת עִמָּהּ. וּמָה הָעֲלִיָּה שֶׁלָּהּ? לְרֵיחַ נִיחֹחַ, לָתֵת רֵיחַ טוֹב לִפְנֵי ה', וְאַחַר כָּךְ נֶאֱמַר בָּהּ, (ויקרא ט) וַיֵּרֶד מֵעֲשּת הַחַטָּאת וְהָעֹלָה. יָרְדָה מְלֵאָה כַּפָּרָה מִכָּל חֲטָאֵי יִשְׂרָאֵל.</p>\n<p>וַהֲרֵי הָעֲלִיָּה שֶׁלָּהּ הִיא בָּעַמּוּד הָאֶמְצָעִי. וּמִפְּנֵי כָּךְ הַיְרִידָה שֶׁלָּהּ הִיא בּוֹ, וְכָל הַצְּבָאוֹת שֶׁלָּהּ. וּמִפְּנֵי זֶה נִקְרָא סֻלָּם, שֶׁבּוֹ כָּל הַהֲוָיוֹת (הכנויים) עוֹלוֹת וְיוֹרְדוֹת, שֶׁהֵן תְּלוּיוֹת מִן יְהֹוָה. וּמִפְּנֵי זֶה כָּל הַקָּרְבָּנוֹת וְהָעוֹלוֹת הֵם לַיהֹוָה. וְנִקְרֵאת קָרְבָּן עַל שֵׁם שֶׁמִּתְקָרְבִים בָּהּ כָּל הַכִּנּוּיִים לַיהֹוָה.</p>\n<p>וּמִפְּנֵי זֶה נֶאֱמַר עָלֶיהָ, (במדבר ז) קָרְבָּנוֹ קַעֲרַת כֶּסֶף אַחַת. אֵין דַּרְגָּה נִקְרֶבֶת לְגַבֵּי יְהֹוָה פְּחוּתָה מִמֶּנָּה. וְאֵין תְּפִלָּה וּמִצְוָה מִכָּל מִצְווֹת הַתּוֹרָה, וְכָל קָרְבָּנוֹת וְעוֹלוֹת, שֶׁהֵם לְחוּץ מִמֶּנָּה. בְּכָל דַּרְגּוֹת הַסְּפִירוֹת לֹא מִתְקַבְּלוֹת לִפְנֵי יְהֹוָה חוּץ מִמֶּנָּה. וּמִפְּנֵי זֶה נֶאֱמַר עָלֶיהָ, (ויקרא טז) בְּזֹּאת יָבא אַהֲרֹן אֶל הַקֹּדֶשׁ. וּמִפְּנֵי זֶה אָמַר הַנָּבִיא, (ירמיה ט) כִּי אִם בְּזֹּאת יִתְהַלֵּל הַמִּתְהַלֵּל.</p>\n<p>הִיא שְׁלָמִים, שְׁלֵמוּת הַשֵּׁם שֶׁל יְהֹוָה, בְּכָל דַּרְגָּה וְדַרְגָּה. הִיא ה'. אֲדנָי. י' שֶׁל יְהֹוָה. הִיא ה' מֵאֱלֹהִים. הִיא ה' מֵאֶהְיֶה. י' מִשַּׁדַּי. סוֹף כָּל הֲוָיָה וְכִנּוּי. וּמִפְּנֵי זֶה נֶאֱמַר בָּהּ, (קהלת יב) סוֹף דָּבָר הַכֹּל נִשְׁמָע אֶת הָאֱלֹהִים יְרָא וְאֶת מִצְוֹתָיו שְׁמוֹר. הִיא סוֹף מֵעֶשֶׂר סְפִירוֹת, יַם סוּף. שְׁלֵמוּת עֶלְיוֹנִים וְתַחְתּוֹנִים. הִיא שַׁעַר לְהִכָּנֵס לְכָל חָכְמָה, לְכָל כִּנּוּי וַהֲוָיָה, וּלְהִכָּנֵס בְּכָל סְפִירָה וּסְפִירָה, יְדִיעָה שֶׁל הַכֹּל. וּפָחוֹת מִמֶּנָּה אֵין רְשׁוּת לְשׁוּם בְּרִיָּה לְהַשְׁגִּיחַ לְשׁוּם יְדִיעָה בָּעוֹלָם. עָלֶיהָ נֶאֱמַר, (תהלים קיח) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבאוּ בוֹ.</p>\n<p>הִיא שֵׁם שֶׁל מ\"ב אוֹתִיּוֹת, שֶׁבָּהֶן נִבְרְאוּ עֶלְיוֹנִים וְתַחְתּוֹנִים. (ואלו הן אותיות כנויים לאותיות ההויות שבהן נבראו עליונים). הִיא נִקְרֵאת עַיִן מִצַּד הַיָּמִין, (תהלים לג) הִנֵּה עֵין יְהֹוָה אֶל יְרֵאָיו. וְנִקְרֵאת אֹזֶן מִצַּד הַשְּׂמֹאל, (דניאלט) הַטֵּה אֱלֹהַי אָזְנְךְ וּשֲׁמָע. וְנִקְרֵאת רֵיחַ מִצַּד הָעַמּוּד הָאֶמְצָעִי. וְנִקְרֵאת פֶּה מֵעַצְמָהּ. זֶהוּ שֶׁכָּתוּב (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ.</p>\n<p>נִקְרֵאת מִצְוָה רִאשׁוֹנָה אָנֹכִי, מִצַּד הַכֶּתֶר, שֶׁהוּא אַיִ\"ן מֵאֱלֹהֵינוּ. אָנֹכִי - בּוֹ כ', כֶּתֶר. וּבוֹ אַיִן. וְכֶתֶר נִקְרָא מִצַּד הָאִמָּא הָעֶלְיוֹנָה, שֶׁהִזְכִּיר אֶצְלָהּ חֲמִשִּׁים פְּעָמִים יְצִיאַת מִצְרַיִם בַּתּוֹרָה. וְהִיא בַּ\"ת מִבְּרֵאשִׁית, שֶׁכּוֹלֶלֶת עֶשֶׂר אֲמִירוֹת מִצַּד הַחָכְמָה, בַּת י', (משלי ג) בְּחָכְמָה יָסַד אֶרֶץ. בְּאַבָּא יָסַד הַבַּת. וְהוּא (איוב כח) נָתִיב לֹא יְדָעוֹ עָיִט, שֶׁכּוֹלֵל ל\"ב נְתִיבוֹת, שֶׁהֵם ל\"ב אֱלֹהִים מִצַּד הָאִמָּא הָעֶלְיוֹנָה, שֶׁנִּקְרֵאת כָּבוֹד. וְכַאֲשֶׁר נִכְלָלִים בַּבַּת, נִקְרָא ל\"ב. וּמִפְּנֵי זֶה כָּבוֹד לְמַעְלָה, ל\"ב לְמַטָּה.</p>\n<p>וַעָשָׂרָה דִּבְּרוֹת נִתְּנוּ. חֲמִשָּׁה בְּלוּחַ אֶחָד, וַחֲמִשָּׁה בְּלוּחַ שֵׁנִי. הִיא כּוֹלֶלֶת אוֹתוֹ, חֲמִשָּׁה מִכֶּתֶר עַד גְּבוּרָה, וַחֲמִשָּׁה מֵהָעַמּוּד הָאֶמְצָעִי עַד הַבַּת. וְהֵם חֲמִשָּׁה חֲמִשָּׁה. וְכִי יֵשׁ לְדַבֵּר בַּעֲשָׂרָה פִּיּוֹת? אֶלָּא כּוֹלֵל אוֹתָם בְּבַת יְחִידָה י', וְנַעֲשׂוּ כֻלָּם אֶחָד. אַף כָּךְ ו' נִקְרָא קוֹל, וְלֹא מַכִּירִים בּוֹ עַד שֶׁמִּשְׁתַּתֵּף עַד (עם) דִּבּוּר. וּמִפְּנֵי זֶה, (דברים ד) קוֹל דְּבָרִים אַתֶּם שּמְעִים.</p>\n<p>הִיא מִצְוָה שְׁנִיָּה מִצַּד הַגְּבוּרָה, יִרְאָה בְּחֶשְׁבּוֹן. וּרְמוּזָה בְּמִלַּת בְּרֵאשִׁית, יָרֵא בשֶׁת. וּפֵרְשׁוּהָ, מִי שֶׁאֵין לוֹ בּשֶׁת פָּנִים, וַדַּאי שֶׁלֹּא עָמְדוּ אֲבוֹתָיו עַל הַר סִינַי.</p>\n<p>הִיא מִצְוָה שְׁלִישִׁית, שֶׁנִּקְרֵאת אַהֲבַת חֶסֶד. זֶהוּ שֶׁכָּתוּב (ירמיה לא) אַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד. אַהֲבָה כְּלוּלָה מֵהָאָבוֹת, שֶׁנִּקְרָא בָּהֶם בַּכֹּל מִכֹּל כֹּל. וְסוֹד הַדָּבָר - (שם ב) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ.</p>\n<p>וְהִיא מִצְוָה רְבִיעִית, יִחוּד, מִצַּד הָעַמּוּד הָאֶמְצָעִי, שְׁמַע יִשְׂרָאֵל. וְהִיא כ\"ה כ\"ה אוֹתִיּוֹת עִמּוֹ בְּשֵׁשׁ תֵּבוֹת, שֶׁהֵן שְׁמַע יִשְׂרָאֵל (וכו'). וּבִגְלָלָהּ אָמַר אַבְרָהָם, (בראשית כב) נֵלְכָה עַד כֹּ\"ה וְנִשְׁתַּחֲוֶה. (שמות יט) כֹּ\"ה תֹאמַר לְבֵית יַעֲקֹב.</p>\n<p>הוּא א\"ח, עַמּוּד הָאֶמְצָעִי, וְהִיא ד', שְׁלֵמוּת הַיִּחוּד שֶׁלּוֹ לְהַשְׁלִים בּוֹ אֶחָד. א\"ח כּוֹלֵל תֵּשַׁע סְפִירוֹת, שֶׁהֵן א' - אֵין סוֹף, ח' - שְׁמוֹנֶה סְפִירוֹת, מֵחָכְמָה עַד יְסוֹד. ד' - מַלְכוּת, הַקּוֹץ שֶׁלָּהּ, בָּהּ נִשְׁלָמוֹת לְעֶשֶׂר, שֶׁהֵם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. ד' כְּלוּלָה מֵאַרְבַּע אוֹתִיּוֹת יְהֹוָה.</p>\n<p>מִצְוָה חֲמִישִׁית, (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. הִיא תּוֹרָה שֶׁבִּכְתָב מִצַּד הַחֶסֶד, וְתוֹרָה שֶׁבְּעַל פֶּה מִצַּד הַגְּבוּרָה, שֶׁבָּהֶן חָכְמָה וּבִינָה. כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הָרוֹצֶה לְהַחְכִּים - יַדְרִים. לְהַעֲשִׁיר - יַצְפִּין. וְהָעַמּוּד הָאֶמְצָעִי כּוֹלֵל אֶת שְׁנֵיהֶם, וּמִפְּנֵי זֶה נִקְרָא שָׁמַיִם, כּוֹלֵל אֵשׁ וּמַיִם, אֵשׁ שֶׁל גְּבוּרָה וּמַיִם שֶׁל חֶסֶד.</p>\n<p>וּמִפְּנֵי זֶה כֶּתֶר, שֶׁהִיא כַּף, (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. שֶׁהֵם יה\"ה, שָׁלֹשׁ אוֹתִיּוֹת, נַעֲשׂוֹת כַּף עַל ו'. וְזֶהוּ כְּנֶגֶד כֶּתֶר תּוֹרָה. ו' זֶה סֵפֶר תּוֹרָה. כַּף עֲטָרָה עַל רֹאשׁוֹ. וְהַכֹּל יְהֹוָ\"ה, עֶשְׂרִים וָשֵׁשׁ בְּחֶשְׁבּוֹן.</p>\n<p>מִצְוָה שִׁשִּׁית הִיא תְּפִלָּה שֶׁל יָד בִּזְרוֹעַ שְׂמֹאל. וּמִצַּד הַגְּבוּרָה ה' שֶׁל יָד כֵּהָה, מִכֶּתֶר וְעַד גְּבוּרָה, חָמֵשׁ סְפִירוֹת, וְהֵן תְּפִלִּין שֶׁל רֹאשׁ שֶׁל הָעַמּוּד הָאֶמְצָעִי. וְהִיא קֶשֶׁר שָׁלֹשׁ רְצוּעוֹת, שֶׁהֵן נֵצַח הוֹד יְסוֹד.</p>\n<p>וְהִיא מִצְוָה שְׁבִיעִית, מִצְוַת צִיצִית, כּוֹלֶלֶת תְּכֵלֶת וְלָבָן, דִּין וְרַחֲמִים. בָּאֵשׁ, אֵשׁ לְבָנָה לֹא אוֹכֶלֶת. תְּכֵלֶת אוֹכֶלֶת וּמְכַלָּה, (מלכים א יח) וַתֹּאכַל אֶת הָעֹלָה. לָבָן מִיָּמִין, תְּכֵלֶת מִשְּׂמֹאל. הָעַמּוּד הָאֶמְצָעִי יִחוּד בֵּין שְׁנֵיהֶם, יָרֹק. מִשּׁוּם כָּךְ פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית? מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּמִפְּנֵי זֶה תִּקְּנוּ פָּרָשַׁת צִיצִית לִקְרֹא אוֹתָהּ בְּיִחוּד.</p>\n<p>וְהִיא מִצְוָה שְׁמִינִית, מְזוּזָה. הַשְּׁכִינָה נִקְרֵאת מְזוּזָה מִצַּד הָעַמּוּד הָאֶמְצָעִי שֶׁל אוֹתִיּוֹת יְהֹוָ\"ה. וּמִצַּד שֶׁל צַדִּיק, סוֹד הַבְּרִית, נִקְרֵאת שַׁדַּי. שַׁדַּי חוֹתֶמֶת הַמֶּלֶךְ, שֶׁהוּא יְהֹוָה.</p>\n<p>מִצְוָה תְּשִׁיעִית, הַשְּׁכִינָה נִקְרֵאת אוֹת בְּרִית מִצַּד שֶׁל צַדִּיק יְסוֹד עוֹלָם. (בראשית ט) זֹּאת אוֹת הַבְּרִית. (שמות לא) בֵּינִי, הָעַמּוּד הָאֶמְצָעִי, וּבֵין בְּנֵי יִשְׂרָאֵל, נֵצַח וְהוֹד. אוֹת - זֶה צַדִּיק. הִיא - זוֹ הַשְּׁכִינָה. כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם - מִכֶּתֶר עַד הָעַמּוּד הָאֶמְצָעִי. שֶׁאֵין שִׁשָּׁה בְּכָל מָקוֹם אֶלָּא מִצַּד הָאוֹת ו'. וְאֵין שְׁבִיעִי אֶלָּא מִצַּד הָאוֹת י', עֲטָרָה עַל רֹאשׁוֹ חָכְמָה עֶלְיוֹנָה, אוֹת הוּא. חָכְמָה תַּחְתּוֹנָה, אוֹת הִיא.</p>\n<p>וְתִקְּנוּ לָמוּל לִשְׁמוֹנָה, שֶׁהֵם ח', מֵחָכְמָה עַד יְסוֹד. לְקַבֵּל בָּהֶם י' קְטַנָּה, לְהַעֲלוֹת אוֹתָהּ עַד כֶּתֶר, לִהְיוֹת עֲטָרָה עַל רֹאשָׁם. וְתִקְּנוּ לָשִׂים הָעָרְלָה בִּכְלִי עָפָר, לְקַיֵּם (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ.</p>\n<p>מִצְוָה עֲשִׂירִית, (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. הַשְּׁכִינָה נִקְרֵאת שַׁבָּת מִצַּד שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁהֵן ש', שְׁלֹשָׁה כְּתָרִים: כֶּתֶר, חָכְמָה, בִּינָה. וְהִיא בַּת, רְבִיעִית לָהֶם. שִׁשָּׁה יָמִים, מֵחֶסֶד עַד יְסוֹד, בָּהֶם תַּעֲשֶׂה מְלָאכָה, מִפְּנֵי שֶׁהַבִּנְיָן מַתְחִיל מֵחֶסֶד. זֶהוּ שֶׁכָּתוּב (תהלים פט) עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִבִּינָה וּלְמַעְלָה הִיא מְנוּחָה וְעֹנֶג וּשְׁבִיתָה לְכָל מַעֲשֶׂה.</p>\n<p>מִצְוָה אַחַת עֶשְׂרֵה הִיא נִקְרֵאת תְּפִלָּה שֶׁל שַׁחֲרִית, מִנְחָה וְעַרְבִית, מִצַּד שְׁלֹשֶׁת הָאָבוֹת, וְהִיא תְּפִלַּת כָּ\"ל פֶּ\"ה. אֵין כֹּל אֶלָּא צַדִּיק, שֶׁכָּתוּב (דברי הימים א כט) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם יוֹנָתָן בֶּן עֻזִּיאֵל, שֶׁאוֹחֵז בַּשָּׁמַיִם וּבָאָרֶץ. פֶּ\"ה כְּחֶשְׁבּוֹן מִילָה. וּמַה בְּרִית בָּהּ מִתְיַחֲדִים זָכָר וּנְקֵבָה שֶׁלְּמַטָּה - אַף בַּיְסוֹד מִתְיַחֵד חָתָן וְכַלָּה שֶׁלְּמַעְלָה, הוּא חַי הָעוֹלָמִים כּוֹלֵל חַ\"י בְּרָכוֹת, זֶהוּ שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק.</p>\n<p>וּמִפְּנֵי זֶה, כָּל הַכּוֹרֵע - כּוֹרֵעַ בְּבָרוּךְ, וְכָל הַזּוֹקֵף - זוֹקֵף בַּשֵּׁם. זוֹ הַשְּׁכִינָה. בְּשֵׁם יְהֹוָ\"ה, בּוֹ צָרִיךְ לִזְקֹף הַשְּׁכִינָה, הַהִיא שֶׁנֶּאֱמַר בָּהּ, (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל, עַל יְדֵי דַרְגָּה אַחֶרֶת. וּמִפְּנֵי זֶה, (שם ט) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ, (תהלים קמו) יְהֹוָ\"ה זוֹקֵף כְּפוּפִים.</p>\n<p>מִצְוָה שְׁתֵּים עֶשְׂרֵה, הִיא נִקְרֵאת חַג הַמַּצּוֹת וְחַג הַשָּׁבוּעוֹת וְחַג הַסֻּכּוֹת, מִצַּד שְׁלֹשֶׁת הָאָבוֹת. וְרֹאשׁ הַשָּׁנָה מֵהַצַּד שֶׁלָּהּ, דִּין הַמַּלְכוּת - דִּין. וְיֵשׁ שֶׁיֹּאמַר, פֶּסַח זְרוֹעַ יָמִין. שָׁבוּעוֹת, מַתַּן תּוֹרָה, שֶׁנִּתְּנָה בַּמִּדְבָּר, שֶׁהוּא מְמֻנֶּה עָלָיו שׁוֹר, מִצַּד הַגְּבוּרָה. סֻכּוֹת, (בראשית לג) וְיַעֲקֹב נָסַע סֻכֹּתָה. מִצְוָה שְׁלֹשׁ עֶשְׂרֵה, קְרִיאַת שְׁמַע.</p>"],[9522012567,"<p>וְיֵשׁ לָדַעַת שֶׁהוּא נִקְרָא חָכָם בְּכָל מִינֵי חָכְמוֹת, וּמֵבִין בְּכָל מִינֵי תְבוּנוֹת, וְחָסִיד בְּכָל מִינֵי חֲסָדִים, וְגִבּוֹר בְּכָל מִינֵי גְבוּרוֹת, וְיוֹעֵץ בְּכָל מִינֵי עֵצוֹת, וְצַדִּיק בְּכָל מִינֵי צְדָקוֹת, וּמֶלֶךְ בְּכָל מִינֵי מַלְכוּת, עַד אֵין סוֹף. עַד (כתר) אֵין חֵקֶר. וּבְכָל אֵלּוּ הַדְּרָגוֹת, בְּאַחַת נִקְרָא רַחֲמָן, וּבְאַחַת נִקְרָא דַּיָּן. וְכָךְ בְּכַמָּה דְרָגוֹת עַד אֵין סוֹף. אִם כָּךְ, שִׁנּוּי יֵשׁ בֵּין רַחֲמָן לְדַיָּן. אֶלָּא קֹדֶם שֶׁבָּרָא הָעוֹלָם נִקְרָא הוּא בְּכָל אֵלּוּ הַדְּרָגוֹת, עַל שֵׁם בְּרִיּוֹת שֶׁהָיוּ עֲתִידוֹת לְהִבָּרְאוֹת. שֶׁאִם לֹא בְּרִיּוֹת הָעוֹלָם, מַדּוּעַ נִקְרָא רַחוּם, דַּיָּן? אֶלָּא עַל שֵׁם הַבְּרִיּוֹת הָעֲתִידוֹת.</p>\n<p>וּמִפְּנֵי זֶה כָּל הַשֵּׁמוֹת הֵם כִּנּוּיִים שֶׁלּוֹ, עַל שֵׁם הַמַּעֲשִׂים שֶׁלּוֹ. כְּמוֹ כֵן בָּרָא הַנְּשָׁמָה בַּדְּמוּת שֶׁלּוֹ, שֶׁנִּקְרֵאת עַל שֵׁם פְּעֻלּוֹת שֶׁלָּהּ בְּכָל אֵיבָר וְאֵיבָר שֶׁל הַגּוּף, שֶׁנִּקְרָא עוֹלָם קָטָן. כְּמוֹ שֶׁאֲדוֹן הָעוֹלָם נוֹהֵג בְּכָל הַבְּרִיּוֹת וּבְכָל דּוֹר כְּפִי מַעֲשָׂיו, כָּךְ הַנְּשָׁמָה כְּפִי מַעֲשָׂיו שֶׁל כָּל אֵיבָר וְאֵיבָר. אוֹתוֹ אֵיבָר שֶׁעוֹשֶׂה בּוֹ מִצְוָה, נִקְרֵאת הַנְּשָׁמָה לְגַבָּיו חֶמְלָה וָחֶסֶד וְחֵן וְרַחֲמִים. וּבְאוֹתוֹ אֵיבָר שֶׁעוֹשֶׂה בּוֹ עֲבֵרָה, נִקְרֵאת הַנְּשָׁמָה לְגַבָּיו דִּין וְחֵמָה וָכַעַס. אֲבָל לַחוּץ מִן הַגּוּף, לְמִי תִהְיֶה חֶמְלָה אוֹ אַכְזָרִיּוּת?</p>\n<p>אַף כָּךְ אֲדוֹן הָעוֹלָם, קֹדֶם שֶׁבָּרָא אֶת הָעוֹלָם וּבָרָא בְּרִיּוֹתָיו, לְמִי נִקְרָא רַחוּם וְחַנּוּן אוֹ דַּיָּן? אֶלָּא כָּל הַשֵּׁמוֹת שֶׁלּוֹ הֵם כִּנּוּיִים, וְלֹא נִקְרָא בָּהֶם אֶלָּא עַל שֵׁם בְּרִיּוֹת הָעוֹלָם. וּמִפְּנֵי זֶה, כַּאֲשֶׁר בַּעֲלֵי הַדּוֹר הֵם טוֹבִים, הוּא נִקְרָא אֶצְלָם יְהֹוָ\"ה, בְּמִדַּת הָרַחֲמִים. וְכַאֲשֶׁר בַּעֲלֵי הַדּוֹר הֵם רְשָׁעִים, נִקְרָא אֲדנָ\"י, בְּמִדַּת הַדִּין. לְכָל דּוֹר וּלְכָל בֶּן אָדָם כְּפִי מִדָּתוֹ. אֲבָל לֹא שֶׁיֵּשׁ לוֹ מִדָּה וְלֹא שֵׁם יָדוּעַ.</p>\n<p>כְּמוֹ הַסְּפִירוֹת, שֶׁכָּל סְפִירָה יֵשׁ לָהּ שֵׁם יָדוּעַ וּמִדָּה וּגְבוּל וּתְחוּם. וּבְאֵלּוּ הַשֵּׁמוֹת אֲדוֹן הָעוֹלָם הוּא מִתְפַּשֵּׁט, וּמוֹלֵךְ בָּהֶם, וְנִקְרָא בָּהֶם, וְנִתְכַסֶּה בָּהֶם, וְגָר בָּהֶם, כַּנְּשָׁמָה אֵצֶל אֶבְרֵי הַגּוּף. וּמָה רִבּוֹן הָעוֹלָמִים אֵין לוֹ שֵׁם יָדוּעַ, וְלֹא מָקוֹם יָדוּעַ, אֶלָּא בְּכָל צַד שִׁלְטוֹנוֹ - אַף כָּךְ אֵין לָהּ לַנְּשָׁמָה שֵׁם יָדוּעַ, וְלֹא מָקוֹם יָדוּעַ בְּכָל הַגּוּף, אֶלָּא בְּכָל צַד שִׁלְטוֹנָהּ, וְאֵין אֵיבָר פָּנוּי מִמֶּנָּה.</p>\n<p>וּמִפְּנֵי זֶה אֵין לְצַיֵּר אוֹתָהּ בְּמָקוֹם אֶחָד, שֶׁאִם לֹא הֲרֵי חָסֵר הַשִּׁלְטוֹן בִּשְׁאָר הָאֵיבָרִים. וְלֹא לִקְרֹא לָהּ בְּשֵׁם אֶחָד, אוֹ בִּשְׁנַיִם, אוֹ בִּשְׁלֹשָׁה, לוֹמַר שֶׁהִיא חֲכָמָה מִבִּינָה וְיֵשׁ לָהּ דַּעַת, וְלֹא יוֹתֵר. שֶׁאִם עוֹשֶׂה כָּךְ, הֲרֵי חָסֵר לָהּ מִשְּׁאָר דְּרָגוֹת.</p>\n<p>כָּל שֶׁכֵּן לַאֲדוֹן הָעוֹלָם שֶׁאֵין לְצַיֵּר אוֹתוֹ בְּמָקוֹם יָדוּעַ, אוֹ לִקְרֹא לוֹ בְּשֵׁמוֹת, אוֹ לִשְׁנוֹת לוֹ בָּהֶם, אוֹ (לשלש) לְהַשְׁלִיט לוֹ כְּמוֹ דַּרְגַּת הַמֶּרְכָּבָה שֶׁנֶּאֱמַר בָּהּ קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. שֶׁכָּל הַדְּרָגוֹת שֶׁל הַמֶּרְכָּבוֹת שֶׁלּוֹ הֵן מְשֻׁלָּשׁוֹת, כְּמוֹ הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, שֶׁהֵם דְּמוּת אַרְיֵה שׁוֹר נֶשֶׁר, שֶׁהֵם מֶרְכָּבָה לְאָדָם, שֶׁנֶּאֱמַר עָלָיו (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וּמִצַּד הַנְּקֵבָה הֵם שׁוֹלְטִים עַל אָדָם, וְהַנְּקֵבָה הִיא מֶרְכָּבָה לְגַבֵּיהֶם. וּמִפְּנֵי זֶה נֶאֱמַר עָלֶיהָ, קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ.</p>\n<p>וְאַף כָּךְ הָאוֹתִיּוֹת, שֶׁהֵן פְּנֵי הַחַיּוֹת, מְשֻׁלָּשׁוֹת, כְּמוֹ זֶה: יה\"ו. הו\"י. וה\"י. ה' רְבִיעִית - קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. הִיא שְׁלָמִים שֶׁל כֻּלָּם, לְהַשְׁלִים בְּכֻלָּם שֵׁם יְהֹוָ\"ה. אֲבָל לַאֲדוֹן הַכֹּל אֵין לְשַׁלֵּשׁ בּוֹ בְּשֵׁמוֹת וְלֹא בְּאוֹתִיּוֹת, אֶלָּא הוּא נִקְרָא בְּכָל הַשֵּׁמוֹת, וְאֵין לוֹ שֵׁם יָדוּעַ, וְכָל שֵׁם וְשֵׁם מֵעִיד עָלָיו שֶׁהוּא אֲדוֹן כָּל הָעוֹלָמוֹת. מֵעִיד עָלָיו אֲדנָי.</p>\n<p>וְאֵין שֶׁיּוֹדְעִים שֶׁיֵּשׁ בֶּן אָדָם שֶׁיּוֹרֵשׁ שְׁלֹשׁ מֵאוֹת וַעֲשָׂרָה עוֹלָמוֹת, זֶהוּ שֶׁכָּתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ. כְּפִי הַדַּרְגָּה שֶׁלּוֹ, שֶׁנִּקְרֵאת יֵשׁ מֵאַיִן. וְזוֹ חָכְמָה עֶלְיוֹנָה. וְיֵשׁ בֶּן אָדָם שֶׁלֹּא יוֹרֵשׁ אֶלָּא עוֹלָם אֶחָד, כְּפִי הַדַּרְגָּה שֶׁלּוֹ, כְּמוֹ שֶׁפֵּרְשׁוּהוּ, כָּל צַדִּיק וְצַדִּיק יֵשׁ לוֹ עוֹלָם בִּפְנֵי עַצְמוֹ. וְכָךְ יוֹרֵשׁ עוֹלָמוֹת כָּל אָדָם מִיִּשְׂרָאֵל כְּפִי הַדַּרְגָּה שֶׁלּוֹ לְמַעְלָה. אֲבָל לַאֲדוֹן הָעוֹלָם אֵין לְצַיֵּר לוֹ עוֹלָמוֹת בְּחֶשְׁבּוֹן, אֶלָּא אֲדוֹן כָּל הָעוֹלָמוֹת, וַאדנָ\"י הוּא מֵעִיד עָלָיו.</p>\n<p>אַף כָּךְ יְהֹוָ\"ה, מִמֶּנּוּ תְּלוּיוֹת כָּל הַהֲוָיוֹת, וְהוּא וְכָל הַהֲוָיוֹת שֶׁלּוֹ מְעִידִים עַל אֲדוֹן הָעוֹלָם, שֶׁהוּא הָיָה קֹדֶם כָּל הַהֲוָיוֹת, וְהוּא בְּתוֹךְ כָּל הֲוָיָה, וְהוּא לְאַחַר כָּל הֲוָיָה. וְזֶה סוֹד שֶׁמְּעִידוֹת הַהֲוָיוֹת עָלָיו - הָיָה, הֹוֶה, וְיִהְיֶה.</p>\n<p>דִּינָא בְּהִפּוּךְ אוֹתִיּוֹת - אֲדנָ\"י. וּמִפְּנֵי זֶה אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, דִּין הַמַּלְכוּת - דִּין. שֵׁם אֵ\"ל מֵעִיד עַל אֲדוֹן הַכֹּל, שֶׁאֵין יְכֹלֶת לְכָל שֵׁם וַהֲוָיָה וְדַרְגָּה. כָּל שֶׁכֵּן לִשְׁאָר בְּרִיּוֹת פָּחוֹת מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (דניאל ד) כְּלֹא נֶחְשָׁבִים וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם וְגוֹ'. אֱלֹהִי\"ם מֵעִיד עַל אֱלָהוּת שֶׁלּוֹ, שֶׁהוּא אֱלֹהִי\"ם וֵאלֹהֵי הָאֱלֹהִים, וְהוּא אֱלוֹהַּ עַל הַכֹּל, וְאֵין אֱלוֹהַּ עָלָיו. צְבָאוֹ\"ת מֵעִיד עָלָיו כְּמוֹ שֶׁכָּתוּב (שם) וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם. שַׁדַּ\"י מֵעִיד עָלָיו, שֶׁכַּאֲשֶׁר הוּא אָמַר לָעוֹלָם דַּי, עָמַד בִּתְחוּמוֹ וְלֹא הִתְפַּשֵּׁט יוֹתֵר. וְגַם לַמַּיִם, וְרוּחַ וְאֵשׁ.</p>\n<p>וְאַף כָּךְ, כָּל הֲוָיָה וְשֵׁם מְעִידִים עָלָיו. שֶׁכַּאֲשֶׁר הָיָה הוּא יָחִיד קֹדֶם שֶׁבָּרָא הָעוֹלָם, מַדּוּעַ הָיָה הוּא צָרִיךְ לְהִקָּרֵא בְּשֵׁמוֹת אֵלּוּ, אוֹ בִּשְׁאָר כִּנּוּיִים, כְּגוֹן (שמותלד) רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְגוֹ', דַּיָּן, אַמִּיץ, חָזָק. וְרַבִּים בְּכָל אֵלּוּ שֵׁמוֹת וְכִנּוּיִים. אֶלָּא נִקְרָא עַל שֵׁם כָּל עוֹלָמוֹת וּבְרִיּוֹת שֶׁלָּהֶם, לְהַרְאוֹת שִׁלְטוֹנוֹ עֲלֵיהֶם.</p>\n<p>אַף כָּךְ הַנְּשָׁמָה, עַל שִׁלְטוֹן כָּל אֶבְרֵי הַגּוּף הִמְשִׁיל אוֹתָהּ אֶצְלוֹ. לֹא שֶׁהִיא דּוֹמָה לוֹ הִיא בְּעַצְמָהּ, שֶׁהוּא בָּרָא אוֹתָהּ, וְאֵין לוֹ אֱלוֹהַּ עָלָיו שֶׁבָּרָא אוֹתוֹ. וְעוֹד, הַנְּשָׁמָה יֵשׁ לָהּ כַּמָּה שִׁנּוּיִים וּמִקְרִים וְסִבּוֹת שֶׁקּוֹרִים לָהּ, מַה שֶּׁאֵין כָּךְ לַאֲדוֹן הַכֹּל. וּמִפְּנֵי זֶה הִיא דּוֹמָה בַּשִּׁלְטוֹן שֶׁלָּהּ עַל כָּל אֶבְרֵי הַגּוּף, אֲבָל לֹא בְּדָבָר אַחֵר.</p>"],[9522012568,"<p>וְעוֹד, (דברים ו) שְׁמַע יִשְׂרָאֵל - שֵׁם ע' רַבָּתִי, ד' מִן אֶחָ\"ד רַבָּתִי, זֶהוּ עֵ\"ד, בֵּין שֵׁ\"ם מִן שְׁמַע, א\"ח מִן אֶחָ\"ד. (שמואל א יב) עֵד ה' בָּכֶם. וְעַל כָּל אֶחָד וְאֶחָד שֶׁמְּיַחֵד אוֹתוֹ בָּעוֹלָם. וְעַל כֵּן אָמַר דָּוִד, (תהלים קד) אָנֹכִי אֶשְׂמַח בַּייָ. ש\"מ מִן שְׁמַע, א\"ח מִן אֶחָ\"ד, הֲרֵי אֶשְׂמַח.</p>\n<p>וְעוֹד, ד' רַבָּתִי - אַרְבָּעָה בָּתֵּי תְפִלִּין, שֶׁמֵּנִיחַ אוֹתָם א\"ח וּמִתְעַטֵּר בָּהֶם, וְהֵם פְּאֵר עַל רֹאשׁוֹ. וְהֵם יְהֹוָ\"ה (יהה\"ו), י' עֲטָרָה עַל ה', וְזוֹהִי בַּת, וְזֶהוּ (משלי ג) יְהֹוָ\"ה בְּחָכְמָה יָסַד אָרֶץ. אַבָּא יָסַד בַּת. ה', אִמָּא עֶלְיוֹנָה, עֲטָרָה עַל ו', שֶׁהוּא בֵּן, וְזֶהוּ (משלי ג) כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בְּאִמָּא כּוֹנֵן בֵּן. וְזֶהוּ שֶׁעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם.</p>"],[9522012569,"<p>וּבַת הִיא תְּפִלָּה שֶׁל יָד כֵּהָ\"ה. י' קֶשֶׁר שֶׁלָּהּ. ה' עֶלְיוֹנָה אִמָּא, תְּפִלִּין שֶׁל רֹאשׁ עַל רֹאשׁ תִּפְאֶרֶת. תְּפִלִּין שֶׁלּוֹ כְּסֵדֶר יְהֹוָ\"ה, שֶׁהוּא: קַדֶּשׁ לִי. וְהָיָה כִּי יְבִאֲךְ. שְׁמַע. וְהָיָה אִם שָׁמֹעַ. אֲבָל בָּעוֹלָם הַבָּא הֲוָיוֹ\"ת בָּאֶמְצַע, שֶׁהֵם ה' ה'. וּמִפְּנֵי זֶה אָמַר הַנָּבִיא, (ירמיה ט) בְּזֹּאת יִ\"תְהַלֵּל הַ\"מִּתְהַלֵּל הַ\"שְׂכֵּל וְ\"יָדעַ אוֹתִי כִּי אֲנִי יְהֹוָ\"ה. וּמִפְּנֵי זֶה פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁיֵּשׁ בָּרֹאשׁ מָקוֹם לְהָנִיחַ שְׁנֵי זוּגוֹת תְּפִלִּין. וְזֶה זוֹכֶה לִשְׁתֵּי מִצְווֹת שֶׁפֵּרְשׁוּ עֲלֵיהֶן, לֹא כָּל אָדָם זוֹכֶה לִשְׁנֵי שֻׁלְחָנוֹת.</p>\n<p>י' -חָכְמָה, ה' -בִּינָה. ו' -הָעַמּוּד הָאֶמְצָעִי. ה' - מַלְכוּת קְדוֹשָׁה. הָרֹאשׁ שֶׁמִּתְעַטֵּר בְּאַרְבַּע אוֹתִיּוֹת זֶה כֶּתֶר הֶקֵּף הָרֹאשׁ שֶׁמְּסוֹבֵב אוֹתָם וּמְכַסֶּה אוֹתָם. אַהֲבָה חֶסֶד קְרִיאַת שְׁמַע, שֶׁשְּׁקוּלָה לַתּוֹרָה שֶׁנִּתְּנָה מִיָּמִין. תְּפִלִּין עֹז, מִשְּׂמֹאל שֶׁל גְּבוּרָה. הָעַמּוּד הָאֶמְצָעִי כּוֹלֵל הַכֹּל, כַּנְפֵי הַמִּצְוָה, נֵצַח וְהוֹד, תְּכֵלֶת וְלָבָן. בַּמְּזוּזָה רָשׁוּם שַׁדַּי, צַדִּיק. וְהַשְּׁכִינָה שַׁעַר הַמְּזוּזָה, זֶה הַשַּׁעַר לַה'.</p>\n<p>וְעוֹד, ש' - שָׁלֹשׁ רְצוּעוֹת. ד' - קֶשֶׁר שֶׁל תְּפִלִּין מֵאֲחוֹרָיו. י' - קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד. וּמִפְּנֵי זֶה שַׁדַּ\"י מִבַּחוּץ, יְהֹוָ\"ה מִבִּפְנִים, שֶׁהִיא אַרְבַּע פָּרָשִׁיּוֹת. שֶׁל אַרְבָּעָה רָאשִׁים רֶמֶז לְאַרְבָּעָה בָּתֵּי הַתְּפִלִּין. שַׁדַּ\"י, אוֹת שֶׁלּוֹ עוֹלָה מְ טַטְרוֹ\"ן.</p>\n<p>וְעוֹד, י' חָכְמָה, קַדֶּשׁ לִי. ה' בִּינָה - וְהָיָה כִּי יְבִאֲךְ. ו' - שְׁמַע, שֵׁשׁ תֵּבוֹת, רוֹמֵז לְשֵׁשׁ סְפִירוֹת, שִׁשָּׁה עַנְפֵי הָאִילָן, שֶׁכּוֹלֶלֶת אוֹתָם תִּפְאֶרֶת. ה' - וְהָיָה אִם שָׁמֹעַ, מַלְכוּת. אֵלּוּ הֵם שֶׁל הָרֹאשׁ, שֶׁהוּא כֶּתֶר, כ', (שמואל א ב) אֵין קָדוֹשׁ כַּה' כִּי אֵין בִּלְתֶּךְ.</p>\n<p>שַׁדַּ\"י, רָמוּז רְצוּעוֹת וּבָתֵּי וְקִשְׁרֵי הַתְּפִלִּין מִבַּחוּץ. אַף כָּךְ בַּמְּזוּזָה, יְהֹוָ\"ה מִבִּפְנִים, שַׁדַּ\"י מִבַּחוּץ, שֶׁל אַרְבָּעָה רָאשִׁים עִם ד', רֶמֶז לְאַרְבָּעָה בָּתִּים וּלְקֶשֶׁר תְּפִלִּין מֵאָחוֹר. ד' כְּפוּלָה, אַף כָּךְ ש' כְּפוּלָה, י' קֶשֶׁר שֶׁל יָד כֵּהָה, שֶׁהוּא בַּיִת חֲמִישִׁי. ד' (י') שֶׁל שַׁדַּ\"י הוּא מֹחַ, שֶׁפֵּרְשׁוּהוּ עָלָיו, בְּמָקוֹם שֶׁמֹּחוֹ שֶׁל תִּינוֹק רוֹפֵס בּוֹ, וְהוּא תִּינוֹק יוֹנֵק מִשְּׁדֵי אִמּוֹ, שַׁדַּ \"י.</p>\n<p>תְּפִלִּין שֶׁל אֲדוֹן הָעוֹלָם - כֶּתֶר. וּמַהוּ הַכֶּתֶר שֶׁל אֲדוֹן הָעוֹלָם? שֵׁם יְהֹוָ\"ה, שֶׁהוּא: י' - חָכְמָה. ה' - בִּינָה. ו' - תִּפְאֶרֶת, כּוֹלֶלֶת שֵׁשׁ סְפִירוֹת. ה' - מַלְכוּת. וּמִפְּנֵי זֶה, (שמואל בז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל. (דברים ד) כִּי מִי גוֹי גָּדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרֹבִים אֵלָיו כַּה' אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. אַרְבָּעָה פְסוּקִים, כֻּלָּם רְשׁוּמִים בְּכ'. סוֹד הָאוֹת כ' - י' י'. שֶׁהוּא י' י' מִן יְאֲהדוָנָהי, (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. כ' מִן כֶּתֶר, כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת, כְּלוּלוֹת מִמַּעְלָה לְמַטָּה, וּמֵעֶשֶׂר סְפִירוֹת מִמַּטָּה לְמַעְלָה.</p>\n<p>וְאֵלּוּ הֵם: (תהלים קמח) וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם, מַיִם עֶלְיוֹנִים - זְכָרִים, מַיִם תַּחְתּוֹנִים - נְקֵבוֹת. וַעֲלֵיהֶם אָמַר רַבִּי עֲקִיבָא לְתַלְמִידָיו: כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר, אַל תֹּאמְרוּ מַיִם מַיִם, שֶׁמָּא תִסְתַּכְּנוּ בְנַפְשְׁכֶם. שֶׁאֵינָם מַיִם כְּמַשְׁמָעָם, אֶלָּא הוּא אוֹר נוֹבֵעַ, וּמִפְּנֵי זֶה נִדְמוּ לְמַיִם נוֹבְעִים, וְזֶה הָאוֹר אֵין לוֹ הֶפְסֵק, וְלֹא קִצּוּץ וּפֵרוּד. וּמִפְּנֵי שֶׁהֵם מִכֶּתֶר, נִקְרְאוּ שֶׁאֵין לָהֶם סוֹף, שֶׁכֶּתֶר נִקְרָא אֵין סוֹף.</p>"],[9522012570,"<p>וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַה' (במדבר כח). בֹּא וּרְאֵה, בְּפֶסַח כָּתוּב וְהִקְרַבְתֶּם אִשֶּׁה עֹלָה לַה'. וְכָאן לֹא כָתוּב אִשֶּׁה (שהרי ביום זה אשה לא כתובבו), אֶלָּא וְהִקְרַבְתֶּם עוֹלָה. מָה הַטַּעַם? יוֹם זֶה, יוֹם שֶׁנִּכְנֶסֶת כַּלָּה לְחֻפָּה הוּא, וְיִשְׂרָאֵל מוֹנִים יְמֵי טָהֳרָה, יָמִים וְשָׁבוּעוֹת, וְנִכְלָלִים וְנִכְנָסִים בִּימֵי הַטָּהֳרָה. וְהִיא יוֹצֵאת מִכָּל צַד רַע, וְשׁוֹמֶרֶת יְמֵי טָהֳרָה כְּמוֹ שֶׁרָאוּי. וְסוֹד זֶה, הַמֶּלֶךְ טַעַם בְּתוּלָה טוֹעֵם. מִשּׁוּם כָּךְ לֹא כָתוּב בּוֹ אִשֶּׁה, שֶׁהֲרֵי אַחֵר לֹא קָרֵב לַמִּשְׁכָּן, וַהֲרֵי מִתְרַחֵק מִשָּׁם. וְעַל כֵּן אִשִּׁים לֹא כָאן, וְלֹא צְרִיכִים לְכָאן, וְיִשְׂרָאֵל מְרֻחָקִים הֵם מִצַּד רַע (ומונים ימי טהרה, ימים ושבועות, ונכללים ונכנסים בימי הטהרה). אָמַר רַבִּי אַבָּא, עֲדַיִן צְרִיכִים אֲנַחְנוּ לְפֶתַח זֶה לִפְתֹּחַ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הֵרַמְתִּי יָדַי בִּתְפִלָּה לְמִי שֶׁבָּרָא הָעוֹלָם, וְסוֹד זֶה מָצָאנוּ בְּסִפְרֵי הָרִאשׁוֹנִים. אִשִּׁים הֵם בָּאֶמְצַע, וּבָאִים בְּצַד זֶה וּבְצַד זֶה, נִדְבָּקִים בְּעֵץ הַדַּעַת טוֹב וָרָע. נִדְבָּקִים בָּרָע וְנִדְבָּקִים בַּטּוֹב. וּמִשּׁוּם כָּךְ בִּשְׁאָר הַיָּמִים כָּתוּב בָּהֶם אִשֶּׁה עוֹלָה, אֲבָל בְּאֵלּוּ הַיָּמִים שֶׁעֵץ הַחַיִּים קַיָּם וְלֹא אַחֵר, אֵין אֲנַחְנוּ צְרִיכִים לְאִשֶּׁה, וְלֹא צָרִיךְ לִהְיוֹת שָׁם. וְיוֹם זֶה יוֹם שֶׁל עֵץ הַחַיִּים הוּא, וְלֹא שֶׁל דַּעַת טוֹב וָרָע. וּמִפְּנֵי זֶה, וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַה', וְלֹא אִשֶּׁה לַה' עוֹלָה. וְעוֹלָה לְשׁוֹן (לשם) עוֹלֶה, כְּמוֹ שֶׁנֶּאֱמַר, וַהֲרֵי הֵעַרְנוּ דְבָרִים שֶׁל פָּרִים בְּנֵי בָקָר, וְכָל אוֹתוֹ קָרְבָּן.</p>\n<p>וּבַחֹדֶשׁ הַשְּׁבִיעִי (במדבר כט), כְּמוֹ שֶׁנֶּאֱמַר, יוֹם שֶׁל רֹאשׁ הַשָּׁנָה דִּין שֶׁל כָּל הָעוֹלָם, דִּין חָזָק וְדִין רָפֶה. וַעֲשִׂיתֶם עוֹלָה?! וְהִקְרַבְתֶּם הָיָה צָרִיךְ לוֹ, כִּשְׁאָר כָּל הַיָּמִים! מַהוּ וַעֲשִׂיתֶם? אֶלָּא בְּיוֹם זֶה כָּתוּב (בראשית כז) וַעֲשֵׂה לִי מַטְעַמִּים. כַּמָּה מַטְעַמִּים וְתַבְשִׁילִים עוֹשִׂים יִשְׂרָאֵל בְּאֵלּוּ הַיָּמִים, בְּעוֹד שֶׁהַמְקַטְרֵג הוֹלֵךְ לְפַשְׁפֵּשׁ בַּחֲטָאֵי הָעוֹלָם. וְעַל כֵּן לֹא כָתוּב וְהִקְרַבְתֶּם, אֶלָּא וַעֲשִׂיתֶם עוֹלָה, וְלֹא אִשֶּׁה עֹלָה. וְכֵן בְּכָל שְׁאָר הַיָּמִים (בקרבנות) לֹא כָתוּב אִשֶּׁה, שֶׁאֵין לָהֶם חֵלֶק בְּכָל אֵלּוּ הַיָּמִים. כָּל שֶׁכֵּן בְּזֶה הַיּוֹם, שֶׁאֲנַחְנוּ עוֹשִׂים מַטְעַמִּים וְתַבְשִׁילִים בְּלִי דַעַת הַצַּד הָאַחֵר, שֶׁהֲרֵי יִצְחָק שׁוֹלֵחַ אוֹתוֹ לָצוּד צִידָה שֶׁל חֲטָאֵי בְּנֵי הָעוֹלָם וּלְהָבִיא אֶצְלוֹ.</p>\n<p>וּבְעוֹד שֶׁהוּא הוֹלֵךְ, יִשְׂרָאֵל לוֹקְחִים עֵצָה מֵרִבְקָה וְעוֹשִׂים כָּל אֵלּוּ הָעֲבוֹדוֹת, כָּל אֵלּוּ הַתְּפִלּוֹת, מְזַמְּנִים שׁוֹפָר וְתוֹקְעִים בּוֹ כְּדֵי לְעוֹרֵר רַחֲמִים. וַהֲרֵי בֵּאַרְנוּ, (שם) וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ, שֶׁבָּא (שאכל) מֵרָחוֹק, מִתּוֹךְ מְקוֹם הַיַּיִן הָעַתִּיק, וְשׁוֹתֶה. וְטוֹעֵם אוֹתוֹ, וְשָׂמֵחַ. וְאַחַר כָּךְ מְבָרֵךְ אוֹתוֹ בְּכַמָּה בְרָכוֹת, וּמַעֲבִיר עַל חֲטָאָיו. מַה כָּתוּב? (שם) וַיְהִי אַךְ יָצֹא יָצָא יַעֲקֹב, וְעֵשָׂו אָחִיו בָּא מִצֵּידוֹ. טָעוּן מִכַּמָּה מַשָּׂאוֹת כְּמוֹ שֶׁנִּתְבָּאֵר, וַהֲרֵי בֵּאַרְנוּ הַדָּבָר.</p>\n<p>וּמִשּׁוּם כָּךְ הוּא יוֹם שֶׁל יְבָבָה, וְהַקָּרְבָּן הוּא עוֹלָה. אַיִל אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר, מִפְּנֵי אֵילוֹ שֶׁל יִצְחָק. וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת, שֹׁחַד לְסָמָאֵל לְכַפֵּר (לשבר) פָּנָיו בְּאוֹתָהּ בְּכִיָּה שֶׁהוּא בּוֹכֶה בְּזֶה הַיּוֹם כֵּיוָן שֶׁרוֹאֶה שֶׁלֹּא נַעֲשָׂה רְצוֹנוֹ וַהֲרֵי לְחִנָּם צָד צִידָה, כְּמוֹ שֶׁנִּתְבָּאֵר. כְּמוֹ כֵן יוֹם הַכִּפּוּרִים, וַהֲרֵי כָּתוּב בְּפָרָשַׁת אֱמֹר.</p>"],[9522012571,"<p>וּבַחֲמִשָּׁה עָשָׂר יוֹם וְגוֹ' (במדבר כט). רַבִּי אַבָּא פָּתַח, (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. בֹּא וּרְאֵה, כָּל אֵלּוּ הַיָּמִים הוֹלֶכֶת אִמָּא עַל הַבָּנִים כְּדֵי שֶׁלֹּא יִשְׁלֹט הַצַּד הָאַחֵר עֲלֵיהֶם וּבִכְדֵי לְהַצִּיל אוֹתָם. כֵּיוָן שֶׁנִּצְּלוּ בָנֶיהָ וַהֲרֵי יוֹשְׁבִים בַּסֻּכּוֹת, שְׁמוּרִים בִּשְׁמִירָה, יוֹם רִאשׁוֹן וְיוֹם שֵׁנִי צִוְּתָה לָהֶם לְיִשְׂרָאֵל לַעֲשׂוֹת סְעוּדָה לִמְמֻנֵּי שְׁאָר הָעַמִּים, וְהִיא לֹא שׁוֹרָה שָׁם. בְּיוֹם שְׁלִישִׁי, שֶׁהוּא י\"ז לַחֹדֶשׁ, מַתְחִילָה לִשְׁרוֹת עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט. הָרִים שֶׁכָּל קְלָלוֹת וְיִסּוּרִים שְׁרוּיִים בְּתוֹכָם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, יוֹם רִאשׁוֹן שֶׁל חַג לֹא שׁוֹרֶה עֲלֵיהֶם, וְלֹא יוֹם שֵׁנִי, אֶלָּא יוֹם שְׁלִישִׁי, שֶׁמּוֹסִיף וְגוֹרֵעַ שׁוֹרֶה עֲלֵיהֶם. מוֹסִיף אוֹתִיּוֹת וְגוֹרֵעַ קָרְבָּנוֹת, שֶׁכָּתוּב עַשְׁתֵּי עָשָׂר וְגוֹ'. וְכָךְ רָאוּי לְרַע עַיִן, מִפְּנֵי שֶׁיּוֹם רִאשׁוֹן וְיוֹם שֵׁנִי שִׂמְחַת בָּנֶיהָ, וְהֵם מְחַלְּקִים שְׁלָלָם לָהֶם. מִיּוֹם שְׁלִישִׁי וָהָלְאָה, שֶׁהִיא שׁוֹרָה עֲלֵיהֶם, מַה כָּתוּב? (שם) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר עַד הַחֹדֶשׁ הָעֲשִׂירִי בָּעֲשִׂירִי בְּאֶחָד לַחֹדֶשׁ נִרְאוּ רָאשֵׁי הֶהָרִים. וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר - אֵלּוּ הַקָּרְבָּנוֹת שֶׁהוֹלְכִים וּמִתְמַעֲטִים. וּכְמוֹ שֶׁהֵם מִתְמַעֲטִים, כָּךְ גַּם מִתְמַעֵט הַטּוֹב שֶׁלָּהֶם.</p>"],[9522012572,"<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, בֹּא וּרְאֵה, מִיּוֹם שֵׁנִי מַתְחִילִים הַמַּיִם לְהֵרָאוֹת. כֵּיוָן שֶׁהִתְחִילוּ הַמַּיִם - מִיּוֹם שְׁלִישִׁי הִיא שׁוֹרָה עֲלֵיהֶם, וְאֵלּוּ הַמַּיִם לֹא הָיוּ יוֹדְעִים הַבַּבְלִים (בכל) מַדּוּעַ רְשׁוּמִים כָּאן, שֶׁהֲרֵי הַטּוֹב שֶׁל יִשְׂרָאֵל אֵינוֹ בִּמְקוֹם הַמִּעוּט, אֶלָּא בִּמְקוֹם הָרִבּוּי. וּמִפְּנֵי שֶׁאֵלּוּ הַמַּיִם שֶׁרְשׁוּמִים כָּאן מִתְמַעֲטִים, בָּא הַפָּסוּק לְהַשְׁמִיעֵנוּ, שֶׁכָּתוּב וְהַמַּיִם, אֵלּוּ שֶׁיְּדוּעִים בִּימֵי הֶחָג, אֵלּוּ שֶׁרְשׁוּמִים תּוֹךְ הַקָּרְבָּנוֹת, שֶׁהֵם הָרֵי קְלָלוֹת, הָיוּ הָלוֹךְ וְחָסוֹר הַטּוֹב שֶׁלָּהֶם. וּמְשִׁיכָה שֶׁנִּמְשֶׁכֶת עֲלֵיהֶם הָיוּ הָלוֹךְ וְחָסוֹר. וּמִפְּנֵי שֶׁאֵלּוּ הַמַּיִם שֶׁלָּהֶם הוּא, לֹא מִתְחַבְּרוֹת אוֹתִיּוֹת, שֶׁלֹּא יִתְחַבֵּר הַטּוֹב שֶׁלָּהֶם אֶלָּא מְעַט מְעַט.</p>\n<p>אֲבָל לְיִשְׂרָאֵל, שֶׁהֵם מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, מַה כָּתוּב? (תהלים לד) וְדֹרְשֵׁי ה' לֹא יַחְסְרוּ כָל טוֹב. רֹאשׁ הַפָּסוּק - כְּפִירִים רָשׁוּ וְרָעֵבוּ - אֵלּוּ הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים. וְדֹרְשֵׁי ה' - אֵלּוּ יִשְׂרָאֵל - לֹא יַחְסְרוּ כָל טוֹב. אֵלּוּ הוֹלְכִים וְעוֹלִים לְמַעְלָה לְמַעְלָה. וּמִשּׁוּם כָּךְ הַטּוֹב שֶׁלָּהֶם, שֶׁהֵם מַיִם, הָיוּ הָלוֹךְ וְחָסוֹר, עַד הַחֹדֶשׁ הָעֲשִׂירִי, זֶה טֵבֵת, שֶׁהֲרֵי אָז יְמֵי הָרָעָה הֵם, וּמִתְעוֹרֶרֶת אוֹתָהּ רָעָה וּמִתְחַזֶּקֶת, וְהַכַּלָּה הַקְּדוֹשָׁה לֹא מְאִירָה מִתּוֹךְ הַשֶּׁמֶשׁ. אָז נִרְאוּ רָאשֵׁי הֶהָרִים, אֵלּוּ הֵם הָרֵי הַחֹשֶׁךְ, הָרֵי הַקְּלָלוֹת נִרְאִים וּמִתְחַזְּקִים וְעוֹשִׂים רָעוֹת בָּעוֹלָם.</p>\n<p>בְּיָמִים אֵלּוּ אִשֶּׁה בְּזוֹ הָעוֹלָה, שֶׁהֲרֵי אָז אֵלּוּ הָאִשִּׁים אוֹכְלִים חֶלְקָם. שִׁבְעִים פָּרִים אֵלּוּ הֵם כְּנֶגֶד שִׁבְעִים מְמֻנִּים שֶׁשּׁוֹלְטִים עַל שִׁבְעִים עַמִּים, וְעוֹלִים בְּיוֹם רִאשׁוֹן, וְיוֹרְדִים בְּכָל יוֹם וָיוֹם, וְנִקְרָאִים פָּרִים מְנַגְּחִים בַּיָּמִים שֶׁלָּהֶם. אֵילִם אַרְבָּעָה עָשָׂר, שְׁנַיִם בְּכָל יוֹם הֵם יַ\"ד יְהֹוָ\"ה. יָד שֶׁשּׁוֹלֶטֶת עֲלֵיהֶם תָּדִיר, בְּכָל יוֹם וָיוֹם. כְּבָשִׂים בְּנֵי שָׁנָה, הַמִּנְיָן שֶׁלָּהֶם חֵ\"ץ.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, רַע עַיִן אָנוּ אֶצְלָם - כֵּן, שֶׁהֲרֵי כָּתוּב (משלי כה) כִּי גֶחָלִים אַתָּה חֹתֶה עַל רֹאשׁוֹ. אֲבָל אֲנַחְנוּ לֹא נוֹתְנִים אֶלָּא בְּשִׂמְחָה, שֶׁאֵין בִּימֵי הַשָּׁנָה שִׂמְחָה כְּאֵלּוּ הַיָּמִים. וּמִפְּנֵי שֶׁאֲנַחְנוּ נוֹתְנִים בְּטוּב לֵב וּבְשִׂמְחָה שֶׁל רָצוֹן - מִתְהַפֵּךְ עֲלֵיהֶם גֶּחָלִים עַל רָאשֵׁיהֶם, גֶּחָלִים לוֹהֲטוֹת שֶׁל הַשִּׂמְחָה שֶׁלָּנוּ עוֹשׂוֹת לָהֶם רָע. י\"ד (ה'), ע', וח\"ץ, כָּךְ עוֹלִים בַּחֶשְׁבּוֹן שֶׁלָּהֶם.</p>\n<p>וְכָל זֶה אִם תֹּאמַר מִי נָתַן לָנוּ לְהַקְרִיב עֲלֵיהֶם, אוּלַי הֵם לֹא רוֹצִים אֶת כָּל זֶה? אֶלָּא אֵין שִׂמְחָה לְכָל אֵלּוּ הַמְמֻנִּים בְּכָל אֵלּוּ הַתּוֹרִים, הָאֵילִים, וְהַכְּבָשִׂים כְּאֵלּוּ, בְּשָׁעָה שֶׁיִּשְׂרָאֵל נָתְנוּ לָהֶם סְעוּדוֹת אֵלּוּ. וְעִם כָּל זֶה לֹא קָרֵב הַכֹּל אֶלָּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ, וְהֵם מִתְקָרְבִים שָׁם וְהוּא מְחַלֵּק לָהֶם. וְעַל זֶה כָּתוּב, (שם) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִלֵהוּ לָחֶם - אֵלּוּ הֵם קָרְבְּנוֹת הֶחָג. וְאִם צָמֵא הַשְׁקֵהוּ מָיִם - אֵלּוּ מַיִם שֶׁרְשׁוּמִים כָּאן בִּימֵי הֶחָג, וּבְיוֹם שֵׁנִי, וּבְיוֹם שִׁשִּׁי וּשְׁבִיעִי, וְסִימָן - (שיר השירים ח) בּוֹ\"ז יָבוּזוּ לוֹ.</p>\n<p>מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה - אֵלּוּ הֵם מַיִם אֲשֶׁר מְנַסְּכִים יִשְׂרָאֵל בְּשִׂמְחָה וּבְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (ישעיה יב) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן. וּנְהָרוֹת לֹא יִשְׁטְפוּהָ - אֵלּוּ הֵם נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר, שֶׁכֻּלָּם דְּבוּקִים וּמִתְקַשְּׁרִים בְּאַהֲבָה זוֹ. אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ - זֶה סָמָאֵל, בְּאַהֲבַת יִשְׂרָאֵל, לִהְיוֹת לוֹ חֵלֶק אִתָּם בְּאֵלּוּ הַמַּיִם שֶׁרְשׁוּמִים כָּאן בַּפָּרָשָׁה, שֶׁכָּתוּב אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ, סִימָן שֶׁל אֵלּו הַמַּיִם בּוֹ\"ז - יָבוּזוּ לוֹ וַדַּאי, שֶׁהֲרֵי כֻּלָּם נֶחְשָׁבִים אֶצְלֵנוּ חֶרֶשׂ נִשְׁבָּר, שֶׁאֵין לוֹ תַּקָּנָה לְעוֹלָמִים.</p>\n<p>הַמַּיִם שֶׁלָּהֶם נֶחֱלָקִים בִּימֵי בּוֹ\"ז. נִשְׁאֲרוּ שְׁאָר יָמִים, שֶׁהֵם ג' ד' ה' (נוטריקון) חֲמִישִׁי רְבִיעִי שְׁלִישִׁי, וְסִימָן - (ישעיה מה) חֶרֶ\"שׂ אֶת חַרְשֵׂי (ה) אֲדָמָה, וְאֵין לָהֶם תִּקּוּן אִתָּנוּ וְלֹא לְעוֹלָמִים. וְאִם תֹּאמַר, בּוֹז יָבוּזוּ לוֹ כָּתוּב שָׁם, (תהלים כב) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת.</p>\n<p>יוֹם רִאשׁוֹן מָה עוֹשֶׂה לוֹ? אֶלָּא לֹא נִקְרָא רִאשׁוֹן וְלֹא נִקְרָא אֶחָד, אֶלָּא חֲמִשָּׁה עָשָׂר סְתָם, בְּלִי רִשּׁוּם כְּלָל. אֲבָל הַתְחָלַת רִשּׁוּם הַמַּיִם מִיּוֹם שֵׁנִי הוּא. וְכָךְ רָאוּי, מִפְּנֵי שֶׁאֵין טוֹב בַּשֵּׁנִי, וּמִשּׁוּם כָּךְ לֹא רָשׁוּם רִאשׁוֹן וְלֹא אֶחָד כְּלָל, וְהוּא בִּסְתָם, וּמַתְחִיל רִשּׁוּם הַיָּמִים בְּיוֹם שֵׁנִי. וְנֶחְלְקוּ מַיִם בְּבוֹ\"ז, וְנִשְׁאֲרוּ בִּימֵי חֶרֶ\"שׂ, כְּמוֹ שֶׁנֶּאֱמַר, וְהַכֹּל כְּמוֹ שֶׁצָּרִיךְ.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁיּוֹדְעִים לְהִכָּנֵס לְתוֹךְ מֹחַ הָאֱגוֹז, וּכְדֵי לְהִכָּנֵס לְתוֹךְ הַמֹּחַ מְשַׁבְּרִים קְלִפּוֹת אֵלּוּ וְנִכְנָסִים. מַה כָּתוּב לְאַחַר כָּל זֶה? בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. לְאַחַר שֶׁשָּׁבְרוּ כָּל אֵלּוּ הַקְּלִפּוֹת, וְשָׁבְרוּ כַּמָּה חֲתִיכוֹת, וְכַמָּה נְחָשִׁים הָרְגוּ, וְכַמָּה עַקְרַבִּים שֶׁהָיוּ לָהֶם בְּאֵלּוּ הָרֵי הַחֹשֶׁךְ, עַד שֶׁמָּצְאוּ מְקוֹם יִשּׁוּב וְעִיר קְדוֹשָׁה מֻקֶּפֶת חוֹמוֹת סָבִיב סָבִיב - אָז נִכְנָסִים אֶצְלָהּ, לַעֲשׂוֹת מְנוּחָה שָׁם וְלִשְׂמֹחַ בָּהּ. וַהֲרֵי בֵּאַרְנוּ הַדָּבָר.</p>\n<p>וְזְהִוּ עֲצֶרֶת, אֲסֵיפָה, מָקוֹם שֶׁנֶּאֱסָף הַכֹּל אֶצְלָהּ. תִּהְיֶה לָכֶם, וְלֹא לְאַחֵר, לִשְׂמֹחַ אִתָּם בַּאֲדוֹנְכֶם, וְהוּא אִתְּכֶם. וְעַל כֵּן כָּתוּב, (תהלים לב) שִׂמְחוּ בַה' וְגִילוּ צַדִּיקִים וְהַרְנִינוּ כָּל יִשְׁרֵי לֵב.</p>"],[9522012573,"<p>וְכֹל הַטַּף בַּנָּשִׁים אֲשֶׁר לֹא יָדְעוּ מִשְׁכַּב זָכָר. שָׁם שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, אֵין הָעוֹלָם מִתְנַהֵג אֶלָּא בִּשְׁנֵי גְוָנִים שֶׁבָּאוּ מִצַּד אִשָּׁה שֶׁנִּמְצְאָה חַכְמַת לֵב. זֶהוּ שֶׁכָּתוּב (שמות לה) וְכָל אִשָּׁה חַכְמַת לֵב בְּיָדֶיהָ טָווּ וַיָּבִיאוּ מַטְוֶה אֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן. וּמַה הֵבִיאוּ? אֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן, גְּוָנִים שֶׁכְּלוּלִים בְּתוֹךְ גְּוָנִים.</p>\n<p>זְהִוּ שֶׁכָּתוּב (משלי לא) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים וַתַּעַשׂ בְּחֵפֶץ כַּפֶּיהָ. וְכָתוּב בְּיָדֶיהָ טָווּ, מַה זֶּה טָווּ? אָמַר רַבִּי יְהוּדָה, טָווּ בְדִין, טָווּ בְרַחֲמִים. אָמַר רַבִּי יִצְחָק, לָמָּה נִקְרְאָה אִשָּׁה? אָמַר לוֹ, שֶׁכְּלוּלָה בְדִין, וּכְלוּלָה בְרַחֲמִים.</p>\n<p>בֹּא וּרְאֵה, שֶׁאָמַר רַבִּי אֶלְעָזָר, כָּל אִשָּׁה נִקְרֵאת בְּדִין עַד שֶׁטּוֹעֶמֶת טַעַם הָרַחֲמִים. שֶׁלָּמַדְנוּ, מִצַּד הָאִישׁ בָּא הַלֹּבֶן, וּמִצַּד הָאִשָּׁה בָּא הָאֹדֶם. טַעַם אִשָּׁה מִלֹּבֶן, וְלֹבֶן עָדִיף.</p>\n<p>וּבֹא וּרְאֵה, לָמָּה נְשׁוֹת שְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁיָּדְעוּ מִשְׁכַּב זָכָר אֲסוּרוֹת? מִשּׁוּם שֶׁשָּׁנִינוּ, יֵשׁ יָמִין וְיֵשׁ שְׂמֹאל, יִשְׂרָאֵל וּשְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְגַן עֵדֶן וְגֵיהִנֹּם, עוֹלָם הַזֶּה וְעוֹלָם הַבָּא. יִשְׂרָאֵל כְּנֶגֶד הָרַחֲמִים, וּשְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת כְּנֶגֶד הַדִּין. וְשָׁנִינוּ, אִשָּׁה שֶׁטָּעֲמָה טַעַם הָרַחֲמִים - הָרַחֲמִים מְנַצְּחִים. וְאִשָּׁה שֶׁטָּעֲמָה טַעַם הַדִּין - דִּין בְּדִין נִדְבָּק, וַעֲלֵיהֶם קָרְאוּ, (ישעיה נו) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה.</p>\n<p>וְעַל זֶה לָמַדְנוּ, הַנִּבְעֶלֶת לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת קְשׁוּרָה בּוֹ כְּכֶלֶב. מָה הַכֶּלֶב תַּקִּיף בְּרוּחוֹ, חָצוּף - גַּם כָּאן דִּין בְּדִין, חֲצוּפָה בַּכֹּל. הַנִּבְעֶלֶת לְיִשְׂרָאֵל, שָׁנִינוּ, כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. מָה הַטַּעַם? מִשּׁוּם שֶׁנִּשְׁמַת יִשְׂרָאֵל בָּאָה מֵרוּחַ אֱלֹהִים חַיִּים, שֶׁכָּתוּב (ישעיה נז) כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף. מַשְׁמָע שֶׁכָּתוּב מִלְּפָנַי. וּמִשּׁוּם זֶה, אִשָּׁה שֶׁהִיא בְּתוּלָה, וְלֹא נִדְבְּקָה בַּדִּין הַקָּשֶׁה שֶׁל שְׁאָר הָעַמִּים, וְנִדְבֶּקֶת בְּיִשְׂרָאֵל - הָרַחֲמִים מְנַצְּחִים, וְנִכְשֶׁרֶת.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (תהלים פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. מַה זֶּה חֶסֶד? הוּא אֶחָד מִכְּתָרִים עֶלְיוֹנִים שֶׁל הַמֶּלֶךְ, שֶׁנִּשְׁמַת יִשְׂרָאֵל קָרָא לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא חֶסֶד, עַל תְּנַאי שֶׁיִּבָּנֶה, וְלֹא יֻשְׁמַד חֶסֶד מֵהָעוֹלָם, מַשְׁמָע שֶׁכָּתוּב יִבָּנֶה. וּמִשּׁוּם כָּךְ שָׁנִינוּ, מִי שֶׁמַּשְׁמִיד חֶסֶד מֵהָעוֹלָם, יֻשְׁמַר הוּא לָעוֹלָם הַבָּא. וְעַל זֶה כָּתוּב, (דברים כה) לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה, בִּשְׁבִיל לַעֲשׂוֹת חֶסֶד עִם הַמֵּת. וְיֵעָשֶׂה הַבִּנְיָן, שֶׁכָּתוּב עוֹלָם חֶסֶד יִבָּנֶה.</p>"],[9522012574,"<p>וָאֶתְחַנַּן אֶל ה' בָּעֵת הַהִוא לֵאמֹר. אֲדֹנָ\"י יֱהִֹוִ\"ה אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךְ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, <Nonesmall>[ישעיה לח]</small> וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה'. בֹּא וּרְאֵה כַּמָּה הוּא הַכֹּחַ הֶחָזָק שֶׁל הַתּוֹרָה וְכַמָּה הוּא עֶלְיוֹן עַל הַכֹּל, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, לֹא פוֹחֵד מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, וְלֹא פוֹחֵד מִמִּקְרִים רָעִים שֶׁל הָעוֹלָם, מִשּׁוּם שֶׁהוּא אָחוּז בְּעֵץ הַחַיִּים וְאוֹכֵל מִמֶּנּוּ בְּכָל יוֹם.</p>\n<p>שֶׁהֲרֵי הַתּוֹרָה מְלַמֶּדֶת אֶת הָאָדָם לָלֶכֶת בְּדֶרֶךְ אֱמֶת, מְלַמֶּדֶת אוֹתוֹ עֵצָה אֵיךְ יָשׁוּב לִפְנֵי רִבּוֹנוֹ <Nonesmall>[לבטל לאותה הגזרה]</small>, וַאֲפִלּוּ שֶׁתִּגָּזֵר עָלָיו מִיתָה – הַכֹּל יִתְבַּטֵּל וְיִסְתַּלֵּק מִמֶּנּוּ וְלֹא יִשְׁרֶה עָלָיו. <Nonesmall>[עצה של אדם בעולם הזה]</small> וְעַל כֵּן צָרִיךְ לְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה וְלֹא יָזוּז מִמֶּנָּה, זֶהוּ שֶׁכָּתוּב <Nonesmall>[יהושע א]</small> וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְאִם מֵזִיז מִמֶּנּוּ אֶת הַתּוֹרָה אוֹ נִפְרָד מִמֶּנָּה, כְּאִלּוּ נִפְרָד מִן הַחַיִּים.</p>\n<p>בֹּא וּרְאֵה, עֵצָה שֶׁל הָאָדָם, כְּשֶׁהוּא בַּלַּיְלָה עַל מִטָּתוֹ, צָרִיךְ לְקַבֵּל עָלָיו עֹל מַלְכוּת שֶׁל מַעְלָה בְּלֵב שָׁלֵם, וּלְהַקְדִּים לִמְסֹר אֵלָיו פִּקְדוֹן נַפְשׁוֹ. וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁכָּל הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת, שֶׁהֲרֵי עֵץ הַמָּוֶת שָׁרוּי בָּעוֹלָם, וְכָל רוּחוֹת בְּנֵי אָדָם יוֹצְאוֹת וְעוֹלוֹת וּמִתְחַבְּאוֹת <Nonesmall>[ונמסרו]</small> אֶצְלוֹ. וּמִשּׁוּם שֶׁהֵן בְּפִקָּדוֹן, כֻּלָּן שָׁבוֹת לִמְקוֹמוֹתֵיהֶן.</p>"],[9522012575,"<p>בֹּא וּרְאֵה, כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן בַּחֲצוֹת הַלַּיְלָה, וְכָרוֹז יוֹצֵא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ בְּרוּחוֹת הַצַּדִּיקִים, אָז מִתְכַּוְּנִים <Nonesmall>[מתעוררים]</small> כָּל בְּנֵי הַמַּלְכָּה וְכָל בְּנֵי הַהֵיכָל לְשַׁבֵּחַ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ. וְאָז כָּל אוֹתָם פִּקְדוֹנוֹת שֶׁל הָרוּחוֹת שֶׁנִּמְסְרוּ בְיָדָהּ, אֶת כֻּלָּם מֵשִׁיב לְבַעְלֵיהֶם. וְרֹב בְּנֵי הָעוֹלָם מִתְעוֹרְרִים בְּאוֹתָהּ שָׁעָה, וַהֲרֵי פִּקָּדוֹן שֶׁל כֻּלָּם מֵשִׁיב אֲלֵיהֶם.</p>\n<p>אוֹתָם שֶׁבְּנֵי הַהֵיכָל הָעֶלְיוֹן עוֹמְדִים בְּעָמְדָם מִתְעוֹרְרִים, מִשְׁתַּדְּלִים בְּתִשְׁבְּחוֹת הַתּוֹרָה, וּמִשְׁתַּתְּפִים בִּכְנֶסֶת יִשְׂרָאֵל עַד שֶׁמֵּאִיר הַיּוֹם. כְּשֶׁמַּגִּיעַ הַבֹּקֶר, הִיא וְכָל בְּנֵי הַהֵיכָל <Nonesmall>[המלך]</small>, כֻּלָּם בָּאִים לַמֶּלֶךְ הַקָּדוֹשׁ, וְהֵם נִקְרָאִים בְּנֵי הַמֶּלֶךְ וְהַמַּלְכָּה, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>כְּשֶׁמַּגִּיעַ הַבֹּקֶר צָרִיךְ לְנַקּוֹת עַצְמוֹ בַּכֹּל וְלַחְגֹּר כְּלֵי מִלְחַמְתּוֹ לְהִשְׁתַּדֵּל עִם הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהֲרֵי בַּלַּיְלָה הִשְׁתַּדֵּל בַּמַּלְכָּה. כָּעֵת בָּא עִם הַמַּלְכָּה לְזַוֵּג אוֹתָהּ עִם הַמֶּלֶךְ.</p>\n<p>בָּא לְבֵית הַכְּנֶסֶת, מְטַהֵר עַצְמוֹ בַּקָּרְבָּנוֹת, מְשַׁבֵּחַ בְּתִשְׁבְּחוֹת דָּוִד הַמֶּלֶךְ, אוֹחֵז תְּפִלִּין בְּרֹאשׁוֹ <Nonesmall>[בידו ובראשו]</small> וְצִיצִית בִּכְנָפָיו, אוֹמֵר \"תְּהִלָּה לְדָוִד\". וַהֲרֵי פֵּרְשׁוּהָ, מִתְפַּלֵּל תְּפִלָּה לִפְנֵי רִבּוֹנוֹ, בַּתְּפִלָּה צָרִיךְ לַעֲמֹד, כְּמוֹ <Nonesmall>[בזווג]</small> מַלְאָכִים הָעֶלְיוֹנִים, לְהִתְחַבֵּר עִמָּם, שֶׁהֵם נִקְרָאִים הָעוֹמְדִים, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[זכריה ג]</small> וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים, וּלְכַוֵּן רְצוֹנוֹ לִפְנֵי רִבּוֹנוֹ, וְיִתְבַּע בַּקָּשָׁתוֹ.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָדָם קָם בַּחֲצוֹת הַלַּיְלָה מִמִּטָּתוֹ לְהִשְׁתַּדֵּל בַּתּוֹרָה, הַכָּרוֹז קוֹרֵא עָלָיו וְאוֹמֵר: <Nonesmall>[תהלים קלד]</small> הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה' הָעֹמְדִים בְּבֵית ה' בַּלֵּילוֹת. עַכְשָׁו כְּשֶׁהוּא עוֹמֵד בִּתְפִלָּה לִפְנֵי רִבּוֹנוֹ, אוֹתוֹ כָּרוֹז קוֹרֵא עָלָיו וְאוֹמֵר: וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה.</p>\n<p>אַחַר שֶׁמְּסַיֵּם תְּפִלָּה בְרָצוֹן <Nonesmall>[ועומד בעצה]</small> לִפְנֵי רִבּוֹנוֹ, הֲרֵי פֵּרְשׁוּהָ שֶׁצָּרִיךְ לִמְסֹר נַפְשׁוֹ בִּרְצוֹן הַלֵּב לְאוֹתוֹ מָקוֹם שֶׁצָּרִיךְ. וְכַמָּה עֵצוֹת יֵשׁ לָאָדָם בַּכֹּל. וּבְשָׁעָה שֶׁהַתְּפִלָּה קַיֶּמֶת <Nonesmall>[הסתימה]</small>, כָּל אוֹתָם דִּבּוּרִים שֶׁמּוֹצִיא אָדָם מִפִּיו בְּאוֹתָהּ תְּפִלָּה, כֻּלָּם עוֹלִים לְמַעְלָה וּבוֹקְעִים אֲוִירִים וּרְקִיעִים, עַד שֶׁמַּגִּיעִים לְאוֹתוֹ מָקוֹם שֶׁמַּגִּיעִים, וּמִתְעַטְּרִים בְּרֹאשׁ הַמֶּלֶךְ וְעוֹשִׂים מֵהֶם עֲטָרָה. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, תְּפִלָּה שֶׁצָּרִיךְ לַקָּדוֹשׁ־בָּרוּךְ־הוּא, לְכַוֵּן שֶׁתִּהְיֶה תְפִלַּת תַּחֲנוּנִים. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב וָאֶתְחַנַּן אֶל ה'. זוֹהִי תְפִלָּה מְעֻלָּה.</p>"],[9522012576,"<p>בֹּא וּרְאֵה, מִי שֶׁעוֹמֵד בַּתְּפִלָּה, צָרִיךְ לְכַוֵּן רַגְלָיו, וּפֵרְשׁוּהָ. וְצָרִיךְ לְכַסּוֹת רֹאשׁוֹ כְּמִי שֶׁעוֹמֵד לִפְנֵי הַמֶּלֶךְ, וְצָרִיךְ לְכַסּוֹת <Nonesmall>[לכסות]</small> <Nonesmall>[לסתם]</small> עֵינָיו כְּדֵי שֶׁלֹּא יִסְתַּכֵּל בַּשְּׁכִינָה. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא אָמַר, מִי שֶׁפּוֹקֵחַ עֵינָיו בִּשְׁעַת הַתְּפִלָּה אוֹ שֶׁלֹּא מַנְמִיךְ אֶת עֵינָיו לָאָרֶץ, מַקְדִּים עָלָיו מַלְאַךְ הַמָּוֶת, וּכְשֶׁתֶּצֵא נַפְשׁוֹ לֹא יִסְתַּכֵּל בְּאוֹר הַשְּׁכִינָה וְלֹא יָמוּת בִּנְשִׁיקָה. מִי שֶׁמְּזַלְזֵל בַּשְּׁכִינָה הוּא מִתְזַלְזֵל בְּאוֹתָהּ שָׁעָה שֶׁהוּא צָרִיךְ אוֹתָהּ, זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמואל א ב]</small> כִּי מְכַבְּדַי אֲכַבֵּד וּבֹזַי יֵקָלּוּ.</p>\n<p>זְהִ מִי שֶׁמִּסְתַּכֵּל בַּשְּׁכִינָה בְּשָׁעָה שֶׁהוּא מִתְפַּלֵּל. וְאֵיךְ יָכוֹל לְהִסְתַּכֵּל בַּשְּׁכִינָה? אֶלָּא לָדַעַת שֶׁוַּדַּאי הַשְּׁכִינָה עוֹמֶדֶת לְפָנָיו. זֶהוּ שֶׁכָּתוּב וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, שֶׁשָּׁם שׁוֹרָה הַשְּׁכִינָה. מִשּׁוּם כָּךְ לֹא צָרִיךְ לִהְיוֹת חוֹצֵץ בֵּינוֹ וּבֵין הַקִּיר, וּפֵרְשׁוּהָ.</p>\n<p>מִי שֶׁעוֹמֵד בַּתְּפִלָּה צָרִיךְ לְסַדֵּר שֶׁבַח רִבּוֹנוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ יְבַקֵּשׁ בַּקָּשָׁתוֹ. שֶׁהֲרֵי מֹשֶׁה כָּךְ אָמַר בַּתְּחִלָּה, אַתָּה הַחִלּוֹתָ וְגוֹ', וּלְבַסּוֹף אֶעְבְּרָה וְגוֹ'. רַבִּי יְהוּדָה אָמַר, מַה שּׁוֹנֶה כָּאן שֶׁכָּתוּב אֲדֹנָ\"י בַּהַתְחָלָה, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד, וּלְבַסּוֹף יֱהִֹוִ\"ה, וְקוֹרְאִים אֱלֹהִי\"ם? אֶלָּא הַסִּדּוּר כָּךְ הוּא – מִלְּמַטָּה לְמַעְלָה, וּלְהַכְלִיל מִדַּת יוֹם בַּלַּיְלָה וּמִדַּת לַיְלָה בַּיּוֹם, וּלְזַוֵּג הַכֹּל כְּאֶחָד כָּרָאוּי.</p>"],[9522012577,"<p>אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךְ. מָה הָרֵאשִׁית כָּאן? אֶלָּא וַדַּאי מֹשֶׁה רֵאשִׁית הָיָה בָּעוֹלָם לִהְיוֹת שָׁלֵם בַּכֹּל. וְאִם תֹּאמַר, יַעֲקֹב הָיָה שָׁלֵם, וְהָאִילָן הִשְׁתַּלֵּם לְמַטָּה כְּמוֹ לְמַעְלָה – כָּךְ זֶה בְּוַדַּאי, אֲבָל מַה שֶּׁהָיָה לְמֹשֶׁה לֹא הָיָה לְאָדָם אַחֵר, שֶׁהֲרֵי הִתְעַטֵּר בִּשְׁלֵמוּת יְתֵרָה בְּכַמָּה אֲלָפִים וּרְבָבוֹת מִיִּשְׂרָאֵל, בַּתּוֹרָה, בַּמִּשְׁכָּן, בַּכֹּהֲנִים, בַּלְוִיִּם, בַּשְּׁנֵים עָשָׂר שְׁבָטִים, גְּדוֹלִים מְמֻנִּים עֲלֵיהֶם, בְּשִׁבְעִים סַנְהֶדְרִין. הוּא הִשְׁתַּלֵּם בְּגוּף שָׁלֵם. אַהֲרֹן לְיָמִין, נַחְשׁוֹן לִשְׂמֹאל, וְהוּא בֵּינֵיהֶם.</p>\n<p>מִשּׁוּם זֶה אֶת גָּדְלְךְ, מִיָּמִין, זֶה אַהֲרֹן. וְאֶת יָדְךְ הַחֲזָקָה, מִשְּׂמֹאל, זֶה נַחְשׁוֹן. וַהֲרֵי נִתְבָּאֵר. מִשּׁוּם כָּךְ מֹשֶׁה הָיָה רֵאשִׁית בָּעוֹלָם. וְאִם תֹּאמַר, מִי הָיָה הַסִּיּוּם <Nonesmall>[שהרי משה היה הראשית]</small> ? הַסִּיּוּם הוּא מֶלֶךְ הַמָּשִׁיחַ, שֶׁהֲרֵי אָז תִּמָּצֵא שְׁלֵמוּת בָּעוֹלָם מַה שֶּׁלֹּא הָיָה כֵּן לְדוֹרֵי דוֹרוֹת. בְּאוֹתוֹ זְמַן תִּמָּצֵא שְׁלֵמוּת לְמַעְלָה וּלְמַטָּה, וְיִהְיוּ הָעוֹלָמוֹת כֻּלָּם בְּזִוּוּג אֶחָד, וְאָז כָּתוּב <Nonesmall>[זכריה יד]</small> בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>וַיֹּאמֶר ה' אֵלַי רַב לָךְ אַל תּוֹסֶף וְגוֹ'. אָמַר רַבִּי חִיָּיא, אָמַר לוֹ הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְמֹשֶׁה, מֹשֶׁה, רַב לָךְ שֶׁהִזְדַּוַּגְתָּ בַּשְּׁכִינָה, מִכָּאן וְאֵילָךְ אַל תּוֹסֶף. רַבִּי יִצְחָק אָמַר, רַב לָךְ בְּאוֹר הַשֶּׁמֶשׁ שֶׁהָיָה לָךְ, אַל תּוֹסֶף, שֶׁהֲרֵי זְמַן הַלְּבָנָה הִגִּיעַ, וּלְבָנָה לֹא יְכוֹלָה לְהָאִיר עַד שֶׁיִּתְכַּנֵּס הַשֶּׁמֶשׁ. אֲבָל, וְצַו אֶת יְהוֹשֻׁעַ וְחַזְּקֵהוּ וְאַמְּצֵהוּ. אַתָּה, שֶׁהוּא הַשֶּׁמֶשׁ, צָרִיךְ לְהָאִיר לַלְּבָנָה, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ'. רַבִּי יוֹסֵי אָמַר, <Nonesmall>[תהלים קמד]</small> אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ וְגוֹ'. אַשְׁרֵי הָעָם שֶׁהַקָּדוֹשׁ־בָּרוּךְ־הוּא בָּחַר בָּהֶם מִכָּל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְהֶעֱלָה אוֹתָם לְגוֹרָלוֹ וּבֵרְכָם בְּבִרְכָתוֹ, בְּבִרְכַּת שְׁמוֹ, זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה סא]</small> כִּי הֵם זֶרַע בֵּרַךְ ה', בֵּרַךְ ה' מַמָּשׁ.</p>\n<p>בֹּא וּרְאֵה, אֶת כָּל שְׁאָר עַמֵּי הָעוֹלָם נָתַן הַקָּדוֹשׁ־בָּרוּךְ־הוּא לִמְמֻנִּים גְּדוֹלִים שֶׁשּׁוֹלְטִים עֲלֵיהֶם, וְאֶת יִשְׂרָאֵל אָחַז הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְגוֹרָלוֹ וּלְחֶלְקוֹ, לְהֵאָחֵז בּוֹ מַמָּשׁ. וְנָתַן לָהֶם תּוֹרָה קְדוֹשָׁה כְּדֵי לְהֵאָחֵז בִּשְׁמוֹ, וְעַל זֶה וְאַתֶּם הַדְּבֵקִים בַּה', וְלֹא בִמְמֻנֶּה אַחֵר כִּשְׁאָר הָעַמִּים, וַהֲרֵי פֵּרְשׁוּהָ בְּכַמָּה מְקוֹמוֹת.</p>"],[9522012578,"<p>וַיְדַבֵּר ה' אֲלֵיכֶם מִתּוֹךְ הָאֵשׁ קוֹל דְּבָרִים אַתֶּם שּמְעִים וְגוֹ' <Nonesmall>[דברים ד]</small>. אָמַר רַבִּי אֶלְעָזָר, בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל. קוֹל דְּבָרִים, מַה זֶּה קוֹל דְּבָרִים? אֶלָּא קוֹל שֶׁנִּקְרָא דִבּוּר, שֶׁכָּל דִּבּוּר תָּלוּי בּוֹ. וְעַל זֶה כָּתוּב וַיְדַבֵּר ה' אֲלֵיכֶם, שֶׁהֲרֵי דִּבּוּר בְּמָקוֹם זֶה תָּלוּי, לָזֶה נִקְרָא קוֹל דְּבָרִים.</p>\n<p>אַתֶּם שּמְעִים, שֶׁשְּׁמִיעָה לֹא תְלוּיָה אֶלָּא בָּזֶה, מִשּׁוּם שֶׁשְּׁמִיעָה תְּלוּיָה בַּדִּבּוּר, וּמִשּׁוּם כָּךְ אַתֶּם שׁוֹמְעִים. <Nonesmall>[אתם שומעים, ושמיעה תלויה בדיבור]</small> וַהֲרֵי פֵּרְשׁוּהָ, <Nonesmall>[שמות כא]</small> וְרָצַע אֲדנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ, מִשּׁוּם שֶׁפָּגַם מָקוֹם שֶׁנִּקְרָא שְׁמִיעָה, וְהוּא דִּבּוּר וְהוּא שְׁמִיעָה.</p>\n<p>קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וּתְמוּנָה אֵינְכֶם רֹאִים. מַה זֶּה וּתְמוּנָה? כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[במדבר יב]</small> וּתְמוּנַת ה' יַבִּיט. דָּבָר אַחֵר וּתְמוּנָה – זֶה קוֹל פְּנִימִי שֶׁלֹּא הָיָה נִרְאֶה כְּלָל. זוּלָתִי קוֹל, זֶה קוֹל אַחֵר שֶׁאָמַרְנוּ. וּתְמוּנָה, לָמָּה נִקְרָא כָּךְ? מִשּׁוּם שֶׁכָּל תִּקּוּן הַגּוּף יוֹצֵא מִמֶּנָּה.</p>\n<p>וְאִם תֹּאמַר, אַחֵר נִקְרָא גַּם כָּךְ – כֵּן. שֶׁזֶּה הָאַחֵר הַתִּקּוּן שֶׁלְּמַטָּה מִמֶּנּוּ יוֹצֵא. וּמִשּׁוּם זֶה ה' עֶלְיוֹנָה ה' תַּחְתּוֹנָה. ה' עֶלְיוֹנָה – קוֹל גָּדוֹל וְלֹא יָסָף <Nonesmall>[דברים ה]</small>, שֶׁלֹּא פוֹסְקִים הַמַּבּוּעִים לְעוֹלָמִים, וְכָל אוֹתָם קוֹלוֹת נִמְצָאִים שָׁם כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל, וְהַכֹּל יוֹצֵא מֵאוֹתוֹ קוֹל פְּנִימִי שֶׁל הַכֹּל, מִשּׁוּם שֶׁבּוֹ תָּלוּי הַדָּבָר.</p>\n<p>זְהִ שֶׁנִּקְרָא מִשְׁנֵה תוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אָמַר אוֹתָם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדָּבָר. לָמָּה כָּךְ? אֶלָּא חָכְמָה עֶלְיוֹנָה, כְּלַל הַתּוֹרָה נִקְרֵאת, וּמִמֶּנָּה הַכֹּל יוֹצֵא בְּאוֹתוֹ קוֹל פְּנִימִי. אַחַר כָּךְ הַכֹּל מִתְיַשֵּׁב וּמִתְאַחֵד בְּמָקוֹם שֶׁנִּקְרָא עֵץ הַחַיִּים, וּבוֹ תָּלוּי כְּלָל וּפְרָט, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, וְהוּא נִקְרָא תוֹרָה וּמִשְׁנֵה תוֹרָה. בַּהַתְחָלָה גְּבוּרָה שֶׁלֹּא פוֹסֶקֶת, וְעַכְשָׁו הַכֹּל כְּאֶחָד. מִשּׁוּם כָּךְ כָּאן בְּאוֹתָם עֲשֶׂרֶת הַדִּבְּרוֹת, הַכֹּל רָשׁוּם בְּוָא\"ו, וְלֹא תִאְנָף, וְלֹא תִגְנֹב, וְלֹא תַעֲנֶה, וְלֹא תַחְמֹד, וְלֹא תִתְאַוֶּה, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַה זֶּה וְלֹא תִתְאַוֶּה, כֵּיוָן שֶׁכָּתוּב וְלֹא תַחְמֹד, שֶׁהֲרֵי בָּזֶה מַסְפִּיק? אָמַר לוֹ, אַשְׁרֵי בַּעֲלֵי הָאֱמֶת, חֲמִידָה דַּרְגָּה אַחַת, תַּאֲוָה דַּרְגָּה אַחֶרֶת. חֲמִידָה – שֶׁאִם יָכוֹל, הוֹלֵךְ לָקַחַת אֶת שֶׁלּוֹ מִשּׁוּם אוֹתָהּ חֲמִידָה שֶׁלָּקַח, הוֹלֵךְ לַעֲשׂוֹת מַעֲשֶׂה. תַּאֲוָה לֹא כָּךְ, שֶׁהֲרֵי אֲפִלּוּ שֶׁלֹּא יִקַּח דֶּרֶךְ לָלֶכֶת אַחֲרֵי זֶה, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, לָמָּה לֹא כָתוּב וְלֹא תִרְצַח, כְּמוֹ הָאֲחֵרִים הַלָּלוּ? אָמַר לוֹ, מִשּׁוּם שֶׁדַּרְגַּת הַדִּין תְּלוּיָה בִּגְבוּרָה, וְלֹא בִּמְקוֹם הָרַחֲמִים, וּמִשּׁוּם זֶה לֹא כָתוּב וָא\"ו בְּלֹא תִרְצַח. וּמִשּׁוּם שֶׁצְּרִיכִים חָמֵשׁ וָוִי\"ם, הִתּוֹסֵף וָא\"ו וְלֹא תִתְאַוֶּה, שֶׁהֲרֵי בְּלֹא תִרְצַח לֹא צָרִיךְ לָשִׂים וָא\"ו, וְהִתּוֹסֵף כָּאן.</p>\n<p>שָׁמַע רַבִּי פִּנְחָס שֶׁיָּשַׁב אַחֲרָיו וּנְשָׁקוֹ. בָּכָה וְחִיֵּךְ. אָמַר, גּוּר אַרְיֵה, אֵין מִי שֶׁיַּעֲמֹד לִפְנֵיהֶם, מִי יָכוֹל לַעֲמֹד לְפָנָיו וְאָבִיו בָּעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, וְאַשְׁרֵי חֶלְקִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא שֶׁזָּכִיתִי לָזֶה. עַל זֶה כָּתוּב, <Nonesmall>[איוב כב]</small> יִרְאוּ צַדִּיקִים וְיִשְׂמָחוּ.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, קְרַב אַתָּה וּשֲׁמָע וְגוֹ'. בּא וּרְאֵה, בְּשָׁעָה שֶׁנִּתְּנָה תּוֹרָה לְיִשְׂרָאֵל, כָּל הַקּוֹלוֹת נִמְצְאוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יָשַׁב עַל הַכִּסֵּא, וְזֶה מִתּוֹךְ זֶה נִרְאָה, וְדִבּוּר שֶׁל זֶה יָצָא מִתּוֹךְ הָעֶלְיוֹן שֶׁמֵּעָלָיו. וְזֶהוּ סוֹד הַכָּתוּב פָּנִים בְּפָנִים דִּבֶּר ה' עִמָּכֶם בָּהָר מִתּוֹךְ הָאֵשׁ. שֶׁדִּבּוּר יָצָא, וְדִבֵּר מִתּוֹךְ אֵשׁ וְשַׁלְהֶבֶת שֶׁדָּחָה אוֹתוֹ הַחוּצָה בְּדפֶק שֶׁל רוּחַ וּמַיִם שֶׁנּוֹתְנִים כֹּחַ. שֶׁאֵשׁ וְרוּחַ וּמַיִם מִתּוֹךְ שׁוֹפָר שֶׁכּוֹלֵל אֶת כֻּלָּם יוֹצְאִים, וְיִשְׂרָאֵל הִתְרַחֲקוּ מִפַּחַד זֶה.</p>\n<p>וּמִשּׁוּם כָּךְ, וְאַתְּ תְּדַבֵּר אֵלֵינוּ. לֹא רוֹצִים בְּכֹחַ עֶלְיוֹן שֶׁלְּמַעְלָה, אֶלָּא מִמָּקוֹם שֶׁל הַנְּקֵבָה וְלֹא יוֹתֵר, וְאַתְּ תְּדַבֵּר אֵלֵינוּ וְגוֹ'. אָמַר מֹשֶׁה, וַדַּאי הֶחֱלַשְׁתֶּם אֶת כֹּחִי, הֶחֱלַשְׁתֶּם כֹּחַ אַחֵר, שֶׁאִלְמָלֵא לֹא הִתְרַחֲקוּ יִשְׂרָאֵל וְיִשְׁמְעוּ כָּל אוֹתוֹ דָּבָר כְּמוֹ בַּתְּחִלָּה, לֹא הָיָה יָכוֹל הָעוֹלָם לִהְיוֹת חָרֵב אַחַר כָּךְ, וְהֵם הָיוּ קַיָּמִים לְדוֹרֵי דוֹרוֹת.</p>\n<p>שֶׁהֲרֵי בְּשָׁעָה רִאשׁוֹנָה מֵתוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ צָרִיךְ, שֶׁהֲרֵי עֵץ הַמָּוֶת גָּרַם. אַחַר שֶׁחָיוּ וְקָמוּ וְהִתְרַבּוּ וְרָצָה הַקָּדוֹשׁ־בָּרוּךְ־הוּא לְהַכְנִיסָם לְעֵץ הַחַיִּים שֶׁעוֹמֵד עַל אוֹתוֹ עֵץ הַמָּוֶת כְּדֵי לִהְיוֹת קַיָּמִים לְעוֹלָמִים, הִתְרַחֲקוּ וְלֹא רָצוּ, וְאָז נֶחֱלַשׁ כֹּחַ מֹשֶׁה עֲלֵיהֶם וְנֶחֱלַשׁ כֹּחַ אַחֵר. אָמַר הַקָּדוֹשׁ־בָּרוּךְ־הוּא, אֲנִי רָצִיתִי לְקַיֵּם אֶתְכֶם בְּמָקוֹם עֶלְיוֹן וּלְהִדָּבֵק בַּחַיִּים – אַתֶּם רְצִיתֶם מָקוֹם שֶׁשְּׁרוּיָה הַנְּקֵבָה, וְלָכֵן לֵךְ אֱמֹר לָהֶם וְגוֹ'. כָּל אֶחָד יֵלֵךְ לַנְּקֵבָה שֶׁלּוֹ וְיִתְיַחֵד עִמָּהּ.</p>\n<p>וְעִם כָּל זֶה, כֵּיוָן שֶׁיִּשְׂרָאֵל לֹא עָשׂוּ אֶלָּא בְּפַחַד עֶלְיוֹן שֶׁהָיָה עֲלֵיהֶם, לֹא נֶאֱמַר עֲלֵיהֶם, אֶלָּא מִי יִתֵּן וְהָיָה לְבָבָם זֶה לָהֶם וְגוֹ'. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁעוֹשֶׂה דָבָר, וְלִבּוֹ וּרְצוֹנוֹ לֹא שָׂם בַּצַּד הָרָע, אַף עַל גַּב שֶׁהוּא רַע – הוֹאִיל וְלֹא עָשָׂה בְרָצוֹן, לֹא שׁוֹרֶה עָלָיו עֹנֶשׁ, וְלֹא כְאָדָם אַחֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא דָן אוֹתוֹ לְרַע.</p>"],[9522012579,"<p>וְאַתָּה פֹּה עֲמֹד עִמָּדִי. מִכָּאן נִפְרַד מִכֹּל וָכֹל מֵאִשְׁתּוֹ, וְנִדְבַּק וְעָלָה בְּמָקוֹם אַחֵר שֶׁל הַזָּכָר, וְלֹא בִנְקֵבָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, נְבִיא הָאֱמֶת, שֶׁזָּכָה לִדְרָגוֹת עֶלְיוֹנוֹת, מַה שֶּׁלֹּא זָכָה אָדָם אַחֵר לְעוֹלָמִים. וְעַל זֶה כָּתוּב, <Nonesmall>[קהלת ז]</small> טוֹב לִפְנֵי הָאֱלֹהִים יִמָּלֵט מִמֶּנָּה. מַה זֶּה טוֹב? זֶה מֹשֶׁה, שֶׁכָּתוּב <Nonesmall>[שמות ב]</small> כִּי טוֹב הוּא. וּמִשּׁוּם שֶׁהָיָה טוֹב, עָלָה לְדַרְגָּה אַחֶרֶת עֶלְיוֹנָה. וְעַל זֶה כָּתוּב <Nonesmall>[שם ג]</small> כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. עוֹמֵד עָלָיו דַּוְקָא. מָה הַטַּעַם? מִשּׁוּם כִּי טוֹב הוּא, וְטוֹב הוּא זָכָר.</p>\n<p>וְאִם תֹּאמַר שֶׁהֲרֵי אָמַר רַבִּי יְהוּדָה, הֲרֵי דָּוִד שֶׁכָּתוּב בּוֹ טוֹב, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שמואל א טז]</small> וְטוֹב רֹאִי, לָמָּה לֹא הָיָה יוֹתֵר? אָמַר לוֹ, כָּתוּב וְטוֹב רֹאִי. טוֹב רֹאִי זֶה שֶׁהוּא מַרְאֶה לְהִסְתַּכֵּל, כָּךְ הָיָה דָּוִד. טוֹב רֹאִי – הָיָה טוֹב שֶׁהוּא מַרְאֶה. וּבְמֹשֶׁה כָּתוּב טוֹב הוּא, מַמָּשׁ, וְכָאן טוֹב רֹאִי, וְעִם כָּל זֶה בִּשְׁנֵיהֶם הָיָה אָחוּז, שֶׁהֲרֵי זֶה בָּזֶה אָחוּז. וּמֹשֶׁה, אַחַר שֶׁהָיָה טוֹב, עָלָה לִהְיוֹת גּוּף אִישׁ. <Nonesmall>[דברים לג]</small> אִישׁ הָאֱלֹהִים. <Nonesmall>[במדבר יב]</small> וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בְּכָל מַעֲשָׂיו צָרִיךְ הָאָדָם לָשִׂים כְּנֶגְדּוֹ אֶת הַקָּדוֹשׁ־בָּרוּךְ־הוּא, וַהֲרֵי בֵּאַרְנוּ אֶת הַדָּבָר. רַבִּי יְהוּדָה לְטַעֲמוֹ. שֶׁאָמַר רַבִּי יְהוּדָה, מִי שֶׁהוֹלֵךְ בַּדֶּרֶךְ יְכַוֵּן לִשְׁלֹשָׁה דְבָרִים, וְעֶלְיוֹן מִכֻּלָּם זוֹ הַתְּפִלָּה. וְאַף עַל גַּב שֶׁתְּפִלָּה יוֹתֵר עֶלְיוֹנָה מֵהַכֹּל, שְׁנֵי חֲבֵרִים אוֹ שְׁלֹשָׁה שֶׁעוֹסְקִים בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי לֹא יִפְחֲדוּ, כִּי הַשְּׁכִינָה <Nonesmall>[ולמעלה מהם תפלה, ועליונה מכלם, חברים בדברי תורה. שהרי השכינה]</small> מִשְׁתַּתֶּפֶת עִמָּם.</p>"],[9522012580,"<p><Nonesmall>[כמו זה ש]</small> רַבִּי אֶלְעָזָר וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי אֶלְעָזָר, כָּתוּב <Nonesmall>[בראשית ג]</small> וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר. וְכִי עַד עַכְשָׁו מֻפְשָׁטִים הָיוּ מֵאוֹתוֹ הָעוֹר? כֵּן. אֶלָּא כְּלֵי לְבוּשֵׁי כָבוֹד הָיוּ. אָמַר לוֹ רַבִּי חִיָּיא, אִם כָּךְ לֹא רָאוּי לָהֶם אֲפִלּוּ כָּתְנוֹת עוֹר. וְאִם תֹּאמַר שֶׁעַד שֶׁלֹּא חָטְאוּ הִלְבִּישׁוּ אוֹתָם – לֹא. אֶלָּא אַחַר שֶׁחָטְאוּ כָּתוּב <Nonesmall>[בראשית ג]</small> וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹ עוֹר וַיַּלְבִּשֵׁם וְגוֹ'.</p>\n<p>אָמַר לוֹ, כָּךְ זֶה בְּוַדַּאי. בַּהַתְחָלָה הָיוּ כְּמוֹ שֶׁלְּמַעְלָה, וּמֻפְשָׁטִים מֵהַגְּוָנִים שֶׁלְּמַטָּה, וְהָיָה הָאוֹר הָעֶלְיוֹן סוֹבֵב עֲלֵיהֶם. אַחַר שֶׁחָטְאוּ הֶחֱזִירָם בְּצוּרוֹת הָעוֹלָם הַזֶּה, וְהֶעֱבִיר מֵהֶם הַצּוּרוֹת שֶׁלְּמַעְלָה. מַה כָּתוּב? וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם, מִצּוּרַת הָעוֹלָם הַזֶּה. כָּתוּב <Nonesmall>[שמות כט]</small> [ואת אהרן] וְאֶת בָּנָיו תַּקְרִיב וְהִלְבַּשְׁתָּם כֻּתֳּנֹת. שָׁם כְּגוֹן עֶלְיוֹן, כָּאן כְּגוֹן תַּחְתּוֹן. שָׁם כָּתְנוֹת שֵׁשׁ, כָּאן כָּתְנוֹת עוֹר. וְאַף עַל גַּב שֶׁכָּךְ הוּא, הַיֹּפִי שֶׁל אוֹתָם לְבוּשִׁים עָלָה עַל הַכֹּל.</p>\n<p>וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם <Nonesmall>[בראשית ג]</small>. <Nonesmall>[בצורת]</small> <Nonesmall>[בדפוס]</small> הָעוֹלָם הַזֶּה, מַה שֶּׁלֹּא הָיָה קֹדֶם שֶׁהָיוּ מַשְׁגִּיחִים וּפוֹקְחִים לְמַעְלָה, לֶעָתִיד לָבֹא כָּתוּב <Nonesmall>[ישעיה מב]</small> וְהוֹלַכְתִּי עִוְרִים בְּדֶרֶךְ לֹא יָדָעוּ וְגוֹ'. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְקֹחַ עֵינַיִם שֶׁל אֲנָשִׁים לֹא חֲכָמִים, וּלְהִסְתַּכֵּל בְּחָכְמָה עֶלְיוֹנָה וּלְהִדָּבֵק בְּמַה שֶּׁלֹּא נִדְבְּקוּ בָּעוֹלָם הַזֶּה, כְּדֵי שֶׁיֵּדְעוּ אֶת רִבּוֹנָם. אַשְׁרֵי הַצַּדִּיקִים שֶׁיִּזְכּוּ לְאוֹתָהּ חָכְמָה, שֶׁאֵין חָכְמָה כְּאוֹתָהּ חָכְמָה, וְלֹא יְדִיעָה כְּאוֹתָהּ יְדִיעָה, וְלֹא דְבֵקוּת כְּאוֹתָהּ דְּבֵקוּת.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים רָאוּ אוֹתָם לִיסְטִים הוֹלְכִים אַחֲרֵיהֶם לְקַפֵּחַ אוֹתָם. הִסְתַּכֵּל בָּהֶם רַבִּי אֶלְעָזָר. בָּאוּ שְׁתֵּי חַיּוֹת שָׂדֶה וְהָרְגוּ אוֹתָם. אָמַר רַבִּי אֶלְעָזָר, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילָנוּ. קָרָא עֲלֵיהֶם, <Nonesmall>[משלי ד]</small> בְּלֶכְתְּךְ לֹא יֵצַר צַעֲדֶךְ וְאִם תָּרוּץ לֹא תִכָּשֵׁל, וְכָתוּב <Nonesmall>[תהלים לא]</small> כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ', וְכָתוּב <Nonesmall>[שם]</small> כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ.</p>"],[9522012581,"<p>לָמַדְנוּ בְּסוֹד עֶלְיוֹן בְּסִפְרָא דִצְנִיעוּתָא, שְׁלֹשָׁה חֲלָלִים שֶׁל אוֹתִיּוֹת רְשׁוּמוֹת הִתְגַּלּוּ בַגֻּלְגֹּלֶת שֶׁל זְעֵיר אַנְפִּין. וְשָׁנִינוּ, שְׁלֹשָׁה מֹחוֹת הֵם שֶׁנִּסְתָּרִים בְּאוֹתָם חֲלָלִים. וּמֵרֵאשִׁית <Nonesmall>[וממשיכות]</small> הַמֹּחַ הָעֶלְיוֹן הַנִּסְתָּר שֶׁל הָעַתִּיק הַקָּדוֹשׁ שֶׁנִּמְשָׁךְ בְּאוֹתוֹ זְעֵיר אַנְפִּין נִמְצְאוּ אַרְבָּעָה מֹחוֹת. וְאַרְבָּעָה הַמֹּחוֹת הַלָּלוּ <Nonesmall>[דין אין כתר מכל כתרי המלך]</small> נִמְצָאִים וּמִתְפַּשְּׁטִים <Nonesmall>[בכל, והם]</small> בְּכָל הַגּוּף, וְהֵם אַרְבַּע פָּרָשִׁיּוֹת שֶׁל אַרְבָּעָה בָּתֵי הַתְּפִלִּין שֶׁמֵּנִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְלָכֵן צָרִיךְ הָאָדָם לְהָנִיחַ בְּכָל יוֹם, מִשּׁוּם שֶׁהֵן שֵׁם קָדוֹשׁ עֶלְיוֹן בְּאוֹתִיּוֹתָיו רְשׁוּמוֹת, שֶׁכָּתוּב <Nonesmall>[דברים כח]</small> וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ. וְשָׁנִינוּ שֵׁם ה' מַמָּשׁ, וְאֵלּוּ תְפִלִּין שֶׁל רֹאשׁ. <Nonesmall>[מח עליון שנמשך במח תחתון נקראו שני מחין, והם שכתוב חכמות, והתפרשו באחד]</small>.</p>\n<p>רַבִּי יִצְחָק אָמַר, הוּא שֶׁכָּתוּב <Nonesmall>[שמות יג]</small> קַדֶּשׁ לִי כָל בְּכוֹר. זֶהוּ כֶּתֶר שֶׁכָּלוּל וּמַסְתִּיר כָּל אוֹתָם הָאֲחֵרִים. <Nonesmall>[כל בכור, כל בכור סתם, לעליון]</small> מְשִׁיכוּת <Nonesmall>[מחנה]</small> שֶׁלְּמַעְלָה נִסְתֶּרֶת בּוֹ. <Nonesmall>[של הכל]</small> וְזֶה נִקְרָא פֶּטֶר כָּל רֶחֶם, פְּתִיחוּת שֶׁל כָּל מְשִׁיכוּת הָרַחֲמִים וִיסוֹד <Nonesmall>[ואור]</small> עֶלְיוֹן.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וְנִסְתָּר בַּיּוֹ\"ד שֶׁל הַשֵּׁם הַקָּדוֹשׁ. וְזֶה <Nonesmall>[יו\"ד]</small> בַּיִת אֶחָד שֶׁל תְּפִלִּין, שֶׁהוּא קַדֶּשׁ לִי כָל בְּכוֹר סְתָם. מֹחַ <Nonesmall>[אבא]</small> עֶלְיוֹן, חָכְמָה.</p>\n<p>בַּיִת שֵׁנִי – וְהָיָה כִּי יְבִיאֲךְ ה' <Nonesmall>[אלהיך]</small>. אָמַר רַבִּי יְהוּדָה, מֹחַ שֶׁשְּׁעָרָיו יוֹצְאִים לַחֲמִשִּׁים שְׁעָרִים, שְׁעָרִים גְּדוֹלִים, וְהֵם כְּנֶגֶד זְמַנִּים רַבִּים, שֶׁכָּתוּב <Nonesmall>[שם כ]</small> אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם. <Nonesmall>[שם יג]</small> הוֹצִיאֲךְ ה' מִמִּצְרַיִם. וְנִזְכַּר פְּעָמִים רַבּוֹת זִכְרוֹן מִצְרַיִם, וְהֵם חֲמִשִּׁים כְּנֶגֶד חֲמִשִּׁים.</p>\n<p>וְשָׁנִינוּ בְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא שֶׁאָמַר, שְׁעָרִים רַבִּים שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה שָׁבַר הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהָיוּ נִסְתָּרִים וּקְשׁוּרִים בְּשַׁלְשְׁלָאוֹתֵיהֶם כְּדֵי לְהוֹצִיא אֶת יִשְׂרָאֵל <Nonesmall>[לחוץ]</small>, שֶׁהֲרֵי מֵהַשְּׁעָרִים הַלָּלוּ שֶׁל אוֹתוֹ הַמֹּחַ נִפְתָּחִים וּמֻתָּרִים כָּל שְׁאָר הַשְּׁעָרִים, וְאִלְמָלֵא שֶׁהִתְעוֹרְרוּ וְנִפְתְּחוּ אוֹתָם שְׁעָרִים שֶׁל הַמֹּחַ הַזֶּה, לֹא הָיוּ נִפְתָּחִים אוֹתָם הָאֲחֵרִים לַעֲשׂוֹת דִּין וּלְהוֹצִיא אֶת יִשְׂרָאֵל מִן הָעַבְדוּת.</p>\n<p>וְהַכֹּל נִסְתָּר בָּזֶה שֶׁנִּקְרֵאת אֵם הָעֶלְיוֹנָה, שֶׁמִּמֶּנָּה מִתְעוֹרֵר כֹּחַ לָאֵם הַתַּחְתּוֹנָה. וּמַהוּ? שֶׁכָּתוּב בָּהּ, <Nonesmall>[ישעיה נא]</small> וּלְאוּמִּי אֵלַי הַאֲזִינוּ. אַל תִּקְרֵי לְאוּמִּי אֶלָּא לְאִמִּי. שֶׁלֹּא זָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּחַבֵּב אֶת כְּנֶסֶת יִשְׂרָאֵל עַד שֶׁקָּרָא לָהּ אִמִּי. וְזֶה יוֹצֵא מֵהָאֵם הָעֶלְיוֹנָה, שֶׁהִיא בַּיִת שֵׁנִי, שֶׁנִּקְרֵאת ה' שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁנִּפְתַּחַת לַחֲמִשִּׁים שְׁעָרִים, וּמִזֶּה יוֹצֵא רוּחַ לְנֶקֶב אֶחָד שֶׁל חוֹר הַחֹטֶם.</p>\n<p>וְשָׁנִינוּ, הַיּוֹבֵל שֶׁיּוֹצְאִים בּוֹ הָעֲבָדִים לְחֵרוּת, בַּמֹּחַ הַזֶּה נֶאֱחָז, וְהֵם חֲמִשִּׁים שְׁנוֹת הַיּוֹבֵל, וְהֵם חֲמִשִּׁים יְמֵי סְפִירַת הָעֹמֶר בּוֹ נֶאֱחָזִים, שֶׁבָּהֶם נָחוֹת רוּחוֹת הָעֲבָדִים וּמוֹצִיאִים רוּחָם <Nonesmall>[ומוציא רוחו]</small> לִמְנוּחָה, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[שם יד]</small> בְּיוֹם הָנִיחַ ה' לְךְ מֵעָצְבְּךְ וּמִרָגְזֶךְ וּמִן הָעֲבֹדָה וְגוֹ'. וּמִשּׁוּם זֶה, ה' מְנוּחַת הָרוּחַ, וּלְהוֹצִיא רוּחַ לַחֵרוּת. וּבְבַיִת זֶה תְּלוּיָה יְצִיאַת מִצְרַיִם, וּבָאוֹת ה' שֶׁל הַשֵּׁם הַקָּדוֹשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר. עַד כָּאן כְּלָל שֶׁל י\"ה שֶׁל הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>בֹּא וּרְאֵה, מִצַּד אַבָּא יוֹצֵא חֶסֶד, מִצַּד אִמָּא יוֹצֵאת גְּבוּרָה, וְהַכֹּל אוֹחֵז הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִתְעַטֵּר בָּהֶם אוֹת וָא\"ו.</p>\n<p>בַּיִת שְׁלִישִׁי – שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. שָׁנָה רַבִּי שִׁמְעוֹן, זֶהוּ סוֹד עֶלְיוֹן שֶׁיִּשְׂרָאֵל הָעֶלְיוֹן הִתְעַטֵּר בְּצַד הָאַבָּא, וּמַהוּ? אַבְרָהָם. וְהִתְעַטֵּר בְּצַד הָאִמָּא, וּמַהוּ? יִצְחָק.</p>\n<p>שָׁנִינוּ, וְאָהַבְתָּ – מִי שֶׁאוֹהֵב אֶת הַמֶּלֶךְ, עוֹשֶׂה יוֹתֵר טוּב חֶסֶד עִם הַכֹּל. וְחֶסֶד יוֹתֵר, אוֹתוֹ שֶׁנִּקְרָא חֶסֶד שֶׁל אֱמֶת, שֶׁלֹּא רוֹצֶה עָלָיו שָׂכָר, אֶלָּא בִּשְׁבִיל אַהֲבַת הַמֶּלֶךְ שֶׁאוֹהֵב אוֹתוֹ יוֹתֵר, וּבְאַהֲבַת הַמֶּלֶךְ תָּלוּי הַחֶסֶד. וְעַל זֶה נִקְרָא <Nonesmall>[ישעיה מא]</small> אַבְרָהָם אוֹהֲבִי. וּמִשּׁוּם שֶׁאוֹהֵב אוֹתוֹ יוֹתֵר, מַגְדִּיל חֶסֶד בָּעוֹלָם. וְעַל זֶה כָּאן וְאָהַבְתָּ. וּבָאַהֲבָה תָּלוּי הַחֶסֶד, וְזֶהוּ הַבַּיִת הַשְּׁלִישִׁי.</p>\n<p>הַבַּיִת הָרְבִיעִי – <Nonesmall>[דברים יא]</small> וְהָיָה אִם שָׁמוֹעַ. הִשָּׁמְרוּ לָכֶם. וְחָרָה אַף ה'. גְּבוּרָה חֲזָקָה וְדִין קָשֶׁה הִיא, וְיוֹצֵאת מִצַּד הָאִמָּא הָעֶלְיוֹנָה. וְשָׁנִינוּ, אַף עַל גַּב שֶׁהִיא אֵינָהּ דִּין, מִצִּדָּהּ יוֹצֵא דִין, <Nonesmall>[שיוצא]</small> גְּבוּרָה עֶלְיוֹנָה. וְאִם תֹּאמַר, וְהָיָה אִם שָׁמוֹעַ שֶׁאֵינֶנּוּ דִין, אֵין כֶּתֶר בְּכָל כִּתְרֵי הַמֶּלֶךְ שֶׁלֹּא יִכָּלְלוּ בוֹ דִּין וְרַחֲמִים, כָּל שֶׁכֵּן גִּבוּרָה שֶׁנִּכְלָל טוֹב וָרַע.</p>\n<p>וְאַרְבָּעָֹה אֵלֶּה לוֹקֵחַ אוֹתָם וָא\"ו וּמִתְעַטֵּר בָּהֶם, וְאֵלּוּ הֵן תְּפִלִּין שֶׁמֵּנִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא. שָׁנִינוּ, הַוָּא\"ו הַזֶּה עוֹלֶה וּמִתְעַטֵּר בְּעַטְרוֹתָיו, וְאוֹחֵז אֶת זֶה וְאֶת זֶה וּמִתְעַטֵּר בְּכֻלָּם, וְעַל זֶה וָא\"ו אֶמְצַע הַכֹּל, שֶׁלְּמַעְלָה וּלְמַטָּה, לְהַרְאוֹת חָכְמָה שְׁלֵמָה מִכָּל צְדָדָיו.</p>\n<p><Nonesmall>[שנה רבי אבא,]</small> כָּתוּב <Nonesmall>[דברים י]</small> רק באבתיך חשק ה'. מכאן אמר רבי שמעון, האבות הם מרכבה קדושה עליונה, וכתוב חשק ה'. בּא וּרְאֵה, כְּמוֹ שֶׁיֵּשׁ מֶרְכָּבָה קְדוֹשָׁה לְמַטָּה, כָּךְ יֵשׁ מֶרְכָּבָה קְדוֹשָׁה לְמַעְלָה. וּמַה הִיא? זֶה שֶׁאָמַרְנוּ, מֶרְכָּבָה קְדוֹשָׁה הַכֹּל נִקְרָא, וְהַכֹּל נִקְשָׁר זֶה בָּזֶה, וְנַעֲשֶׂה הַכֹּל אֶחָד.</p>\n<p>רַק בַּאֲבֹתֶיךְ – שְׁלֹשָׁה, וּמֶרְכָּבָה – אַרְבָּעָה. אַרְבָּעָה מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיִּבְחַר בְּזַרְעָם אַחֲרֵיהֶם. מַה מַּשְׁמִיעַ? לְהַכְלִיל בָּהֶם אֶת דָּוִד הַמֶּלֶךְ, שֶׁהוּא רְבִיעִי לְהִתְתַּקֵּן בַּמֶּרְכָּבָה הַקְּדוֹשָׁה. שֶׁשָּׁנִינוּ, הָאָבוֹת תִּקּוּן שְׁלֵמוּת הַכֹּל, וְהַגּוּף מִשְׁתַּכְלֵל בָּהֶם וְנִבְנֶה, וּבָהֶם נֶאֱחָז. בָּא דָוִד הַמֶּלֶךְ וְשִׁכְלֵל הַכֹּל, וְהִתְקִין הַגּוּף וְהִשְׁלִימָם בָּהֶם. וְאָמַר רַבִּי יִצְחָק, כְּמוֹ שֶׁזָּכוּ הָאָבוֹת לְהִתְעַטֵּר בַּמֶּרְכָּבָה הַקְּדוֹשָׁה, כָּךְ זָכָה דָוִד לְהִתְתַּקֵּן בָּעַמּוּד הָרְבִיעִי שֶׁל הַמֶּרְכָּבָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּתוּב בְּדָוִד <Nonesmall>[שמואל א טז]</small> וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. מָה הַטַּעַם אַדְמוֹנִי? מִשּׁוּם שֶׁחֵלֶק גּוֹרָלוֹ גָּרַם לוֹ. אַדְמוֹנִי, דִּין וַדַּאי. עִם יְפֵה עֵינַיִם, דִּין בְּרַחֲמִים, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[ישעיה נה]</small> חַסְדֵי דָוִד הַנֶּאֱמָנִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, חַסְדֵי דָוִד, בִּמְקוֹמוֹ בֵּאַרְנוּ. אֶלָּא וְהוּא אַדְמוֹנִי, כְּמוֹ שֶׁאָמַרְנוּ. עִם יְפֵה עֵינַיִם – אֵלּוּ הָאָבוֹת. בֹּא וּרְאֵה, יְרוּשָׁלַיִם וְצִיּוֹן – דִּין וְרַחֲמִים, וְאַף עַל פִּי כֵן כָּתוּב <Nonesmall>[מלכים א ח]</small> [מ] עִיר דָּוִד הִיא צִיּוֹן, וּכְתִיב <Nonesmall>[הושע יא]</small> בְּקִרְבְּךְ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר. נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִכָּנֵס בִּירוּשָׁלַיִם שֶׁל מַעְלָה וְכוּ'. אֵימָתַי? אָמַר רַבִּי יְהוּדָה, כְּשֶׁתַּחֲזֹּר מַלְכוּת בֵּית דָּוִד לִמְקוֹמָהּ לְמַטָּה.</p>\n<p>רַבִּי יִצְחָק אָמַר, ש' שֶׁמְּצֻיֶּרֶת בִּשְׁלֹשֶׁת הַקְּשָׁרִים, <Nonesmall>[של ארבעה קשרים, רמוזה היא לשלשה, ורמוזה לארבעה. שלשה זה שאמרנו. ארבעה, להיות מרכבה קדושה כאחד, שהרי הוא כלל התקון העליון. ומכאן נפרדים ונמשכים התחתונים בדרכיהם ברצועותיהם, שתלויים בשערות הללו של הראש שתלויים בהם, ונמשכים מהם כל אותם אחרים, עד שנקשרים במקומם]</small>.</p>\n<p>שָׁנִינוּ, ו' נוֹטֵל אוֹתָם עֶלְיוֹנִים שֶׁאָמַרְנוּ, וְאֵלּוּ תְּפִלִּין שֶׁמֵּנִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא. מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְהִתְפָּאֵר בָּהֶם, עֲלֵיהֶם כָּתוּב וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ, שֵׁם ה' מַמָּשׁ. וְאֵלּוּ אוֹתָם תְּפִלִּין שֶׁל רֹאשׁ. תְּפִלִּין שֶׁל זְרוֹעַ הִיא שְׂמֹאל, שֶׁנִּקְרָא עֹז, וְיָרְשָׁה מֵעֹז, זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמות יג]</small> וְהָיָה לְאוֹת עַל יָדְכָה, בְּהֵ\"א, וְהִיא הֵ\"א שֶׁבֵּאַרְנוּ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל. וְעַל זֶה הֵ\"א אַחֲרוֹנָה לָקְחָה תְפִלִּין, שֶׁהִיא שְׂמֹאל.</p>\n<p>לְמִי הֵם אַרְבַּע אֵלֶּה, שֶׁהֵם גּוּף אֶחָד, וְעַל זֶה כְּלוּלִים בְּאֶחָד, וּמִי הֵם? תִּפְאֶרֶת נֵצַח הוֹד יְסוֹד. וְהִיא הֵ\"א שֶׁל יָדְכָה, וְכֻלָּם אֲחוּזִים בָּהּ בִּשְׁבִיל לְהִתְבָּרֵךְ מֵהֶם, וּכְלוּלָה מִכֻּלָּם.</p>\n<p>אָמַר רַבִּי חִיָּיא, אִם כָּךְ, הֲרֵי כָּתוּב <Nonesmall>[שמות לג]</small> וְרָאִיתָ אֶת אֲחֹרָי, וְשָׁנִינוּ, זֶה קֶשֶׁר שֶׁל תְּפִלִּין. אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ, וְיָפֶה הוּא, וְהַכֹּל בֵּרוּר הַדָּבָר. וְעַל זֶה מִזֶּה תְּלוּיָה רְצוּעָה אַחַת לְמַטָּה, שֶׁהֲרֵי מִמֶּנָּה תְּלוּיִים הַתַּחְתּוֹנִים וְנִזּוֹנִים מִמֶּנָּה. וְעַל זֶה נִקְרָא אוֹת, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[בראשית ט]</small> זֹּאת אוֹת הַבְּרִית. וְכָתוּב וְהָיָה לְאוֹת עַל יָדְכָה, בְּהֵ\"א, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>שְׁמַע יִשְׂרָאֵל. אָמַר רַבִּי יֵיסָא, יִשְׂרָאֵל סָבָא. רַבִּי יִצְחָק אָמַר, ע' גְּדוֹלָה, לִכְלֹל שִׁבְעִים שֵׁמוֹת, עֵדוּת הַכֹּל שְׁמַע יִשְׂרָאֵל, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[ישעיה א]</small> שִׁמְעוּ שָׁמַיִם. וְכָתוּב <Nonesmall>[דברים לב]</small> הַאֲזִינוּ הַשָּׁמַיִם. גַּם כָּאן שְׁמַע יִשְׂרָאֵל. וְהַכֹּל דָּבָר אֶחָד הוּא. יְהֹוָ\"ה – רֹאשׁ הַכֹּל בְּאוֹר הָעַתִּיק הַקָּדוֹשׁ, וְזֶהוּ שֶׁנִּקְרָא אָ\"ב. אֱלֹהֵינוּ – עֹמֶק הַנְּחָלִים וְהַמַּבּוּעִים שֶׁיּוֹצְאִים וְשׁוֹפְעִים לַכֹּל.</p>\n<p>יְהֹוָ\"ה – גּוּף הָאִילָן, שְׁלֵמוּת הַשָּׁרָשִׁים. אֶחָד – כְּנֶסֶת יִשְׂרָאֵל. וְהַכֹּל שְׁלֵמוּת אַחַת, וְנִקְשָׁר זֶה בָּזֶה, וְלֹא נִמְצָא פֵרוּד, אֶלָּא הַכֹּל אֶחָד.</p>\n<p>שָׁנָה רַבִּי יִצְחָק, מֶרְכָּבָה קְדוֹשָׁה עֶלְיוֹנָה, אַרְבָּעָה בָּתֵּי תְפִלִּין שֶׁמֵּנִיחַ ו', כְּמוֹ שֶׁנֶּאֱמַר. מֶרְכָּבָה קְדוֹשָׁה אַחֶרֶת, אַרְבָּעָה אֲחֵרִים שֶׁכְּלוּלִים בְּאֶחָד, שֶׁמֵּנִיחַ ה' הָאַחֲרוֹנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>"],[9522012582,"<p>שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד. מִצְוָה זוֹ לְיַחֵד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם, שֶׁהֲרֵי כְּמוֹ שֶׁמְּיַחֲדִים שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, כָּךְ מִתְיַחֵד שְׁמוֹ לְמַעְלָה. נִמְצָא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָחִיד מַעְלָה וּמַטָּה. מִי שֶׁמְּיַחֵד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, יָשִׂים לִבּוֹ וּרְצוֹנוֹ בְּאוֹתוֹ יִחוּד שֶׁאָמַרְנוּ, וִיחַבֵּר כָּל אֵיבָרָיו בְּאוֹתוֹ יִחוּד לִהְיוֹת כֻּלָּם אֶחָד. כְּמוֹ שֶׁשָּׂם כָּל אֵיבָרָיו בְּסוֹד אֶחָד, כָּךְ לְמַעְלָה מְחַבֵּר כָּל הָאֵיבָרִים הָעֶלְיוֹנִים בְּאוֹתוֹ יִחוּד לִהְיוֹת כֻּלָּם אֶחָד.</p>\n<p>בְּשָׁעָה שֶׁבָּא אָדָם לְיַחֵד אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל חֵילוֹת הַשָּׁמַיִם עוֹמְדִים שׁוּרוֹת שׁוּרוֹת כְּדֵי לְהִתְתַּקֵּן וּלְהִכָּלֵל כֻּלָּם בְּאוֹתוֹ יִחוּד, לַעֲמֹד בְּסוֹד אֶחָד בְּיִחוּד אֶחָד. כֻּלָּם מִתְתַּקְּנִים בְּתִקּוּנֵיהֶם כָּרָאוּי. בְּאוֹתָהּ שָׁעָה עוֹמֵד מְמֻנֶּה אֶחָד שַׁמָּשׁ שֶׁעוֹמֵד תַּחַת מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה עוֹלָמוֹת, וְכֻלָּם נִקְרָאִים אֵיבְרֵי הַגּוּף. וְזֶה נִקְרָא הלני\"ו, עוֹמֵד וּמְחַכֶּה לְאוֹתוֹ יִחוּד, וְזֶהוּ מְלַקֵּט שׁוֹשַׁנִּים, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שיר השירים ו]</small> וְלִלְקֹט שׁוֹשַׁנִּים, שֶׁהֵם אֵיבְרֵי הַגּוּף.</p>\n<p>הָאֵיבָרִים הָעֶלְיוֹנִים לוֹקֵט אוֹתָם הַשֵּׁם הָעֶלְיוֹן בְּסוֹד הַיִּחוּד שֶׁהִתְיַחֵד בְּסוֹד אַרְבָּעִים וּשְׁנַיִם שֵׁמוֹת, וְלוֹקֵט כָּל אוֹתָם שׁוֹשַׁנִּים עֶלְיוֹנִים, וְשַׁמָּשׁ זֶה לוֹקֵט כָּל אוֹתָם הַתַּחְתּוֹנִים, שֶׁכֻּלָּם מְמֻנִּים בַּכְּלָל שֶׁל שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וְנִלְקָטִים כֻּלָּם בְּאוֹתוֹ הַיִּחוּד, וְנַעֲשִׂים כֻּלָּם גּוּף אֶחָד בְּסוֹד אֶחָד. וְאוֹתוֹ הַיִּחוּד עוֹלֶה, וּמְיַחֵד הַכֹּל בִּשְׁנֵי צְדָדִים בְּיִחוּד אֶחָד. בְּאוֹתָהּ שָׁעָה מִתְלַקְּטִים כָּל הָאֵיבָרִים וּמִתְחַבְּרִים בְּחִבּוּר אֶחָד, לִהְיוֹת כֻּלָּם בְּסוֹד אֶחָד, לְמַעְלָה וּלְמַטָּה, בְּסוֹד שֶׁל ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>וְעַל כֵּן מַאֲרִיכִים בְּאֶחָד בִּשְׁתֵּי אוֹתִיּוֹת, לִלְקֹט שׁוֹשַׁנִּים, לְהִתְיַחֵד בְּסוֹד שֶׁל אֶחָד בְּיִחוּד שָׁלֵם. כֵּיוָן שֶׁכָּל הָאֵיבָרִים מִתְיַחֲדִים בְּסוֹד אֶחָד שֶׁל יִחוּד אֶחָד, אָז נִקְרָא הַכֹּל קָרְבָּן שָׁלֵם, וְעַל סוֹד זֶה הִכְנִיס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אָדָם הָרִאשׁוֹן לְגַן עֵדֶן, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[בראשית ב]</small> לְעָבְדָהּ וּלְשָׁמְרָהּ. וְשָׁנִינוּ שֶׁאֵלֶּה אוֹתָם קָרְבָּנוֹת שְׁנַיִם, סוֹד שֶׁל ה' אֶחָד וּשְׁמוֹ אֶחָד. שֶׁבְּאֵלּוּ קָרְבָּנוֹת כָּתוּב וְלִלְקֹט שׁוֹשַׁנִּים. <Nonesmall>[שהקדוש ברוך הוא הוא לוקט שושנים, לוקט כל אותם איברים שלמעלה ומטה לחבר אותם ביחוד באותו שאמרנו. אז מתעורר מי שמתעורר ללקט שושנים]</small> אֵלּוּ הָאֵיבָרִים שֶׁל שְׁנֵי צְדָדִים שֶׁהֵם אֶחָד.</p>\n<p>שׁוֹשַׁנִּים, סוֹד הוּא. שֶׁכְּשֶׁמִּתְחַבְּרִים כָּל <Nonesmall>[אותם]</small> אֵיבָרִים כְּאֶחָד, לִהְיוֹת כֻּלָּם בְּיִחוּד אֶחָד, סוֹד הַקָּרְבָּן, אָז מִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בַּעֲטָרָה בָּרֹאשׁ שֶׁל כֶּתֶם פָּז, לִהְיוֹת בִּכְבוֹדוֹ מִתְעַטֵּר. וְסוֹד זֶה הָיָה, שֶׁכָּתוּב שׁוֹשַׁנִּים, סוֹד שֶׁל כָּל אוֹתָם אֵיבָרִים שֶׁלְּמַעְלָה וּלְמַטָּה. וְסוֹד שֶׁל אוֹתוֹ פָּז, עִטּוּר שֶׁמִּתְעַטֵּר וְעוֹלֶה מִבֵּינֵיהֶם, וְהַכֹּל נִמְצָא בּוֹ.</p>\n<p>בַּשּׁוֹשַׁנִּים הַלָּלוּ יֵשׁ שֵׁשׁ מֵאוֹת וּשְׁלֹשׁ עֶשְׂרֵה מִצְווֹת, שֶׁהֵם אֵיבָרִים שֶׁל שְׁנֵי צְדָדִים, סוֹד שֶׁל יְהֹוָ\"ה אֶחָד וּשְׁמוֹ אֶחָד. וְיֵשׁ בּוֹ עֲלִיָּה שֶׁל אוֹתוֹ פָּז שֶׁעוֹלֶה מִבֵּינֵיהֶם. וּבְכָל מָקוֹם שֶׁהֵם נִמְצָאִים, אוֹתָהּ עֲלִיָּה עֶלְיוֹנָה נִמְצֵאת מִבֵּינֵיהֶם לַעֲלוֹת. וְסוֹד זֶה <Nonesmall>[שיר השירים ב]</small> תַּפּוּחַ בַּעֲצֵי הַיַּעַר, וְשׁוֹשַׁנָּה בֵּין הַחוֹחִים. זֶה וָזֶה צְרִיכִים לַעֲלוֹת כְּאֶחָד בְּיִחוּד שָׁלֵם. אַשְׁרֵי מִי שֶׁמַּקְרִיב קָרְבָּנוֹת אֵלּוּ, וַדַּאי לְרָצוֹן לוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522012583,"<p>מִצְוָה לְיִרְאָה <Nonesmall>[ה]</small> בְּדֶרֶךְ כְּלָל וּבְדֶרֶךְ פְּרָט. וַהֲרֵי יִרְאָה בֵּאַרְנוּ, מִשּׁוּם שֶׁיֵּשׁ עַל הָאָדָם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[דברים כח]</small> לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא הַזֶּה אֵת ה' אֱלֹהֶיךְ. וּבִשְׁבִיל יִרְאָה זוֹ יִשָּׁמֵר בִּדְרָכָיו. וְיִרְאָה, מָקוֹם הוּא שֶׁנִּקְרָא יִרְאָה, מִשּׁוּם שֶׁשָּׁם נִמְצֵאת יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא, הִיא יִרְאַת ה' לִירָא מִמֶּנּוּ, וְזֶהוּ סוֹד הַכָּתוּב <Nonesmall>[ויקרא יט]</small> וּמִקְדָּשִׁי תִּירָאוּ. בַּיִּרְאָה הַזּוֹ שְׁרוּיָה מַכַּת אֵשׁ, לְהַלְקוֹת אֶת הָרְשָׁעִים שֶׁלֹּא שׁוֹמְרִים מִצְווֹת הַתּוֹרָה, וְעַל זֶה בְּדֶרֶךְ כְּלָל יֵשׁ לִירָא.</p>\n<p>וְאַחַר כָּךְ בְּדֶרֶךְ פְּרָט, כְּשֶׁיּוֹדֵעַ הָאָדָם מַהִי יִרְאַת ה', וְזוֹהִי יִרְאָה שֶׁל חֲבִיבוּת, שֶׁהִיא עִקָּר וִיסוֹד לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. <Nonesmall>[אחר]</small> יִרְאָה זוֹ עוֹשֶׂה כְּדֵי לִשְׁמֹר כָּל מִצְווֹת הַתּוֹרָה, לִהְיוֹת אָדָם עֶבֶד נֶאֱמָן לַקָּדוֹשׁ־בָּרוּךְ־הוּא כָּרָאוּי. <Nonesmall>[יראה]</small></p>"],[9522012584,"<p>מִצְוָה <Nonesmall>[ו]</small> לְאַהֲבָה, וַהֲרֵי בֵּאַרְנוּ אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁצָּרִיךְ הָאָדָם לֶאֱהֹב אוֹתוֹ אַהֲבָה רַבָּה כְּמוֹ אַבְרָהָם שֶׁאָהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכַמָּה אֲהָבוֹת וּמָסַר אֵלָיו גּוּפוֹ וְנַפְשׁוֹ. מִכָּאן לָמַדְנוּ, מִי שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מְקַיֵּם עֶשֶׂר אֲמִירוֹת מַעְלָה וּמַטָּה. וְעַל זֶה כָּל אוֹתָם עֲשָׂרָה נִסְיוֹנוֹת שֶׁהִתְנַסָּה אַבְרָהָם וְעָמַד בְּכֻלָּם, כְּנֶגֶד עֶשֶׂר אֲמִירוֹת, כָּל נִסָּיוֹן הִיא אֲמִירָה, וְהִתְנַסָּה בְּאוֹתָהּ אֲמִירָה וְעָמַד בָּהּ.</p>\n<p>וְעַל זֶה אוֹתָם עֲשָׂרָה נִסְיוֹנוֹת, וּבְכֻלָּם עָמַד אַבְרָהָם, מִשּׁוּם שֶׁהִתְקַשֵּׁר וְנִדְבַּק בִּימִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִיא אַהֲבָה רַבָּה. מָה הַטַּעַם נִקְרֵאת אַהֲבָה רַבָּה? מִשּׁוּם מִי שֶׁעוֹמֵד בָּאַהֲבָה הַזּוֹ, מִתְקַשֵּׁר בָּעוֹלָם הָעֶלְיוֹן. אַהֲבַת עוֹלָם, זֶה סוֹד הָעוֹלָם הַתַּחְתּוֹן, שֶׁהִתְקַשְּׁרָה בּוֹ אַהֲבָתוֹ, וְהַכֹּל סוֹד אֶחָד בְּלִי פֵרוּד. וַהֲרֵי נִתְבָּאֵר סוֹד הָאַהֲבָה, אַהֲבָה זוֹ עוֹלָה עַל כָּל עֲבוֹדוֹת הָעוֹלָם, בָּזֶה נִכְבָּד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מֵהַכֹּל וּמִתְבָּרֵךְ. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, וְסוֹד הָאַהֲבָה נִתְבָּאֵר.</p>\n<p>מִצְוָה <Nonesmall>[ז]</small> לִקְרֹא קְרִיאַת שְׁמַע פַּעֲמַיִם בְּכָל יוֹם, אַחַת כְּנֶגֶד דַּרְגַּת יוֹם, וְאַחַת כְּנֶגֶד דַּרְגַּת לַיְלָה, לְהַכְלִיל בַּיּוֹם דַּרְגַּת הַלַּיְלָה, וּלְהַכְלִיל בַּלַּיְלָה דַּרְגַּת יוֹם, וַהֲרֵי נִתְבָּאֵר. וְעַל זֶה פַּעֲמַיִם בְּכָל יוֹם, אֶחָד בַּיּוֹם וְאֶחָד בַּלַּיְלָה.</p>"],[9522012585,"<p>מִצְוָה שֶׁיִּקְבַּע אָדָם מְזוּזָה לְשַׁעֲרוֹ, לִהְיוֹת כָּל אָדָם שָׁמוּר מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁיּוֹצֵא וּכְשֶׁנִּכְנָס. וְהַסּוֹד – <Nonesmall>[תהלים קכא]</small> ה' יִשְׁמָר צֵאתְךְ וּבֹאֶךְ מֵעַתָּה וְעַד עוֹלָם. מִשּׁוּם שֶׁסּוֹד הַמְּזוּזָה עוֹמֵד תָּמִיד לַפֶּתַח, וְזֶהוּ פֶּתַח שֶׁלְּמַעְלָה, וְזוֹהִי דַרְגָּה שֶׁנִּקְרֵאת שׁוֹמֵר, לְהִמָּצֵא בִשְׁמִירָה.</p>\n<p>שֶׁאָדָם אֵינוֹ שָׁמוּר, רַק מִשְּׁמִירַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא תָּמִיד שׁוֹמֵר, וְעוֹמֵד לַפֶּתַח, וְהָאָדָם בִּפְנִים. וְעוֹד, שֶׁלֹּא יִשְׁכַּח אָדָם זִכְרוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים. וְזֶהוּ כְּמוֹ הַצִּיצִית, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[במדבר טו]</small> וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת וְגוֹ'. כֵּיוָן שֶׁרוֹאֶה הָאָדָם אֶת הַזִּכָּרוֹן הַזֶּה, נִזְכָּר בְּעַצְמוֹ לַעֲשׂוֹת מִצְוַת רִבּוֹנוֹ. וְסוֹד הָאֱמוּנָה, מְזוּזָה כְּלָל שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד.</p>\n<p>בְּסִפְרוֹ שֶׁל שְׁלֹמֹה, סָמוּךְ לַפֶּתַח, כְּנֶגֶד שְׁתֵּי דְרָגוֹת, מִזְדַּמֵּן שֵׁד אֶחָד <Nonesmall>[וזהו]</small> וְיֵשׁ לוֹ רְשׁוּת לְחַבֵּל, וְהוּא עוֹמֵד לְצַד שְׂמֹאל. מֵרִים הָאָדָם אֶת עֵינָיו, וְרוֹאֶה אֶת סוֹד שֵׁם רִבּוֹנוֹ, וְנִזְכָּר בּוֹ, וְלֹא יָכוֹל לְהָרַע לוֹ. וְאִם תֹּאמַר, אִם כָּךְ, כְּשֶׁהָאָדָם יוֹצֵא מֵהַשַּׁעַר הַחוּצָה הֲרֵי אוֹתוֹ שֵׁד עוֹמֵד לִימִינוֹ, וּמְזוּזָה לִשְׂמֹאלוֹ, וְאֵיךְ נִשְׁמָר הָאָדָם כְּשֶׁהוּא שׁוֹרֶה לִשְׂמֹאלוֹ?</p>\n<p>אֶלָּא כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל דָּבָר וְדָבָר נִמְשָׁךְ אַחַר מִינוֹ. בָּאָדָם יֵשׁ שְׁתֵּי דְרָגוֹת, אַחַת מִיָּמִין וְאַחַת מִשְּׂמֹאל. אוֹתוֹ שֶׁמִּיָּמִין נִקְרָא יֵצֶר הַטּוֹב, וְאוֹתוֹ שֶׁל הַשְּׂמֹאל נִקְרָא יֵצֶר הָרָע. כֵּיוָן שֶׁיָּצָא אָדָם מִשַּׁעַר בֵּיתוֹ, אוֹתוֹ שֵׁד מֵרִים עֵינָיו, וְרוֹאֶה אֶת הַיֵּצֶר הָרָע שֶׁשּׁוֹרֶה לִשְׂמֹאל, נִמְשָׁךְ לְאוֹתוֹ צַד וְזָז מִיָּמִין. וּבְאוֹתוֹ צַד עוֹמֵד שֵׁם שֶׁל רִבּוֹנוֹ, וְלֹא יָכוֹל לְהִתְקָרֵב וּלְהָרַע לוֹ, וְיוֹצֵא הָאָדָם וְנִצּוֹל מִמֶּנּוּ. כְּשֶׁנִּכְנָס, הֲרֵי הַשֵּׁם הַקָּדוֹשׁ עוֹמֵד לְיָמִין וְלֹא יָכוֹל לְקַטְרֵג עִמּוֹ.</p>\n<p>וְעַל זֶה צָרִיךְ הָאָדָם שֶׁלֹּא יַעֲשֶׂה <Nonesmall>[יעביר]</small> טִנּוּף וְלִכְלוּךְ בְּשַׁעַר בֵּיתוֹ וְלֹא יִשְׁפֹּךְ מַיִם עֲכוּרִים. אֶחָד, שֶׁלֹּא יַעֲשֶׂה קָלוֹן לְשֵׁם רִבּוֹנוֹ. וְאֶחָד, שֶׁיֵּשׁ רְשׁוּת לְאוֹתוֹ הַמְחַבֵּל לְחַבֵּל. וְלָכֵן יִזָּהֵר הָאָדָם מִזֶּה, וְיִזָּהֵר הָאָדָם שֶׁלֹּא יִמְנַע מִשַּׁעַר בֵּיתוֹ שֵׁם רִבּוֹנוֹ.</p>\n<p>וּכְשֶׁאָדָם מַתְקִין מְזוּזָה לְפִתְחוֹ, כְּשֶׁנִּכְנָס <Nonesmall>[אותו האדם]</small>, אוֹתוֹ יֵצֶר הָרָע וְאוֹתוֹ שֵׁד בְּעַל כָּרְחָם שׁוֹמְרִים אוֹתוֹ, וְאוֹמְרִים <Nonesmall>[תהלים קיח]</small> זה השער לה' צדיקים יבאו בו. וכשלא עומדת מזוזה בפתח האיש, יצר הרע ואותו שד מתתקנים כאחד, שמים ידיהם על ראשו בזמן שנכנס, פותחים ואומרים: אוי לו לפלוני שיצא מרשות רבונו! מאותו זמן הוא עומד בלי שמירה, שאין מי שישמר עליו. הרחמן יצילנו.</p>"]]});
